bool CImageAPI::DeductBasePhase(PHASE_DATA BasePhase, int &Phase)//扣除相平面
{
	Phase -= BasePhase;//注意若使用unsigned short則需要更大的整數來使用, 避免溢位			
	if ( Phase < 0 ) 
	{	Phase += PHASE_PERIOD; }
	else if ( Phase > PHASE_PERIOD ) 
	{	Phase -= PHASE_PERIOD; }	
	return true;
}
