//-------------------------------------------------------------------------------------//
bool CImageAPI::ConvertPhaseToSpace(int CvtMode, int idx, float Phase, const float* p1, const float *p2, float &Space)//相位轉成高度值
{
	if ( PHASE_CONVERT_HEIGHT_SCALE != CvtMode ) { return true; }
	float space=0.0f;	
	if ( NULL != p1 )
	{	space += (Phase*p1[idx]);	}
	if ( NULL != p2 ) 
	{	space += (Phase*Phase*p2[idx]); }	
	Space = (SPACE_DATA)(space/PHASE_HEIGHT_FACTOR_SCALE);
	//Space*PHASE_HEIGHT_FACTOR_SCALE = (Phase*KValue)	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ConvertSpaceToPhase(int CvtMode, int idx, float Space, const float* p1, const float *p2, int &Phase)//高度轉成相位值
{
	if ( PHASE_CONVERT_HEIGHT_SCALE != CvtMode ) { return true; }
	float phase=0.0f;		
	if ( NULL != p1 )
	{
		Space = Space*PHASE_HEIGHT_FACTOR_SCALE;	
		if ( NULL == p2 )
		{	phase = (Space/p1[idx]);	}
		else
		{	
			//ax^2 + bx + c = 0, x=(-b+sqrt(D))/2a, D=b*b-4ac
			float a =  p2[idx];
			float b =  p1[idx];
			float c = -Space;
			float D = (b*b)-(4*a*c);
			phase = (sqrt(D)-b)/(2*a);
		}
	}		
	//Space*PHASE_HEIGHT_FACTOR_SCALE/KValue=(Phase)
	Phase = (int)(phase);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ConvertPhaseToSpaceMapFunc(int CvtMode, double X, double Y, int Phase, const double* T0, const double* T1, const double* T2, float &Space)//相位轉成高度值
{
	if ( PHASE_CONVERT_HEIGHT_SCALE == CvtMode )
	{	return true; }
	if ( NULL==T0 || NULL==T1 || NULL==T2 )
	{	return false; }	

	//求得對應XY的a值	
	double a[4]={0};	
	switch ( CvtMode )
	{	
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_7://3階, a0+a1X+a2Y+a3XX+a4YY+a5XXX+a6YYY
	{		
		double XX=X*X;
		double XXX=XX*X;
		double YY=Y*Y;
		double YYY=YY*Y;
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(XX*T0[3])+(YY*T0[4])+(XXX*T0[5])+(YYY*T0[6]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(XX*T1[3])+(YY*T1[4])+(XXX*T1[5])+(YYY*T1[6]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(XX*T2[3])+(YY*T2[4])+(XXX*T2[5])+(YYY*T2[6]);
	}
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_6://2階, a0+a1X+a2Y+a3XY+a4XX+a5YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3])+(X*X*T0[4])+(Y*Y*T0[5]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3])+(X*X*T1[4])+(Y*Y*T1[5]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3])+(X*X*T2[4])+(Y*Y*T2[5]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_5://2階, a0+a1X+a2Y+a3XX+a4YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*X*T0[3])+(Y*Y*T0[4]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*X*T1[3])+(Y*Y*T1[4]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*X*T2[3])+(Y*Y*T2[4]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_4://2階, a0+a1X+a2Y+a3XY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_3://2階, a0+a1X+a2Y
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2]);
		break;
	default:
		break;
	}
	//Height;	
	a[3] = a[0]+(Phase*a[1])+(Phase*Phase*a[2]);
	Space = (float)(a[3]); 
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ConvertSpaceToPhaseMapFunc(int CvtMode, double X, double Y, float Space, const double* T0, const double* T1, const double* T2, int &Phase)//高度轉成相位值
{	
	if ( PHASE_CONVERT_HEIGHT_SCALE == CvtMode )
	{	return true; }
	if ( NULL==T0 || NULL==T1 || NULL==T2 )
	{	return false; }
	
	//求得對應XY的a值	
	double a[4]={0};	
	switch ( CvtMode )
	{	
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_7://3階, a0+a1X+a2Y+a3XX+a4YY+a5XXX+a6YYY
	{
		double XX=X*X;
		double XXX=XX*X;
		double YY=Y*Y;
		double YYY=YY*Y;
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(XX*T0[3])+(YY*T0[4])+(XXX*T0[5])+(YYY*T0[6]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(XX*T1[3])+(YY*T1[4])+(XXX*T1[5])+(YYY*T1[6]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(XX*T2[3])+(YY*T2[4])+(XXX*T2[5])+(YYY*T2[6]);
	}
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_6://2階, a0+a1X+a2Y+a3XY+a4XX+a5YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3])+(X*X*T0[4])+(Y*Y*T0[5]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3])+(X*X*T1[4])+(Y*Y*T1[5]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3])+(X*X*T2[4])+(Y*Y*T2[5]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_5://2階, a0+a1X+a2Y+a3XX+a4YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*X*T0[3])+(Y*Y*T0[4]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*X*T1[3])+(Y*Y*T1[4]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*X*T2[3])+(Y*Y*T2[4]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_4://2階, a0+a1X+a2Y+a3XY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_3://2階, a0+a1X+a2Y
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2]);
		break;
	default:
		break;
	}	
	//ax^2 + bx + c = 0, x=(-b+sqrt(D))/2a, D=b*b-4ac
	double A =  a[2];
	double B =  a[1];
	double C =  a[0]-Space;
	double D =  (B*B)-(4*A*C);
	double phase = (sqrt(D)-B)/(2*A);	
	Phase = (int)(phase);
	return true;
}
//-------------------------------------------------------------------------------------//
MASK_DATA CImageAPI::CombinePhaseMask(MASK_DATA Mask1, MASK_DATA Mask2)
{
	MASK_DATA Mask=0;
	if ( (Mask1&PHASE_MASK_LOW_CONTRAST)!=0 || (Mask2&PHASE_MASK_LOW_CONTRAST)!=0 )
	{	Mask |= PHASE_MASK_LOW_CONTRAST;	}	
	else if ( (Mask1&PHASE_MASK_LOW_POTENTIAL)!=0 || (Mask2&PHASE_MASK_LOW_POTENTIAL)!=0 )
	{	Mask |= PHASE_MASK_LOW_POTENTIAL;	}
	else if ( (Mask1&PHASE_MASK_OVER_SATURATED)!=0 || (Mask2&PHASE_MASK_OVER_SATURATED)!=0 )
	{	Mask |= PHASE_MASK_OVER_SATURATED;	}
	else
	{	Mask = PHASE_MASK_VALID; }
	return Mask;
}
