//-------------------------------------------------------------------------------------//
int CImageAPI::CalcFilterCount(int FilterSize, int UseSize)
{
	int FilterCount=0;
	if ( 0==UseSize || UseSize>=(FilterSize/2)  )
	{	return FilterSize*FilterSize;	}

	int i=0;
	int UseCnt=0;
	int TempCnt=0;
	int TempSize=FilterSize;	
	while ( TempSize > 2 ) 
	{
		TempCnt = (TempSize+TempSize-2)*2;
		FilterCount += TempCnt;
		UseCnt ++;
		TempSize -= 2;
		if ( UseCnt >= UseSize )
		{	break; }
	};	
	return FilterCount;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::CombinePhasePeriod_MaxMin(int Phase1, int Phase2, double Ratio)
{
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM = (int)(Ratio*PHASE_PERIOD);//以第1週期為主的大週期	

	//基本公式如下
	//1.相位差=相位1-相位2
	//2.如果相位差<0，則相位差加上周期
	//3.將相位差x比例1則可得到還原後的相位1
	//4.將相位差x比例2則可得到還原後的相位2

	//Kai-20161006-直接將週期2打成大週期, 因此合成的週期為相位2, 改成以短周期相位為主的合成相位
	int PhaseM = Phase2;
	//Kai-20161005-改成以短周期相位為主的合成相位
	int PhaseMT = PhaseM;
	int PhaseMFull = (int)(PhaseMT*Ratio);//將合併相位轉到以小週期下的相位
	//計算落於小週期下第幾個週期
	double dPeriod = (PhaseMFull-Phase1+PhaseDummy+0.0)/PHASE_PERIOD;//加上0.0是轉成浮點數			
	int    nPeriod = JetAPI::Floor(dPeriod);//使用此函數主要是當dPeriod為負數時的計算
	int    PhaseMFullNew = Phase1+(nPeriod*PHASE_PERIOD);//使用小週期計算出的新相位
	if ( PhaseMFullNew < 0 ) //當新相位小於0, 則需要補足整各小週期的週期
	{	PhaseMFullNew += FullPeriodM; }
	if ( PhaseMFullNew > FullPeriodM )
	{	PhaseMFullNew -= FullPeriodM; }
	double dValue = (PhaseMFullNew/Ratio);
	int PhaseMNew  = (int)(PhaseMFullNew/Ratio);//將新相位轉落於合併週期的座標系裡
	PhaseM  = PhaseMNew;
	return PhaseM;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::CombinePhasePeriod_Sibling(int Phase1, int Phase2, double Ratio)//合併鄰近週期
{
	int PhaseM = 0;
	int PhaseMT = 0;
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;
	int nPeriod = 0;	
	double dPeriod = 0.0;
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM1 = (int)(Ratio*PHASE_PERIOD);//以第1週期為主的大週期
	if ( Phase2 > Phase1 )
	{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
	else
	{	PhaseM = Phase1-Phase2;	}

	//Kai-20161005-改成以短周期相位為主的合成相位
	PhaseMT = PhaseM;
	PhaseMFull = (int)(PhaseMT*Ratio);//將合併相位轉到以小週期下的相位
	//計算落於小週期下第幾個週期
	dPeriod = (PhaseMFull-Phase1+PhaseDummy+0.0)/PHASE_PERIOD;
	nPeriod = JetAPI::Floor(dPeriod);//使用此函數主要是當dPeriod為負數時的計算
	PhaseMFullNew = Phase1+(nPeriod*PHASE_PERIOD);//使用小週期計算出的新相位
	if ( PhaseMFullNew < 0 ) //當新相位小於0, 則需要補足整各小週期的週期
	{	PhaseMFullNew += FullPeriodM1; }
	if ( PhaseMFullNew > FullPeriodM1 )
	{	PhaseMFullNew -= FullPeriodM1; }
	PhaseMNew  = (int)(PhaseMFullNew/Ratio);//將新相位轉落於合併週期的座標系裡
	PhaseM  = PhaseMNew;	
	return PhaseM;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::CombinePhasePeriod(int Mode, int Phase1, int Phase2, double Ratio)//合併兩個週期
{
	if ( COMBINE_PHASE_SIBLING_PERIOD == Mode )
	{	return CombinePhasePeriod_Sibling(Phase1, Phase2, Ratio); }
	return CombinePhasePeriod_MaxMin(Phase1, Phase2, Ratio);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcCombinePhasePeriodRatio(int Mode, double P1, double P2, double &Ratio)//計算合併比例
{
	const double PP1 = __min(P1, P2);
	const double PP2 = __max(P1, P2);
	if ( COMBINE_PHASE_SIBLING_PERIOD == Mode )
	{
		double Ratio1=0.0;
		double Ratio2=0.0;
		if ( P2 > P1 )//P2 為主
		{	
			//dRatio = PP1*Precision/(PP2-PP1); 		
			Ratio1 = PP2/(PP2-PP1);
			Ratio2 = PP1/(PP2-PP1);
			Ratio = Ratio1;
		}
		else //P1為主 
		{	
			//dRatio = PP2*Precision/(PP2-PP1);	
			Ratio1 = PP1/(PP2-PP1);
			Ratio2 = PP2/(PP2-PP1);
			Ratio = Ratio2;
		}	
	}
	else
	{	
		if ( P2 > P1 )//P2 為主
		{	Ratio = P2/P1;	}
		else //P1為主 
		{	Ratio = 1;	}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::CombinePhasePeriod_GrayCode(int Phase, int Period, int NPeriod, int k1, int k2)//合併相位與GrayCode
{
	int PhaseM;
	const int PeriodQart1 =   Period/4;//90
	const int PeriodQart3 = 3*Period/4;//270
	if ( Phase <= PeriodQart1 ) 
	{	PhaseM=Phase+(Period*k2); }
	else if ( Phase >= PeriodQart3 ) 
	{	PhaseM=Phase+(Period*k2)-(Period); }
	else
	{	PhaseM=Phase+(Period*k1); }		
	PhaseM = (PhaseM/NPeriod);
	if ( PhaseM > Period )
	{	PhaseM -= Period; }
	return PhaseM;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc3PhaseContrast(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3)
{	//Test 尚未確認
	float Ave=(P1+P3)/2.0f;
	float Im=P1-P2;
	float Re=P3-P2;
	float Contrast=0.0f;	
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc21PhaseContrast(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3)
{
	float Ave=P2;
	float Im=P1-P2;
	float Re=P3-P2;
	float Contrast=0.0f;	
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc4PhaseContrast(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, PHASE_DATA P4)
{
	float Ave=(P1+P2+P3+P4)/2.0f;
	float Im=P4-P2;
	float Re=P1-P3;
	float Contrast=0.0f;
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc3PhasePotential(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3)
{
	return (abs(P3-P2)+abs(P1-P2));	
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc21PhasePotential(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3)
{
	return 2*(abs(P3-P2)+abs(P1-P2));	
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc4PhasePotential(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, PHASE_DATA P4)
{
	return (abs(P1-P3)+abs(P2-P4));	
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Calc5PhasePotential(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, PHASE_DATA P4, PHASE_DATA P5)
{
	return (abs(P1-P3)+abs(P2-P4));
}
