//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4PhaseMeanContrastRatio(int P1, int P2, int P3, int P4, float &A, float &B, float &CV)
{		
	const float Dif13=P1-P3;
	const float Dif24=P2-P4;	
	const float Sum=(P1+P2+P3+P4);

	B=sqrtf((Dif13*Dif13)+(Dif24*Dif24))*0.5f;
	if ( Sum > 0.01 )
	{
		A = Sum/4.0f;
		CV = B/A;
	}
	else
	{	A = CV = 0.0f; }
	return true;
}
