bool CImageAPI::Check3PhaseSaturated(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, int SatTh)
{
	int OverSaturatedCnt = 0;
	if ( P1>SatTh ) { OverSaturatedCnt++; }
	if ( P2>SatTh ) { OverSaturatedCnt++; }
	if ( P3>SatTh ) { OverSaturatedCnt++; }	
	if ( OverSaturatedCnt > 1 ) { return true; }
	return false;
}
