//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc3PhaseParam(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, int &a, int &b, PHASE_DATA &c)
{
	a = P3-P2;//-256 ~ 256 => 512
	b = P1-P2;//-256 ~ 256 => 512
	c = (P1+P3)/2;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc21PhaseParam(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, int &a, int &b, PHASE_DATA &c)//2+1
{
	a = P3-P2;//-256 ~ 256 => 512
	b = P1-P2;//-256 ~ 256 => 512
	c = P2;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4PhaseParam(PHASE_DATA P1, PHASE_DATA P2, PHASE_DATA P3, PHASE_DATA P4, int &a, int &b, PHASE_DATA &c)
{	
	a = P4-P2;//-256 ~ 256 => 512
	b = P1-P3;//-256 ~ 256 => 512
	c = (P1+P2+P3+P4)>>2;//全部平均		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc5PhaseParam(int P1, int P2, int P3, int P4, int P5, int &a, int &b, PHASE_DATA &c)
{	
	a = 2*(P2-P4);//-512 ~ 512	
	b = 2*P3-P5-P1;//-512 ~ 512
	//a = 2*(P4-P2);//-512 ~ 512	
	//b = P5+P1-(2*P3);//-512 ~ 512
	c = (P1+P2+P3+P4)>>2;//前4個平均	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc3PhaseParamMask(int P1, int P2, int P3, int NoiseMask, int LowContrast, int LowPotential, int OverSaturated, PHASE_DATA &Phase, MASK_DATA &Mask)
{
	int         a=0, b=0;
	PHASE_DATA  c=0;
	int         Contrast=0;		
	const bool  bNewContrast=GetUseNewContrast();//20190530
	const BOOL  bCheckLowContrast   = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_CONTRAST);
	Mask = PHASE_MASK_VALID;
	Calc3PhaseParam(P1, P2, P3, a, b, c);
	if ( CalcArctangent(a, b, Phase) == false )
	{	return false; }
	if ( bCheckLowContrast )//對比不足
	{
		if ( PHASE_MASK_VALID == Mask )
		{	
			if ( false == bNewContrast )
			{	Contrast = CalcPhaseContrast(a, b, c); }
			else
			{	Contrast = Calc3PhaseContrast(P1, P2, P3); }
			if ( Contrast < LowContrast )
			{	
				Mask = PHASE_MASK_LOW_CONTRAST;	
				return true;
			}
		}
	}

	int         Potential=0;	
	const BOOL  bCheckLowPotential  = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_POTENTIAL);	
	if ( bCheckLowPotential )//潛能過低
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			Potential=Calc3PhasePotential(P1, P2, P3);
			if ( Potential < LowPotential)
			{	
				Mask = PHASE_MASK_LOW_POTENTIAL;	
				return true;
			}
		}	
	}

	const BOOL  bCheckOverSaturated = (BOOL)(NoiseMask&PHASE_NOSIE_OVER_SATURATED);	
	if ( bCheckOverSaturated )//過飽合
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			if ( Check3PhaseSaturated(P1, P2, P3, OverSaturated) == true )
			{	
				Mask = PHASE_MASK_OVER_SATURATED;	
				return true;
			}	
		}
	}
	return true;
}
