//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4PhaseParamMask_2(int P1, int P2, int P3, int P4, int NoiseMask, int LowContrast, int LowPotential, int OverSaturated, PHASE_DATA &Phase, MASK_DATA &Mask)
{
	int         a=0, b=0;
	PHASE_DATA  c=0;		
	float       A=0, B=0, CV=0;		
	Mask = PHASE_MASK_VALID;
	Calc4PhaseParam(P1, P2, P3, P4, a, b, c);
	if ( CalcArctangent(a, b, Phase) == false ) 
	{	return false; }
	if ( Calc4PhaseMeanContrastRatio(P1, P2, P3, P4, A, B, CV) == false )
	{	return false; }

	//LowContrast = 30;//0.3
	float       Contrast=0;
	const float fLowContrast=GetPhaseNoiseMinCV(LowContrast);
	const BOOL  bCheckLowContrast   = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_CONTRAST);
	if ( bCheckLowContrast )//對比不足
	{		
		if ( PHASE_MASK_VALID == Mask )
		{	
			Contrast = (float)(CV);
			if ( Contrast < fLowContrast )
			{	
				Mask = PHASE_MASK_LOW_CONTRAST;	//Check CV
				return true;
			}
		}
	}

	//LowPotential= 20;//2
	float       Potential=0;		
	const float fLowPotential=GetPhaseNoiseMinB(LowPotential);
	const BOOL  bCheckLowPotential  = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_POTENTIAL);	
	if ( bCheckLowPotential )//潛能過低
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			Potential=(float)(B);
			if ( Potential < fLowPotential)
			{	
				Mask = PHASE_MASK_LOW_POTENTIAL;//Check B
				return true;
			}
		}	
	}

	//OverSaturated = 250;
	const BOOL  bCheckOverSaturated = (BOOL)(NoiseMask&PHASE_NOSIE_OVER_SATURATED);	
	if ( bCheckOverSaturated )//過飽合
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			if ( Check4PhaseSaturated(P1, P2, P3, P4, OverSaturated) == true )
			{	
				Mask = PHASE_MASK_OVER_SATURATED;
				return true;
			}	
		}
	}

	//Calc4PhasePhaseThreshold(P1, P2, P3, P4, Mask, Phase);	
	return true;
}
