//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4GrayCodeParam(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	if ( glUseNewGrayCodeThreshold )
	{	return Calc4GrayCodeParam_2(P1, P2, P3, P4, Th, Map1, Map2, k1, k2); }
	return Calc4GrayCodeParam_1(P1, P2, P3, P4, Th, Map1, Map2, k1, k2);	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4GrayCodeParam_1(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	if ( NULL==Map1 || NULL==Map2 ) { return false; }

	int Code1 = 0;
	int Code2 = 0;
	const bool bGrayCodeInvert = false;//16G->32G->64G->128G->256B	
	if ( P1 > Th)
	{	Code2 |= 0x01;	}
	if ( P2 > Th)
	{
		Code1 |= 0x01;
		Code2 |= 0x02;
	}
	if ( P3 > Th)
	{
		Code1 |= 0x02;
		Code2 |= 0x04;
	}
	if ( P4 > Th)
	{
		Code1 |= 0x04;
		Code2 |= 0x08;
	}
	k1 = Map1[Code1];
	k2 = Map2[Code2];
	k2 = (k2+1)/2;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc4GrayCodeParam_2(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	if ( NULL==Map1 || NULL==Map2 ) { return false; }

	int PMax=P1;
	int PMin=P1;
	int Code1 = 0;
	int Code2 = 0;
	float Ratio=0.1f;
	const float RatioPitch=0.5f/4.0f;
	const bool bGrayCodeInvert = false;//16G->32G->64G->128G->256B	
	if ( PMax < P2 ) { PMax=P2; }
	if ( PMin > P2 ) { PMin=P2; }
	if ( PMax < P3 ) { PMax=P3; }
	if ( PMin > P3 ) { PMin=P3; }
	if ( PMax < P4 ) { PMax=P4; }
	if ( PMin > P4 ) { PMin=P4; }
	const float PAve=Th;
	const float PMid=(PMax+PMin)/2.0f;

	Ratio = RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P1 > Th)
	{	Code2 |= 0x01;	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P2 > Th)
	{
		Code1 |= 0x01;
		Code2 |= 0x02;
	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P3 > Th)
	{
		Code1 |= 0x02;
		Code2 |= 0x04;
	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P4 > Th)
	{
		Code1 |= 0x04;
		Code2 |= 0x08;
	}
	k1 = Map1[Code1];
	k2 = Map2[Code2];
	k2 = (k2+1)/2;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Calc5GrayCodeParam(int P1, int P2, int P3, int P4, int P5, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//5階GrayCode解碼
{
	if ( glUseNewGrayCodeThreshold )
	{	return Calc5GrayCodeParam_2(P1, P2, P3, P4, P5, Th, Map1, Map2, k1, k2); }
	return Calc5GrayCodeParam_1(P1, P2, P3, P4, P5, Th, Map1, Map2, k1, k2);	
}
