//-------------------------------------------------------------------------------------//
bool CImageAPI::CompareNSpaceHeight(const MASK_DATA MaskList[], const float SpaceList[], int SpaceCount, MASK_DATA &Mask, float &Space)//比較空間高度
{
	const int SpaceCnt = SpaceCount;
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;
	if ( SpaceCnt > MaxSpaceCount ) { return false; }
	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();	
	const int CastMergeMode = SystemParam.m_SpaceNoiseMultiCastMergeMode;
	const SPACE_DATA CastValidDifference = (SPACE_DATA)(SystemParam.m_SpaceNoiseMultiCastValidDifference);
	const SPACE_DATA CastValidBestRatio = (SPACE_DATA)(SystemParam.m_SpaceNoiseMultiCastValidBestRatio/100.0);
	const SPACE_DATA CastValidBestVal = CastValidDifference*CastValidBestRatio;
	if ( CastValidDifference < 0.5 )	{	return false; }

	int   i=0;
	bool  Mached=false;	
	float Space1=0;
	float Space2=0;
	float Space3=0;
	float Space4=0;
	float SpaceDif = 0;
	float SpaceNew = 0;
	float SpaceDif12 = 0;
	float SpaceAve12 = 0;
	float SpaceDif34 = 0;
	float SpaceAve34 = 0;
	float SpaceDif1234 = 0;	
	int   TotalGoupCount = 0;			
	int   SpaceGroupCnt[MaxSpaceCount];
	float SpaceGroupAve[MaxSpaceCount];
	float SpaceGroupMin[MaxSpaceCount];
	float SpaceGroupMax[MaxSpaceCount];
	float SortList[MaxSpaceCount];
	const float CastGroupRange = CastValidDifference*1.5;
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;//PHASE_MASK_VALID_BEST;//20190530
	
	for ( i=0; i<SpaceCount; i++ )
	{		
		SpaceGroupCnt[i] = 0;
		SortList[i] = SpaceList[i];
		SpaceGroupAve[i] = SpaceGroupMin[i] = SpaceGroupMax[i] = 0.0f;
	}

	TotalGoupCount = 0;	
	for ( i=0; i<SpaceCount; i+=4 )
	{
		Space1 += SpaceList[i];
		Space2 += SpaceList[i+1];
		Space3 += SpaceList[i+2];
		Space4 += SpaceList[i+3];
		TotalGoupCount ++;
	}
	if ( 0 == TotalGoupCount ) { return false; }		

	Space1    /= TotalGoupCount;
	Space2    /= TotalGoupCount;
	Space3    /= TotalGoupCount;
	Space4    /= TotalGoupCount;
	SpaceDif12 = ::fabs(Space1-Space2);	
	SpaceDif34 = ::fabs(Space3-Space4);
	SpaceAve12 = (Space1+Space2)*0.5f;
	SpaceAve34 = (Space3+Space4)*0.5f;
	SpaceDif1234 = ::fabs(SpaceAve12-SpaceAve34);

	//for Type I 
	Mached=false;
	if ( SpaceDif12>CastValidDifference || SpaceDif34>CastValidDifference )
	{	Mached = false;	}
	else
	{
		const float CastValidBestVal2 = CastValidBestVal/2.0f;
		if ( SpaceDif1234 < CastValidBestVal2 ) 
		{	Mached = true;	}
	}
	if ( true == Mached ) 
	{
		int index = 0;
		float GroupRange = 200;		
		SortSpcaeHeight(SortList, SpaceCnt);
		if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
		{
			GroupRange = CastGroupRange;
			GroupSpcaeHeightByMean(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount);	
		}
		else
		{
			GroupRange = 200;
			GroupSpcaeHeightByRange(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
		}
		index = GetMassGroupIndex(SpaceGroupCnt, TotalGoupCount);		
		Mask  = Mask_ValidBest;
		Space = SpaceGroupAve[index];
		if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
		{
			if ( TotalGoupCount == SpaceCount )
			{
				Mask  = Mask_ValidBest;
				Space = AverageSpaceHeight(SortList, SpaceCnt);
			}
		}
		return true;
	}

	//for Type II	
	float SpaceDifMin = MIN(SpaceDif12, SpaceDif34);
	if ( SpaceDifMin < CastValidDifference )
	{
		if ( ::fabs(Space3-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space3-Space2)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space2)<CastValidDifference ) 
		{	Mached = true; }			
		if ( true == Mached )
		{
			int index = 0;
			float GroupRange = 200;			
			SortSpcaeHeight(SortList, SpaceCnt);
			if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
			{
				GroupRange = CastGroupRange;
				GroupSpcaeHeightByMean(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount);	
			}
			else
			{
				GroupRange = 200;
				GroupSpcaeHeightByRange(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
			}
			index = GetMassGroupIndex(SpaceGroupCnt, TotalGoupCount);
			Mask  = Mask_ValidBest;
			Space = SpaceGroupAve[index];
			if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
			{
				if ( TotalGoupCount == SpaceCount )
				{
					Mask  = Mask_ValidBest;
					Space = AverageSpaceHeight(SortList, SpaceCnt);
				}
			}
			return true;
		}
	}	
	return false;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CompareNSpaceHeight(const std::vector<MASK_DATA> &MaskList, const std::vector<float> &SpaceList, MASK_DATA &Mask, float &Space)//比較空間高度
{
	const size_t MaskCount=MaskList.size();
	const size_t SpaceCount=SpaceList.size();
	if ( MaskCount != SpaceCount ) { return false; }

	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();	
	const int CastMergeMode = SystemParam.m_SpaceNoiseMultiCastMergeMode;
	const SPACE_DATA CastValidDifference = (SPACE_DATA)(SystemParam.m_SpaceNoiseMultiCastValidDifference);
	const SPACE_DATA CastValidBestRatio = (SPACE_DATA)(SystemParam.m_SpaceNoiseMultiCastValidBestRatio/100.0);
	const SPACE_DATA CastValidBestVal = CastValidDifference*CastValidBestRatio;
	if ( CastValidDifference < 0.5 )	{	return false; }

	int   i=0;
	bool  Mached=false;	
	float Space1=0;
	float Space2=0;
	float Space3=0;
	float Space4=0;
	float SpaceDif = 0;
	float SpaceNew = 0;
	float SpaceDif12 = 0;
	float SpaceAve12 = 0;
	float SpaceDif34 = 0;
	float SpaceAve34 = 0;
	float SpaceDif1234 = 0;	
	int   TotalGoupCount = 0;			
	std::vector<int>   SpaceGroupCnt;
	std::vector<float> SpaceGroupAve;
	std::vector<float> SpaceGroupMin;
	std::vector<float> SpaceGroupMax;
	std::vector<float> SortList;
	const float CastGroupRange = CastValidDifference*1.5;
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;//PHASE_MASK_VALID_BEST;//20190530

	TotalGoupCount = 0;
	for ( i=0; i<SpaceCount; i+=4 )
	{
		Space1 += SpaceList[i];
		Space2 += SpaceList[i+1];
		Space3 += SpaceList[i+2];
		Space4 += SpaceList[i+3];
		TotalGoupCount ++;
	}
	if ( 0 == TotalGoupCount ) { return false; }
	Space1    /= TotalGoupCount;
	Space2    /= TotalGoupCount;
	Space3    /= TotalGoupCount;
	Space4    /= TotalGoupCount;
	SpaceDif12 = ::fabs(Space1-Space2);	
	SpaceDif34 = ::fabs(Space3-Space4);
	SpaceAve12 = (Space1+Space2)*0.5f;
	SpaceAve34 = (Space3+Space4)*0.5f;
	SpaceDif1234 = ::fabs(SpaceAve12-SpaceAve34);

	//for Type I 
	Mached=false;
	if ( SpaceDif12>CastValidDifference || SpaceDif34>CastValidDifference )
	{	Mached = false;	}
	else
	{
		const float CastValidBestVal2 = CastValidBestVal/2.0f;
		if ( SpaceDif1234 < CastValidBestVal2 ) 
		{	Mached = true;	}
	}
	if ( true == Mached ) 
	{
		int index = 0;
		float GroupRange = 200;
		SortList = SpaceList;
		SortSpcaeHeight(SortList);		
		if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
		{
			GroupRange = CastGroupRange;
			GroupSpcaeHeightByMean(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt);	
		}
		else
		{
			GroupRange = 200;
			GroupSpcaeHeightByRange(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt); 
		}
		TotalGoupCount = (int)(SpaceGroupCnt.size());
		index = GetMassGroupIndex(SpaceGroupCnt);		
		Mask  = Mask_ValidBest;
		Space = SpaceGroupAve[index];
		if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
		{
			if ( TotalGoupCount == SpaceCount )
			{
				Mask  = Mask_ValidBest;
				Space = AverageSpaceHeight(SortList);
			}
		}
		return true;
	}

	//for Type II	
	float SpaceDifMin = MIN(SpaceDif12, SpaceDif34);
	if ( SpaceDifMin < CastValidDifference )
	{
		if ( ::fabs(Space3-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space3-Space2)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space2)<CastValidDifference ) 
		{	Mached = true; }			
		if ( true == Mached )
		{
			int index = 0;
			float GroupRange = 200;
			SortList = SpaceList;
			SortSpcaeHeight(SortList);
			if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
			{
				GroupRange = CastGroupRange;
				GroupSpcaeHeightByMean(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt); 
			}
			else
			{
				GroupRange = 200;
				GroupSpcaeHeightByRange(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt); 
			}
			TotalGoupCount = (int)(SpaceGroupCnt.size());
			index = GetMassGroupIndex(SpaceGroupCnt);
			Mask  = Mask_ValidBest;
			Space = SpaceGroupAve[index];
			if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
			{
				if ( TotalGoupCount == SpaceCount )
				{
					Mask  = Mask_ValidBest;
					Space = AverageSpaceHeight(SortList);
				}
			}
			return true;
		}
	}	
	return false;	
}
//-------------------------------------------------------------------------------------//
int CImageAPI::GetMassGroupIndex(int GroupCnt[], int Count)//取得群組數量最多的引數
{
	int i=0;
	int index = 0;
	int MaxCnt=-1;
	for ( i=0; i<Count; i++ )
	{
		if ( 0==i || MaxCnt<GroupCnt[i])
		{
			index = i;
			MaxCnt=GroupCnt[i]; 
		}
	}
	return index;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::GetMassGroupIndex(const std::vector<int> &GroupCntList)//取得群組數量最多的引數
{
	int i=0;
	int index = 0;
	int MaxCnt=-1;
	const int Count = (int)(GroupCntList.size());
	for ( i=0; i<Count; i++ )
	{
		if ( 0==i || MaxCnt<GroupCntList[i])
		{
			index = i;
			MaxCnt=GroupCntList[i]; 
		}
	}
	return index;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AddGroupSpcaeHeightByMean(float Space, float Range, float &Group, int &GroupCnt)//加入高度分群-依照平均值
{
	const float SpaceDif = ::fabsf(Space-Group);
	if ( SpaceDif > Range ) { return false; }
	const float Sum = (Group*GroupCnt)+Space; 
	GroupCnt ++;
	Group = Sum/GroupCnt;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AddGroupSpcaeHeightByRange(float Space, float Range, float &GroupMin, float &GroupMax, float &GroupAve, int &GroupCnt)//加入高度分群-依照範圍值
{
	const float SpaceDifMin = ::fabsf(Space-GroupMin);
	const float SpaceDifMax = ::fabsf(Space-GroupMax);
	const float SpaceDif = MIN(SpaceDifMin, SpaceDifMax);
	if ( SpaceDif > Range )
	{	return false; }

	const float Sum = (GroupAve*GroupCnt)+Space; 
	GroupCnt ++;
	GroupAve = Sum/GroupCnt;
	if ( Space < GroupMin ) { GroupMin = Space; }
	if ( Space > GroupMax ) { GroupMax = Space; }
	return true;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::GetMinValueIndex(float SpaceList[], int StartIdx, int SpaceCnt)//取得最低值引數
{	
	int i=0;
	int idx=StartIdx;
	for ( i=StartIdx+1; i<SpaceCnt; i++ )
	{
		if ( SpaceList[idx] > SpaceList[i] )
		{	idx = i;	}		
	}
	return idx;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CheckArraySorted(float SpaceList[], int SpaceCnt)//確認陣列排序過
{
	if ( 0==SpaceCnt || 1==SpaceCnt ) { return true; }
	for ( int i=0; i<SpaceCnt-1; i++ )
	{	
		if ( SpaceList[i] > SpaceList[i+1] )
		{	return false; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight(std::vector<float> &SpaceList)//高度排序
{
	std::sort(SpaceList.begin(), SpaceList.end());
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight(float SpaceList[], int SpaceCnt)//高度排序
{		
	//if ( CheckArraySorted(SpaceList, SpaceCnt) == true )
	//{	return true; }
	//return SortSpcaeHeight_QuickSort(SpaceList, SpaceCnt);
	//return SortSpcaeHeight_MergeSort(SpaceList, SpaceCnt);
	//return SortSpcaeHeight_Selection(SpaceList, SpaceCnt);		
	//return SortSpcaeHeight_Insertion(SpaceList, SpaceCnt);	
	if ( SpaceCnt > 32 ) 
	{		
		std::vector<float> TempList;		
		TempList.assign(SpaceList, SpaceList+SpaceCnt);
		std::sort(TempList.begin(), TempList.end());		
		::memcpy(SpaceList, TempList.data(), sizeof(float)*SpaceCnt);
		return true;		
	}	
	return SortSpcaeHeight_Insertion(SpaceList, SpaceCnt);		
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight_Insertion(float SpaceList[], int SpaceCnt)//高度排序-插入法
{
	int   i=0,j=0;
	float key=0.0f;	
	for (i=1; i <SpaceCnt; i++) 
	{
		j = i-1;
		key = SpaceList[i];		
		while (key<SpaceList[j] && j>=0) 
		{
			SpaceList[j+1] = SpaceList[j];
			j--;
		}
		SpaceList[j+1] = key;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight_Selection(float SpaceList[], int SpaceCnt)//高度排序
{	
	int idx=0;	
	int i=0, j=0;	
	float Min=0.0f;
	float Temp=0.0f;
	//選擇排序法	
	for ( i=0; i<SpaceCnt-1; i++ )
	{	
		idx = GetMinValueIndex(SpaceList, i, SpaceCnt);//沒有問題, 但為了與Cuda一致化, 所以變更
		/*
		idx = i;		
		for ( j=i+1; j<SpaceCnt; j++ )
		{
			if ( SpaceList[idx] > SpaceList[j] )
			{	idx = j;	}
		}*/
		Temp = SpaceList[i];
		SpaceList[i] = SpaceList[idx];
		SpaceList[idx] = Temp;		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
void CImageAPI::QuickSort_Swap(float &a, float &b)
{
	float tmp = a;
	a = b;
	b = tmp;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::QuickSort_Partition(float array[], int front, int end)//快速排序-分割
{	
	int   i = front-1;	
	float Pivot = array[end];    
    for (int j=front; j<end; j++)
	{
        if (array[j] < Pivot)
		{
            i++;
            QuickSort_Swap(array[i], array[j]);
        }
    }
    i++;
    QuickSort_Swap(array[i], array[end]);
    return i;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::QuickSort_Recursion(float array[], int front, int end)//快速排序-分割
{
	if (front < end) 
	{
        int Pivot = QuickSort_Partition(array, front, end);
        QuickSort_Recursion(array, front, Pivot-1);
        QuickSort_Recursion(array, Pivot+1, end);
    }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::QuickSort_Iterative(float array[], int front, int end)//快速排序-疊代
{
	int h = end;
	int l = front;
	const int Size = h-l + 1;
	const int MaxSize = MULTI_CAST_PATCH_MAX_COUNT;
	if ( Size > MaxSize )
	{	return false; }

	// Create an auxiliary stack 
    int stack[MaxSize]; 
  
    // initialize top of stack 
    int top = -1; 
  
    // push initial values of l and h to stack 
    stack[++top] = l; 
    stack[++top] = h; 
  
    // Keep popping from stack while is not empty 
    while (top >= 0) 
	{ 
        // Pop h and l 
        h = stack[top--]; 
        l = stack[top--]; 
  
        // Set pivot element at its correct position 
        // in sorted array 
        int p = QuickSort_Partition(array, l, h); 
  
        // If there are elements on left side of pivot, 
        // then push left side to stack 
        if ( (p-1) > l)
		{ 
            stack[++top] = l; 
            stack[++top] = p - 1; 
        } 

        // If there are elements on right side of pivot, 
        // then push right side to stack 
        if ( (p+1) < h) 
		{ 
            stack[++top] = p + 1; 
            stack[++top] = h; 
        } 
    } ;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight_QuickSort(float SpaceList[], int SpaceCnt)//高度排序-快速排序
{
	//return QuickSort_Recursion(SpaceList, 0, SpaceCnt-1);	
	return QuickSort_Iterative(SpaceList, 0, SpaceCnt-1);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeSort_Merge(float array[], int front, int mid, int end)//合併排序-合併
{
	// 利用 std::vector 的constructor, 
    // 把array[front]~array[mid]放進 LeftSub[]
    // 把array[mid+1]~array[end]放進 RightSub[]
	const int LeftSize =mid-front+1;
	const int RightSize=end-mid;
	const int MaxSize = MULTI_CAST_PATCH_MAX_COUNT;
	if ( (LeftSize+1)>MaxSize || (RightSize+1)>MaxSize )
	{	return false; }

	int   i=0;
    float LeftSub[MaxSize];
	float RightSub[MaxSize];
	for ( i=0; i<LeftSize; i++ )
	{	LeftSub[i] = array[front+i]; }
	for ( i=0; i<RightSize; i++ )
	{	RightSub[i] = array[mid+1+i]; }	
	LeftSub[LeftSize] = FLT_MAX;// 在LeftSub[]尾端加入值為 Max 的元素
	RightSub[RightSize] = FLT_MAX;// 在RightSub[]尾端加入值為 Max 的元素

    int idxLeft = 0, idxRight = 0;
    for (i=front; i<=end; i++) 
	{
        if (LeftSub[idxLeft] <= RightSub[idxRight] ) 
		{
            array[i] = LeftSub[idxLeft];
            idxLeft++;
        }
        else
		{
            array[i] = RightSub[idxRight];
            idxRight++;
        }
    }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeSort_Recursion(float array[], int front, int end)//合併排序-遞迴
{
	if (front < end)  // 表示目前的矩陣範圍是有效的
	{                   
        int mid = (front+end)/2;         // mid即是將矩陣對半分的index
		if ( MergeSort_Recursion(array, front, mid) == false )// 繼續divide矩陣的前半段subarray
		{	return false; }        
        if ( MergeSort_Recursion(array, mid+1, end) == false ) // 繼續divide矩陣的後半段subarray
		{	return false; }
        if ( MergeSort_Merge(array, front, mid, end) == false )// 將兩個subarray做比較, 並合併出排序後的矩陣
		{	return false; }
    }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeSort_Iterative(float array[], int count)//合併排序-疊代
{
	int curr_size;  // For current size of subarrays to be merged 
                   // curr_size varies from 1 to n/2 
	int left_start; // For picking starting index of left subarray 
                   // to be merged 
  
   // Merge subarrays in bottom up manner.  First merge subarrays of 
   // size 1 to create sorted subarrays of size 2, then merge subarrays 
   // of size 2 to create sorted subarrays of size 4, and so on. 
   for (curr_size=1; curr_size<=count-1; curr_size = 2*curr_size) 
   { 
       // Pick starting point of different subarrays of current size 
       for (left_start=0; left_start<count-1; left_start += 2*curr_size) 
       { 
           // Find ending point of left subarray. mid+1 is starting  
           // point of right 
           int mid = MIN(left_start + curr_size - 1, count-1); 
  
           int right_end = MIN(left_start + 2*curr_size - 1, count-1); 
  
           // Merge Subarrays arr[left_start...mid] & arr[mid+1...right_end] 
           if ( MergeSort_Merge(array, left_start, mid, right_end) == false )
		   {	return false; }
       } 
   } 
   return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SortSpcaeHeight_MergeSort(float SpaceList[], int SpaceCnt)//高度排序-合併排序
{
	//return MergeSort_Recursion(SpaceList, 0, SpaceCnt-1);
	return MergeSort_Iterative(SpaceList, SpaceCnt);
	return true;
}
//-------------------------------------------------------------------------------------//
float CImageAPI::AverageSpaceHeight(const float SpaceList[],int SpaceCnt)//平均高度
{
	if ( 0 == SpaceCnt ) { return 0.0f; }
	int i=0;
	float Ave=0.0f;	
	for ( i=0; i<SpaceCnt; i++ )
	{	Ave += SpaceList[i];	}
	Ave /= SpaceCnt;
	return Ave;
}
//-------------------------------------------------------------------------------------//
float CImageAPI::AverageSpaceHeight(const std::vector<float> &SpaceList)//平均高度
{
	const int SpaceCnt=(int)(SpaceList.size());
	if ( 0 == SpaceCnt ) { return 0.0f; }
	int i=0;
	float Ave=0.0f;	
	for ( i=0; i<SpaceCnt; i++ )
	{	Ave += SpaceList[i];	}
	Ave /= SpaceCnt;
	return Ave;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GeometryMedianSpaceHeight(const float SpaceList[], int SpaceCnt, float ZeroPlane, float &Space)//幾何中值法
{
	int   i=0;
	int   IterCnt=0;
	float SpaceCur=0;
	float SpaceNxt=0;
	float SpaceAve=0;	
	float SpaceErr=0;	
	const int MaxIterCnt=10;
	float SpaceErrList[MaxIterCnt+1];
	float SpaceResList[MaxIterCnt+1];
	
	if ( 0 == SpaceCnt )
	{
		Space = 0.0f;
		return true;
	}
	if ( 1 == SpaceCnt )
	{
		Space = SpaceList[0];
		return true;
	}
	for ( i=0; i<=MaxIterCnt; i++ )
	{	
		SpaceResList[i] = 0.0; 
		SpaceErrList[i] = FLT_MAX;
	}
	for ( i=0; i<SpaceCnt; i++ )
	{
		SpaceAve += SpaceList[i]; 		
	}
	SpaceAve /= SpaceCnt;
	SpaceResList[0] = SpaceNxt = SpaceCur = SpaceAve;
	SpaceResList[0] = SpaceNxt = SpaceCur = ZeroPlane;//ZeroPlane;
	while ( true )
	{
		if ( GeometryMedianSpaceHeightKernel(SpaceList, SpaceCnt, SpaceNxt) == false )
		{	return false;  }
		SpaceErr =  SpaceNxt-SpaceCur;
		if ( SpaceErr < 0 ) { SpaceErr=-SpaceErr; }
		if ( SpaceErr < 10.001f ) 
		{	break; }
		IterCnt ++;
		if ( IterCnt > MaxIterCnt ) 
		{	break; }
		SpaceErrList[IterCnt] = SpaceErr;
		SpaceResList[IterCnt] = SpaceCur = SpaceNxt;
	};

	if ( IterCnt > MaxIterCnt ) 
	{
		float MinErr=FLT_MAX;
		SpaceNxt = SpaceResList[0];
		for ( i=1; i<MaxIterCnt; i++ )
		{
			if ( MinErr > SpaceErrList[i] ) 
			{
				MinErr = SpaceErrList[i];
				SpaceNxt = SpaceResList[i];
			}
		}		
	}
	Space = SpaceNxt;	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GeometryMedianSpaceHeightKernel(const float SpaceList[], int SpaceCnt, float &Space)//幾何中值法
{
	int   i=0;
	float A=0, B=0;
	float Len=0;
	float Len2=0;
	float SumA=0;
	float SumB=0;
	for ( i=0; i<SpaceCnt; i++ )
	{
		Len = (SpaceList[i]-Space);		
		Len2 = Len*Len; 
		if ( Len2 < 0.0001 ) //剛好落於本身點上
		{	continue; }

		A = SpaceList[i]/Len2;
		B = 1.0f/Len2;
		SumA += A;
		SumB += B;
	}
	Space = SumA/SumB;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GroupSpcaeHeightByMean(const float SpaceList[], float Range, float GroupAveList[], int GroupCntList[], int SpaceCnt, int &GoupCount)//多高度分群	
{
	int i=0, j=0;
	GoupCount = 0;
	if ( 0 == SpaceCnt ) { return false; }
	for ( i=0; i<SpaceCnt; i++ )
	{
		for ( j=0; j<GoupCount; j++ )
		{
			if ( AddGroupSpcaeHeightByMean(SpaceList[i], Range, GroupAveList[j], GroupCntList[j]) == true ) 
			{	break; }
		}
		if ( j == GoupCount ) 
		{
			GroupAveList[GoupCount] = SpaceList[i];
			GroupCntList[GoupCount] = 1;
			GoupCount ++ ;
		}
	}
	return true;
}
