double CImageAPI::AdjustRotateAngle(double Angle)//調整旋轉角度
{
	double dAngle = ::fmod(Angle, 360.0);//角度, 注意回傳區間為-360 ~ 360
	if ( dAngle < 0.0 ) { dAngle += 360.0; }
	return dAngle; 
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildRGBVTable()//建立RGBV表
{
	DeleteRGBVTable();
	const size_t RGBSize = 256*256*256;	
	m_RGBToRedTable = new unsigned char[RGBSize];	
	if ( this->m_RGBToRedTable == NULL )
	{
		this->m_ErrorString.Format(_T("Error, Build RGBV Table Fault"));
		return false; 
	}	

	const double IF=208.3;
	const double sqrt_6=::sqrt(6.0);
	const double sqrt_2=::sqrt(2.0);

	int    step = 1;
	int    R=0, G=0, B=0;	
	double r=0, g=0, b=0;
	double ir=0, ig=0, ib=0, ii=0;
	double vr=0;
	int   VR=0;

	::memset(m_RGBToRedTable, 0x00, sizeof(unsigned char)*RGBSize);	
	for ( R=0; R<256; R+=step )
	{		
		for ( G=0; G<256; G+=step )
		{
			for ( B=0; B<256; B+=step )
			{		
				if ( R!=0 || G!=0 || B!=0 )
				{
					r = R;
					g = G;
					b = B;

					r = r/255.0;
					g = g/255.0;
					b = b/255.0;

					ii = r+g+b;
					ir = r/ii;
					ig = g/ii;
					ib = b/ii;

					vr = (2*ir)-ig-ib;
					vr = vr/sqrt_6;

					VR = (int)(vr*IF+85);

					if ( VR > 255 )
					{
						VR = VR;
					}
					if ( VR < 0 ) 
					{
						VR = VR;
					}
				}
				else
				{
					VR = 0+85;
				}				
				if ( VR > 255 ) { VR = 255; }
				else if ( VR < 0 ) { VR = 0; }
				m_RGBToRedTable[R*256*256+G*256+B] = (unsigned char)(VR);
			}
		}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DeleteRGBVTable()//刪除RGBV表
{
	if ( NULL == m_RGBToRedTable ) { return true; }
	delete[] m_RGBToRedTable;
	m_RGBToRedTable=NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildArctangentTable()//建立arctangent表-加速用
{	
	int i=0, j=0, idx=0;
	long double a=0, b=0, c=0;	
	const int RangeX = ARCTANGENT_TABLE_COL;
	const int RangeY = ARCTANGENT_TABLE_ROW;
	const int RangeX2 = ARCTANGENT_TABLE_COL2;
	const int RangeY2 = ARCTANGENT_TABLE_ROW2;
	const int RangeSize = ARCTANGENT_TABLE_SIZE;
	const double PeriodRad = PERIOD_RAD;
	const double Phase_Rad2Short = PHASE_RAD2SHORT;

	DeleteArctangentTable();
	this->m_pArctanTable = new PHASE_DATA[RangeSize];
	if ( NULL == this->m_pArctanTable )
	{
		this->m_ErrorString.Format(_T("Error, Create Arctangent Table Fault"));
		return false; 
	}

	idx = 0;
	double MaxC = -DBL_MAX;
	double MinC =  DBL_MAX;
	for ( i=0; i<RangeX; i++ )
	{
		a = i-RangeX2;
		for ( j=0; j<RangeY; j++ )
		{
			b = j-RangeY2;
			c = ::atan2(a, b);
			if ( c < 0 )
			{	c = c+PERIOD_RAD; }
			c = c*PHASE_RAD2SHORT;
			if ( MaxC < c ) { MaxC = c; }
			if ( MinC > c ) { MinC = c; }
			m_pArctanTable[idx] = static_cast<PHASE_DATA>(c);
			idx++;
		}
	}
	int aaa = static_cast<PHASE_DATA>(MaxC);
	int bbb = static_cast<PHASE_DATA>(MinC);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DeleteArctangentTable()//刪除arctangent表-加速用	
{
	if ( NULL == m_pArctanTable ) { return true; }
	delete[] m_pArctanTable; 
	m_pArctanTable = NULL;
	return true;	
}
//-------------------------------------------------------------------------------------//
unsigned char* CImageAPI::BuildLocalGammaTable(float ScaleVal)//建立局部Gamma的表格
{	
	const char fnName[] = "CImageAPI::BuildLocalGammaTable";
	int   u=0, v=0;
	const int LutWH=256;
	const int LutSize=LutWH*LutWH;
	float BacVal = 0.0f;
	float TmpVal = 0.0f;
	float GamVal = 0.0f;
	float ResVal = 0.0f;	
	float Gamma=1.0f/ScaleVal;
	unsigned char *LutPtr=NULL;
	if ( JetMemory.alloc_func(LutSize, LutPtr, fnName, "LutPtr") == false )
	{	return NULL; }
	//255*pow(Y/255.0, pow(2, (128-(255-Mask))/128.0f), 以下是建表
	for ( u=0; u<LutWH; u++ )//for Y Loop
	{
		for ( v=0; v<LutWH; v++ )//For Mask Loop
		{
			BacVal = u/255.0f;
			TmpVal = (128-(255-v))/128.0f;
			GamVal = pow(2.0f, TmpVal);//Gamma
			GamVal *= Gamma;//Gamma
			ResVal = 255.0f*pow(BacVal, GamVal);
			if ( ResVal < 0 ) { ResVal = 0.0f; }
			else if ( ResVal > 255.0f ) { ResVal = 255.0f; }
			LutPtr[u*LutWH+v] = (unsigned char)(ResVal);//Y*256 + Mask
		}
	}
	return LutPtr;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildGainOffsetTable(double Offset, double Gain, int nTable, unsigned char *Table)
{
	if ( NULL == Table )
	{	return false; }

	int    i=0;
	double val=0.0;
	for ( i=0; i<nTable; i++ )
	{
		//val = (i*Gain)-Offset;		
		val = (i-Offset)*Gain;
		if ( val < 0 ) 
		{	Table[i] = 0; }
		else if ( val > 255 )
		{	Table[i] = 255; }
		else
		{	Table[i] = (unsigned char)(val);	}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcArctangent(int y, int x, PHASE_DATA &val)//利用查表來取得atan
{	
//	if ( NULL == m_pArctanTable )
//	{
//		this->m_ErrorString.Format(_T("Error, Not Arctangent Table"));
//		return false;
//	}
	/*
	if ( y<=-ARCTANGENT_TABLE_ROW2 || y>=ARCTANGENT_TABLE_ROW2 || x<=-ARCTANGENT_TABLE_COL2 || x>=ARCTANGENT_TABLE_COL2 )
	{
		this->m_ErrorString.Format(_T("Error, Value Out of Arctangent Table Range (%d ~ %d)"), -ARCTANGENT_TABLE_COL2, ARCTANGENT_TABLE_COL2);
		return false; 
	}*/
	int idx = (y+ARCTANGENT_TABLE_ROW2)*ARCTANGENT_TABLE_COL+(x+ARCTANGENT_TABLE_COL2);	
	//int idx = (x+ARCTANGENT_TABLE_ROW2)*ARCTANGENT_TABLE_COL+(y+ARCTANGENT_TABLE_COL2);	
	if ( idx >= ARCTANGENT_TABLE_SIZE ) 
	{
		this->m_ErrorString.Format(_T("Error, Index Out of Arctangent Table Range (%d//%d)"), idx, ARCTANGENT_TABLE_SIZE);
		return false; 
	}
	val = this->m_pArctanTable[idx];
	return true;
}
//-------------------------------------------------------------------------------------//
double CImageAPI::Calc2PhaseNewPeriode(double P1, double P2)//計算新週期
{
	return P1*P2/fabs(P2-P1);
}
//-------------------------------------------------------------------------------------//
double CImageAPI::CalcBestPeriode3(double P1, double P2, double P3)//計算最好的新週期
{	
	const double P12 = this->Calc2PhaseNewPeriode(P1, P2);
	const double P23 = this->Calc2PhaseNewPeriode(P2, P3);
	const double P31 = this->Calc2PhaseNewPeriode(P3, P1);
	const double P12_23 = this->Calc2PhaseNewPeriode(P12, P23);
	const double P23_31 = this->Calc2PhaseNewPeriode(P23, P31);
	const double P31_12 = this->Calc2PhaseNewPeriode(P31, P12);

	double P = __max(P12_23, P23_31);
	P = __max(P, P31_12);
	return P;
}
