//-------------------------------------------------------------------------------------//
bool CImageAPI::CreateBMPInfoBuffer(BITMAPINFO *&pBMPInfo, size_t &BufferSize)//建立BMP的資訊檔案	
{	
	unsigned char *BufferPtr=NULL;	
	delete[] pBMPInfo; pBMPInfo=NULL;
	BufferSize = sizeof(BITMAPINFO)+255*sizeof(RGBQUAD);
	BufferPtr = new unsigned char[BufferSize];		
	if ( NULL == BufferPtr ) 
	{	
		this->m_ErrorString.Format(_T("Error, Memory Allocate Fault"));	
		return false;	
	}
	::memset(BufferPtr, 0x00, sizeof(unsigned char)*BufferSize);
	pBMPInfo = (BITMAPINFO*)(BufferPtr);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SetBMPInfo(BITMAPINFO *pBMPInfo, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE BitCount)//建立BMP的資訊檔案
{
	int      i=0; 
	DWORD    bitmapInfoSize=0;	
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);
	if ( NULL == pBMPInfo ) 
	{	
		m_ErrorString.Format(_T("Error, pBMPInfo is NULL"));	
		return false;	
	}

	switch ( BitCount )
	{
	case 24:
		bitmapInfoSize = sizeof(BITMAPINFO);

		pBMPInfo->bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
		pBMPInfo->bmiHeader.biPlanes = 1;
		pBMPInfo->bmiHeader.biBitCount = 24;
		pBMPInfo->bmiHeader.biCompression = BI_RGB;
		pBMPInfo->bmiHeader.biSizeImage = ImageW*ImageH;
		pBMPInfo->bmiHeader.biXPelsPerMeter = 0;
		pBMPInfo->bmiHeader.biYPelsPerMeter = 0;
		pBMPInfo->bmiHeader.biClrUsed = 0;
		pBMPInfo->bmiHeader.biClrImportant = 0;

		pBMPInfo->bmiHeader.biWidth = nImageW;
		pBMPInfo->bmiHeader.biHeight = -nImageH;
		break;
	case 8:
		bitmapInfoSize = sizeof(BITMAPINFO) + 255*sizeof(RGBQUAD);

		pBMPInfo->bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
		pBMPInfo->bmiHeader.biPlanes = 1;
		pBMPInfo->bmiHeader.biBitCount = 8;
		pBMPInfo->bmiHeader.biCompression = BI_RGB;
		pBMPInfo->bmiHeader.biSizeImage = ImageW*ImageH;
		pBMPInfo->bmiHeader.biXPelsPerMeter = 0;
		pBMPInfo->bmiHeader.biYPelsPerMeter = 0;
		pBMPInfo->bmiHeader.biClrUsed = 0;
		pBMPInfo->bmiHeader.biClrImportant = 0;

		pBMPInfo->bmiHeader.biWidth = nImageW;
		pBMPInfo->bmiHeader.biHeight = -nImageH;

		for ( i=0; i<256; i++ )
		{
			pBMPInfo->bmiColors[i].rgbRed      = i;
			pBMPInfo->bmiColors[i].rgbGreen    = i;
			pBMPInfo->bmiColors[i].rgbBlue     = i;
			pBMPInfo->bmiColors[i].rgbReserved = 0;
		}
		break;
	default:
		break;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CreateBMPInfo(BITMAPINFO *&pBMPInfo, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE BitCount)//建立BMP的資訊檔案
{
	DWORD    bitmapInfoSize=0;	
	unsigned char *BufferPtr=NULL;
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);
	delete[] pBMPInfo; pBMPInfo=NULL;
	switch ( BitCount )
	{
	case 24:	bitmapInfoSize = sizeof(BITMAPINFO);						break;
	case 8:		bitmapInfoSize = sizeof(BITMAPINFO)+255*sizeof(RGBQUAD);	break;
	default:
		break;
	}
	BufferPtr = new unsigned char[bitmapInfoSize];		
	if ( NULL == BufferPtr ) 
	{	
		this->m_ErrorString.Format(_T("Error, Memory Allocate Fault"));	
		return false;	
	}
	::memset(BufferPtr, 0x00, sizeof(unsigned char)*bitmapInfoSize);
	pBMPInfo = (BITMAPINFO*)(BufferPtr);
	return SetBMPInfo(pBMPInfo, ImageW, ImageH, BitCount);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcImageWndZoom(double OldZoom, double NewZoom, TPOINT2D &OffsetPt)//計算影像視窗縮放參數
{
	if ( fabs(OldZoom)<0.0001 || fabs(NewZoom)<0.0001 )
	{	return false; }
	OffsetPt.x *= OldZoom;
	OffsetPt.y *= OldZoom;
	OffsetPt.x /= NewZoom;
	OffsetPt.y /= NewZoom;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcImageWndFitZoom(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const RECT &WndRect, const double Ratio, double &Zoom)//計算影像視窗縮放參數
{
	if ( ImageW<=0 || ImageH<=0 ) { return false; }
	double WndW = WndRect.right-WndRect.left;
	double WndH = WndRect.bottom-WndRect.top;
	double ScaleX = WndW/ImageW;
	double ScaleY = WndH/ImageH;

	size_t NewWndW = (size_t)(ImageW*ScaleY);
	size_t NewWndH = (size_t)(ImageH*ScaleX);
	if ( NewWndW > WndW )
	{	Zoom = 1/ScaleX;	}
	else
	{	Zoom = 1/ScaleY;	}

	double AdjustZ = 1.0;

	if ( ::fabs(Ratio-1.0) < 0.00001 )
	{	return true;	}

	Zoom = Zoom*Ratio;
	return true;
	if ( Zoom >= 1 )
	//if ( Ratio >= 1.0 )
	{
		while ( true )
		{
			AdjustZ *= Ratio;
			if ( AdjustZ >= Zoom )
			{
				Zoom = AdjustZ;
				break;
			}
		};
	}
	else
	{
		while ( true )
		{			
			AdjustZ /= Ratio;
			//AdjustZ *= Ratio;
			if ( AdjustZ <= Zoom )
			{
				Zoom = AdjustZ;
				break;
			}
		};
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawImageToDC(HDC hDC, const BITMAPINFO *pImageInfo, const unsigned char *pImage, const RECT &ImageWndRect, const TPOINT2D &OffsetPt2D, double ZoomScale, COLORREF clrBK)
{
	const int BltMode = AOIDataCollect.GetSystemParameter().m_StretchBltMode;
	return DrawImageToDC(hDC, pImageInfo, pImage, ImageWndRect, OffsetPt2D, ZoomScale, clrBK, BltMode);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawImageToDC(HDC hDC, const BITMAPINFO *pImageInfo, const unsigned char *pImage, const RECT &ImageWndRect, const TPOINT2D &OffsetPt2D, double ZoomScale, COLORREF clrBK, int BltMode)
{	
	if ( NULL == pImage ) { return false; }	
	if ( NULL == pImageInfo ) { return false; }	

	POINT OffsetPt={0};
	OffsetPt.x = JetAPI::Round(OffsetPt2D.x*ZoomScale);
	OffsetPt.y = JetAPI::Round(OffsetPt2D.y*ZoomScale);
	const double sizeX = (ImageWndRect.right-ImageWndRect.left)/2.0;
	const double sizeY = (ImageWndRect.bottom-ImageWndRect.top)/2.0;

	const int nImageW = abs(pImageInfo->bmiHeader.biWidth);
	const int nImageH = abs(pImageInfo->bmiHeader.biHeight);
	const int ImageFullW = nImageW;
	const int ImageFullH = nImageH;
	const int ImageHalfW = ImageFullW/2;
	const int ImageHalfH = ImageFullH/2;
	
	POINT WndCp;
	RECT SrcRect={0};	
	WndCp.x = (ImageWndRect.left+ImageWndRect.right)/2;
	WndCp.y = (ImageWndRect.top+ImageWndRect.bottom)/2;		
	//if ( BltMode != HALFTONE )
	{
		HBRUSH hBrush = ::CreateSolidBrush(clrBK);
		if ( hBrush != NULL )
		{
			::FillRect(hDC, &ImageWndRect, hBrush);
			::DeleteObject(hBrush); hBrush=NULL;
		}
	}
	if ( ZoomScale < 0   )
	{
		SrcRect.left   = (long)0;
		SrcRect.top    = (long)0;
		SrcRect.right  = (long)ImageFullW;
		SrcRect.bottom = (long)ImageFullH;		
		int OldMode = ::SetStretchBltMode(hDC, BltMode);		//m_pBinaryImage
		int FrameW =  ImageWndRect.right-ImageWndRect.left;
		int FrameH = ImageWndRect.bottom-ImageWndRect.top;

		double ScaleX = (double)FrameW/(double)ImageFullW;
		double ScaleY = (double)FrameH/(double)ImageFullH;
		double TempScale = (ScaleX>ScaleY)?ScaleY:ScaleX;

		int ImageW = (int)(ImageFullW*TempScale);		
		int ImageH = (int)(ImageFullH*TempScale);

		RECT DstRect = ImageWndRect;			
		DstRect.right = DstRect.left+ImageW;
		DstRect.bottom = DstRect.top+ImageH;
		::StretchDIBits (
			hDC,	// handle of device context
			DstRect.left,	// x-coordinate of upper-left corner of dest. rect. 
			DstRect.top,	// y-coordinate of upper-left corner of dest. rect. 
			DstRect.right,	// width of destination rectangle 
			DstRect.bottom,	// height of destination rectangle 
			SrcRect.left,	// x-coordinate of lower-left corner of source rect. 
			SrcRect.top,	// y-coordinate of lower-left corner of source rect. 
			SrcRect.right,	// source rectangle width 
			SrcRect.bottom,	// source rectangle height 
			pImage,	// address of array with DIB bits 
			pImageInfo,	// address of structure with bitmap info. 
			DIB_RGB_COLORS,	// RGB or palette indices 
			SRCCOPY		// raster operation code
		);
		::SetStretchBltMode(hDC, OldMode);
	}
	else
	{		
		POINT SP;
		SIZE size;
		int OldMode = ::SetStretchBltMode(hDC, BltMode);		//m_pBinaryImage
		/*
		size.cx =  ImageWndRect.right-ImageWndRect.left;
		size.cy = ImageWndRect.bottom-ImageWndRect.top;		
		size.cx = (long)(size.cx*ZoomScale);
		size.cy = (long)(size.cy*ZoomScale);		
		SP.x = ImageHalfW-OffsetPt.x-size.cx/2;		
		SP.y = ImageHalfH+OffsetPt.y-size.cy/2;
		::StretchDIBits (
			hDC,	// handle of device context
			ImageWndRect.left,	// x-coordinate of upper-left corner of dest. rect. 
			ImageWndRect.top,	// y-coordinate of upper-left corner of dest. rect. 
			ImageWndRect.right,	// width of destination rectangle 
			ImageWndRect.bottom,	// height of destination rectangle 
			SP.x,	// x-coordinate of lower-left corner of source rect. 
			SP.y,	// y-coordinate of lower-left corner of source rect. 
			size.cx,	// source rectangle width 
			size.cy,	// source rectangle height 
			pImage,	// address of array with DIB bits 
			pImageInfo,	// address of structure with bitmap info. 
			DIB_RGB_COLORS,	// RGB or palette indices 
			SRCCOPY		// raster operation code
		);
		*/
		RECT DstRect;		
		const int ResultW = (int)(nImageW/ZoomScale);
		const int ResultH = (int)(nImageH/ZoomScale);
		const int OffsetX = JetAPI::Round(OffsetPt2D.x);
		const int OffsetY = JetAPI::Round(OffsetPt2D.y);
		DstRect.left = WndCp.x-(ResultW/2)+OffsetX;		
		DstRect.top  = WndCp.y-(ResultH/2)+OffsetY;
		DstRect.right = ResultW;
		DstRect.bottom = ResultH;

		SP.x = 0;		
		SP.y = 0;
		size.cx = ImageFullW;
		size.cy = ImageFullH;
		::StretchDIBits (
			hDC,	// handle of device context
			DstRect.left,	// x-coordinate of upper-left corner of dest. rect. 
			DstRect.top,	// y-coordinate of upper-left corner of dest. rect. 
			DstRect.right,	// width of destination rectangle 
			DstRect.bottom,	// height of destination rectangle 
			SP.x,	// x-coordinate of lower-left corner of source rect. 
			SP.y,	// y-coordinate of lower-left corner of source rect. 
			size.cx,	// source rectangle width 
			size.cy,	// source rectangle height 
			pImage,	// address of array with DIB bits 
			pImageInfo,	// address of structure with bitmap info. 
			DIB_RGB_COLORS,	// RGB or palette indices 
			SRCCOPY		// raster operation code
		);
		::SetStretchBltMode(hDC, OldMode);	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawImageToDC(HDC hDC, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const RECT &ImageWndRect, const TPOINT2D &OffsetPt2D, double ZoomScale, COLORREF clrBK)
{
	if ( (ImageW<=0) || (ImageH<=0) ) { return false; }
	if ( NULL == pImage ) { return false; }	

	BITMAPINFO *pImageInfo = NULL;

	if ( this->CreateBMPInfo(pImageInfo, ImageW, ImageH, BitCount) == false )
	{	return false; }

	const bool bIsOK =DrawImageToDC(hDC, pImageInfo, pImage, ImageWndRect, OffsetPt2D, ZoomScale, clrBK);	
	delete[] pImageInfo; pImageInfo=NULL;	
	return bIsOK;
}
//-------------------------------------------------------------------------------------//
bool  CImageAPI::DrawImageToDC(HDC hDC, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const RECT &ImageWndRect, const TPOINT2D &OffsetPt2D, double ZoomScale, COLORREF clrBK, int BltMode)
{
	if ( (ImageW<=0) || (ImageH<=0) ) { return false; }
	if ( NULL == pImage ) { return false; }	

	BITMAPINFO *pImageInfo = NULL;

	if ( this->CreateBMPInfo(pImageInfo, ImageW, ImageH, BitCount) == false )
	{	return false; }

	const bool bIsOK =DrawImageToDC(hDC, pImageInfo, pImage, ImageWndRect, OffsetPt2D, ZoomScale, clrBK, BltMode);	
	delete[] pImageInfo; pImageInfo=NULL;	
	return bIsOK;
}
