bool CImageAPI::MapWndPtToImagePt_INT(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const RECT &WndRect, const POINT &OffsetPt, double ZoomScale, const POINT &WndPt, POINT &ImagePt)
{	
	const int ImageW2 = (int)(ImageW/2);
	const int ImageH2 = (int)(ImageH/2);
	const int WndCPX = (WndRect.right+WndRect.left)/2;
	const int WndCPY = (WndRect.top+WndRect.bottom)/2;
	if ( ZoomScale < 0 ) 
	{
		ImagePt.x = WndPt.x + OffsetPt.x;
		ImagePt.y = WndPt.y + OffsetPt.y;
	}
	else
	{		
		//四捨五入使用round
		//ImagePt.x = this->Round((WndPt.x-WndCPX)*ZoomScale-OffsetPt.x+ImageW2);
		//ImagePt.y = this->Round((WndPt.y-WndCPY)*ZoomScale-OffsetPt.y+ImageH2);

		ImagePt.x = Round((WndPt.x-WndCPX-OffsetPt.x)*ZoomScale+ImageW2);
		ImagePt.y = Round((WndPt.y-WndCPY-OffsetPt.y)*ZoomScale+ImageH2);
	}
	return true;
}
