bool CImageAPI::MapImageCornerPtToWndCornerPt_INT(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const RECT &WndRect, const POINT &OffsetPt, double ZoomScale, const POINT ImagePt[], POINT WndPt[])
{
	const int ImageW2 = (int)(ImageW/2);
	const int ImageH2 = (int)(ImageH/2);
	const int WndCPX = (WndRect.right+WndRect.left)/2;
	const int WndCPY = (WndRect.top+WndRect.bottom)/2;
	if ( ZoomScale < 0 ) 
	{
		WndPt[0].x    = ImagePt[0].x - OffsetPt.x;
		WndPt[0].y    = ImagePt[0].y - OffsetPt.y;		
		WndPt[1].x    = ImagePt[1].x - OffsetPt.x;
		WndPt[1].y    = ImagePt[1].y - OffsetPt.y;
		WndPt[2].x    = ImagePt[2].x - OffsetPt.x;
		WndPt[2].y    = ImagePt[2].y - OffsetPt.y;
		WndPt[3].x    = ImagePt[3].x - OffsetPt.x;
		WndPt[3].y    = ImagePt[3].y - OffsetPt.y;
	}
	else
	{		
		//四捨五入使用round
		/*
		WndRc.left   = Round((ImageRc.left-WndCPX)*ZoomScale-OffsetPt.x+ImageW2);
		WndRc.top    = Round((ImageRc.top-WndCPY)*ZoomScale-OffsetPt.y+ImageH2);
		WndRc.right  = Round((ImageRc.right-WndCPX)*ZoomScale-OffsetPt.x+ImageW2);
		WndRc.bottom = Round((ImageRc.bottom-WndCPY)*ZoomScale-OffsetPt.y+ImageH2);
		*/
		WndPt[0].x   = Round((WndCPX+((ImagePt[0].x-ImageW2)/ZoomScale)+OffsetPt.x));
		WndPt[0].y   = Round((WndCPY+((ImagePt[0].y-ImageH2)/ZoomScale)+OffsetPt.y));
		WndPt[1].x   = Round((WndCPX+((ImagePt[1].x-ImageW2)/ZoomScale)+OffsetPt.x));
		WndPt[1].y   = Round((WndCPY+((ImagePt[1].y-ImageH2)/ZoomScale)+OffsetPt.y));
		WndPt[2].x   = Round((WndCPX+((ImagePt[2].x-ImageW2)/ZoomScale)+OffsetPt.x));
		WndPt[2].y   = Round((WndCPY+((ImagePt[2].y-ImageH2)/ZoomScale)+OffsetPt.y));
		WndPt[3].x   = Round((WndCPX+((ImagePt[3].x-ImageW2)/ZoomScale)+OffsetPt.x));
		WndPt[3].y   = Round((WndCPY+((ImagePt[3].y-ImageH2)/ZoomScale)+OffsetPt.y));		
	}
	return true;
}
