//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawRectLine(HDC hDC, const RECT &Rect)//繪製矩形線段
{
	::MoveToEx(hDC, Rect.left, Rect.top, NULL);
	::LineTo(hDC, Rect.right, Rect.top);
	::LineTo(hDC, Rect.right, Rect.bottom);
	::LineTo(hDC, Rect.left, Rect.bottom);
	::LineTo(hDC, Rect.left, Rect.top);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawRectLine(HDC hDC, const POINT &pt1, const POINT &pt2)//繪製矩形線段		
{
	RECT Rect;
	Rect.left   = MIN(pt1.x, pt2.x);
	Rect.top    = MIN(pt1.y, pt2.y);
	Rect.right  = MAX(pt1.x, pt2.x);
	Rect.bottom = MAX(pt1.y, pt2.y);
	return DrawRectLine(hDC, Rect);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawRectLine(HDC hDC, const POINT &pt, int HalfW, int HalfH)//繪製矩形線段	
{
	::MoveToEx(hDC, pt.x-HalfW, pt.y-HalfH, NULL);
	::LineTo(hDC, pt.x+HalfW, pt.y-HalfH);
	::LineTo(hDC, pt.x+HalfW, pt.y+HalfH);
	::LineTo(hDC, pt.x-HalfW, pt.y+HalfH);
	::LineTo(hDC, pt.x-HalfW, pt.y-HalfH);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawRectRoughLine(HDC hDC, const RECT &Rect, COLORREF color, int Gap)//繪製矩形粗造線段
{
	bool bDraw=true;
	const int RectW=Rect.right-Rect.left;
	const int RectH=Rect.bottom-Rect.top;
	const int RectX=(Rect.right+Rect.left)/2;
	const int RectY=(Rect.bottom+Rect.top)/2;
	if ( RectW < Gap )
	{
		if ( RectH < Gap )
		{	::SetPixel(hDC, RectX, RectY, color);	}
		else
		{
			::MoveToEx(hDC, RectX, Rect.top, NULL);
			::LineTo(hDC, RectX, Rect.bottom);
		}
	}
	else
	{
		if ( RectH < Gap )
		{
			::MoveToEx(hDC, Rect.left, RectY, NULL);
			::LineTo(hDC, Rect.right, RectY);
		}
		else
		{	bDraw = false;	}
	}
	return bDraw;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawEllipseLine(HDC hDC, const RECT &Rect)//繪製圓形線段		
{
	//::Pie(hDC, Rect.left, Rect.top, Rect.right, Rect.bottom, Rect.left, Rect.top, Rect.left, Rect.top);
	::Arc(hDC, Rect.left, Rect.top, Rect.right, Rect.bottom, Rect.left, Rect.top, Rect.left, Rect.top);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawPolyLine(HDC hDC, POINT *PtList, int NPts)//繪製多邊形
{
	if ( 0 == NPts ) { return false; }
	if ( NULL == PtList ) { return false; }

	if ( 4 == NPts )
	{
		::MoveToEx(hDC, PtList[0].x, PtList[0].y, NULL);
		::LineTo(hDC, PtList[1].x, PtList[1].y);
		::LineTo(hDC, PtList[2].x, PtList[2].y);
		::LineTo(hDC, PtList[3].x, PtList[3].y);
		::LineTo(hDC, PtList[0].x, PtList[0].y);
		return true;
	}
	
	int i=0;
	::MoveToEx(hDC, PtList[0].x, PtList[0].y, NULL);
	for ( i=1; i<NPts; i++ )
	{	::LineTo(hDC, PtList[i].x, PtList[i].y);	}
	::LineTo(hDC, PtList[0].x, PtList[0].y);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawPolyLine(HDC hDC, TPOINT2D *PtList, int NPts)//繪製多邊形
{
	if ( 0 == NPts ) { return false; }
	if ( NULL == PtList ) { return false; }

	POINT pt;
	if ( 4 == NPts )
	{
		pt.x = CImageAPI::Floor(PtList[0].x);
		pt.y = CImageAPI::Floor(PtList[0].y);
		::MoveToEx(hDC, pt.x, pt.y, NULL);
		pt.x = CImageAPI::Floor(PtList[1].x);
		pt.y = CImageAPI::Floor(PtList[1].y);
		::LineTo(hDC, pt.x, pt.y);	
		pt.x = CImageAPI::Floor(PtList[2].x);
		pt.y = CImageAPI::Floor(PtList[2].y);
		::LineTo(hDC, pt.x, pt.y);	
		pt.x = CImageAPI::Floor(PtList[3].x);
		pt.y = CImageAPI::Floor(PtList[3].y);
		::LineTo(hDC, pt.x, pt.y);	
		pt.x = CImageAPI::Floor(PtList[0].x);
		pt.y = CImageAPI::Floor(PtList[0].y);
		::LineTo(hDC, pt.x, pt.y);	
		return true;
	}
	
	int i=0;	
	pt.x = CImageAPI::Floor(PtList[0].x);
	pt.y = CImageAPI::Floor(PtList[0].y);
	::MoveToEx(hDC, pt.x, pt.y, NULL);
	for ( i=1; i<NPts; i++ )
	{	
		pt.x = CImageAPI::Floor(PtList[i].x);
		pt.y = CImageAPI::Floor(PtList[i].y);
		::LineTo(hDC, pt.x, pt.y);	
	}
	pt.x = CImageAPI::Floor(PtList[0].x);
	pt.y = CImageAPI::Floor(PtList[0].y);
	::LineTo(hDC, pt.x, pt.y);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawCrosshair(HDC hDC, const POINT &Pt, const RECT &Rect, COLORREF clr)//繪製十字線
{
	if ( NULL == hDC ) { return false; }
	HPEN hPen=::CreatePen(PS_DOT, 1, clr);
	if ( NULL == hPen ) { return false; }
	HPEN hOldPen = (HPEN)::SelectObject(hDC, hPen);
	::MoveToEx(hDC, Rect.left, Pt.y, NULL);
	::LineTo(hDC, Rect.right, Pt.y);
	::MoveToEx(hDC, Pt.x, Rect.top, NULL);
	::LineTo(hDC, Pt.x, Rect.bottom);
	::SelectObject(hDC, hOldPen);
	::DeleteObject(hPen);	
	return true;
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Round(double val)//四捨五入
{
	return std::round(val);	
#ifndef OPENCV_DISABLE
	return cvRound(val);//有小數誤差
#else
	return (int)(val+0.5);
#endif
}
//-------------------------------------------------------------------------------------//
int CImageAPI::Ceil(double val)//無條件進入(2.1=>3)
{
	return std::ceil(val);
#ifndef OPENCV_DISABLE
	return cvCeil(val);
#else
	return ::ceil(val);
#endif
}
//-----------------------------------------------------------------------------//
int CImageAPI::Floor(double val)//無條件捨去(2.9=>2)
{
	return std::floor(val);
#ifndef OPENCV_DISABLE
	return cvFloor(val);
#else
	return ::floor(val);
#endif
}
//-----------------------------------------------------------------------------//
IMAGE_SIZE CImageAPI::GetImageChannels(IMAGE_SIZE BitCount)//取得影像通道數
{
	if ( 8 == BitCount ) { return 1; }
	if ( 24 == BitCount ) { return 3; }
	return 0;
}
//-------------------------------------------------------------------------------------//
IMAGE_SIZE CImageAPI::GetImageRealWidth(IMAGE_SIZE ImageW, IMAGE_SIZE BitCount)//取得影像實際寬度
{
	if ( 8 == BitCount ) { return ImageW; }
	if ( 24 == BitCount ) { return ImageW*3; }
	return 0;
}
//----------------------------------------------------------------------------//
IMAGE_SIZE CImageAPI::GetImageAlignedWidth(IMAGE_SIZE ImageW, IMAGE_SIZE BitCount, int Align)//取得影像對齊寬度
{
	assert((Align & (Align - 1)) == 0); // Align is a power of 2
	switch ( BitCount )
	{
	case 8:  ImageW = ImageW; break;
	case 24: ImageW = ImageW*3; break;
	case 32: ImageW = ImageW*4; break;
	default: ImageW = 0; break;
	}
    return (ImageW + Align-1) & -Align;
}
//----------------------------------------------------------------------------//
int  CImageAPI::GetKernelSize(int val)//取得核心尺寸
{
	return ((val/2)*2)+1;
}
//-----------------------------------------------------------------------------//
double  CImageAPI::CalcImageWndScale(IMAGE_SIZE ImageSize, IMAGE_SIZE WndSize)//取得圖像與視窗比例
{
	if ( WndSize == 0 ) { return 1; }
	double Scale = ImageSize;
	Scale = Scale/(WndSize);
	return Scale;
}
//-------------------------------------------------------------------------------------//
double CImageAPI::CalcImageWndFitScale(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, const RECT &WndRect)//取得圖像與視窗比例
{
	double Scale = 1.0;
	const int WndSizeW = WndRect.right-WndRect.left;
	const int WndSizeH = WndRect.bottom-WndRect.top;
	double ScaleX = this->CalcImageWndScale(ImageW, WndSizeW);
	double ScaleY = this->CalcImageWndScale(ImageH, WndSizeH);
	
	const int NewWndSizeW = this->Floor(ImageW/ScaleY);
	const int NewWndSizeH = this->Floor(ImageH/ScaleX);
	if ( NewWndSizeW <= WndSizeW ) { return ScaleY; } 
	return ScaleX;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadImage(LPCTSTR pfilename, IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, IMAGE_SIZE &BitCount, unsigned char *&pImage, int Align, bool Reverse)//讀取圖檔
{
	bool IsOK = false;
	CString ExtName;
	JetAPI::ExtractExtendFileName(pfilename, ExtName);
	if ( ExtName.CompareNoCase(_T("PNG")) == 0 ) 
	{	IsOK = LoadPNGImage(pfilename, ImageW, ImageH, ImageStep, BitCount, pImage, Align, Reverse);	}
	else if ( ExtName.CompareNoCase(_T("JPG")) == 0 ) 
	{	IsOK = LoadJPGImage(pfilename, ImageW, ImageH, ImageStep, BitCount, pImage, Align, Reverse);	}
	else if ( ExtName.CompareNoCase(_T("BMP")) == 0 ) 
	{	IsOK = LoadBMPImage(pfilename, ImageW, ImageH, ImageStep, BitCount, pImage, Align, Reverse);	}
	else
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Image Filename Exception (%s)"), pfilename);	
		UnlockImageAPI();
	}
	return IsOK;
}
