//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveUniFrameImage_Offline(LPCTSTR pfilename, const std::vector<TUNI_FRAME> &UniFrameList, bool UseRawSpace)//儲存通用圖檔-離線編程使用
{
	size_t       i=0, j=0;
	size_t       LastJ=0;
	RECT         RoiRect={0,0,0,0};
	CString      ExtName;
	CString      MainName;
	CString      FileName;
	TUNI_FRAME   UniFrame;
	TUNI_FRAME   UniFrameTmp;
	size_t       ImageSize=0;
	size_t       BufferStep=0;
	size_t       BufferSize=0;	
	IMAGE_PTR    ImagePtr=NULL;
	IMAGE_PTR    BufferPtr=NULL;
	const bool   Reverse=true;
	const size_t MaxAddExistCount=64;
	const size_t UniFrameCount = UniFrameList.size();
	//const double SpaceRatio = AOIDataCollect.GetSpaceToGrayRatio();

	JetAPI::ExtractMainFileName(pfilename, MainName);
	JetAPI::ExtractExtendFileName(pfilename, ExtName);

	LastJ = 0;
	for ( i=0; i<UniFrameCount; i++ )
	{
		UniFrame = UniFrameList[i];		
		//if ( false == UniFrame.SaveFile ) { continue; }

		ImageSize = CalcBufferSize(UniFrame.ImageStep, UniFrame.ImageH);
		if ( ImageSize > BufferSize )
		{			
			BufferStep = GetImageAlignedWidth(UniFrame.ImageW, 24, 4);
			BufferSize = BufferStep*UniFrame.ImageH;
			JetMemory.free_func(BufferPtr);
			if ( JetMemory.alloc_func(BufferSize, BufferPtr, "CImageAPI::SaveUniFrameImage_Offline", "BufferPtr") == false )
			{	return false;	}
		}
		
		if ( NULL != UniFrame.ImagePtr )
		{			
			ImagePtr = UniFrame.ImagePtr;
			FileName.Format(_T("%s#%d.%s"), MainName, i+1, ExtName);			
			if ( SaveImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, ImagePtr, Reverse) == false )
			{
				JetMemory.free_func(BufferPtr);
				return false; 
			}
		}

		MASK_PTR  MaskPtr=UniFrame.MaskPtr;
		SPACE_PTR SpacePtr=UniFrame.SpacePtr;
		if ( true == UseRawSpace )
		{
			MaskPtr=UniFrame.RawMaskPtr;
			SpacePtr=UniFrame.RawSpacePtr;
		}
		if ( NULL!=MaskPtr && NULL!=SpacePtr )
		{	
			RoiRect.left = 0; 
			RoiRect.top = 0;
			RoiRect.right = (int)(UniFrame.ImageW);
			RoiRect.bottom = (int)(UniFrame.ImageH);
			IMAGE_SIZE RoiStep = GetImageAlignedWidth(UniFrame.ImageW, 8, 4);
			FileName.Format(_T("%s#%d.%s"), MainName, i+1, ExtName);
			bool bSaveSpaceImage=false;
			if ( true == bSaveSpaceImage )
			{
				const double SpaceRatio = 50.0;
				SpaceGrayImageConvertToGray3(UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.SpacePtr, UniFrame.MaskPtr, RoiRect, RoiStep, BufferPtr, SpaceRatio, false);
				ImagePtr = BufferPtr; 			
				if ( CImageAPI::SaveImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, ImagePtr, Reverse) == false )
				{
					JetMemory.free_func(BufferPtr);
					return false; 
				}
			}

			FileName.Format(_T("%s#%d.%s"), MainName, i+1, EXT_NAME_SPACE);				
			if ( CImageAPI::SaveSpaceGrayImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, SpacePtr, Reverse) == false )
			{	
				JetMemory.free_func(BufferPtr);
				return false; 
			}

			FileName.Format(_T("%s#%d.%s"), MainName, i+1, EXT_NAME_MASK);				
			if ( CImageAPI::SaveMaskGrayImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, MaskPtr, Reverse) == false )
			{	
				JetMemory.free_func(BufferPtr);
				return false; 
			}
		}
	}
	JetMemory.free_func(BufferPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveUniFrameImage(LPCTSTR pfilename, const std::vector<TUNI_FRAME> &UniFrameList, bool Reverse, bool Enhance, bool Save3D, bool Append, double SpaceRatio)//儲存通用圖檔
{
	size_t       i=0, j=0;
	size_t       LastJ=0;
	RECT         RoiRect={0,0,0,0};
	CString      ExtName;
	CString      MainName;
	CString      FileName;
	TUNI_FRAME   UniFrame;
	TUNI_FRAME   UniFrameTmp;
	size_t       ImageSize=0;
	size_t       BufferStep=0;
	size_t       BufferSize=0;	
	IMAGE_PTR    ImagePtr=NULL;
	IMAGE_PTR    BufferPtr=NULL;
	const size_t MaxAddExistCount=64;
	const size_t UniFrameCount = UniFrameList.size();
	//const double SpaceRatio = AOIDataCollect.GetSpaceToGrayRatio();

	JetAPI::ExtractMainFileName(pfilename, MainName);
	JetAPI::ExtractExtendFileName(pfilename, ExtName);

	LastJ = 0;
	for ( i=0; i<UniFrameCount; i++ )
	{
		UniFrame = UniFrameList[i];		
		ImageSize = CalcBufferSize(UniFrame.ImageStep, UniFrame.ImageH);
		if ( ImageSize > BufferSize )
		{			
			BufferStep = GetImageAlignedWidth(UniFrame.ImageW, 24, 4);
			BufferSize = BufferStep*UniFrame.ImageH;
			JetMemory.free_func(BufferPtr);
			if ( JetMemory.alloc_func(BufferSize, BufferPtr, "CImageAPI::SaveUniFrameImage", "BufferPtr") == false )
			{	return false;	}
		}
		
		if ( NULL != UniFrame.ImagePtr )
		{			
			if ( false == Enhance )
			{	ImagePtr = UniFrame.ImagePtr; }
			else
			{	
				ImagePtr = BufferPtr; 
				AOIDataCollect.ExecEnhanceDisplayImage(UniFrame, BufferPtr);
			}
			FileName.Format(_T("%s#%d.%s"), MainName, i+1, ExtName);
			if ( true == Append )
			{
				if ( 0 == LastJ )
				{
					for ( j=0; j<MaxAddExistCount; j++ )
					{
						if ( j>0 )
						{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, j, ExtName); }
						if ( JetAPI::IsFileExist(FileName) == false )
						{
							LastJ = j;
							break; 
						}
					}
				}
				else
				{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, LastJ, ExtName); }
			}
			if ( CImageAPI::SaveImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, ImagePtr, Reverse) == false )
			{
				JetMemory.free_func(BufferPtr);
				return false; 
			}
		}
		if ( NULL!=UniFrame.MaskPtr && NULL!=UniFrame.SpacePtr )
		{	
			RoiRect.left = 0; 
			RoiRect.top = 0;
			RoiRect.right = (int)(UniFrame.ImageW);
			RoiRect.bottom = (int)(UniFrame.ImageH);
			IMAGE_SIZE RoiStep = GetImageAlignedWidth(UniFrame.ImageW, 8, 4);

			//FileName.Format(_T("%s#%d_Mask.%s"), MainName, i+1, ExtName);			
			//SaveImage(str, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, UniFrame.MaskPtr, true); 
			
			FileName.Format(_T("%s#%d.%s"), MainName, i+1, ExtName);
			if ( true == Append )
			{
				if ( 0 == LastJ )
				{
					for ( j=0; j<MaxAddExistCount; j++ )
					{
						if ( j>0 )
						{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, j, ExtName); }
						if ( JetAPI::IsFileExist(FileName) == false )
						{
							LastJ = j;
							break; 
						}
					}
				}
				else
				{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, LastJ, ExtName); }
			}
			SpaceGrayImageConvertToGray3(UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.SpacePtr, UniFrame.MaskPtr, RoiRect, RoiStep, BufferPtr, SpaceRatio, false);
			ImagePtr = BufferPtr; 
			if ( true == Enhance )
			{	
				UniFrameTmp = UniFrame;
				UniFrameTmp.ImagePtr = BufferPtr;
				AOIDataCollect.ExecEnhanceDisplayImage(UniFrameTmp, BufferPtr);	
			}
			if ( CImageAPI::SaveImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, ImagePtr, Reverse) == false )
			{
				JetMemory.free_func(BufferPtr);
				return false; 
			}

			if ( true == Save3D )
			{				
				FileName.Format(_T("%s#%d.%s"), MainName, i+1, _T("Z3D"));
				if ( true == Append )
				{
					if ( 0 == LastJ )
					{
						for ( j=0; j<MaxAddExistCount; j++ )
						{
							if ( j>0 )
							{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, j, _T("Z3D")); }
							if ( JetAPI::IsFileExist(FileName) == false )
							{	break; }
						}
					}
					else
					{	FileName.Format(_T("%s#%d-%d.%s"), MainName, i+1, LastJ, _T("Z3D")); }
				}
				if ( CImageAPI::SaveSpaceGrayImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.SpacePtr, Reverse) == false )
				{	
					JetMemory.free_func(BufferPtr);
					return false; 
				}
			}
		}
	}
	JetMemory.free_func(BufferPtr);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadUniFrameImage(LPCTSTR pfilename, std::vector<TUNI_FRAME> &UniFrameList, bool Reverse, size_t Count)//載入通用圖檔
{
	size_t       i=0;	
	CString      ExtName;
	CString      MainName;
	CString      FileName;
	TUNI_FRAME   UniFrame;
	const int    nAlign = 4;
	const size_t UniFrameCount = Count;
	JetAPI::ExtractMainFileName(pfilename, MainName);
	JetAPI::ExtractExtendFileName(pfilename, ExtName);
	for ( i=0; i<UniFrameCount; i++ )
	{
		UniFrame = TUNI_FRAME();
		FileName.Format(_T("%s_%d.%s"), MainName, i+1, ExtName);
		if ( LoadImage(FileName, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, UniFrame.ImagePtr, nAlign, Reverse) == false )
		{	return false; }
		UniFrameList.push_back(UniFrame);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadBMPFile(LPCTSTR pfilename, CDib &dib)//載入BMP圖檔
{
	if ( dib.Load(pfilename) == FALSE )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Load BMP File Fault. (%s)"), pfilename);
		UnlockImageAPI();
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadBMPImage(LPCTSTR pfilename, int Align, bool Reverse, TIMAGE &Image)//讀取BMP圖檔	
{
	const char fnName[] = ("CImageAPI::LoadBMPImage");
	CDib dib;	
	if ( this->LoadBMPFile(pfilename, dib) == false )
	{	return false; }

	BITMAPINFO *pInfo = dib.GetDIBInfo();
	if ( NULL == pInfo )
	{
		this->m_ErrorString.Format(_T("Error, BMP File Load Fault. (%s)"), pfilename);		
		return false;
	}
	if ( CImageAPI::CheckBitCount(pInfo->bmiHeader.biBitCount) == false ) 
	{	return false; }

	unsigned char *pImage = NULL;
	unsigned char *pSrc = dib.GetDIBBits();	
	IMAGE_SIZE ImageW = pInfo->bmiHeader.biWidth;
	IMAGE_SIZE ImageH = pInfo->bmiHeader.biHeight;
	IMAGE_SIZE BitCount = pInfo->bmiHeader.biBitCount;		
	const IMAGE_SIZE RealImageW  = this->GetImageRealWidth(ImageW, BitCount);
	const IMAGE_SIZE BMP_Width_Strip = CImageAPI::GetImageAlignedWidth(ImageW, BitCount, 4);
	const IMAGE_SIZE BytePerLine = CImageAPI::GetImageAlignedWidth(RealImageW, 8, Align);
	const IMAGE_SIZE ImageStep = BytePerLine;
	const size_t     ImageSize = CalcBufferSize(BytePerLine, ImageH);
	
	if ( JetMemory.alloc_func(ImageSize, pImage, fnName, "pImage") == false )	
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}
	size_t i=0, j=0;
	size_t u=0, v=0;
	size_t s=0, t=0;	
	if ( false == Reverse )
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = j*BytePerLine;
			s = j*BMP_Width_Strip;
			::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
		}
	}
	else
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = (ImageH-1-j)*BytePerLine;
			s = j*BMP_Width_Strip;
			::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
		}		
	}	
	Image = TIMAGE(ImageW, ImageH, ImageStep, BitCount, pImage);
	return true;
}
