bool CImageAPI::LoadBMPGrayImage(LPCTSTR pfilename, IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, unsigned char *&pImage, int Align, bool Reverse)//讀取BMP灰階圖檔
{
	const char fnName[] = ("CImageAPI::LoadBMPGrayImage");
	CDib dib;
	JetMemory.free_func(pImage);
	if ( this->LoadBMPFile(pfilename, dib) == false )
	{	return false; }

	BITMAPINFO *pInfo = dib.GetDIBInfo();
	if ( (pInfo==NULL) || (pInfo->bmiHeader.biBitCount!=8) )
	{
		this->m_ErrorString.Format(_T("Error, BMP File is not gray mode. (%s)"), pfilename);		
		return false;
	}
	
	ImageW = pInfo->bmiHeader.biWidth;
	ImageH = pInfo->bmiHeader.biHeight;
	unsigned char *pSrc = dib.GetDIBBits();	
	const IMAGE_SIZE RealImageW  = ImageW;
	const IMAGE_SIZE BMP_Width_Strip = CImageAPI::GetImageAlignedWidth(ImageW, pInfo->bmiHeader.biBitCount, 4);
	const IMAGE_SIZE BytePerLine = CImageAPI::GetImageAlignedWidth(RealImageW, 8, Align);
	const size_t     ImageSize = CalcBufferSize(BytePerLine, ImageH);
	ImageStep = BytePerLine;
	if ( JetMemory.alloc_func(ImageSize, pImage, fnName, "pImage") == false )	
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}
	
	size_t i=0, j=0;
	size_t u=0, v=0;
	size_t s=0, t=0;	
	if ( false == Reverse )
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = j*BytePerLine;
			s = j*BMP_Width_Strip;
			::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
		}
	}
	else
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = (ImageH-1-j)*BytePerLine;
			s = j*BMP_Width_Strip;
			::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
		}		
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadBMPColorImage(LPCTSTR pfilename, IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, unsigned char *&pImage, int Align, bool Reverse)//讀取BMP彩色圖檔
{
	const char fnName[] = ("CImageAPI::LoadBMPColorImage");
	CDib dib;
	JetMemory.free_func(pImage);
	if ( this->LoadBMPFile(pfilename, dib) == false )
	{	return false; }

	BITMAPINFO *pInfo = dib.GetDIBInfo();
	if ( (pInfo==NULL) || ((pInfo->bmiHeader.biBitCount!=24)&&(pInfo->bmiHeader.biBitCount!=32)) )
	{
		this->m_ErrorString.Format(_T("Error, BMP File is not color mode. (%s)"), pfilename);		
		return false;
	}
	
	ImageW = pInfo->bmiHeader.biWidth;
	ImageH = pInfo->bmiHeader.biHeight;
	unsigned char *pSrc = dib.GetDIBBits();	
	const IMAGE_SIZE RealImageW  = ImageW*3;
	const IMAGE_SIZE BMP_Width_Strip = CImageAPI::GetImageAlignedWidth(ImageW, pInfo->bmiHeader.biBitCount, 4);
	const IMAGE_SIZE BytePerLine = CImageAPI::GetImageAlignedWidth(RealImageW, 8, Align);
	const size_t     ImageSize = CalcBufferSize(BytePerLine, ImageH);
	ImageStep = BytePerLine;
	if ( JetMemory.alloc_func(ImageSize, pImage, fnName, "pImage") == false )	
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}
	
	size_t i=0, j=0;
	size_t u=0, v=0;
	size_t s=0, t=0;
	if ( 32 == pInfo->bmiHeader.biBitCount )
	{
		if ( false == Reverse )
		{
			for ( j=0; j<ImageH; j++ )
			{
				u = j*BytePerLine;
				s = j*BMP_Width_Strip;
				for ( i=0; i<ImageW; i++ )
				{
					pImage[u++] = pSrc[s++];
					pImage[u++] = pSrc[s++];
					pImage[u++] = pSrc[s++];
					s ++;
				}				
			}
		}
		else
		{
			for ( j=0; j<ImageH; j++ )
			{
				u = (ImageH-1-j)*BytePerLine;
				s = j*BMP_Width_Strip;
				for ( i=0; i<ImageW; i++ )
				{
					pImage[u++] = pSrc[s++];
					pImage[u++] = pSrc[s++];
					pImage[u++] = pSrc[s++];
					s ++;
				}
			}		
		}
	}
	else if ( 24 == pInfo->bmiHeader.biBitCount )
	{
		if ( false == Reverse )
		{
			for ( j=0; j<ImageH; j++ )
			{
				u = j*BytePerLine;
				s = j*BMP_Width_Strip;
				::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
			}
		}
		else
		{
			for ( j=0; j<ImageH; j++ )
			{
				u = (ImageH-1-j)*BytePerLine;
				s = j*BMP_Width_Strip;
				::memcpy(&(pImage[u]), &(pSrc[s]), sizeof(unsigned char)*RealImageW);
			}		
		}	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadBMPRGBImage(LPCTSTR pfilename, IMAGE_SIZE &ImageW, IMAGE_SIZE &ImageH, IMAGE_SIZE &ImageStep, unsigned char *&pR, unsigned char *&pG, unsigned char *&pB, int Align, bool Reverse)//讀取BMP-RGB圖檔
{
	const char fnName[] = ("CImageAPI::LoadBMPRGBImage");
	CDib dib;
	JetMemory.free_func(pR);
	JetMemory.free_func(pG);
	JetMemory.free_func(pB);
	if ( this->LoadBMPFile(pfilename, dib) == false )
	{	return false; }

	BITMAPINFO *pInfo = dib.GetDIBInfo();
	if ( (pInfo==NULL) || (pInfo->bmiHeader.biBitCount!=24) )
	{
		this->m_ErrorString.Format(_T("Error, BMP File is not color mode. (%s)"), pfilename);		
		return true;
	}
	
	ImageW = pInfo->bmiHeader.biWidth;
	ImageH = pInfo->bmiHeader.biHeight;
	unsigned char *pSrc = dib.GetDIBBits();	
	const IMAGE_SIZE RealImageW  = ImageW*3;
	const IMAGE_SIZE BMP_Width_Strip = CImageAPI::GetImageAlignedWidth(RealImageW, 8, 4);
	const IMAGE_SIZE BytePerLine = CImageAPI::GetImageAlignedWidth(ImageW, 8, Align);
	const size_t     ImageSize = CalcBufferSize(BytePerLine, ImageH);
	ImageStep = BytePerLine;
	if ( JetMemory.alloc_func(ImageSize, pR, fnName, "pR") == false ||
	     JetMemory.alloc_func(ImageSize, pG, fnName, "pG") == false ||
	     JetMemory.alloc_func(ImageSize, pB, fnName, "pB") == false )
	{			
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pR);
		JetMemory.free_func(pG);
		JetMemory.free_func(pB);
		return false;	
	}
	
	size_t i=0, j=0;
	size_t u=0, v=0;
	size_t s=0, t=0;	
	if ( false == Reverse )
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = j*BytePerLine;
			s = j*BMP_Width_Strip;
			for ( i=0; i<ImageW; i++ )
			{
				pB[u] = pSrc[s]; s++;
				pG[u] = pSrc[s]; s++;
				pR[u] = pSrc[s]; s++;
				u ++;
			}
		}
	}
	else
	{
		for ( j=0; j<ImageH; j++ )
		{
			u = (ImageH-1-j)*BytePerLine;
			s = j*BMP_Width_Strip;
			for ( i=0; i<ImageW; i++ )
			{
				pB[u] = pSrc[s]; s++;
				pG[u] = pSrc[s]; s++;
				pR[u] = pSrc[s]; s++;
				u ++;
			}
		}		
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPImage(LPCTSTR pfilename, TIMAGE &Image, bool Reverse)//儲存BMP圖檔
{
	const int nType      = Image.GetType();
	const int nChannels  = Image.GetChannels();
	IMAGE_SIZE ImageW    = Image.GetImageW();
	IMAGE_SIZE ImageH    = Image.GetImageH();
	IMAGE_SIZE ImageStep = Image.GetRowStep();
	IMAGE_SIZE BitCount  = Image.GetBitCount();
	if ( 1==nChannels && IMG_TYPE_08U==nType )
	{
		IMAGE_PTR Ptr = Image.Get08uPtr();
		return CImageAPI::SaveBMPImage(pfilename, ImageW, ImageH, ImageStep, BitCount, Ptr, Reverse);
	}
	else if ( 3==nChannels && IMG_TYPE_08U==nType )
	{
		IMAGE_PTR PtrR = Image.Get08uPtrR();
		IMAGE_PTR PtrG = Image.Get08uPtrG();
		IMAGE_PTR PtrB = Image.Get08uPtrB();
		return CImageAPI::SaveBMPRGBImage(pfilename, ImageW, ImageH, ImageStep, PtrR, PtrG, PtrB, Reverse);
	}
	this->m_ErrorString.Format(_T("Error, No match formate to save BMP file"));
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPImage(LPCTSTR pfilename, const TUNI_FRAME &UniFrame, bool Reverse)//儲存BMP圖檔
{
	return SaveBMPImage(pfilename, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, UniFrame.ImagePtr, Reverse);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPImage(LPCTSTR pfilename, const TUNI_FRAME &UniFrame, const unsigned char *pImage, bool Reverse)//儲存BMP圖檔
{
	return SaveBMPImage(pfilename, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.BitCount, pImage, Reverse);
}
