bool CImageAPI::SaveBMPImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, bool Reverse)//儲存BMP圖檔
{	
	if ( 8 == BitCount )
	{	return SaveBMPGrayImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse);	}
	else if ( 24 == BitCount )
	{	return SaveBMPColorImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse);	}	
	this->m_ErrorString.Format(_T("Error, Save BMP Imae Fualt (BitCount:%d"), BitCount);
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPGrayImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, bool Reverse)//儲存BMP灰階圖檔
{	
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	CDib dib;
	if ( dib.SetImage(pImage, ImageW, ImageH, ImageStep, 8, Reverse) == false )
	{
		this->m_ErrorString.Format(_T("Error, Set BMP Image Fault"));
		return false;
	}

	if ( dib.Save(pfilename) == FALSE )
	{
		this->m_ErrorString.Format(_T("Error, Save BMP File Fault (%s)"), pfilename);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPColorImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, bool Reverse)//儲存BMP彩色圖檔
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	CDib dib;
	if ( dib.SetImage(pImage, ImageW, ImageH, ImageStep, 24, Reverse) == false )
	{
		this->m_ErrorString.Format(_T("Error, Set BMP Image Fault"));
		return false;
	}

	if ( dib.Save(pfilename) == FALSE )
	{
		this->m_ErrorString.Format(_T("Error, Save BMP File Fault (%s)"), pfilename);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveBMPRGBImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, bool Reverse)//儲存BMP-RGB圖檔
{
	if ( CImageAPI::CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }

	unsigned char *pColor = NULL;
	const IMAGE_SIZE StepClr = CImageAPI::GetImageAlignedWidth(ImageW, 24, 4);
	if ( CImageAPI::RGBImageToColorImage(ImageW, ImageH, ImageStep, pR, pG, pB, StepClr, pColor, false) == false )
	{	return false;	}

	CDib dib;	
	if ( dib.SetImage(pColor, ImageW, ImageH, StepClr, 24, Reverse) == false )
	{
		JetMemory.free_func(pColor);
		this->m_ErrorString.Format(_T("Error, Set BMP Image Fault"));
		return false;
	}
	JetMemory.free_func(pColor);

	if ( dib.Save(pfilename) == FALSE )
	{
		this->m_ErrorString.Format(_T("Error, Save BMP File Fault (%s)"), pfilename);
		return false;
	}	
	return true;
}
