{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) { return false; }
	if ( 8 == BitCount ) 
	{	return CImageAPI::SaveJPGGrayImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse); }
	if ( 24 == BitCount ) 
	{	return CImageAPI::SaveJPGColorImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveJPGGrayImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, bool Reverse)//儲存JPG灰階圖檔
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	//const int Quality = 90;
	const int Quality = AOIDataCollect.GetSystemParameter().m_SaveJpegQuality;
#ifndef OPENCV_DISABLE		
	#if OPEN_CV_VERSION == OPEN_CV_3_4_16_00_V14
	std::vector<int> Params;
	Params.push_back(cv::IMWRITE_JPEG_QUALITY);	Params.push_back(Quality);
	return SaveMatImage(pfilename, ImageW, ImageH, ImageStep, 8, pImage, Reverse, Params);
	#else
	int Params[3];
	Params[0] = CV_IMWRITE_JPEG_QUALITY;	Params[1]=Quality;	Params[2]=0;
	return SaveCVGrayImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse, Params);
	#endif//OPEN_CV_VERSION
#else
	JpegFile Jpeg;	
	unsigned char *pDst = NULL;
	if ( CImageAPI::AlignGrayImageBuffer(ImageW, ImageH, ImageStep, pImage, ImageW, pDst, !Reverse) == false )
	{	return false; }

	if ( Jpeg.SaveToJpegFile(pfilename, pDst, ImageW, ImageH, FALSE, Quality) == false )//會再顛倒一次
	{	
		JetMemory.free_func(pDst);
		this->m_ErrorString.Format(_T("Error, Save JPG File Fault (%s)"), pfilename);
		return false;
	}
	JetMemory.free_func(pDst);
#endif//OPENCV_DISABLE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveJPGColorImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, bool Reverse)//儲存JPG彩色圖檔	
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	//const int Quality = 90;
	const int Quality = AOIDataCollect.GetSystemParameter().m_SaveJpegQuality;
#ifndef OPENCV_DISABLE			
	#if OPEN_CV_VERSION == OPEN_CV_3_4_16_00_V14		
	std::vector<int> Params;
	Params.push_back(cv::IMWRITE_JPEG_QUALITY);	Params.push_back(Quality);
	return SaveMatImage(pfilename, ImageW, ImageH, ImageStep, 24, pImage, Reverse, Params);
	#else
	int Params[3];
	Params[0] = CV_IMWRITE_JPEG_QUALITY;	Params[1]=Quality;	Params[2]=0;
	return SaveCVColorImage(pfilename, ImageW, ImageH, ImageStep, pImage, Reverse, Params);
	#endif//OPEN_CV_VERSION
#else
	JpegFile Jpeg;	
	unsigned char *pDst = NULL;
	if ( CImageAPI::AlignColorImageBuffer(ImageW, ImageH, ImageStep, pImage, ImageW*3, pDst, !Reverse) == false )
	{	return false; }

	Jpeg.BGRFromRGB(pDst, ImageW, ImageH);
	if ( Jpeg.SaveToJpegFile(pfilename, pDst, ImageW, ImageH, TRUE, Quality) == false )//會再顛倒一次
	{	
		JetMemory.free_func(pDst);
		this->m_ErrorString.Format(_T("Error, Save JPG File Fault (%s)"), pfilename);
		return false;
	}
	JetMemory.free_func(pDst);
#endif//OPENCV_DISABLE
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveJPGRGBImage(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, bool Reverse)//儲存JPG-RGB圖檔
{
	if ( CImageAPI::CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )	
	{	return false; }
	
	JpegFile Jpeg;
	const int Quality = 90;
	unsigned char *pDst = NULL;
	const IMAGE_SIZE ClrStep = CImageAPI::GetImageRealWidth(ImageW, 24);
	if ( CImageAPI::RGBImageToColorImage(ImageW, ImageH, ImageStep, pR, pG, pB, ClrStep, pDst, !Reverse) == false )
	//if ( CImageAPI::AlignColorImageBuffer(ImageW, ImageH, ImageStep, pImage, ImageW*3, pDst, !Reverse) == false )
	{	return false; }

	Jpeg.BGRFromRGB(pDst, ImageW, ImageH);
	if ( Jpeg.SaveToJpegFile(pfilename, pDst, ImageW, ImageH, TRUE, Quality) == false )//會再顛倒一次
	{	
		JetMemory.free_func(pDst);
		this->m_ErrorString.Format(_T("Error, Save JPG File Fault (%s)"), pfilename);
		return false;
	}
	JetMemory.free_func(pDst);
	return true;
}
