//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadMaskGrayImage(LPCTSTR pfilename, IMAGE_SIZE &MaskW, IMAGE_SIZE &MaskH, IMAGE_SIZE &MaskStep, MASK_PTR &MaskPtr, bool Reverse)//讀取Mask灰階圖檔
{
#ifdef ZLIB_USE	
	CJetZip JetZip;
	IMAGE_SIZE BitCount = 0;
	unsigned char *SharPtr = NULL;
	CJetZip::LockJetZip();
	if ( JetZip.LoadGZipGrayImage(pfilename, MaskW, MaskH, MaskStep, BitCount, SharPtr) == false )
	{
		CJetZip::UnlockJetZip();
		SetErrorString(JetZip.GetErrorString());
		return false;
	}
	CJetZip::UnlockJetZip();
	if ( 8 != BitCount ) 
	{
		JetMemory.free_func(SharPtr);
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Load Mark Gray Image Fault (BitCount:%d)"), BitCount);
		UnlockImageAPI();
		return false;
	}

	if ( true == Reverse )
	{
		if ( CImageAPI::ReverseGrayImage(MaskW, MaskH, MaskStep, SharPtr, MaskPtr) == false )
		{
			JetMemory.free_func(SharPtr);
			return false;
		}
		JetMemory.free_func(SharPtr);
	}
	else
	{	MaskPtr = SharPtr;	}	
	return true;
#endif//ZLIB_USE
	LockImageAPI();
	this->m_ErrorString = _T("Error, No JetZip to Load Mark File");
	UnlockImageAPI();
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveMaskGrayImage(LPCTSTR pfilename, const TUNI_FRAME &UniFrame, bool Reverse)//儲存Mask灰階圖檔	
{
	return SaveMaskGrayImage(pfilename, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.MaskPtr, Reverse);//儲存Mask灰階圖檔	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveMaskGrayImage(LPCTSTR pfilename, IMAGE_SIZE MaskW, IMAGE_SIZE MaskH, IMAGE_SIZE MaskStep, const MASK_PTR MaskPtr, bool Reverse)//儲存Mask灰階圖檔	
{
#ifdef ZLIB_USE
	CJetZip JetZip;
	IMAGE_SIZE BitCount = 8;
	bool   Allocated = false;
	unsigned char *SharPtr = NULL;
	if ( true == Reverse )
	{
		if ( CImageAPI::ReverseGrayImage(MaskW, MaskH, MaskStep, MaskPtr, SharPtr) == false )
		{	return false; }
		Allocated = true;
	}
	else
	{	SharPtr = (unsigned char*)MaskPtr;	}

	CJetZip::LockJetZip();
	if ( JetZip.SaveGZipGrayImage(pfilename, MaskW, MaskH, MaskStep, BitCount, SharPtr) == false )
	{
		CJetZip::UnlockJetZip();
		if ( true == Allocated )
		{	JetMemory.free_func(SharPtr); }
		SetErrorString(JetZip.GetErrorString());
		return false;
	}
	CJetZip::UnlockJetZip();
	if ( true == Allocated )
	{	JetMemory.free_func(SharPtr); }
	return true;
#endif//ZLIB_USE
	LockImageAPI();
	this->m_ErrorString = _T("Error, No JetZip to Save Mark File");
	UnlockImageAPI();
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageConvertToFloat(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_PTR ImagePtr, float *&FloatPtr, bool Reverse)//灰階圖檔轉浮點數
{
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, ImagePtr) == false ) 
	{	return false; }

	const char fnName[]="CImageAPI::GrayImageConvertToFloat";
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(FloatPtr);
	if ( JetMemory.alloc_func(BufferSize, FloatPtr, fnName, "FloatPtr") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}

	if ( GrayImageConvertToFloat3(ImageW, ImageH, ImageStep, ImagePtr, FloatPtr, Reverse) == false )
	{
		JetMemory.free_func(FloatPtr);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageConvertToFloat3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_PTR ImagePtr, float *FloatPtr, bool Reverse)//灰階圖檔轉浮點數
{
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, ImagePtr, FloatPtr) == false ) 
	{	return false; }

	size_t i=0, j=0, idxSrc=0, idxDst=0;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	if ( false == Reverse )
	{
		for ( i=0; i<BufferSize; i++ )
		{	FloatPtr[i] = static_cast<float>(ImagePtr[i]);	}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			idxSrc = i*ImageStep;
			idxDst = (ImageH-i-1)*ImageStep;
			for ( j=0; j<ImageW; j++ )
			{				
				FloatPtr[idxDst] = static_cast<float>(ImagePtr[idxSrc]);	
				idxSrc ++;
				idxDst ++;
			}
		}
	}
	return true;
}
