bool CImageAPI::SaveGrayImageFloatFile(LPCTSTR pfilename, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_PTR ImagePtr, bool Reverse)//儲存浮點數灰階圖檔
{
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, ImagePtr) == false ) 
	{	return false; }

	float *FloatPtr = NULL;
	if ( GrayImageConvertToFloat(ImageW, ImageH, ImageStep, ImagePtr, FloatPtr, Reverse) == false )
	{	return false; }
	if ( SaveGrayFloatFile(pfilename, ImageW, ImageH, ImageStep, FloatPtr, false) == false )
	{
		JetMemory.free_func(FloatPtr);
		return false;
	}
	JetMemory.free_func(FloatPtr);
	return true;	
}
