//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveGrayFloatFile(LPCTSTR pfilename, IMAGE_SIZE FloatW, IMAGE_SIZE FloatH, IMAGE_SIZE FloatStep, SPACE_PTR FloatPtr, bool Reverse)//儲存浮點數灰階浮點數
{
	if ( CheckGrayImage(FloatW, FloatH, FloatStep, FloatPtr) == false ) 
	{	return false; }

	CString str;
	FILE *pfile = NULL;
	pfile = _tfopen(pfilename, _T("wb"));
	if ( NULL == pfile )
	{		
		str.Format(_T("Error, Open File Fault[%s]"), pfilename);
		SetErrorString(str);
		return false;
	}

	size_t i=0;//for one channel
	const int nChannel = 1;
	const int nW = (int)(FloatW);
	const int nH = (int)(FloatH);
	const int nStep = (int)(FloatStep);	

	if ( ::fwrite(&nW, sizeof(nW), 1, pfile) != 1 )	
	{			
		::fclose(pfile);		
		str.Format(_T("Error, Write File Fault[%s]"), _T("Width"));
		SetErrorString(str);
		return false; 
	}
	if ( ::fwrite(&nH, sizeof(nH), 1, pfile) != 1 )	
	{			
		::fclose(pfile);		
		str.Format(_T("Error, Write File Fault[%s]"), _T("Height"));
		SetErrorString(str);
		return false; 
	}
	if ( ::fwrite(&nChannel, sizeof(nChannel), 1, pfile) != 1 )	
	{			
		::fclose(pfile);		
		str.Format(_T("Error, Write File Fault[%s]"), _T("Channel"));
		SetErrorString(str);
		return false; 
	}

	if ( false== Reverse )
	{
		for ( i=0; i<FloatH; i++ )
		{	
			if ( ::fwrite(&(FloatPtr[i*FloatStep]), sizeof(float), FloatW, pfile) != FloatW )
			{
				::fclose(pfile);		
				str.Format(_T("Error, Write File Fault[%s]"), _T("Float Data"));
				SetErrorString(str);
				return false; 
			}
		}
	}
	else
	{
		for ( i=0; i<FloatH; i++ )
		{	
			if ( ::fwrite(&(FloatPtr[(FloatH-i-1)*FloatStep]), sizeof(float), FloatW, pfile) != FloatW )
			{
				::fclose(pfile);		
				str.Format(_T("Error, Write File Fault[%s]"), _T("Float Data"));
				SetErrorString(str);
				return false; 
			}
		}
	}
	::fclose(pfile);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadGrayFloatFile(LPCTSTR pfilename, IMAGE_SIZE &FloatW, IMAGE_SIZE &FloatH, IMAGE_SIZE &FloatStep, IMAGE_SIZE &BitCount, SPACE_PTR &FloatPtr, bool Reverse, int nAlign)//載入浮點數灰階浮點數
{
	const char fnName[] = "CImageAPI::LoadGrayFloatFile";	

	CString str;
	FILE *pfile = NULL;
	pfile = _tfopen(pfilename, _T("rb"));
	if ( NULL == pfile )
	{	
		str.Format(_T("Error, Open File Fault[%s]"), pfilename);
		SetErrorString(str);
		return false;
	}

	size_t i=0;//for one channel
	int nChannel = 0;	
	int nW = (int)(FloatW);
	int nH = (int)(FloatH);
	int nBit = (int)(BitCount);
	int nStep = (int)(FloatStep);	
	
	if ( ::fread(&nW, sizeof(nW), 1, pfile) != 1 )
	{
		::fclose(pfile);		
		str.Format(_T("Error, Read File Fault[%s]"), _T("Width"));
		SetErrorString(str);
		return false; 
	}
	if ( ::fread(&nH, sizeof(nH), 1, pfile) != 1 )
	{
		::fclose(pfile);		
		str.Format(_T("Error, Read File Fault[%s]"), _T("Height"));
		SetErrorString(str);
		return false; 
	}
	if ( ::fread(&nChannel, sizeof(nChannel), 1, pfile) != 1 )
	{
		::fclose(pfile);		
		str.Format(_T("Error, Read File Fault[%s]"), _T("Channel"));
		SetErrorString(str);
		return false; 
	}

	
	switch ( nChannel )
	{
	case 1:	nBit = 8;	break;
	case 3:	nBit = 24;	break;
	default:	
		nBit = 0;		
		str.Format(_T("Error, Read File Fault[%s-%d]"), _T("Channel"), nChannel);
		SetErrorString(str);
		break;
	}
	if ( 0 == nBit )
	{
		::fclose(pfile);
		return false;	
	}
	
	float *Ptr = NULL;
	nStep = JetAPI::GetBMPImagePixelsPerLine(nW, nBit, nAlign);
	const size_t BufferSize = CalcBufferSize(nStep, nH);
	if ( JetMemory.alloc_func(BufferSize, Ptr, fnName, "Ptr") == false )
	{
		::fclose(pfile);
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	
	const size_t CopyLen=nW*nChannel;
	if ( false== Reverse )
	{
		for ( i=0; i<nH; i++ )
		{	
			if ( ::fread(&(Ptr[i*nStep]), sizeof(float), CopyLen, pfile) != nW ) 
			{
				::fclose(pfile);	
				JetMemory.free_func(Ptr);
				str.Format(_T("Error, Read File Fault[%s]"), _T("Float Data"));
				SetErrorString(str);
				return false; 
			}
		}		
	}
	else
	{
		for ( i=0; i<nH; i++ )
		{	
			if ( ::fread(&(Ptr[(nH-i-1)*nStep]), sizeof(float), CopyLen, pfile) != nW )
			{
				::fclose(pfile);
				JetMemory.free_func(Ptr);
				str.Format(_T("Error, Read File Fault[%s]"), _T("Float Data"));
				SetErrorString(str);
				return false; 
			}
		}
	}
	::fclose(pfile);

	FloatW = nW;
	FloatH = nH;
	BitCount = nBit;
	FloatStep = nStep;
	FloatPtr = Ptr;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveSpaceValueFile(LPCTSTR pfilename, IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr)//儲存Space數據檔案
{
	if ( CheckGrayImage(SpaceW, SpaceH, SpaceStep, SpacePtr) == false ) { return false; }

	FILE *pfile = NULL;
	pfile = ::_tfopen(pfilename, _T("w+"));
	if ( NULL == pfile ) 
	{
		m_ErrorString.Format(_T("Error, Open File Fault(%s)"), pfilename);
		return false;
	}

	size_t       i=0;
	const size_t BufferSize=CalcBufferSize(SpaceStep, SpaceH);
	for ( i=0; i<BufferSize; i++ )
	{	::_ftprintf(pfile, _T("%.6f\n"), SpacePtr[i]);	}
	::fclose(pfile); pfile = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LoadSpaceGrayImage(LPCTSTR pfilename, IMAGE_SIZE &SpaceW, IMAGE_SIZE &SpaceH, IMAGE_SIZE &SpaceStep, SPACE_PTR &SpacePtr, bool Reverse)//讀取Space灰階圖檔
{
#ifdef ZLIB_USE	
	CJetZip JetZip;
	IMAGE_SIZE BitCount = 0;
	short *ShortPtr = NULL;
	CJetZip::LockJetZip();
	if ( JetZip.LoadGZipGrayImage(pfilename, SpaceW, SpaceH, SpaceStep, BitCount, ShortPtr) == false )
	{
		CJetZip::UnlockJetZip();
		SetErrorString(JetZip.GetErrorString());
		return false;
	}
	CJetZip::UnlockJetZip();
	if ( 8 != BitCount ) 
	{
		JetMemory.free_func(ShortPtr);
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Load Space Gray Image Fault (BitCount:%d)"), BitCount);
		UnlockImageAPI();
		return false;
	}
	if ( CImageAPI::ShortGrayImageConvertToSpace(SpaceW, SpaceH, SpaceStep, ShortPtr, SpacePtr, Reverse) == false )
	{
		JetMemory.free_func(ShortPtr);
		return false;
	}
	JetMemory.free_func(ShortPtr);
	return true;
#endif//ZLIB_USE
	LockImageAPI();
	this->m_ErrorString = _T("Error, No JetZip to Load Space File");
	UnlockImageAPI();
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveSpaceGrayImage(LPCTSTR pfilename, const TUNI_FRAME &UniFrame, bool Reverse)//儲存Space灰階圖檔	
{
	return SaveSpaceGrayImage(pfilename, UniFrame.ImageW, UniFrame.ImageH, UniFrame.ImageStep, UniFrame.SpacePtr, Reverse);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaveSpaceGrayImage(LPCTSTR pfilename, IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, bool Reverse)//儲存Space灰階圖檔	
{
#ifdef ZLIB_USE
	CJetZip JetZip;
	IMAGE_SIZE BitCount = 8;
	short *ShortPtr = NULL;
	if ( CImageAPI::SpaceGrayImageConvertToShort(SpaceW, SpaceH, SpaceStep, SpacePtr, ShortPtr, Reverse) == false )
	{	return false;	}

	CJetZip::LockJetZip();
	if ( JetZip.SaveGZipGrayImage(pfilename, SpaceW, SpaceH, SpaceStep, BitCount, ShortPtr) == false )
	{
		CJetZip::UnlockJetZip();
		JetMemory.free_func(ShortPtr);
		SetErrorString(JetZip.GetErrorString());
		return false;
	}
	CJetZip::UnlockJetZip();
	JetMemory.free_func(ShortPtr);
	return true;
#endif//ZLIB_USE
	LockImageAPI();
	this->m_ErrorString = _T("Error, No JetZip to Save Space File");
	UnlockImageAPI();
	return false;
}
