bool CImageAPI::LoadPhaseBinFile(LPCTSTR pfilename, IMAGE_SIZE &PhaseW, IMAGE_SIZE &PhaseH, IMAGE_SIZE &PhaseStep, PHASE_PTR &PhasePtr)//讀取Phase Bin檔案
{
	if ( NULL == pfilename ) { return false; }
	size_t NReads = 0;
	FILE *pFile = NULL;
	const char fnName[] = "CImageAPI::LoadPhaseBinFile";

	pFile = ::_tfopen(pfilename, _T("rb"));
	if ( NULL == pFile )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Open File Fault(%s)"), pfilename);
		UnlockImageAPI();
		return true;
	}
	NReads = ::fread(&PhaseW, sizeof(PhaseW), 1, pFile);
	if ( 1 != NReads )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Read File Fault(%s::%s)"), pfilename, _T("PhaseW"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	NReads = ::fread(&PhaseH, sizeof(PhaseH), 1, pFile);
	if ( 1 != NReads )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Read File Fault(%s::%s)"), pfilename, _T("PhaseH"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}

	NReads = ::fread(&PhaseStep, sizeof(PhaseStep), 1, pFile);
	if ( 1 != NReads )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Read File Fault(%s::%s)"), pfilename, _T("PhaseStep"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}

	const size_t BufferSize = CalcBufferSize(PhaseStep, PhaseH);
	if ( 0 == BufferSize ) 
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Read File Fault(%s::%s)"), pfilename, _T("BufferSize"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}	
	if ( JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	NReads = ::fread(PhasePtr, sizeof(PHASE_DATA), BufferSize, pFile);
	if ( BufferSize != NReads )
	{
		JetMemory.free_func(PhasePtr);
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Read File Fault(%s::%s)"), pfilename, _T("PhasePtr"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}	
	::fclose(pFile);
	pFile = NULL;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SavePhaseBinFile(LPCTSTR pfilename, IMAGE_SIZE PhaseW, IMAGE_SIZE PhaseH, IMAGE_SIZE PhaseStep, const PHASE_PTR PhasePtr)//儲存Phase Bin檔案
{
	if ( NULL == pfilename ) { return false; }
	bool    IsOK = true;	
	FILE   *pFile = NULL;
	size_t  NWrites = 0;
	CString Filename = pfilename;

	IMAGE_SIZE PhaseZeroW = PhaseW;
	IMAGE_SIZE PhaseZeroH = PhaseH;
	IMAGE_SIZE PhaseZeroStep = PhaseStep;
	const PHASE_PTR  PhaseZeroPtr = PhasePtr;
	if ( NULL == PhaseZeroPtr ) 
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Write File Fault(%s::%s)"), Filename, _T("m_PhaseZeroPtr"));
		UnlockImageAPI();
		return false;
	}

	pFile = ::_tfopen(Filename, _T("wb"));
	if ( NULL == pFile )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Open File Fault(%s)"), Filename);
		UnlockImageAPI();
		return false;
	}
	NWrites = ::fwrite(&PhaseZeroW, sizeof(PhaseZeroW), 1, pFile);
	if ( 1 != NWrites )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Write File Fault(%s::%s)"), Filename, _T("m_PhaseZeroW"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	NWrites = ::fwrite(&PhaseZeroH, sizeof(PhaseZeroH), 1, pFile);
	if ( 1 != NWrites )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Write File Fault(%s::%s)"), Filename, _T("m_PhaseZeroH"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	NWrites = ::fwrite(&PhaseZeroStep, sizeof(PhaseZeroStep), 1, pFile);
	if ( 1 != NWrites )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Write File Fault(%s::%s)"), Filename, _T("m_PhaseZeroStep"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	const size_t BufferSize = PhaseZeroH*PhaseZeroStep;
	NWrites = ::fwrite(PhaseZeroPtr, sizeof(PHASE_DATA), BufferSize, pFile);
	if ( BufferSize != NWrites )
	{
		LockImageAPI();
		this->m_ErrorString.Format(_T("Error, Write File Fault(%s::%s)"), Filename, _T("m_PhaseZeroPtr"));
		UnlockImageAPI();
		::fclose(pFile);	pFile = NULL;
		return false;
	}
	::fclose(pFile);
	pFile = NULL;
	return true;
}
