bool CImageAPI::Compare2PhaseBinFile(IMAGE_SIZE PhaseW, IMAGE_SIZE PhaseH, IMAGE_SIZE PhaseStep, const PHASE_PTR PhasePtr1, const PHASE_PTR PhasePtr2, int &ErrCnt)//比較2個Phase Bin檔案
{
	if ( NULL==PhasePtr1 || NULL==PhasePtr2 ) { return false; }

	size_t       i=0;
	const size_t BufferSize = CalcBufferSize(PhaseStep, PhaseH);

	ErrCnt = 0;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( PhasePtr1[i] == PhasePtr2[i] ) { continue; }
		ErrCnt ++;
	}
	return true;
}
