//-------------------------------------------------------------------------------------//
bool CImageAPI::CloneImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *&pDest, bool Reverse)//複製圖像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) { return false; }	
	if ( 8 == BitCount ) 
	{	return CImageAPI::CloneGrayImage(ImageW, ImageH, ImageStep, pImage, pDest, Reverse); }
	if ( 24 == BitCount ) 
	{	return CImageAPI::CloneColorImage(ImageW, ImageH, ImageStep, pImage, pDest, Reverse); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CloneImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *pDest, bool Reverse)//複製圖像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) { return false; }	
	if ( 8 == BitCount ) 
	{	return CImageAPI::CloneGrayImage3(ImageW, ImageH, ImageStep, pImage, pDest, Reverse); }
	if ( 24 == BitCount ) 
	{	return CImageAPI::CloneColorImage3(ImageW, ImageH, ImageStep, pImage, pDest, Reverse); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CloneGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, unsigned char *&pDest, bool Reverse)//複製圖像
{
	const char fnName[] = ("CImageAPI::CloneGrayImage");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDest);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDest, fnName, "pDest") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->CloneGrayImage3(ImageW, ImageH, ImageStep, pImage, pDest, Reverse) == false )
	{
		JetMemory.free_func(pDest);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CloneGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, unsigned char *pDest, bool Reverse)//複製圖像
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDest) == false )
	{	return false; }	
	
	if ( true == Reverse )
	{
		if ( CImageAPI::CheckPtrNoRepeat2(pImage, pDest) == false )
		{	return false; }

		size_t i=0;
		size_t srcIdx=0;
		size_t destIdx=0;
		size_t CopyLen = sizeof(unsigned char)*ImageStep;
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			destIdx = (ImageH-i-1)*ImageStep;

			::memcpy(&(pDest[destIdx]), &(pImage[srcIdx]), sizeof(unsigned char)*ImageStep);
		}
	}
	else
	{
		const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
		if ( CImageAPI::CheckPtrNoRepeat2(pImage, pDest) == true )
		{	::memcpy(pDest, pImage, sizeof(unsigned char)*BufferSize);	}
	}
	return true;
}
