bool CImageAPI::CloneRGBImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char *&pDestR, unsigned char *&pDestG, unsigned char *&pDestB, bool Reverse)//複製圖像
{	
	const char fnName[] = ("CImageAPI::CloneRGBImage");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }

	JetMemory.free_func(pDestR);
	JetMemory.free_func(pDestG);
	JetMemory.free_func(pDestB);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDestR, fnName, "pDestR") == false ||
	     JetMemory.alloc_func(BufferSize, pDestG, fnName, "pDestG") == false ||
	     JetMemory.alloc_func(BufferSize, pDestB, fnName, "pDestB") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pDestR);
		JetMemory.free_func(pDestG);
		JetMemory.free_func(pDestB);
		return false;
	}
	if ( this->CloneRGBImage3(ImageW, ImageH, ImageStep, pR, pG, pB, pDestR, pDestG, pDestB, Reverse) == false )
	{
		JetMemory.free_func(pDestR);
		JetMemory.free_func(pDestG);
		JetMemory.free_func(pDestB);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CloneRGBImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char *pDestR, unsigned char *pDestG, unsigned char *pDestB, bool Reverse)//複製圖像
{
	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, pR, pG, pB, pDestR, pDestG, pDestB) == false )
	{	return false; }	

	if ( true == Reverse )
	{
		if ( CImageAPI::CheckPtrNoRepeat2(pR, pDestR) == false || 
			 CImageAPI::CheckPtrNoRepeat2(pG, pDestG) == false ||
			 CImageAPI::CheckPtrNoRepeat2(pB, pDestB) == false )
		{	return false; }

		size_t i=0;
		size_t srcIdx=0;
		size_t destIdx=0;
		const size_t CopyLen = sizeof(unsigned char)*ImageStep;
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			destIdx = (ImageH-i-1)*ImageStep;

			::memcpy(&(pDestR[destIdx]), &(pR[srcIdx]), CopyLen);
			::memcpy(&(pDestG[destIdx]), &(pG[srcIdx]), CopyLen);
			::memcpy(&(pDestB[destIdx]), &(pB[srcIdx]), CopyLen);
		}
	}
	else
	{	
		const size_t CopyLen = sizeof(unsigned char)*CalcBufferSize(ImageStep, ImageH);
		if ( CImageAPI::CheckPtrNoRepeat2(pR, pDestR) == true )
		{	::memcpy(pDestR, pR, CopyLen);	 }
		if ( CImageAPI::CheckPtrNoRepeat2(pG, pDestG) == true )
		{	::memcpy(pDestG, pG, CopyLen);	}
		if ( CImageAPI::CheckPtrNoRepeat2(pB, pDestB) == true )
		{	::memcpy(pDestB, pB, CopyLen);	}
	}
	return true;
}
