bool CImageAPI::RGBImageToGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, int StepGry, unsigned char *&pGray, float wR, float wG, float wB)//RGB轉灰階
{
	const char fnName[] = ("CImageAPI::RGBImageToGrayImage");
	if ( CImageAPI::CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( CImageAPI::CheckGraySize(ImageW, ImageH, StepGry) == false )
	{	return false; }	

	JetMemory.free_func(pGray);
	const size_t BufferSize = CalcBufferSize(StepGry, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pGray, fnName, "pGray") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->RGBImageToGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB, StepGry, pGray, wR, wG, wB) == false )
	{
		JetMemory.free_func(pGray);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RGBImageToGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, int StepGry, unsigned char *pGray, float wR, float wG, float wB)//RGB轉灰階
{
	if ( CImageAPI::CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, StepGry, pGray) == false )
	{	return false; }	


	float   val=0.0f;
	size_t  i=0, j=0;
	size_t  sIdx=0, gIdx=0;		
	const float wSum=wR+wG+wB;	
	if ( fabs(wSum) < 0.000001 )
	{ 
		::memset(pGray, 0x00, sizeof(IMAGE_DATA)*StepGry*ImageH);		
		return true; 
	}
	const float wR2=wR/wSum;
	const float wG2=wG/wSum;
	const float wB2=wB/wSum;	
	if ( ImageStep == StepGry )
	{
		const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
		for ( i=0; i<BufferSize; i++ )
		{
			//val = (pB[i]*wB)+(pG[i]*wG)+(pR[i]*wR);
			//val /= wSum;
			//if ( val < 0.0f ) { val = 0.0f; }
			//else if ( val > 255.0f ) { val = 255.0f; }
			//pGray[i] = (unsigned char)(val);

			val = (pB[i]*wB2)+(pG[i]*wG2)+(pR[i]*wR2);			
			pGray[i] = (unsigned char)(val);
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			gIdx = (i*StepGry);
			sIdx = (i*ImageStep);
			for ( j=0; j<ImageW; j++ )
			{			
				//val = (pB[sIdx]*wB)+(pG[sIdx]*wG)+(pR[sIdx]*wR);
				//val /= wSum;
				//if ( val < 0.0f ) { val = 0.0f; }
				//else if ( val > 255.0f ) { val = 255.0f; }
				//pGray[gIdx] = (unsigned char)(val);

				val = (pB[sIdx]*wB2)+(pG[sIdx]*wG2)+(pR[sIdx]*wR2);				
				pGray[gIdx] = (unsigned char)(val);

				gIdx ++;
				sIdx ++;
			}
		}
	}
	return true;
}
