bool CImageAPI::GrayImageConvertToPhase(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int StepShort, PHASE_PTR &PhasePtr, bool Reverse)//影像轉unsigned short
{
	const char fnName[] = ("CImageAPI::GrayImageConvertToPhase");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckGraySize(ImageW, ImageH, StepShort) == false )
	{	return false; }

	JetMemory.free_func(PhasePtr);
	const size_t BufferSize = CalcBufferSize(StepShort, ImageH);
	if ( JetMemory.alloc_func(BufferSize, PhasePtr, fnName, "PhasePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( GrayImageConvertToPhase3(ImageW, ImageH, ImageStep, pImage, StepShort, PhasePtr, Reverse) == false )
	{	
		JetMemory.free_func(PhasePtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageConvertToPhase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int StepShort, PHASE_PTR PhasePtr, bool Reverse)//影像轉unsigned short
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckGrayImage(ImageW, ImageH, StepShort, PhasePtr) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx=0, destIdx=0;
	int    Phase = 0;
	const int PhaseMin = PHASE_MIN;
	const size_t BitShift = IMG_SHIFT_PHASE_BIT;	
	if ( false == Reverse )
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			destIdx = i*StepShort;
			for ( j=0; j<ImageW; j++ )
			{	
				Phase= pImage[srcIdx];
				Phase = Phase< BitShift;				
				PhasePtr[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);
				srcIdx ++;
				destIdx ++;
			}
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = (ImageH-i-1)*ImageStep;
			destIdx = i*StepShort;
			for ( j=0; j<ImageW; j++ )
			{	
				Phase = pImage[srcIdx];	
				Phase = Phase<<BitShift;
				PhasePtr[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);				
				srcIdx ++;
				destIdx ++;
			}
		}
	}
	return true;
}
