//-------------------------------------------------------------------------------------//
bool CImageAPI::RGBImageConvertToPhase3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, int StepShort, PHASE_PTR pSR, PHASE_PTR pSG, PHASE_PTR pSB, bool Reverse)//RGB影像轉unsigned short
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckGrayImage3(ImageW, ImageH, StepShort, pSR, pSG, pSB) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx=0, destIdx=0;
	int    Phase = 0;
	const int PhaseMin = PHASE_MIN;
	const size_t BitShift = IMG_SHIFT_PHASE_BIT;
	if ( false == Reverse )
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			destIdx = i*StepShort;
			for ( j=0; j<ImageW; j++ )
			{	
				Phase = pR[srcIdx];	
				Phase = Phase<<BitShift;
				pSR[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);

				Phase = pG[srcIdx];	
				Phase = Phase<<BitShift;
				pSG[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);

				Phase = pB[srcIdx];	
				Phase = Phase<<BitShift;
				pSB[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);				

				destIdx ++;
				srcIdx  ++;
			}
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = (ImageH-i-1)*ImageStep;
			destIdx = i*StepShort;
			for ( j=0; j<ImageW; j++ )
			{
				Phase = pR[srcIdx];	
				Phase = Phase<<BitShift;
				pSR[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);

				Phase = pG[srcIdx];	
				Phase = Phase<<BitShift;
				pSG[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);

				Phase = pB[srcIdx];	
				Phase = Phase<<BitShift;
				pSB[destIdx] = static_cast<PHASE_DATA>(Phase+PhaseMin);
				
				destIdx ++;
				srcIdx  ++;
			}
		}
	}
	return true;
}
