//-------------------------------------------------------------------------------------//
bool CImageAPI::PhaseGrayImageConvertToGray3(IMAGE_SIZE PhaseW, IMAGE_SIZE PhaseH, IMAGE_SIZE PhaseStep, const PHASE_PTR pPhase, int ImageStep, unsigned char *pImage, bool Reverse)//unsigned short影像轉灰階
{
	if ( this->CheckGrayImage(PhaseW, PhaseH, PhaseStep, pPhase) == false )
	{	return false; }
	if ( this->CheckGrayImage(PhaseW, PhaseH, ImageStep, pImage) == false )
	{	return false; }
	
	int value = 0;
	size_t i=0, j=0, idx=0;
	size_t srcIdx=0, destIdx=0;	
	//const int  PhaseMin = 0;
	//const size_t BitShift = 7;
	//const int  PhaseMin = PHASE_MIN;	
	//const size_t BitShift = IMG_SHIFT_PHASE_BIT;
	const size_t BufferSize = CalcBufferSize(PhaseStep, PhaseH);
	
	PHASE_DATA  Phase = 0;
	PHASE_DATA  PhaseMin=PHASE_MAX;
	PHASE_DATA  PhaseMax=PHASE_MIN;
	for ( i=0; i<PhaseH; i++ )
	{
		idx = i*PhaseStep;
		for ( j=0; j<PhaseW; j++ )
		{
			if ( PhaseMin > pPhase[idx] ) { PhaseMin = pPhase[idx]; }
			if ( PhaseMax < pPhase[idx] ) { PhaseMax = pPhase[idx]; }
			idx ++;
		}
	}
	double PhaseNew = 0.0;
	double PhaseRange = PhaseMax-PhaseMin;
	double PhaseScale = PhaseRange/255;
	//PHASE_DATA PhaseRange = PhaseMax-PhaseMin;
	//PHASE_DATA PhaseScale = PhaseRange/255;
	if ( PhaseScale == 0 ) { PhaseScale = 1; }
	if ( false == Reverse )
	{
		for ( i=0; i<PhaseH; i++ )
		{
			srcIdx = i*PhaseStep;
			destIdx = i*ImageStep;
			for ( j=0; j<PhaseW; j++ )
			{
				PhaseNew = pPhase[srcIdx+j];
				PhaseNew -= PhaseMin;
				PhaseNew /= PhaseScale;	
				Phase = static_cast<unsigned char>(PhaseNew);				
				pImage[destIdx+j] = Phase;
			}
		}
	}
	else
	{
		for ( i=0; i<PhaseH; i++ )
		{
			srcIdx = (PhaseH-i-1)*PhaseStep;
			destIdx = i*ImageStep;
			for ( j=0; j<PhaseW; j++ )
			{
				PhaseNew = pPhase[srcIdx+j];
				PhaseNew -= PhaseMin;
				PhaseNew /= PhaseScale;
				Phase = static_cast<unsigned char>(PhaseNew);
				//pChar[destIdx+j] = (Phase) >> BitShift;					
				pImage[destIdx+j] = Phase;
			}
		}
	}
	return true;
}
