bool CImageAPI::SpaceGrayImageConvertToColor(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR pSpace, const MASK_PTR pMask, int ImageStep, unsigned char *&pImage, double Ratio, bool Reverse)//unsigned short影像轉彩色
{
	const char fnName[] = ("CImageAPI::SpaceGrayImageConvertToColor");
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, pSpace, pMask) == false )
	{	return false; }
	if ( this->CheckColorSize(SpaceW, SpaceH, ImageStep) == false )
	{	return false; }

	JetMemory.free_func(pImage);
	const size_t BufferSize = CalcBufferSize(ImageStep, SpaceH);
	if ( JetMemory.alloc_func(BufferSize, pImage, fnName, "pImage") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}	
	if ( SpaceGrayImageConvertToColor3(SpaceW, SpaceH, SpaceStep, pSpace, pMask, ImageStep, pImage, Ratio, Reverse) == false )
	{	
		JetMemory.free_func(pImage);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SpaceGrayImageConvertToColor3(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR pSpace, const MASK_PTR pMask, int ImageStep, unsigned char *pImage, double Ratio, bool Reverse)//unsigned short影像轉彩色
{
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, pSpace, pMask) == false )
	{	return false; }
	if ( this->CheckColorImage(SpaceW, SpaceH, ImageStep, pImage) == false )
	{	return false; }
	
	int value = 0;
	size_t i=0, j=0, k=0, idx=0;
	size_t srcIdx=0, destIdx=0;
	const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	COLORREF PhaseNoiseLowContrastColor = SysParam.m_PhaseNoiseLowContrastColor;
	COLORREF PhaseNoiseLowPotentialColor = SysParam.m_PhaseNoiseLowPotentialColor;
	COLORREF PhaseNoiseOverSaturatedColor = SysParam.m_PhaseNoiseOverSaturatedColor;
	COLORREF PhaseNoiseExtendVoidColor = SysParam.m_PhaseNoiseExtendVoidColor;
	COLORREF SpaceNoiseHeightUnexpectedColor = SysParam.m_SpaceNoiseHeightUnexpectedColor;
	COLORREF SpaceNoiseOverLowColor = SysParam.m_SpaceNoiseHeightOverLowColor;		
	const unsigned char LowContrastClrRed   = GetRValue(PhaseNoiseLowContrastColor);
	const unsigned char LowContrastClrGreen = GetGValue(PhaseNoiseLowContrastColor);
	const unsigned char LowContrastClrBlue  = GetBValue(PhaseNoiseLowContrastColor);
	const unsigned char LowPotentialClrRed   = GetRValue(PhaseNoiseLowPotentialColor);
	const unsigned char LowPotentialClrGreen = GetGValue(PhaseNoiseLowPotentialColor);
	const unsigned char LowPotentialClrBlue  = GetBValue(PhaseNoiseLowPotentialColor);
	const unsigned char OverSaturatedClrRed   = GetRValue(PhaseNoiseOverSaturatedColor);
	const unsigned char OverSaturatedClrGreen = GetGValue(PhaseNoiseOverSaturatedColor);
	const unsigned char OverSaturatedClrBlue  = GetBValue(PhaseNoiseOverSaturatedColor);
	const unsigned char ExtendVoidClrRed   = GetRValue(PhaseNoiseExtendVoidColor);
	const unsigned char ExtendVoidClrGreen = GetGValue(PhaseNoiseExtendVoidColor);
	const unsigned char ExtendVoidClrBlue  = GetBValue(PhaseNoiseExtendVoidColor);
	const unsigned char HeightUnexpectedClrRed   = GetRValue(SpaceNoiseHeightUnexpectedColor);
	const unsigned char HeightUnexpectedClrGreen = GetGValue(SpaceNoiseHeightUnexpectedColor);
	const unsigned char HeightUnexpectedClrBlue  = GetBValue(SpaceNoiseHeightUnexpectedColor);
	const unsigned char HeightOverLowClrRed   = GetRValue(SpaceNoiseOverLowColor);
	const unsigned char HeightOverLowClrGreen = GetGValue(SpaceNoiseOverLowColor);
	const unsigned char HeightOverLowClrBlue  = GetBValue(SpaceNoiseOverLowColor);

	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	int         nGray=0;
	SPACE_DATA  Space = 0;
	SPACE_DATA  SpaceMin=SPACE_MAX;
	SPACE_DATA  SpaceMax=SPACE_MIN;
	SPACE_DATA  UNWRAP_DATA_AVOID_VALUE = UNWRAP_DATA_AVOID-1;	
	SPACE_DATA SpaceRange = 0;
	SPACE_DATA SpaceScale = 1;

	if ( Ratio <= 0 ) 
	{
		for ( i=0; i<SpaceH; i++ )
		{
			idx = i*SpaceStep;
			for ( j=0; j<SpaceW; j++ )
			{
				if ( (pMask[idx]&PHASE_MASK_NOISE)!=NULL ) 
				{
					idx ++;
					continue; 
				}
				if ( SpaceMin > pSpace[idx] ) { SpaceMin = pSpace[idx]; }
				if ( SpaceMax < pSpace[idx] ) { SpaceMax = pSpace[idx]; }
				idx ++;
			}
		}	
		SpaceRange = SpaceMax-SpaceMin;
		SpaceScale = SpaceRange/255;
	}
	else
	{
		SpaceMin = 0.0f;
		SpaceScale = (SPACE_DATA)(1.00/Ratio);
	}
	if ( fabs(SpaceRange) < 0.0001 )	{ SpaceScale = 1.0f; }
	if ( false == Reverse )
	{
		for ( i=0; i<SpaceH; i++ )
		{
			k=0;
			srcIdx = i*SpaceStep;
			destIdx = i*ImageStep;
			for ( j=0; j<SpaceW; j++ )
			{
				if ( (pMask[srcIdx+j]&PHASE_MASK_LOW_CONTRAST)!=NULL )
				{ 
					pImage[destIdx+k] = LowContrastClrBlue;
					pImage[destIdx+k+1] = LowContrastClrGreen;
					pImage[destIdx+k+2] = LowContrastClrRed;
					k += 3;
					continue; 
				}				
				if ( (pMask[srcIdx+j]&PHASE_MASK_LOW_POTENTIAL)!=NULL )
				{ 
					pImage[destIdx+k] = LowPotentialClrBlue;
					pImage[destIdx+k+1] = LowPotentialClrGreen;
					pImage[destIdx+k+2] = LowPotentialClrRed;
					k += 3;
					continue; 
				}
				if ( (pMask[srcIdx+j]&PHASE_MASK_OVER_SATURATED)!=NULL )
				{ 
					pImage[destIdx+k] = OverSaturatedClrBlue;
					pImage[destIdx+k+1] = OverSaturatedClrGreen;
					pImage[destIdx+k+2] = OverSaturatedClrRed;
					k += 3;
					continue; 
				}
				if ( (pMask[srcIdx+j]&PHASE_MASK_EXTEND_VOID)!=NULL )
				{ 
					pImage[destIdx+k] = ExtendVoidClrBlue;
					pImage[destIdx+k+1] = ExtendVoidClrGreen;
					pImage[destIdx+k+2] = ExtendVoidClrRed;
					k += 3;
					continue; 
				}
				if ( (pMask[srcIdx+j]&PHASE_MASK_HEIGHT_UNEXPECTED)!=NULL )
				{ 
					pImage[destIdx+k] = HeightUnexpectedClrBlue;
					pImage[destIdx+k+1] = HeightUnexpectedClrGreen;
					pImage[destIdx+k+2] = HeightUnexpectedClrRed;
					k += 3;
					continue; 
				}
				if ( (pMask[srcIdx+j]&PHASE_MASK_OVER_LOW)!=NULL )
				{ 
					pImage[destIdx+k] = HeightOverLowClrBlue;
					pImage[destIdx+k+1] = HeightOverLowClrGreen;
					pImage[destIdx+k+2] = HeightOverLowClrRed;
					k += 3;
					continue; 
				}				
				Space = pSpace[srcIdx+j];				
				Space -= SpaceMin;
				Space /= SpaceScale;

				nGray = static_cast<int>(Space);
				if ( nGray > 255 )
				{	pImage[destIdx+k] = 255; }
				else if ( nGray < 0 )
				{	pImage[destIdx+k] = 0; }
				else
				{	pImage[destIdx+k] = static_cast<unsigned char>(nGray); }				
				pImage[destIdx+k+2] = pImage[destIdx+k+1] = pImage[destIdx+k];
				k += 3;
			}
		}
	}
	else
	{
		for ( i=0; i<SpaceH; i++ )
		{
			k=0;
			srcIdx = (SpaceH-i-1)*SpaceStep;
			destIdx = i*ImageStep;
			for ( j=0; j<SpaceW; j++ )
			{				
				if ( (pMask[srcIdx+j]&PHASE_MASK_LOW_CONTRAST)!=NULL )
				{ 
					pImage[destIdx+k] = LowContrastClrBlue;
					pImage[destIdx+k+1] = LowContrastClrGreen;
					pImage[destIdx+k+2] = LowContrastClrRed;
					k += 3;
					continue; 
				}				
				if ( (pMask[srcIdx+j]&PHASE_MASK_LOW_POTENTIAL)!=NULL )
				{ 
					pImage[destIdx+k] = LowPotentialClrBlue;
					pImage[destIdx+k+1] = LowPotentialClrGreen;
					pImage[destIdx+k+2] = LowPotentialClrRed;
					k += 3;
					continue; 
				}	
				if ( (pMask[srcIdx+j]&PHASE_MASK_OVER_SATURATED)!=NULL )
				{ 
					pImage[destIdx+k] = OverSaturatedClrBlue;
					pImage[destIdx+k+1] = OverSaturatedClrGreen;
					pImage[destIdx+k+2] = OverSaturatedClrRed;
					k += 3;
					continue; 
				}	
				if ( (pMask[srcIdx+j]&PHASE_MASK_EXTEND_VOID)!=NULL )
				{ 
					pImage[destIdx+k] = ExtendVoidClrBlue;
					pImage[destIdx+k+1] = ExtendVoidClrGreen;
					pImage[destIdx+k+2] = ExtendVoidClrRed;
					k += 3;
					continue; 
				}
				if ( (pMask[srcIdx+j]&PHASE_MASK_HEIGHT_UNEXPECTED)!=NULL )
				{ 
					pImage[destIdx+k] = HeightUnexpectedClrBlue;
					pImage[destIdx+k+1] = HeightUnexpectedClrGreen;
					pImage[destIdx+k+2] = HeightUnexpectedClrRed;
					k += 3;
					continue; 
				}
				Space = pSpace[srcIdx+j];				
				Space -= SpaceMin;
				Space /= SpaceScale;
				//pChar[destIdx+j] = (Space) >> BitShift;	
				nGray = static_cast<int>(Space);
				if ( nGray > 255 )
				{	pImage[destIdx+k] = 255; }
				else if ( nGray < 0 )
				{	pImage[destIdx+k] = 0; }
				else
				{	pImage[destIdx+k] = static_cast<unsigned char>(nGray); }	
				pImage[destIdx+k+2] = pImage[destIdx+k+1] = pImage[destIdx+k];
				k += 3;
			}
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractUniRoiImage(const TUNI_FRAME &UniFrame, const RECT &RoiRect, int nAlign, const char *fnName, TUNI_FRAME &RoiFrame)
{	
	IMAGE_SIZE ImageW = UniFrame.ImageW;
	IMAGE_SIZE ImageH = UniFrame.ImageH;
	IMAGE_SIZE ImageStep = UniFrame.ImageStep;
	IMAGE_SIZE BitCount = UniFrame.BitCount;
	IMAGE_SIZE GrayBitCount = 8;
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	MASK_PTR   RoiMaskPtr=NULL;
	PHASE_PTR  RoiPhasePtr=NULL;
	SPACE_PTR  RoiSpacePtr=NULL;
	IMAGE_PTR  RoiImagePtr=NULL;	
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	const int RoiStep = GetImageAlignedWidth(RoiW, BitCount, nAlign);
	const int GraykStep = GetImageAlignedWidth(RoiW, GrayBitCount, nAlign);
	const size_t RoiBufferSize = CalcBufferSize(RoiStep, RoiH);
	const size_t GrayBufferSize = CalcBufferSize(GraykStep, RoiH);
	if ( NULL != UniFrame.ImagePtr )
	{
		if ( JetMemory.alloc_func(RoiBufferSize, RoiImagePtr, fnName, "RoiImagePtr") == false )
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		if ( ExtractRoiImage3(ImageW, ImageH, ImageStep, BitCount, UniFrame.ImagePtr, RoiRect, RoiStep, RoiImagePtr, false) == false )
		{
			JetMemory.free_func(RoiImagePtr);
			return false;
		}				
	}

	if ( NULL != UniFrame.MaskPtr )
	{
		if ( 8 != BitCount )
		{	RoiMaskPtr = NULL; }

		if ( JetMemory.alloc_func(GrayBufferSize, RoiMaskPtr, fnName, "RoiMaskPtr") == false )
		{
			JetMemory.free_func(RoiImagePtr);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		if ( ExtractRoiImage3(ImageW, ImageH, ImageStep, GrayBitCount, UniFrame.MaskPtr, RoiRect, GraykStep, RoiMaskPtr, false) == false )
		{
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiImagePtr);			
			return false;
		}				
	}
	if ( NULL != UniFrame.PhasePtr )
	{
		if ( 8 != BitCount )
		{	RoiPhasePtr = NULL; }

		if ( JetMemory.alloc_func(GrayBufferSize, RoiPhasePtr, fnName, "RoiPhasePtr") == false )
		{
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiImagePtr);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		if ( ExtractPhaseGrayRoiImage3(ImageW, ImageH, ImageStep, UniFrame.PhasePtr, RoiRect, GraykStep, RoiPhasePtr, false) == false )
		{
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiPhasePtr);			
			JetMemory.free_func(RoiImagePtr);
			return false;
		}				
	}
	if ( NULL != UniFrame.SpacePtr )
	{
		if ( 8 != BitCount )
		{	RoiSpacePtr = NULL; }

		if ( JetMemory.alloc_func(GrayBufferSize, RoiSpacePtr, fnName, "RoiSpacePtr") == false )
		{
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiPhasePtr);
			JetMemory.free_func(RoiImagePtr);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		if ( ExtractSpaceGrayRoiImage3(ImageW, ImageH, ImageStep, UniFrame.SpacePtr, RoiRect, GraykStep, RoiSpacePtr, false) == false )
		{
			JetMemory.free_func(RoiMaskPtr);
			JetMemory.free_func(RoiPhasePtr);
			JetMemory.free_func(RoiSpacePtr);
			JetMemory.free_func(RoiImagePtr);
			return false;
		}				
	}
	RoiFrame.ImageW = RoiW;
	RoiFrame.ImageH = RoiH;
	RoiFrame.ImageStep = RoiStep;
	RoiFrame.BitCount = BitCount;
	RoiFrame.ImagePtr = RoiImagePtr;
	RoiFrame.MaskPtr = RoiMaskPtr;
	RoiFrame.PhasePtr = RoiPhasePtr;
	RoiFrame.SpacePtr = RoiSpacePtr;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractRoiImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *&pRoi, bool Reverse)//切割子影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return  this->ExtractGrayRoiImage(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	if ( 24 == BitCount ) 
	{	return  this->ExtractColorRoiImage(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi, bool Reverse)//切割子影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return  this->ExtractGrayRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	if ( 24 == BitCount ) 
	{	return  this->ExtractColorRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractGrayRoiImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *&pRoi, bool Reverse)//灰階切割子影像
{
	const char fnName[] = ("CImageAPI::ExtractGrayRoiImage");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckGraySize(RoiW, RoiH, RoiStep) == false )
	{	return false; }

	JetMemory.free_func(pRoi);
	const size_t BufferSize = CalcBufferSize(RoiStep, RoiH);
	if ( JetMemory.alloc_func(BufferSize, pRoi, fnName, "pRoi") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	::memset(pRoi, 0x00, sizeof(unsigned char)*BufferSize);
	if ( this->ExtractGrayRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse) == false )
	{
		JetMemory.free_func(pRoi);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractGrayRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi, bool Reverse)//灰階切割子影像
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckGrayImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	int i=0, j=0;
	size_t gryIdx1=0;
	size_t roiIdx1=0;		 
	const size_t szRoiStep = RoiStep;	
	const size_t szImageStep = ImageStep;	
	const size_t szRoiRectT = RoiRect.top;
	const size_t szRoiRectL = RoiRect.left;
	const size_t size_roi_w = sizeof(unsigned char)*RoiW;

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (RoiH-i+szRoiRectT-1)*szRoiStep;
			gryIdx1 = (i*szImageStep)+szRoiRectL;
			::memcpy(&(pRoi[roiIdx1]), &(pImage[gryIdx1]), size_roi_w);			
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (i-szRoiRectT)*szRoiStep;
			gryIdx1 = (i*szImageStep)+szRoiRectL;
			::memcpy(&(pRoi[roiIdx1]), &(pImage[gryIdx1]), size_roi_w);			
		}
	}
	return true;
}
