bool CImageAPI::ExtractColorRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi, bool Reverse)//灰階切割子影像
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckColorImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	int i=0, j=0;
	size_t clrIdx1=0;
	size_t roiIdx1=0;		 
	const size_t szRoiStep = RoiStep;	
	const size_t szImageStep = ImageStep;	
	const size_t szRoiRectT = RoiRect.top;
	const size_t szRoiRectL = RoiRect.left;
	const size_t size_roi_w = sizeof(unsigned char)*RoiW*3;

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (RoiH-i+szRoiRectT-1)*szRoiStep;
			clrIdx1 = (i*szImageStep)+(szRoiRectL*3);
			::memcpy(&(pRoi[roiIdx1]), &(pImage[clrIdx1]), size_roi_w);
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (i-szRoiRectT)*szRoiStep;
			clrIdx1 = (i*szImageStep)+(szRoiRectL*3);
			::memcpy(&(pRoi[roiIdx1]), &(pImage[clrIdx1]), size_roi_w);
		}
	}
	return true;
}
