//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractRGBRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoiClr, bool Reverse)//RGB切割子影像
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckColorImage(RoiW, RoiH, RoiStep, pRoiClr) == false )
	{	return false; }

	int i=0, j=0;
	size_t gryIdx1=0;
	size_t roiIdx1=0;
	const size_t szRoiStep = RoiStep;	
	const size_t szImageStep = ImageStep;	
	const size_t szRoiRectT = RoiRect.top;
	const size_t szRoiRectL = RoiRect.left;
	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (RoiH-i+szRoiRectT-1)*szRoiStep;
			gryIdx1 = (i*szImageStep)+szRoiRectL;
			for ( j=RoiRect.left; j<RoiRect.right; j++ )
			{
				pRoiClr[roiIdx1] = pB[gryIdx1]; roiIdx1++;
				pRoiClr[roiIdx1] = pG[gryIdx1]; roiIdx1++;
				pRoiClr[roiIdx1] = pB[gryIdx1]; roiIdx1++;
				gryIdx1 ++;
			}
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (i-szRoiRectT)*szRoiStep;
			gryIdx1 = (i*szImageStep)+szRoiRectL;
			for ( j=RoiRect.left; j<RoiRect.right; j++ )
			{
				pRoiClr[roiIdx1] = pB[gryIdx1]; roiIdx1++;
				pRoiClr[roiIdx1] = pG[gryIdx1]; roiIdx1++;
				pRoiClr[roiIdx1] = pB[gryIdx1]; roiIdx1++;
				gryIdx1 ++;
			}
		}
	}
	return true;
}
