{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckGrayImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	int i=0, j=0;
	int gryIdx1=0;
	int roiIdx1=0;
	const size_t size_roi_w = sizeof(PHASE_DATA)*RoiW;
	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (RoiH-i+RoiRect.top-1)*RoiStep;
			gryIdx1 = (i*ImageStep)+RoiRect.left;
			::memcpy(&(pRoi[roiIdx1]), &(pImage[gryIdx1]), size_roi_w);			
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			roiIdx1 = (i-RoiRect.top)*RoiStep;
			gryIdx1 = (i*ImageStep)+RoiRect.left;
			::memcpy(&(pRoi[roiIdx1]), &(pImage[gryIdx1]), size_roi_w);			
		}
	}
	return true;	
}
