bool CImageAPI::ExtractSpaceRoiImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const SPACE_PTR pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, SPACE_PTR &pRoi, bool Reverse)//切割子影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false )
	{	return false; }
	if (  8 == BitCount ) 
	{	return ExtractSpaceGrayRoiImage(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	if ( 24 == BitCount ) 
	{	return ExtractSpaceColorRoiImage(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse); }
	return false;	
}
