bool CImageAPI::ExtractRoiImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const TRECT4D &RoiRect, IMAGE_SIZE RoiStep, unsigned char *&pRoi, bool Reverse)//切割子影像
{
	const char fnName[] = ("CImageAPI::ExtractRoiImage");
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = CImageAPI::Floor(RoiRect.right-RoiRect.left);
	const int RoiH = CImageAPI::Floor(RoiRect.bottom-RoiRect.top);
	if ( this->CheckGraySize(RoiW, RoiH, RoiStep) == false )
	{	return false; }

	JetMemory.free_func(pRoi);
	const size_t BufferSize = CalcBufferSize(RoiStep, RoiH);
	if ( JetMemory.alloc_func(BufferSize, pRoi, fnName, "pRoi") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	//::memset(pRoi, 0x00, sizeof(unsigned char)*BufferSize);
	if ( this->ExtractRoiImage3(ImageW, ImageH, ImageStep, BitCount, pImage, RoiRect, RoiStep, pRoi, Reverse) == false )
	{
		JetMemory.free_func(pRoi);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const TRECT4D &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi, bool Reverse)//切割子影像	
{
	const char fnName[] = "CImageAPI::ExtractRoiImage3";
	const int RoiW = CImageAPI::Floor(RoiRect.right-RoiRect.left);
	const int RoiH = CImageAPI::Floor(RoiRect.bottom-RoiRect.top);
	if ( this->CheckImage(RoiW, RoiH, RoiStep, BitCount, pRoi) == false ) 
	{	return false; }
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false ) 
	{	return false; }	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }
#ifndef OPENCV_DISABLE
	try
	{	
		cv::Mat MatDst=CreateMat(RoiW, RoiH, RoiStep, BitCount, pRoi);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);		
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		const float CpX=(float)((RoiRect.left+RoiRect.right)*0.5);
		const float CpY=(float)((RoiRect.top+RoiRect.bottom)*0.5);
		cv::getRectSubPix(MatSrc, cv::Size(RoiW,RoiH), cv::Point2f(CpX, CpY), MatDst);
		if ( CloneMatData(MatDst, RoiW, RoiH, RoiStep, BitCount, pRoi) == false )
		{	return false;	}
		if ( true == Reverse )
		{
			unsigned char *TempPtr=NULL;
			const size_t TmpSize=CalcBufferSize(RoiStep, RoiH);
			if ( JetMemory.alloc_func(TmpSize, TempPtr, fnName, "TempPtr") == false )
			{
				SetErrorString(JetMemory.GetErrorString());
				return false;
			}
			::memcpy(TempPtr, pRoi, sizeof(unsigned char)*TmpSize);
			if ( ReverseImage(RoiW, RoiH, RoiStep, BitCount, TempPtr, pRoi) == false )
			{
				JetMemory.free_func(TempPtr);
				return false;
			}
			JetMemory.free_func(TempPtr);
		}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);
		return false;
	}		
#else
	RECT nRoiRect;
	nRoiRect.left = CImageAPI::Floor(RoiRect.left);
	nRoiRect.top = CImageAPI::Floor(RoiRect.top);
	nRoiRect.right = CImageAPI::Floor(RoiRect.right);
	nRoiRect.bottom = CImageAPI::Floor(RoiRect.bottom);
	if ( CImageAPI::ExtractRoiImage3(ImageW, ImageH, ImageStep, pImage, nRoiRect, RoiStep, pRoi, Reverse) == false ) 
	{	return false; }	
#endif//OPENCV_DISABLE
	return true;
}
