bool CImageAPI::ExtractDynamicRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi)//動態切割子影像	
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return  this->ExtractDynamicGrayRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi); }
	if ( 24 == BitCount ) 
	{	return  this->ExtractDynamicColorRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi); }
	return false;
}
