bool CImageAPI::ExtractDynamicColorRoiImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *&pRoi)
{
	const char fnName[] = ("CImageAPI::ExtractDynamicColorRoiImage");
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }	

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckColorSize(RoiW, RoiH, RoiStep) == false )
	{	return false; }

	JetMemory.free_func(pRoi);
	const size_t BufferSize = CalcBufferSize(RoiStep, RoiH);
	if ( JetMemory.alloc_func(BufferSize, pRoi, fnName, "pRoi") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}	
	
	if ( this->ExtractDynamicColorRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi) == false )
	{
		JetMemory.free_func(pRoi);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ExtractDynamicColorRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *pRoi)
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }	

	const int nImageW=(int)(ImageW);
	const int nImageH=(int)(ImageH);	
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckColorImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	const size_t RoiSize=CalcBufferSize(RoiStep, RoiH);
	::memset(pRoi, 0x00, sizeof(unsigned char)*RoiSize);
	if ( RoiRect.left>nImageW || RoiRect.top>nImageH || RoiRect.right<0 || RoiRect.bottom<0 )
	{	return true; }

	const int Channels=3;
	int RoiX=0, RoiY=0;//Roi上座標	
	int ImgX=RoiRect.left, ImgY=RoiRect.top;//影像上座標
	int CopyLenX = RoiRect.right-RoiRect.left;
	int CopyLenY = RoiRect.bottom-RoiRect.top;
	
	if ( RoiRect.left < 0 )
	{	ImgX = 0;	RoiX = -RoiRect.left;	}
	if ( RoiRect.top < 0 )
	{	ImgY = 0;	RoiY = -RoiRect.top;	}
	CopyLenX = MIN(CopyLenX, (ImageW-ImgX));
	CopyLenY = MIN(CopyLenY, (ImageH-ImgY));
	CopyLenX = MIN(CopyLenX, (RoiW-RoiX));
	CopyLenY = MIN(CopyLenY, (RoiH-RoiY));
	CopyLenX *=Channels;
	if ( CopyLenX<0 || CopyLenY<0 )
	{	return false;	}

	RoiX *= Channels;
	ImgX *= Channels;
	for ( int i=0; i<CopyLenY; i++ )
	{
		const int RoiIdx=((RoiY+i)*RoiStep)+RoiX;
		const int ImgIdx=((ImgY+i)*ImageStep)+ImgX;
		::memcpy(&pRoi[RoiIdx], &pImage[ImgIdx], sizeof(unsigned char)*CopyLenX);
	}
	return true;
}
