bool CImageAPI::ReverseImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *&pDst)//反向影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false )
	{	return false; }
	if (  8 == BitCount ) 
	{	return ReverseGrayImage(ImageW, ImageH, ImageStep, pImage, pDst); }
	if ( 24 == BitCount ) 
	{	return ReverseColorImage(ImageW, ImageH, ImageStep, pImage, pDst); }
	return false;
}
