{
	const char fnName[] = ("CImageAPI::ReverseGrayImage");
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( CImageAPI::ReverseGrayImage3(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ReverseGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, unsigned char *pDst)//反向灰階影像
{
	if ( CImageAPI::CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	if ( CImageAPI::CheckPtrNoRepeat2(pImage, pDst) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx=0, srcDst=0;
	const size_t CopyLen = sizeof(unsigned char)*ImageStep;
	for ( i=0; i<ImageH; i++ )
	{
		srcIdx = i*ImageStep;
		srcDst = (ImageH-i-1)*ImageStep;
		::memcpy(&(pDst[srcDst]), &(pImage[srcIdx]), CopyLen);
	}
	return true;
}
