{
	const char fnName[] = ("CImageAPI::MoveGrayImage");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false ) 
	{	return false; }	

	JetMemory.free_func(DstPtr);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->MoveGrayImage3(ImageW, ImageH, ImageStep, pImage, sX, sY, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);		
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MoveGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int sX, int sY, unsigned char *DstPtr)//移動灰階影像
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, DstPtr) == false ) 
	{	return false; }	
	
	int   szW=0, szH=0;
	RECT  rcSrc={0,0,0,0};
	RECT  rcDst={0,0,0,0};
	const int DstW=(int)(ImageW);//須轉成int 否則比較負數可能會有問題
	const int DstH=(int)(ImageH);//須轉成int 否則比較負數可能會有問題
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);	
	::memset(DstPtr, 0x00, sizeof(unsigned char)*BufferSize);

	szW = DstW;
	szH = DstH;
	rcSrc.right=DstW;
	rcSrc.bottom=DstH;
	rcDst = rcSrc;
	rcDst.left  += sX;
	rcDst.right += sX;
	rcDst.top   -= sY;
	rcDst.bottom-= sY;		
	if ( rcDst.right > DstW )
	{	
		rcDst.right = DstW;
		szW=rcDst.right-rcDst.left;
		if ( szW < 0 ) { return true; }
		rcSrc.right = rcSrc.left+szW;
	}
	else if ( rcDst.left < 0 )
	{
		rcDst.left = 0;
		szW=rcDst.right-rcDst.left;
		if ( szW < 0 ) { return true; }
		rcSrc.left = rcSrc.right-szW;
	}

	if ( rcDst.bottom > DstH )
	{	
		rcDst.bottom = DstH;
		szH=rcDst.bottom-rcDst.top;
		if ( szH < 0 ) { return true; }		
		rcSrc.bottom = rcSrc.top+szH;
	}
	else if ( rcDst.top < 0 )
	{
		rcDst.top = 0;
		szH=rcDst.bottom-rcDst.top;
		if ( szH < 0 ) { return true; }
		rcSrc.top = rcSrc.bottom-szH;
	}
	if ( rcDst.top<0 || rcDst.left<0 || rcDst.right>ImageW || rcDst.bottom>ImageH )
	{	return true; }

	int i=0;
	int idxSrc=0, idxDst=0;	
	const int CopyLen=sizeof(unsigned char)*(szW);
	for ( i=0; i<szH; i++ )
	{
		idxSrc=((i+rcSrc.top)*ImageStep)+(rcSrc.left);
		idxDst=((i+rcDst.top)*ImageStep)+(rcDst.left);
		::memcpy(&DstPtr[idxDst], &pImage[idxSrc], CopyLen);		
	}
	return true;
}
