bool CImageAPI::RotateGrayImage3_180(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//灰階影像旋轉
{
	IMAGE_SIZE BitCount = 8;
	if ( RotateImage3_180(ImageW, ImageH, ImageStep, BitCount, pImage, DstW, DstH, DstStep, pDst) == false )
	{	return false; }
	return true;

	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstW || ImageH!=DstH )
	{
		this->m_ErrorString.Format(_T("Error, Image size is exception"));
		return false;
	}
	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRow=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{
		SrcIdxRow = ((DstH-i-1)*ImageStep)+DstW-1;
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = SrcIdxRow-j;
			DstIdx = DstIdxRow+j;
			pDst[DstIdx] = pImage[SrcIdx];
		}
	}
	return true;
}
