bool CImageAPI::RotateColorImage3_090(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//彩色影像旋轉
{
	IMAGE_SIZE BitCount = 24;
	if ( RotateImage3_090(ImageW, ImageH, ImageStep, BitCount, pImage, DstW, DstH, DstStep, pDst) == false )
	{	return false; }
	return true;

	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckColorImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstH || ImageH!=DstW )
	{
		this->m_ErrorString.Format(_T("Error, Image size is exception"));
		return false;
	}	
	
	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRds=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{	
		SrcIdxRds = (DstH-i-1)*3;
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = (j*ImageStep)+SrcIdxRds;
			DstIdx = DstIdxRow+(j*3);
			pDst[DstIdx] = pImage[SrcIdx];
			pDst[DstIdx+1] = pImage[SrcIdx+1];
			pDst[DstIdx+2] = pImage[SrcIdx+2];
		}
	}
	return true;
}
