bool CImageAPI::RotateColorImage3_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//彩色影像旋轉
{
	IMAGE_SIZE BitCount = 24;
	if ( RotateImage3_Any(Angle, ImageW, ImageH, ImageStep, BitCount, pImage, DstW, DstH, DstStep, pDst) == false )
	{	return false; }
	return true;

	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckColorImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	const int ImageSizeSrc  = (int)(ImageStep*ImageH);
	const int ImageSizeDest = (int)(DstStep*DstH);	

	int i=0, j=0, m=0, n=0;
	double x=0, y=0, p=0, q=0;	
	int dR=0, d1R=0, d2R=0, d3R=0, d4R=0;
	int dG=0, d1G=0, d2G=0, d3G=0, d4G=0;
	int dB=0, d1B=0, d2B=0, d3B=0, d4B=0;
	int index = 0;
	int idx1=0, idx2=0, idx3=0, idx4=0;

	const int nChannels = 3;
	const int xt = (int)(ImageW/2);
	const int yt = (int)(ImageH/2);	
	const int BytePerLine = (int)(ImageStep);
	const int NewImageW = (int)(DstW);
	const int NewImageH = (int)(DstH);
	const int DestBytePerLine = (int)(DstStep);
	const int xs = NewImageW/2;
	const int ys = NewImageH/2;	
	double r = Angle*DEG_TO_RAD_DBL;
	double c = (double)(cos(r));
	double s = (double)(sin(r));	

	int StartI=0, EndI=0;
	int StartJ=0, EndJ=0;
	RECT *pCareRect = NULL;
	if ( pCareRect == NULL )
	{
		StartI = -ys;
		EndI   =  ys;
		StartJ = -xs;
		EndJ   =  xs;
	}
	else
	{
		StartI = pCareRect->top;
		EndI   = pCareRect->bottom;
		StartJ = pCareRect->left;
		EndJ   = pCareRect->right;

		StartI = StartI-ys;
		EndI   = EndI-ys;
		StartJ = StartJ-xs;
		EndJ   = EndJ-xs;
	}

	//for ( i=-ys; i<ys; i++ )//目的影像的引數-Y
	for ( i=StartI; i<EndI; i++ )//目的影像的引數-Y
	{
		//for ( j=-xs; j<xs; j++ )//目的影像的引數-X
		for ( j=StartJ; j<EndJ; j++ )//目的影像的引數-X
		{
			y = j*s + i*c;//來源影像的Y
			x = j*c - i*s;//來源影像的X

			if ( y > 0 ) { m = (int)y; }
			else {	m = (int)(y-1);	}

			if ( x > 0 ) { n = (int)x; }
			else { n = (int)(x-1); }

			q = y - m;
			p = x - n;

			if ( q == 1 ) { q = 0; m = m+1; }
			if ( p == 1 ) { p = 0; n = n+1; }
			if ( m<-yt || m>=yt || n<-xt || n>=xt )
			{
				index = (i+ys)*DestBytePerLine+(j+xs)*nChannels;
				pDst[index]   = 0 ; 
				pDst[index+1] = 0 ; 
				pDst[index+2] = 0 ;				
				continue; 
			}
			
			idx1 = (m+yt)*BytePerLine+(n+xt)*nChannels;
			idx2 = idx1+nChannels; //(m+yt)*BytePerLine+(n+xt+1)*nChannels;
			idx3 = idx1+BytePerLine;//(m+yt+1)*BytePerLine+(n+xt)*nChannels;
			idx4 = idx3+nChannels;//(m+yt+1)*BytePerLine+(n+xt+1)*nChannels;
			if ( idx1>=ImageSizeSrc || idx2>=ImageSizeSrc || idx3>=ImageSizeSrc || idx4>=ImageSizeSrc )
			{
				index = (i+ys)*DestBytePerLine+(j+xs)*nChannels;
				pDst[index]   = 0 ; 
				pDst[index+1] = 0 ; 
				pDst[index+2] = 0 ; 
				continue; 
			}
			d1R = pImage[idx1+2];
			d1G = pImage[idx1+1];
			d1B = pImage[idx1];

			d2R = pImage[idx2+2];
			d2G = pImage[idx2+1];
			d2B = pImage[idx2];

			d3R = pImage[idx3+2];
			d3G = pImage[idx3+1];
			d3B = pImage[idx3];

			d4R = pImage[idx4+2];
			d4G = pImage[idx4+1];
			d4B = pImage[idx4];

			dR = (int)((1.0-q)*((1.0-p)*d1R+p*d2R)+q*((1.0-p)*d3R+p*d4R));
			dG = (int)((1.0-q)*((1.0-p)*d1G+p*d2G)+q*((1.0-p)*d3G+p*d4G));
			dB = (int)((1.0-q)*((1.0-p)*d1B+p*d2B)+q*((1.0-p)*d3B+p*d4B));
			if ( dR < 0 ) { dR = 0; }
			else
			{
				if ( dR > 255 ) { dR = 255; }
			}
			if ( dG < 0 ) { dG = 0; }
			else
			{
				if ( dG > 255 ) { dG = 255; }
			}
			if ( dB < 0 ) { dB = 0; }
			else
			{
				if ( dB > 255 ) { dB = 255; }
			}			
			index = (i+ys)*DestBytePerLine+(j+xs)*nChannels;
			pDst[index+2] = dR; 
			pDst[index+1] = dG; 
			pDst[index]   = dB; 
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDstR, unsigned char *&pDstG, unsigned char *&pDstB)//RGB影像旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateRGBImage_000(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateRGBImage_090(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateRGBImage_180(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateRGBImage_270(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else
	{	bIsOK = RotateRGBImage_Any(Angle, ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}	
	return bIsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage3(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB)//RGB影像旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateRGBImage3_000(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateRGBImage3_090(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateRGBImage3_180(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateRGBImage3_270(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}
	else
	{	bIsOK = RotateRGBImage3_Any(Angle, ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB);	}	
	return bIsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage_000(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDstR, unsigned char *&pDstG, unsigned char *&pDstB)//RGB影像旋轉
{
	const char fnName[] = ("CImageAPI::RotateRGBImage_000");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }

	DstW = ImageW;
	DstH = ImageH;
	DstStep = ImageStep;
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDstR);
	JetMemory.free_func(pDstG);
	JetMemory.free_func(pDstB);
	if ( JetMemory.alloc_func(BufferSize, pDstR, fnName, "pDstR") == false ||
		 JetMemory.alloc_func(BufferSize, pDstG, fnName, "pDstG") == false ||
		 JetMemory.alloc_func(BufferSize, pDstB, fnName, "pDstB") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pDstR);
		JetMemory.free_func(pDstG);
		JetMemory.free_func(pDstB);
		return false;
	}
	if ( RotateRGBImage3_000(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDstR);
		JetMemory.free_func(pDstG);
		JetMemory.free_func(pDstB);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage3_000(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB)//RGB影像旋轉
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckGrayImage3(DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )
	{	return false; }

	if ( ImageW!=DstW || ImageH!=DstH || ImageStep!=DstStep )
	{
		this->m_ErrorString.Format(_T("Error, Image size is exception"));
		return false;
	}
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDstR, pR, sizeof(unsigned char)*BufferSize);
	::memcpy(pDstG, pG, sizeof(unsigned char)*BufferSize);
	::memcpy(pDstB, pB, sizeof(unsigned char)*BufferSize);
	return true;
}
