bool CImageAPI::RotateRGBImage_090(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDstR, unsigned char *&pDstG, unsigned char *&pDstB)//RGB影像旋轉
{
	const char fnName[] = ("CImageAPI::RotateRGBImage_090");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }

	const IMAGE_SIZE AlignByte = 4;
	DstW = ImageH;
	DstH = ImageW;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, AlignByte);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDstR);
	JetMemory.free_func(pDstG);
	JetMemory.free_func(pDstB);
	if ( JetMemory.alloc_func(BufferSize, pDstR, fnName, "pDstR") == false ||
		 JetMemory.alloc_func(BufferSize, pDstG, fnName, "pDstG") == false ||
		 JetMemory.alloc_func(BufferSize, pDstB, fnName, "pDstB") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pDstR);
		JetMemory.free_func(pDstG);
		JetMemory.free_func(pDstB);
		return false;
	}
	if ( RotateRGBImage3_090(ImageW, ImageH, ImageStep, pR, pG, pB, DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDstR);
		JetMemory.free_func(pDstG);
		JetMemory.free_func(pDstB);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage3_090(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB)//RGB影像旋轉
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckGrayImage3(DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )
	{	return false; }

	if ( ImageW!=DstH || ImageH!=DstW )
	{
		this->m_ErrorString.Format(_T("Error, Image size is exception"));
		return false;
	}	

	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRds=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{	
		SrcIdxRds = (DstH-i-1);
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = (j*ImageStep)+SrcIdxRds;
			DstIdx = DstIdxRow+j;
			pDstR[DstIdx] = pR[SrcIdx];
			pDstG[DstIdx] = pG[SrcIdx];
			pDstB[DstIdx] = pB[SrcIdx];
		}
	}
	return true;
}
