bool CImageAPI::RotateRGBImage3_180(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB)//RGB影像旋轉
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckGrayImage3(DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )
	{	return false; }

	if ( ImageW!=DstW || ImageH!=DstH )
	{
		this->m_ErrorString.Format(_T("Error, Image size is exception"));
		return false;
	}
	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRow=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{
		SrcIdxRow = ((DstH-i-1)*ImageStep)+DstW-1;
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = SrcIdxRow-j;
			DstIdx = DstIdxRow+j;
			pDstR[DstIdx] = pR[SrcIdx];
			pDstG[DstIdx] = pG[SrcIdx];
			pDstB[DstIdx] = pB[SrcIdx];
		}
	}
	return true;
}
