//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateRGBImage3_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB)//RGB影像旋轉
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckGrayImage3(DstW, DstH, DstStep, pDstR, pDstG, pDstB) == false )
	{	return false; }	

	int i=0, j=0, m=0, n=0;
	double x=0, y=0, p=0, q=0;
	int dR=0, d1R=0, d2R=0, d3R=0, d4R=0;
	int dG=0, d1G=0, d2G=0, d3G=0, d4G=0;
	int dB=0, d1B=0, d2B=0, d3B=0, d4B=0;
	int index = 0;
	int idx1=0, idx2=0, idx3=0, idx4=0;

	const int xt = (int)(ImageW/2);
	const int yt = (int)(ImageH/2);
	const int BytePerLine = (int)(ImageStep);
	const int ImageSizeSrc = (int)(ImageStep*ImageH);
	const int NewImageW = (int)(DstW);
	const int NewImageH = (int)(DstH);		
	const int DestBytePerLine = (int)(DstStep);
	const int xs = NewImageW/2;
	const int ys = NewImageH/2;
	const double r = Angle*DEG_TO_RAD_DBL;
	const double c = (double)(cos(r));
	const double s = (double)(sin(r));

	int StartI=0, EndI=0;
	int StartJ=0, EndJ=0;
	RECT *pCareRect = NULL;
	if ( pCareRect == NULL )
	{
		StartI = -ys;
		EndI   =  ys;
		StartJ = -xs;
		EndJ   =  xs;
	}
	else
	{
		StartI = pCareRect->top;
		EndI   = pCareRect->bottom;
		StartJ = pCareRect->left;
		EndJ   = pCareRect->right;

		StartI = StartI-ys;
		EndI   = EndI-ys;
		StartJ = StartJ-xs;
		EndJ   = EndJ-xs;
	}

	for ( i=StartI; i<EndI; i++ )//目的影像的引數-Y
	{	
		for ( j=StartJ; j<EndJ; j++ )//目的影像的引數-X
		{
			y = j*s + i*c;//來源影像的Y
			x = j*c - i*s;//來源影像的X

			if ( y > 0 ) { m = (int)y; }
			else {	m = (int)(y-1);	}

			if ( x > 0 ) { n = (int)x; }
			else { n = (int)(x-1); }

			q = y - m;
			p = x - n;

			if ( q == 1 ) { q = 0; m = m+1; }
			if ( p == 1 ) { p = 0; n = n+1; }			
			if ( m<-yt || m>=yt || n<-xt || n>=xt )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDstR[index] = 0 ;
				pDstG[index] = 0 ;
				pDstB[index] = 0 ;
				continue; 
			}

			idx1 = (m+yt)*BytePerLine+n+xt;
			idx2 = idx1+1;//(m+yt)*BytePerLine+n+xt+1;
			idx3 = idx1+BytePerLine;//(m+yt+1)*BytePerLine+n+xt;
			idx4 = idx3+1;//(m+yt+1)*BytePerLine+n+xt+1;
			if ( idx1>=ImageSizeSrc || idx2>=ImageSizeSrc || idx3>=ImageSizeSrc || idx4>=ImageSizeSrc )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDstR[index] = 0 ;
				pDstG[index] = 0 ;
				pDstB[index] = 0 ;
				continue; 
			}
			d1R = pR[idx1];
			d1G = pG[idx1];
			d1B = pB[idx1];

			d2R = pR[idx2];
			d2G = pG[idx2];
			d2B = pB[idx2];

			d3R = pR[idx3];
			d3G = pG[idx3];
			d3B = pB[idx3];

			d4R = pR[idx4];
			d4G = pG[idx4];
			d4B = pB[idx4];

			dR = (int)((1.0-q)*((1.0-p)*d1R+p*d2R)+q*((1.0-p)*d3R+p*d4R));
			dG = (int)((1.0-q)*((1.0-p)*d1G+p*d2G)+q*((1.0-p)*d3G+p*d4G));
			dB = (int)((1.0-q)*((1.0-p)*d1B+p*d2B)+q*((1.0-p)*d3B+p*d4B));
			if ( dR < 0 ) { dR = 0; }
			else
			{
				if ( dR > 255 ) { dR = 255; }
			}
			if ( dG < 0 ) { dG = 0; }
			else
			{
				if ( dG > 255 ) { dG = 255; }
			}
			if ( dB < 0 ) { dB = 0; }
			else
			{
				if ( dB > 255 ) { dB = 255; }
			}
			index = (i+ys)*DestBytePerLine+j+xs;
			pDstR[index] = dR;
			pDstG[index] = dG;
			pDstB[index] = dB;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, float *&pDst)//空間高度旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateSpace_000(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateSpace_090(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateSpace_180(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateSpace_270(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else
	{	bIsOK = RotateSpace_Any(Angle, ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}	
	return bIsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateSpace3_000(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateSpace3_090(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateSpace3_180(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateSpace3_270(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}
	else
	{	bIsOK = RotateSpace3_Any(Angle, ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst);	}	
	return bIsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace_000(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, float *&pDst)//空間高度旋轉
{
	const char fnName[] = ("CImageAPI::RotateSpace_000");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }

	DstW = ImageW;
	DstH = ImageH;
	DstStep = ImageStep;
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateSpace3_000(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_000(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstW || ImageH!=DstH || ImageStep!=DstStep )
	{
		this->m_ErrorString.Format(_T("Error, Space size is exception"));
		return false;
	}
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pSpace, sizeof(float)*BufferSize);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace_090(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, float *&pDst)//空間高度旋轉
{
	const char fnName[] = ("CImageAPI::RotateSpace_090");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }

	const IMAGE_SIZE AlignByte = 4;
	DstW = ImageH;
	DstH = ImageW;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, AlignByte);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateSpace3_090(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_090(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstH || ImageH!=DstW )
	{
		this->m_ErrorString.Format(_T("Error, Space size is exception"));
		return false;
	}	

	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRds=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{	
		SrcIdxRds = (DstH-i-1);
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = (j*ImageStep)+SrcIdxRds;
			DstIdx = DstIdxRow+j;
			pDst[DstIdx] = pSpace[SrcIdx];
		}
	}
	return true;
}
