bool CImageAPI::RotateSpace_180(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, float *&pDst)//空間高度旋轉
{
	const char fnName[] = ("CImageAPI::RotateSpace_180");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }

	DstW = ImageW;
	DstH = ImageH;
	DstStep = ImageStep;
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateSpace3_180(ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_180(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstW || ImageH!=DstH )
	{
		this->m_ErrorString.Format(_T("Error, Space size is exception"));
		return false;
	}
	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRow=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{
		SrcIdxRow = ((DstH-i-1)*ImageStep)+DstW-1;
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = SrcIdxRow-j;
			DstIdx = DstIdxRow+j;
			pDst[DstIdx] = pSpace[SrcIdx];
		}
	}
	return true;
}
