//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_270(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }

	if ( ImageW!=DstH || ImageH!=DstW )
	{
		this->m_ErrorString.Format(_T("Error, Space size is exception"));
		return false;
	}	

	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	size_t SrcIdxRds=0, DstIdxRow=0;	
	for ( i=0; i<DstH; i++ )
	{	
		SrcIdxRds = i;
		DstIdxRow = (i*DstStep);
		for ( j=0; j<DstW; j++ )
		{
			SrcIdx = ((DstW-j-1)*ImageStep)+SrcIdxRds;
			DstIdx = DstIdxRow+j;
			pDst[DstIdx] = pSpace[SrcIdx];
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, float *&pDst)//空間高度旋轉
{
	const char fnName[] = ("CImageAPI::RotateSpace_Any");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }

	const IMAGE_SIZE AlignByte = 4;
	DstW = CImageAPI::CalcRotateImageSize(ImageW, ImageH);
	DstH = DstW;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, AlignByte);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateSpace3_Any(Angle, ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( RotateSpace3_OpenCV(Angle, ImageW, ImageH, ImageStep, pSpace, DstW, DstH, DstStep, pDst) == false )//時間差不多
	{	return false; }
	return true;	

	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }	

	int i=0, j=0, m=0, n=0;
	double x=0, y=0, p=0, q=0;	
	double d=0, d1=0, d2=0, d3=0, d4=0;
	int index = 0;
	int idx1=0, idx2=0, idx3=0, idx4=0;

	const int xt = (int)(ImageW/2);
	const int yt = (int)(ImageH/2);
	const int BytePerLine = (int)(ImageStep);
	const int ImageSizeSrc = (int)(ImageStep*ImageH);
	const int NewImageW = (int)(DstW);
	const int NewImageH = (int)(DstH);		
	const int DestBytePerLine = (int)(DstStep);
	const int xs = NewImageW/2;
	const int ys = NewImageH/2;
	const double r = Angle*DEG_TO_RAD_DBL;
	const double c = (double)(cos(r));
	const double s = (double)(sin(r));

	int StartI=0, EndI=0;
	int StartJ=0, EndJ=0;
	RECT *pCareRect = NULL;
	if ( pCareRect == NULL )
	{
		StartI = -ys;
		EndI   =  ys;
		StartJ = -xs;
		EndJ   =  xs;
	}
	else
	{
		StartI = pCareRect->top;
		EndI   = pCareRect->bottom;
		StartJ = pCareRect->left;
		EndJ   = pCareRect->right;

		StartI = StartI-ys;
		EndI   = EndI-ys;
		StartJ = StartJ-xs;
		EndJ   = EndJ-xs;
	}

	for ( i=StartI; i<EndI; i++ )//目的影像的引數-Y
	{	
		for ( j=StartJ; j<EndJ; j++ )//目的影像的引數-X
		{
			y = j*s + i*c;//來源影像的Y
			x = j*c - i*s;//來源影像的X

			if ( y > 0 ) { m = (int)y; }
			else {	m = (int)(y-1);	}

			if ( x > 0 ) { n = (int)x; }
			else { n = (int)(x-1); }

			q = y - m;
			p = x - n;

			if ( q == 1 ) { q = 0; m = m+1; }
			if ( p == 1 ) { p = 0; n = n+1; }			
			if ( m<-yt || m>=yt || n<-xt || n>=xt )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDst[index] = 0 ;
				continue; 
			}

			idx1 = (m+yt)*BytePerLine+n+xt;
			idx2 = idx1+1;//(m+yt)*BytePerLine+n+xt+1;
			idx3 = idx1+BytePerLine;//(m+yt+1)*BytePerLine+n+xt;
			idx4 = idx3+1;//(m+yt+1)*BytePerLine+n+xt+1;
			if ( idx1>=ImageSizeSrc || idx2>=ImageSizeSrc || idx3>=ImageSizeSrc || idx4>=ImageSizeSrc )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDst[index] = 0 ; 
				continue; 
			}
			d1 = pSpace[idx1];
			d2 = pSpace[idx2];
			d3 = pSpace[idx3];
			d4 = pSpace[idx4];			

			d = (int)((1.0-q)*((1.0-p)*d1+p*d2)+q*((1.0-p)*d3+p*d4));			
			index = (i+ys)*DestBytePerLine+j+xs;
			pDst[index] = (float)(d);
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateSpace3_OpenCV(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, float *pDst)//空間高度旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }	
#ifndef OPENCV_DISABLE
	try
	{	
		cv::Mat MatWarp;
		cv::Point2f center;		
		IMAGE_SIZE BitCount = 8;
		cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pSpace);			
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		
		const int nDstW=(int)(DstW);
		const int nDstH=(int)(DstH);
		const int nSrcW=(int)(ImageW);
		const int nSrcH=(int)(ImageH);		
		const int nOffX=(nDstW-nSrcW)/2;
		const int nOffY=(nDstH-nSrcH)/2;
		const float angle = Angle;
		const float scale = 1.0f;
		//::cvWarpAffine(MatSrc, MatDst, warp_mat);
		center.x = (nSrcW*0.5f);
		center.y = (nSrcH*0.5f);		
		MatWarp = cv::getRotationMatrix2D(center, angle, scale);				
		double &ox=MatWarp.at<double>(0, 2, 0);
		double &oy=MatWarp.at<double>(1, 2, 0);
		const int flags = cv::InterpolationFlags::INTER_LINEAR;//INTER_NEAREST, INTER_LINEAR, INTER_CUBIC
		ox += nOffX;//移至目標影像中央-X
		oy += nOffY;//移至目標影像中央-Y
		cv::warpAffine(MatSrc, MatDst, MatWarp, cv::Size(nDstW,nDstH), flags);
		if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);				
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateMask(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pMask, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//遮罩影像旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateGrayImage_000(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateGrayImage_090(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateGrayImage_180(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateGrayImage_270(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else
	{	bIsOK = RotateMask_Any(Angle, ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}	
	return bIsOK;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateMask3(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pMask, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//遮罩影像旋轉
{
	bool  bIsOK = true;	
	const double dPrecision = 0.001;
	const double dAngle = AdjustRotateAngle(Angle);
	if ( ::fabs(dAngle)<dPrecision || ::fabs(dAngle-360.0)<dPrecision )
	{	bIsOK = RotateGrayImage3_000(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-90.0) < dPrecision )
	{	bIsOK = RotateGrayImage3_090(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-180.0) < dPrecision )
	{	bIsOK = RotateGrayImage3_180(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else if ( ::fabs(dAngle-270.0) < dPrecision )
	{	bIsOK = RotateGrayImage3_270(ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}
	else
	{	bIsOK = RotateMask3_Any(Angle, ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst);	}	
	return bIsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateMask_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pMask, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//遮罩影像旋轉
{
	const char fnName[] = ("CImageAPI::RotateMask_Any");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pMask) == false )
	{	return false; }

	const IMAGE_SIZE AlignByte = 4;
	DstW = CImageAPI::CalcRotateImageSize(ImageW, ImageH);
	DstH = DstW;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, AlignByte);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateMask3_Any(Angle, ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateMask3_Any(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pMask, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//遮罩影像旋轉
{
	if ( RotateMask3_OpenCV(Angle, ImageW, ImageH, ImageStep, pMask, DstW, DstH, DstStep, pDst) == false )//時間差不多
	{	return false; }
	return true;

	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pMask) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }	

	int i=0, j=0, m=0, n=0;
	double x=0, y=0, p=0, q=0;	
	int d=0, d1=0, d2=0, d3=0, d4=0;
	int index = 0;
	int idx1=0, idx2=0, idx3=0, idx4=0;

	const int xt = (int)(ImageW/2);
	const int yt = (int)(ImageH/2);
	const int BytePerLine = (int)(ImageStep);
	const int ImageSizeSrc = (int)(ImageStep*ImageH);
	const int NewImageW = (int)(DstW);
	const int NewImageH = (int)(DstH);		
	const int DestBytePerLine = (int)(DstStep);
	const int xs = NewImageW/2;
	const int ys = NewImageH/2;
	const double r = Angle*DEG_TO_RAD_DBL;
	const double c = (double)(cos(r));
	const double s = (double)(sin(r));

	int StartI=0, EndI=0;
	int StartJ=0, EndJ=0;
	RECT *pCareRect = NULL;
	if ( pCareRect == NULL )
	{
		StartI = -ys;
		EndI   =  ys;
		StartJ = -xs;
		EndJ   =  xs;
	}
	else
	{
		StartI = pCareRect->top;
		EndI   = pCareRect->bottom;
		StartJ = pCareRect->left;
		EndJ   = pCareRect->right;

		StartI = StartI-ys;
		EndI   = EndI-ys;
		StartJ = StartJ-xs;
		EndJ   = EndJ-xs;
	}

	for ( i=StartI; i<EndI; i++ )//目的影像的引數-Y
	{	
		for ( j=StartJ; j<EndJ; j++ )//目的影像的引數-X
		{
			y = j*s + i*c;//來源影像的Y
			x = j*c - i*s;//來源影像的X

			if ( y > 0 ) { m = (int)y; }
			else {	m = (int)(y-1);	}

			if ( x > 0 ) { n = (int)x; }
			else { n = (int)(x-1); }

			q = y - m;
			p = x - n;

			if ( q == 1 ) { q = 0; m = m+1; }
			if ( p == 1 ) { p = 0; n = n+1; }			
			if ( m<-yt || m>=yt || n<-xt || n>=xt )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDst[index] = 0 ;
				continue; 
			}

			idx1 = (m+yt)*BytePerLine+n+xt;
			idx2 = idx1+1;//(m+yt)*BytePerLine+n+xt+1;
			idx3 = idx1+BytePerLine;//(m+yt+1)*BytePerLine+n+xt;
			idx4 = idx3+1;//(m+yt+1)*BytePerLine+n+xt+1;
			if ( idx1>=ImageSizeSrc || idx2>=ImageSizeSrc || idx3>=ImageSizeSrc || idx4>=ImageSizeSrc )
			{
				index = (i+ys)*DestBytePerLine+j+xs;
				pDst[index] = 0 ; 
				continue; 
			}

			d = PHASE_MASK_VALID;
			if ( CheckSpaceMaskValid(pMask[idx1])==false )
			{ d = pMask[idx1];	}
			else if ( CheckSpaceMaskValid(pMask[idx2])==false  )
			{ d = pMask[idx2];	}
			else if ( CheckSpaceMaskValid(pMask[idx3])==false  )
			{ d = pMask[idx3];	}
			else if ( CheckSpaceMaskValid(pMask[idx4])==false  )
			{ d = pMask[idx4];	}

			index = (i+ys)*DestBytePerLine+j+xs;
			pDst[index] = d;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateMask3_OpenCV(double Angle, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pMask, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//遮罩影像旋轉
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pMask) == false )
	{	return false; }
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }	
#ifndef OPENCV_DISABLE
	try
	{	
		cv::Mat MatWarp;
		cv::Point2f center;		
		IMAGE_SIZE BitCount = 8;
		cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pMask);			
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		
		const int nDstW=(int)(DstW);
		const int nDstH=(int)(DstH);
		const int nSrcW=(int)(ImageW);
		const int nSrcH=(int)(ImageH);		
		const int nOffX=(nDstW-nSrcW)/2;
		const int nOffY=(nDstH-nSrcH)/2;
		const float angle = Angle;
		const float scale = 1.0f;
		//::cvWarpAffine(MatSrc, MatDst, warp_mat);
		center.x = (nSrcW*0.5f);
		center.y = (nSrcH*0.5f);		
		MatWarp = cv::getRotationMatrix2D(center, angle, scale);				
		double &ox=MatWarp.at<double>(0, 2, 0);
		double &oy=MatWarp.at<double>(1, 2, 0);
		const int flags = cv::InterpolationFlags::INTER_NEAREST;
		ox += nOffX;//移至目標影像中央-X
		oy += nOffY;//移至目標影像中央-Y
		cv::warpAffine(MatSrc, MatDst, MatWarp, cv::Size(nDstW,nDstH), flags);
		if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);				
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateImage(double Angle, double PivotX, double PivotY, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *&pDst)//影像旋轉
{
	const char fnName[] = ("CImageAPI::RotateImage");
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RotateImage3(Angle, PivotX, PivotY, ImageW, ImageH, ImageStep, BitCount, pImage, DstW, DstH, DstStep, pDst) == false )//灰階影像旋轉
	{
		JetMemory.free_func(pDst);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RotateImage3(double Angle, double PivotX, double PivotY, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//影像旋轉
{
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }
	if ( this->CheckImage(DstW, DstH, DstStep, BitCount, pDst) == false )
	{	return false; }	
#ifndef OPENCV_DISABLE
	try
	{			
		cv::Mat MatWarp;
		cv::Point2f center;
		cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);			
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		
		const int nDstW=(int)(DstW);
		const int nDstH=(int)(DstH);
		const int nSrcW=(int)(ImageW);
		const int nSrcH=(int)(ImageH);		
		const int nOffX=(nDstW-nSrcW)/2;
		const int nOffY=(nDstH-nSrcH)/2;
		const float angle = Angle;
		const float scale = 1.0f;
		//::cvWarpAffine(MatSrc, MatDst, warp_mat);		
		center.x = (float)(PivotX);//(nSrcW*0.5f);
		center.y = (float)(PivotY);//(nSrcH*0.5f);
		MatWarp = cv::getRotationMatrix2D(center, angle, scale);		
		double &ox=MatWarp.at<double>(0, 2, 0);
		double &oy=MatWarp.at<double>(1, 2, 0);		
		ox += nOffX;//移至目標影像中央-X
		oy += nOffY;//移至目標影像中央-Y
		cv::warpAffine(MatSrc, MatDst, MatWarp, cv::Size(nDstW,nDstH));
		if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
