bool CImageAPI::DrawImageBoundary3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int Size, unsigned char Red, unsigned char Grn, unsigned char Blu, unsigned char *pDst)//繪製圖像邊框
{
	if ( CImageAPI::CheckBitCount(BitCount) == false )
	{	return false; }
	if (  8 == BitCount ) 
	{	return DrawGrayImageBoundary3(ImageW, ImageH, ImageStep, pImage, Size, Red, pDst); }
	if ( 24 == BitCount ) 
	{	return DrawColorImageBoundary3(ImageW, ImageH, ImageStep, pImage, Size, Red, Grn, Blu, pDst); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawGrayImageBoundary3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int Size, unsigned char Gry, unsigned char *pDst)//繪製灰階圖像邊框
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	if ( Size>ImageW || Size>ImageH ) 
	{	return false; }
	size_t  i=0, j=0, idx=0, k=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( pImage != pDst )
	{	::memcpy(pDst, pImage, sizeof(unsigned char)*BufferSize);	}

	//Vertical
	for ( i=0; i<Size; i++ )
	{
		//Top
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{	pDst[idx++] = Gry;	}

		//Bottom
		idx = (ImageH-i-1)*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{	pDst[idx++] = Gry;	}
	}

	//Horizontal
	for ( i=0; i<Size; i++ )
	{
		//Left		
		k = i;
		for ( j=0; j<ImageH; j++ )
		{
			idx = (j*ImageStep)+k;
			pDst[idx] = Gry;	
		}

		//Right
		k = ImageW-i-1;
		for ( j=0; j<ImageH; j++ )
		{	
			idx = (j*ImageStep)+k;
			pDst[idx] = Gry;	
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DrawColorImageBoundary3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int Size, unsigned char Red, unsigned char Grn, unsigned char Blu, unsigned char *pDst)//繪製彩色圖像邊框
{
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	if ( Size>ImageW || Size>ImageH ) 
	{	return false; }
	size_t  i=0, j=0, idx=0, k=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( pImage != pDst )
	{	::memcpy(pDst, pImage, sizeof(unsigned char)*BufferSize);	}

	//Vertical
	for ( i=0; i<Size; i++ )
	{
		//Top
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{	
			pDst[idx++] = Blu;	
			pDst[idx++] = Grn;	
			pDst[idx++] = Red;
		}

		//Bottom
		idx = (ImageH-i-1)*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{
			pDst[idx++] = Blu;	
			pDst[idx++] = Grn;	
			pDst[idx++] = Red;
		}
	}

	//Horizontal
	for ( i=0; i<Size; i++ )
	{
		//Left		
		k = i*3;
		for ( j=0; j<ImageH; j++ )
		{
			idx = (j*ImageStep)+k;
			pDst[idx++] = Blu;	
			pDst[idx++] = Grn;	
			pDst[idx++] = Red;
		}

		//Right
		k = (ImageW-i-1)*3;
		for ( j=0; j<ImageH; j++ )
		{	
			idx = (j*ImageStep)+k;
			pDst[idx++] = Blu;	
			pDst[idx++] = Grn;	
			pDst[idx++] = Red;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CombineHorSpaceImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pImageFixed, const float *pImage, int Offset, float *&pDst)//兩張圖左右合併
{
	const char fnName[] = ("CImageAPI::CombineHorSpaceImage");
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImageFixed, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->CombineHorSpaceImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, Offset, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CombineHorSpaceImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pImageFixed, const float *pImage, int Offset, float *pDst)//兩張圖左右合併
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, pDst) == false )
	{	return false; }

	size_t i=0, idxSrc=0, idxDst=0;
	int    j=0;
	int    XS=0, XE=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pImageFixed, sizeof(float)*BufferSize);
	int len = static_cast<int>(ImageW);

	if ( Offset >= 0 ) 
	{
		len = len-Offset;
		if ( len < 0 ) { return true; }
		//右移
		for ( i=0; i<ImageH; i++ )
		{
			idxSrc = (i*ImageStep);
			idxDst = (i*ImageStep)+Offset;
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(float)*len);
		}
	}
	else
	{
		len = len+Offset;
		if ( len < 0 ) { return true; }
		//左移
		for ( i=0; i<ImageH; i++ )
		{
			idxSrc = (i*ImageStep)-Offset;
			idxDst = (i*ImageStep);
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(float)*len);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CombineVerSpaceImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pImageFixed, const float *pImage, int Offset, float *&pDst)//兩張圖上下合併
{
	const char fnName[] = ("CImageAPI::CombineVerSpaceImage");
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImageFixed, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->CombineVerSpaceImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, Offset, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CombineVerSpaceImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pImageFixed, const float *pImage, int Offset, float *pDst)//兩張圖上下合併
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, pDst) == false )
	{	return false; }

	int    i=0, idxSrc=0, idxDst=0;
	int    j=0;
	int    XS=0, XE=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pImageFixed, sizeof(float)*BufferSize);
	int len = static_cast<int>(ImageH);

	if ( Offset >= 0 ) 
	{
		len = len-Offset;
		if ( len < 0 ) { return true; }
		//上移
		for ( i=0; i<len; i++ )
		{
			idxSrc = (i*ImageStep);
			idxDst = (i+Offset)*ImageStep;
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(float)*ImageStep);
		}
	}
	else
	{
		len = len+Offset;
		if ( len < 0 ) { return true; }
		//下移
		for ( i=0; i<len; i++ )
		{
			idxSrc = (i-Offset)*ImageStep;
			idxDst = (i*ImageStep);
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(float)*ImageStep);
		}
	}	
	return true;
}
