bool CImageAPI::CombineHorGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImageFixed, const unsigned char *pImage, int Offset, unsigned char *&pDst)//兩張圖左右合併
{
	const char fnName[] = ("CImageAPI::CombineHorGrayImage");
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImageFixed, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->CombineHorGrayImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, Offset, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CombineHorGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImageFixed, const unsigned char *pImage, int Offset, unsigned char *pDst)//兩張圖左右合併
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pImageFixed, pImage, pDst) == false )
	{	return false; }

	size_t i=0, idxSrc=0, idxDst=0;
	int    j=0;
	int    XS=0, XE=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pImageFixed, sizeof(unsigned char)*BufferSize);
	int len = static_cast<int>(ImageW);

	if ( Offset >= 0 ) 
	{
		len = len-Offset;
		if ( len < 0 ) { return true; }
		//右移
		for ( i=0; i<ImageH; i++ )
		{
			idxSrc = (i*ImageStep);
			idxDst = (i*ImageStep)+Offset;
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(unsigned char)*len);
		}
	}
	else
	{
		len = len+Offset;
		if ( len < 0 ) { return true; }
		//左移
		for ( i=0; i<ImageH; i++ )
		{
			idxSrc = (i*ImageStep)-Offset;
			idxDst = (i*ImageStep);
			::memcpy(&(pDst[idxDst]), &(pImage[idxSrc]), sizeof(unsigned char)*len);
		}
	}
	return true;
}
