bool CImageAPI::PasteRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, const unsigned char *pRoi, bool Reverse, bool theSameSize)//回貼子影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return PasteGrayRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse, theSameSize); }
	if ( 24 == BitCount ) 
	{	return PasteColorRoiImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, RoiStep, pRoi, Reverse, theSameSize); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PasteGrayRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, const unsigned char *pRoi, bool Reverse, bool theSameSize)//灰階回貼子影像
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckGrayImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	int i=0, j=0;
	int gryIdx1=0;
	int roiIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*RoiW;

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = ((ImageH-i-1)*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (RoiH-i+RoiRect.top-1)*RoiStep;	}			
			gryIdx1 = (i*ImageStep)+RoiRect.left;			
			::memcpy(&(pImage[gryIdx1]), &(pRoi[roiIdx1]), size_roi_w);			
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = (i*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (i-RoiRect.top)*RoiStep;	}			
			gryIdx1 = (i*ImageStep)+RoiRect.left;
			::memcpy(&(pImage[gryIdx1]), &(pRoi[roiIdx1]), size_roi_w);			
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PasteColorRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, const unsigned char *pRoi, bool Reverse, bool theSameSize)//彩色回貼子影像
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckColorImage(RoiW, RoiH, RoiStep, pRoi) == false )
	{	return false; }

	int i=0, j=0;
	int clrIdx1=0;
	int roiIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*RoiW*3;

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = ((ImageH-i-1)*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (RoiH-i+RoiRect.top-1)*RoiStep; }
			clrIdx1 = (i*ImageStep)+(RoiRect.left*3);
			::memcpy(&(pImage[clrIdx1]), &(pRoi[roiIdx1]), size_roi_w);
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = (i*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (i-RoiRect.top)*RoiStep; }
			clrIdx1 = (i*ImageStep)+(RoiRect.left*3);
			::memcpy(&(pImage[clrIdx1]), &(pRoi[roiIdx1]), size_roi_w);
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PasteColorRoiImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, IMAGE_SIZE RoiStep, const unsigned char *pRoiR, const unsigned char *pRoiG, const unsigned char *pRoiB, bool Reverse, bool theSameSize)//彩色回貼子影像
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;
	if ( this->CheckGrayImage3(RoiW, RoiH, RoiStep, pRoiR, pRoiG, pRoiB) == false )
	{	return false; }

	int i=0, j=0;
	int clrIdx1=0;
	int roiIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*RoiW*3;

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = ((ImageH-i-1)*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (RoiH-i+RoiRect.top-1)*RoiStep; }
			clrIdx1 = (i*ImageStep)+(RoiRect.left*3);
			for ( j=RoiRect.left; j<RoiRect.right; j++ )
			{
				pImage[clrIdx1++] = pRoiB[roiIdx1];
				pImage[clrIdx1++] = pRoiG[roiIdx1];
				pImage[clrIdx1++] = pRoiR[roiIdx1];
				roiIdx1 ++;
			}
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			if ( true == theSameSize )
			{	roiIdx1 = (i*RoiStep)+RoiRect.left;	}
			else
			{	roiIdx1 = (i-RoiRect.top)*RoiStep; }
			clrIdx1 = (i*ImageStep)+(RoiRect.left*3);
			for ( j=RoiRect.left; j<RoiRect.right; j++ )
			{
				pImage[clrIdx1++] = pRoiB[roiIdx1];
				pImage[clrIdx1++] = pRoiG[roiIdx1];
				pImage[clrIdx1++] = pRoiR[roiIdx1];
				roiIdx1 ++;
			}
		}
	}	
	return true;
}
