bool CImageAPI::AlignImageBuffer(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int NewStep, unsigned char *&pDest, bool Reverse)//影像記憶體重新排列
{
	if ( CImageAPI::CheckBitCount(BitCount) == false )
	{	return false; }
	if (  8 == BitCount ) 
	{	return AlignGrayImageBuffer(ImageW, ImageH, ImageStep, pImage, NewStep, pDest, Reverse); }
	if ( 24 == BitCount ) 
	{	return AlignColorImageBuffer(ImageW, ImageH, ImageStep, pImage, NewStep, pDest, Reverse); }
	return false;
}
