bool CImageAPI::AlignGrayImageBuffer(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int NewStep, unsigned char *&pDest, bool Reverse)//灰階影像記憶體重新排列
{
	const char fnName[] = ("AlignGrayImageBuffer");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckGraySize(ImageW, ImageH, NewStep) == false )
	{	return false; }
	
	JetMemory.free_func(pDest);
	const size_t BufferSize = CalcBufferSize(NewStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDest, fnName, "pDest") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->AlignGrayImageBuffer3(ImageW, ImageH, ImageStep, pImage, NewStep, pDest, Reverse) == false )
	{
		JetMemory.free_func(pDest);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AlignGrayImageBuffer3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int NewStep, unsigned char *pDest, bool Reverse)//灰階影像記憶體重新排列
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckGrayImage(ImageW, ImageH, NewStep, pDest) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx1=0;
	size_t destIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*ImageW;

	if ( true == Reverse )
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx1 = (i*ImageStep);
			destIdx1 = (ImageH-1-i)*NewStep;
			::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx1 = (i*ImageStep);
			destIdx1 = (i*NewStep);
			::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
		}
	}
	return true;
}
