bool CImageAPI::AlignGrayImageBuffer3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, int NewStep, unsigned char *pDest, bool Reverse)//灰階影像記憶體重新排列
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckGrayImage(ImageW, ImageH, NewStep, pDest) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx1=0;
	size_t destIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*(RoiRect.right-RoiRect.left);

	if ( true == Reverse )
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			srcIdx1 = (i*ImageStep)+(RoiRect.left);
			destIdx1 = ((ImageH-1-i)*NewStep)+(RoiRect.left);
			::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
		}
	}
	else
	{
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			srcIdx1 = (i*ImageStep)+(RoiRect.left);
			destIdx1 = (i*NewStep)+(RoiRect.left);
			::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AlignColorImageBuffer(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int NewStep, unsigned char *&pDest, bool Reverse)//彩色影像記憶體重新排列
{
	const char fnName[] = ("CImageAPI::AlignColorImage");
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckColorSize(ImageW, ImageH, NewStep) == false )
	{	return false; }
	
	JetMemory.free_func(pDest);
	const size_t BufferSize = CalcBufferSize(NewStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDest, fnName, "pDest") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->AlignColorImageBuffer3(ImageW, ImageH, ImageStep, pImage, NewStep, pDest, Reverse) == false )
	{
		JetMemory.free_func(pDest);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AlignColorImageBuffer3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int NewStep, unsigned char *pDest, bool Reverse)//彩色影像記憶體重新排列
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckColorImage(ImageW, ImageH, NewStep, pDest) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx1=0;
	size_t destIdx1=0;
	size_t size_roi_w = sizeof(unsigned char)*ImageW*3;

	if ( true == Reverse )
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx1 = (i*ImageStep);
			destIdx1 = (ImageH-1-i)*NewStep;
			::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
		}
	}
	else
	{
		if ( ImageStep != NewStep )
		{
			for ( i=0; i<ImageH; i++ )
			{
				srcIdx1 = (i*ImageStep);
				destIdx1 = (i*NewStep);
				::memcpy(&(pDest[destIdx1]), &(pImage[srcIdx1]), size_roi_w);
			}
		}
		else
		{
			const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
			::memcpy(pDest, pImage, sizeof(unsigned char)*BufferSize);
		}
	}
	return true;
}
