bool CImageAPI::ImageOffsetGain(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pSrc, unsigned char *&pDst, double offset, double gain)//灰階影像增益與平移
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount )
	{	return CImageAPI::GrayImageOffsetGain(ImageW, ImageH, ImageStep, pSrc, pDst, offset, gain);	}
	else if ( 24 == BitCount )
	{	return CImageAPI::ColorImageOffsetGain(ImageW, ImageH, ImageStep, pSrc, pDst, offset, gain);	}
	return false;
}
