bool CImageAPI::GrayImageOffsetGain(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pSrc, unsigned char *&pDst, double offset, double gain)//灰階影像增益與平移
{
	const char fnName[] = ("CImageAPI::GrayImageOffsetGain");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pSrc) == false ) 
	{	return false; }	

	JetMemory.free_func(pDst);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->GrayImageOffsetGain3(ImageW, ImageH, ImageStep, pSrc, pDst, offset, gain) == false )
	{
		JetMemory.free_func(pDst);		
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageOffsetGain3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pSrc, unsigned char *pDst, double offset, double gain)//灰階影像增益與平移
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pSrc, pDst) == false ) 
	{	return false; }	
	
	const double Precision = DBL_PRECISION;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( fabs(offset)<Precision && fabs(gain-1.0)<Precision )
	{
		::memcpy(pDst, pSrc, sizeof(unsigned char)*BufferSize);
		return true;
	}
	
	const int BufferLevel = 256;
	unsigned char Buffer[BufferLevel] = {0};
	::memset(Buffer, 0x00, sizeof(Buffer));
	if ( BuildGainOffsetTable(offset, gain, BufferLevel, Buffer) == false )
	{	return false;	}	
	
	size_t i = 0;
	for ( i=0; i<BufferSize; i++ )
	{	pDst[i] = Buffer[pSrc[i]];	}
	return true;
}
