bool CImageAPI::RGBImageOffsetGain3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char *pDestR, unsigned char *pDestG, unsigned char *pDestB, double offset, double gain)//灰階影像增益與平移
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false ) 
	{	return false; }	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pDestR, pDestG, pDestB) == false ) 
	{	return false; }	

	const double Precision = DBL_PRECISION;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( fabs(offset)<Precision && fabs(gain-1.0)<Precision )
	{
		::memcpy(pDestR, pR, sizeof(unsigned char)*BufferSize);
		::memcpy(pDestG, pG, sizeof(unsigned char)*BufferSize);
		::memcpy(pDestB, pB, sizeof(unsigned char)*BufferSize);
		return true;
	}

	const int BufferLevel = 256;
	unsigned char Buffer[BufferLevel] = {0};
	if ( BuildGainOffsetTable(offset, gain, BufferLevel, Buffer) == false )
	{	return false;	}

	size_t i = 0;
	for ( i=0; i<BufferSize; i++ )
	{	
		pDestR[i] = Buffer[pR[i]];	
		pDestG[i] = Buffer[pG[i]];	
		pDestB[i] = Buffer[pB[i]];	
	}
	return true;
}
