//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageOffsetGain3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pSrc, const RECT &RoiRect, unsigned char *pDst, double offset, double gain)//灰階影像增益與平移
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pSrc, pDst) == false ) 
	{	return false; }	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }
	
	size_t       i=0, j=0, k=0;	
	const double Precision = DBL_PRECISION;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( fabs(offset)<Precision && fabs(gain-1.0)<Precision )
	{
		const size_t CopyLen=RoiRect.right-RoiRect.left;
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			j = (i*ImageStep)+RoiRect.left;
			::memcpy(&(pDst[j]), &(pSrc[j]), sizeof(unsigned char)*CopyLen);			
		}
		return true;
	}

	const int BufferLevel = 256;
	unsigned char Buffer[BufferLevel] = {0};
	if ( BuildGainOffsetTable(offset, gain, BufferLevel, Buffer) == false )
	{	return false;	}
	
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		k = (i*ImageStep)+RoiRect.left;
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{			
			pDst[k] = Buffer[pSrc[k]];
			k ++;
		}		
	}
	return true;
}
