	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->SaturateGrayImage3(ImageW, ImageH, ImageStep, pSrc, pDst, Wr, Wb) == false )
	{
		JetMemory.free_func(pDst);	
		return false; 
	}
