//-------------------------------------------------------------------------------------//
bool CImageAPI::SaturateColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pSrc, unsigned char *pDst, double Wr, double Wb)//彩色影像飽和調整
{
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pSrc, pDst) == false ) 
	{	return false; }	
	
	const double Precision = DBL_PRECISION;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( fabs(Wr-1.0)<Precision && fabs(Wb-1.0)<Precision )
	{
		::memcpy(pDst, pSrc, sizeof(unsigned char)*BufferSize);
		return true;
	}

	size_t i=0, j=0, k=0;
	double Cr2=0.0, Cb2=0.0;
	double Y=0.0, Cr=0.0, Cb=0.0;
	double srcR=0.0, srcG=0.0, srcB=0.0;
	double dstR=0.0, dstG=0.0, dstB=0.0;

	/*
	//RGB to YCrCb
	//Y  = 0.299 * R + 0.587 * G + 0.114 * B
	//Cr = 0.500 * R - 0.419 * G - 0.081 * B 
	//Cb = -0.169 * R - 0.331 * G + 0.500 * B 

	//YCrCb to RGB
	//R = Y + 1.371 * Cr
	//G = Y – 0.6982 * Cr – 0.3365 * Cb
	//B = Y + 1.732 * Cb

	//change saturation
	//Cr2 = Cr * Wr
	//Cb2 = Cb * Wb

	//Result
	//R = Y + 1.371 * Cr2
	//G = Y – 0.6982 * Cr2 – 0.3365 * Cb2
	//B = Y + 1.732 * Cb2

	*/	
	for ( i=0; i<ImageH; i++ )
	{
		k = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{		
			srcB = pSrc[k];	
			srcG = pSrc[k+1];	
			srcR = pSrc[k+2];	

			Y  = (0.299*srcR) + (0.587*srcG) + (0.114*srcB);
			Cr = (0.500*srcR) - (0.419*srcG) - (0.081*srcB);
			Cb = (-0.169*srcR) - (0.331*srcG) + (0.500*srcB);

			Cr2 = Cr*Wr;
			Cb2 = Cb*Wb;

			dstR = Y + (1.371*Cr2);
			dstG = Y - (0.6982*Cr2)-(0.3365*Cb2);
			dstB = Y + (1.732*Cb2);

			if ( dstB > 255.0 ) { pDst[k] = 255; }
			else if ( dstB < 0.0 ) { pDst[k] = 0; }
			else { pDst[k] = (unsigned char)(dstB); }

			if ( dstG > 255.0 ) { pDst[k+1] = 255; }
			else if ( dstG < 0.0 ) { pDst[k+1] = 0; }
			else { pDst[k+1] = (unsigned char)(dstG); }

			if ( dstR > 255.0 ) { pDst[k+2] = 255; }
			else if ( dstR < 0.0 ) { pDst[k+2] = 0; }
			else { pDst[k+2] = (unsigned char)(dstR); }

			k += 3;			
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaturateRGBImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char *&pDstR, unsigned char *&pDstG, unsigned char *&pDstB, double Wr, double Wb)//三色影像飽和調整
{
	const char fnName[] = ("CImageAPI::SaturateRGBImage");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false ) 
	{	return false; }
	
	JetMemory.free_func(pDstR);
	JetMemory.free_func(pDstG);
	JetMemory.free_func(pDstB);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDstR, fnName, "pDstR") == false ||
		 JetMemory.alloc_func(BufferSize, pDstG, fnName, "pDstG") == false ||
		 JetMemory.alloc_func(BufferSize, pDstB, fnName, "pDstB") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pDstR);	
		JetMemory.free_func(pDstG);	
		JetMemory.free_func(pDstB);	
		return false; 
	}
	if ( this->SaturateRGBImage3(ImageW, ImageH, ImageStep, pR, pG, pB, pDstR, pDstG, pDstB, Wr, Wb) == false )
	{
		JetMemory.free_func(pDstR);	
		JetMemory.free_func(pDstG);	
		JetMemory.free_func(pDstB);	
		return false; 
	}

	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SaturateRGBImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char *pDstR, unsigned char *pDstG, unsigned char *pDstB, double Wr, double Wb)//三色影像飽和調整
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false ) 
	{	return false; }	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pDstR, pDstG, pDstB) == false ) 
	{	return false; }	

	const double Precision = DBL_PRECISION;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( fabs(Wr-1.0)<Precision && fabs(Wb-1.0)<Precision )
	{
		::memcpy(pDstR, pR, sizeof(unsigned char)*BufferSize);
		::memcpy(pDstG, pG, sizeof(unsigned char)*BufferSize);
		::memcpy(pDstB, pB, sizeof(unsigned char)*BufferSize);
		return true;
	}

	size_t i=0;
	double Cr2=0.0, Cb2=0.0;
	double Y=0.0, Cr=0.0, Cb=0.0;
	double srcR=0.0, srcG=0.0, srcB=0.0;
	double dstR=0.0, dstG=0.0, dstB=0.0;

	/*
	//RGB to YCrCb
	//Y  = 0.299 * R + 0.587 * G + 0.114 * B
	//Cr = 0.500 * R - 0.419 * G - 0.081 * B 
	//Cb = -0.169 * R - 0.331 * G + 0.500 * B 

	//YCrCb to RGB
	//R = Y + 1.371 * Cr
	//G = Y – 0.6982 * Cr – 0.3365 * Cb
	//B = Y + 1.732 * Cb

	//change saturation
	//Cr2 = Cr * Wr
	//Cb2 = Cb * Wb

	//Result
	//R = Y + 1.371 * Cr2
	//G = Y – 0.6982 * Cr2 – 0.3365 * Cb2
	//B = Y + 1.732 * Cb2

	*/
	for ( i=0; i<BufferSize; i++ )
	{
		srcB = pB[i];	
		srcG = pG[i];	
		srcR = pR[i];	

		Y  = (0.299*srcR) + (0.587*srcG) + (0.114*srcB);
		Cr = (0.500*srcR) - (0.419*srcG) - (0.081*srcB);
		Cb = (-0.169*srcR) - (0.331*srcG) + (0.500*srcB);

		Cr2 = Cr*Wr;
		Cb2 = Cb*Wb;

		dstR = Y + (1.371*Cr2);
		dstG = Y - (0.6982*Cr2)-(0.3365*Cb2);
		dstB = Y + (1.732*Cb2);

		if ( dstB > 255.0 ) { pDstB[i] = 255; }
		else if ( dstB < 0.0 ) { pDstB[i] = 0; }
		else { pDstB[i] = (unsigned char)(dstB); }

		if ( dstG > 255.0 ) { pDstG[i] = 255; }
		else if ( dstG < 0.0 ) { pDstG[i] = 0; }
		else { pDstG[i] = (unsigned char)(dstG); }

		if ( dstR > 255.0 ) { pDstR[i] = 255; }
		else if ( dstR < 0.0 ) { pDstR[i] = 0; }
		else { pDstR[i] = (unsigned char)(dstR); }		
	}	
	return true;
}
