bool CImageAPI::SetGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, unsigned char val)//灰階影像設定
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false;	}	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	for ( size_t i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		size_t idx=(i*ImageStep)+(RoiRect.left);
		for ( size_t j=RoiRect.left; j<RoiRect.right; j++ )
		{	pImage[idx++] = val;	}
	}
	return true;
}
