bool CImageAPI::RGBImageApplyLUT(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char LUT[], unsigned char *&pDestR, unsigned char *&pDestG, unsigned char *&pDestB)//RGB影像套用LUT
{
	const char fnName[] = ("CImageAPI::RGBImageApplyLUT");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false;	}	

	JetMemory.free_func(pDestR);
	JetMemory.free_func(pDestG);
	JetMemory.free_func(pDestB);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDestR, fnName, "pDestR") == false ||
		 JetMemory.alloc_func(BufferSize, pDestG, fnName, "pDestG") == false ||
		 JetMemory.alloc_func(BufferSize, pDestB, fnName, "pDestB") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pDestR);
		JetMemory.free_func(pDestG);
		JetMemory.free_func(pDestB);
		return false;
	}
	if ( this->RGBImageApplyLUT3(ImageW, ImageH, ImageStep, pR, pG, pB, LUT, pDestR, pDestG, pDestB) == false )
	{
		JetMemory.free_func(pDestR);
		JetMemory.free_func(pDestG);
		JetMemory.free_func(pDestB);
		return false;
	}
	return true;
}
