bool CImageAPI::RGBImageApplyLUT3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, unsigned char LUT[], unsigned char *pDestR, unsigned char *pDestG, unsigned char *pDestB)//RGB影像套用LUT
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false;	}	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pDestR, pDestG, pDestB) == false )
	{	return false;	}	

	size_t i = 0;
	const size_t ImageWH = CalcBufferSize(ImageStep, ImageH);
	for ( i=0; i<ImageWH; i++ )
	{	
		pDestR[i] = LUT[pR[i]];	
		pDestG[i] = LUT[pG[i]];	
		pDestB[i] = LUT[pB[i]];	
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildGammaLookUpTable(double Gamma, unsigned char GammaTable[])//建立Gamma的LUT
{
	int i=0;	
	const int MaxI = 256;	
	double value = 0;
	double NewValue = 0;
	double MaxValue = 255.0;
	double TempV = 0;
	const double gamma = Gamma;	

	if ( Gamma <= 0 ) 
	{
		for ( i=0; i<MaxI; i++ )
		{	GammaTable[i] = i; }
		return false; 
	}

	for ( i=0; i<MaxI; i++ )
	{
		value = i;
		TempV = value/MaxValue;
		TempV = pow(TempV, gamma);
		NewValue = (TempV*MaxValue)+0.5;
		if ( NewValue < 0 ) 
		{	GammaTable[i] = 0; }
		else if ( NewValue > 255 ) 
		{	GammaTable[i] = 255; }
		else
		{	GammaTable[i] = (unsigned char)(NewValue); }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GammaGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, double Gamma, unsigned char *&pDest)//灰階影像Gamma增益
{
	int i=0;
	unsigned char  GammaTable[256]={0};
	if ( this->BuildGammaLookUpTable(Gamma, GammaTable) == false )
	{	return false; }
	if ( this->GrayImageApplyLUT(ImageW, ImageH, ImageStep, pImage, GammaTable, pDest) == false )
	{	return false; }
	return true;
}
