//-------------------------------------------------------------------------------------//
bool CImageAPI::LocalGammaColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int CalcSize, double Gamma, unsigned char *pDest)//彩色影像Local-Gamma增益
{
	const char fnName[] = ("CImageAPI::LocalGammaColorImage3");
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDest) == false )
	{	return false;	}	

	const int nAlign = 4;	
	unsigned char *RefPtr=NULL;//Refference
	unsigned char *LumPtr1=NULL;//Orignal
	unsigned char *LumPtr2=NULL;//After Gamma	
	const IMAGE_SIZE LumStep = GetImageAlignedWidth(ImageW, 8, 4);
	const size_t LumBufferSiZe=CalcBufferSize(LumStep, ImageH);
	if ( JetMemory.alloc_func(LumBufferSiZe, RefPtr, fnName, "RefPtr") == false ||
		 JetMemory.alloc_func(LumBufferSiZe, LumPtr1, fnName, "LumPtr1") == false ||
		 JetMemory.alloc_func(LumBufferSiZe, LumPtr2, fnName, "LumPtr2") == false )
	{
		SetErrorString(JetMemory.GetErrorString());	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}	
	size_t i=0, j=0;
	size_t cIdx=0, gidx=0;
	int    R=0, G=0, B=0, Lum=0;
	const float YCbCrYRF = 0.299f;
	const float YCbCrYGF = 0.587f;
	const float YCbCrYBF = 0.114f;

	//取得亮度通道
	if ( ColorImageToGrayImage3(ImageW, ImageH, ImageStep, pImage, LumStep, LumPtr1, YCbCrYRF, YCbCrYGF, YCbCrYBF) == false )
	{
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}
	//取得平滑圖來當作參考數據
	//if ( SmoothGrayImageByIntegral3(ImageW, ImageH, LumStep, LumPtr1, CalcSize, RefPtr) == false )//慢
	if ( SmoothGrayImage3(ImageW, ImageH, LumStep, LumPtr1, CalcSize, RefPtr) == false )
	{	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}

	if ( fabs(Gamma) < 0.001 ) { Gamma = 1.0; }
	unsigned char *LutPtr = BuildLocalGammaTable(Gamma);
	if ( NULL == LutPtr )
	{	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;	
	}
	//針對亮度做局部Gamma處理
	for ( i=0; i<LumBufferSiZe; i++ )
	{	LumPtr2[i] = (unsigned char)(LutPtr[LumPtr1[i]*256+RefPtr[i]]);	}
	JetMemory.free_func(LutPtr);

	//計算最末彩色影像
	int Y=0, Y2=0;
	int R2=0, G2=0, B2=0;
	//R = (Yf(R+Y)/Y+R-Y)/2
	//G = (Yf(G+Y)/Y+G-Y)/2
	//B = (Yf(B+Y)/Y+B-Y)/2
	for ( i=0; i<ImageH; i++ )
	{
		gidx=(i*LumStep);
		cIdx=(i*ImageStep);				
		for ( j=0; j<ImageW; j++ )
		{	
			B = pImage[cIdx];
			G = pImage[cIdx+1];
			R = pImage[cIdx+2];
			Y = LumPtr1[gidx];
			Y2= LumPtr2[gidx];
			if ( 0 == Y ) 
			{	R2 = G2 = B2 = 0;	}
			else
			{
				R2 = ((Y2*(R+Y)/Y)+R-Y)/2;
				G2 = ((Y2*(G+Y)/Y)+G-Y)/2;
				B2 = ((Y2*(B+Y)/Y)+B-Y)/2;
			}
			if ( R2 < 0 ) { R2 = 0; }
			else if ( R2 > 255 ) { R2 = 255; }
			if ( G2 < 0 ) { G2 = 0; }
			else if ( G2 > 255 ) { G2 = 255; }
			if ( B2 < 0 ) { B2 = 0; }
			else if ( B2 > 255 ) { B2 = 255; }
			
			pDest[cIdx] = B2;
			pDest[cIdx+1] = G2;
			pDest[cIdx+2] = R2;			
			gidx ++;
			cIdx += 3;			
		}
	}	
	JetMemory.free_func(RefPtr);
	JetMemory.free_func(LumPtr1);
	JetMemory.free_func(LumPtr2);
	return true;
}
