bool CImageAPI::LocalGammaRGBImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, int CalcSize, double Gamma, unsigned char *&pDstR, unsigned char *&pDstG, unsigned char *&pDstB)//RGB影像Local-Gamma增益
{
	const char fnName[] = ("CImageAPI::LocalGammaRGBImage");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false;	}	

	JetMemory.free_func(pDstR);	
	JetMemory.free_func(pDstG);	
	JetMemory.free_func(pDstB);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDstR, fnName, "pDstR") == false ||
		 JetMemory.alloc_func(BufferSize, pDstG, fnName, "pDstG") == false ||
		 JetMemory.alloc_func(BufferSize, pDstB, fnName, "pDstB") == false  )
	{
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(pDstR);	
		JetMemory.free_func(pDstG);	
		JetMemory.free_func(pDstB);	
		return false;
	}
	if ( this->LocalGammaRGBImage3(ImageW, ImageH, ImageStep, pR, pG, pB, CalcSize, Gamma, pDstR, pDstG, pDstB) == false )
	{
		JetMemory.free_func(pDstR);	
		JetMemory.free_func(pDstG);	
		JetMemory.free_func(pDstB);	
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LocalGammaRGBImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, int CalcSize, double Gamma, unsigned char *pDstR, unsigned char *&pDstG, unsigned char *&pDstB)//RGB影像Local-Gamma增益
{
	const char fnName[] = ("CImageAPI::LocalGammaRGBImage3");
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false;	}	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pDstR, pDstG, pDstB) == false )
	{	return false;	}	

	unsigned char *RefPtr=NULL;//Refference
	unsigned char *LumPtr1=NULL;//Orignal
	unsigned char *LumPtr2=NULL;//After Gamma	
	const IMAGE_SIZE LumStep = ImageStep;
	const size_t LumBufferSiZe=CalcBufferSize(LumStep, ImageH);
	if ( JetMemory.alloc_func(LumBufferSiZe, RefPtr, fnName, "RefPtr") == false ||
		 JetMemory.alloc_func(LumBufferSiZe, LumPtr1, fnName, "LumPtr1") == false ||
		 JetMemory.alloc_func(LumBufferSiZe, LumPtr2, fnName, "LumPtr2") == false )
	{
		SetErrorString(JetMemory.GetErrorString());	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}	
	size_t i=0;
	int    R=0, G=0, B=0, Lum=0;
	const float YCbCrYRF = 0.299f;
	const float YCbCrYGF = 0.587f;
	const float YCbCrYBF = 0.114f;

	//取得亮度通道
	if ( RGBImageToGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB, LumStep, LumPtr1, YCbCrYRF, YCbCrYGF, YCbCrYBF) == false )
	{
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}	
	
	//取得平滑圖來當作參考數據
	//if ( SmoothGrayImageByIntegral3(ImageW, ImageH, LumStep, LumPtr1, CalcSize, RefPtr) == false )//慢
	if ( SmoothGrayImage3(ImageW, ImageH, LumStep, LumPtr1, CalcSize, RefPtr) == false )
	{	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;
	}

	if ( fabs(Gamma) < 0.001 ) { Gamma = 1.0; }
	unsigned char *LutPtr = BuildLocalGammaTable(Gamma);
	if ( NULL == LutPtr )
	{	
		JetMemory.free_func(RefPtr);
		JetMemory.free_func(LumPtr1);
		JetMemory.free_func(LumPtr2);
		return false;	
	}
	//針對亮度做局部Gamma處理
	for ( i=0; i<LumBufferSiZe; i++ )
	{	LumPtr2[i] = (unsigned char)(LutPtr[LumPtr1[i]*256+RefPtr[i]]);	}
	JetMemory.free_func(LutPtr);

	//計算最末彩色影像
	int Y=0, Y2=0;
	int R2=0, G2=0, B2=0;
	//R = (Yf/Y(R+Y)+R-Y)/2
	//G = (Yf/Y(G+Y)+G-Y)/2
	//B = (Yf/Y(B+Y)+B-Y)/2
	for ( i=0; i<LumBufferSiZe; i++ )
	{
		B = pB[i];
		G = pG[i];
		R = pR[i];
		Y = LumPtr1[i];
		Y2= LumPtr2[i];
		if ( 0 == Y ) 
		{	R2 = G2 = B2 = 0;	}
		else
		{
			R2 = ((Y2*(R+Y)/Y)+R-Y)/2;
			G2 = ((Y2*(G+Y)/Y)+G-Y)/2;
			B2 = ((Y2*(B+Y)/Y)+B-Y)/2;
		}
		if ( R2 < 0 ) { R2 = 0; }
		else if ( R2 > 255 ) { R2 = 255; }
		if ( G2 < 0 ) { G2 = 0; }
		else if ( G2 > 255 ) { G2 = 255; }
		if ( B2 < 0 ) { B2 = 0; }
		else if ( B2 > 255 ) { B2 = 255; }
			
		pDstB[i] = B2;
		pDstG[i] = G2;
		pDstR[i] = R2;		
	}	
	JetMemory.free_func(RefPtr);
	JetMemory.free_func(LumPtr1);
	JetMemory.free_func(LumPtr2);
	return true;
}
//-------------------------------------------------------------------------------------//
COLORREF CImageAPI::InvertColor(COLORREF clr)//負片顏色
{
	int Red = GetRValue(clr);	
	int Grn = GetGValue(clr);	
	int Blu = GetBValue(clr);	
	int R = 255-Red;
	int G = 255-Grn;
	int B = 255-Blu;
	return (RGB(R, G, B));
}
//-------------------------------------------------------------------------------------//
COLORREF CImageAPI::InterpolateColorValue(COLORREF clrHigh, COLORREF clrLow, double Ratio)//計算中間顏色
{
	int RedH = GetRValue(clrHigh);
	int RedL = GetRValue(clrLow);
	int GrnH = GetGValue(clrHigh);
	int GrnL = GetGValue(clrLow);
	int BluH = GetBValue(clrHigh);
	int BluL = GetBValue(clrLow);
	int R=0, G=0, B=0;

	Ratio = Ratio/100.0;
	R = (int)((RedH*Ratio)+(RedL*(1-Ratio)));
	G = (int)((GrnH*Ratio)+(GrnL*(1-Ratio)));
	B = (int)((BluH*Ratio)+(BluL*(1-Ratio)));
	return (RGB(R, G, B));
}
