bool CImageAPI::InvertImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *&pDst)//影像反相
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return InvertGrayImage(ImageW, ImageH, ImageStep, pImage, pDst); }
	if ( 24 == BitCount ) 
	{	return InvertColorImage(ImageW, ImageH, ImageStep, pImage, pDst); }
	return false;	
}
