bool CImageAPI::InvertGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, unsigned char *&pDst)//灰階影像反相
{
	const char fnName[] = "CImageAPI::InvertGrayImage";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }		
	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->InvertGrayImage3(ImageW, ImageH, ImageStep, pImage, RoiRect, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::InvertGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &RoiRect, unsigned char *pDst)//灰階影像反相
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }		
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }		

	size_t       i=0, j=0, k=0;
	const size_t  TableSize=256;
	unsigned char Table[TableSize]={0};
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);

	for ( i=0; i<TableSize; i++ )
	{	Table[i] = 255-i;	}
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			k=(i*ImageStep)+j;
			pDst[k] = Table[pImage[k]] ;
		}
	}	
	return true;
}
