bool CImageAPI::FlipImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int FlipMode, unsigned char *&pDst)//影像翻轉
{
	const char fnName[] = "CImageAPI::FlipImage";
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }		
	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FlipImage3(ImageW, ImageH, ImageStep, BitCount, pImage, FlipMode, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FlipImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int FlipMode, unsigned char *pDst)//影像翻轉
{
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pDst) == false )
	{	return false; }	
#ifndef OPENCV_DISABLE
	try
	{	
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);			
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		int flipCode = -1;//XY-Flip
		if ( FLIP_X_AXIS == FlipMode ) 
		{	flipCode = 0; }
		if ( FLIP_Y_AXIS == FlipMode ) 
		{	flipCode = 1; }
		if ( FLIP_XY_AXIS == FlipMode ) 
		{	flipCode = -1; }		
		cv::flip(MatSrc, MatDst, flipCode);
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FlipGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int FlipMode, unsigned char *&pDst)//灰階影像翻轉
{
	const char fnName[] = "CImageAPI::FlipGrayImage";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }		
	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FlipGrayImage3(ImageW, ImageH, ImageStep, pImage, FlipMode, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FlipGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int FlipMode, unsigned char *pDst)//灰階影像翻轉
{
	IMAGE_SIZE BitCount = 8;
	if ( FlipImage3(ImageW, ImageH, ImageStep, BitCount, pImage, FlipMode, pDst) == false ) 
	{	return false; }
	return true;

	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }		
	
	size_t       i=0, j=0;
	size_t       srcIdx=0, dstIdx=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);

	if ( FLIP_X_AXIS == FlipMode )//對X軸翻轉
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = srcIdx+ImageW-1;
			for ( j=0; j<ImageW; j++ )
			{	pDst[dstIdx--] = pImage[srcIdx++];	}
		}
	}

	if ( FLIP_Y_AXIS == FlipMode )//對Y軸翻轉
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = (ImageH-i-1)*ImageStep;
			::memcpy(&(pDst[dstIdx]), &(pImage[srcIdx]), sizeof(unsigned char)*ImageStep);
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FlipColorImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int FlipMode, unsigned char *&pDst)//彩色影像翻轉
{
	const char fnName[] = "CImageAPI::FlipColorImage";
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }		
	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FlipColorImage3(ImageW, ImageH, ImageStep, pImage, FlipMode, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FlipColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int FlipMode, unsigned char *pDst)//彩色影像翻轉
{
	IMAGE_SIZE BitCount = 24;
	if ( FlipImage3(ImageW, ImageH, ImageStep, BitCount, pImage, FlipMode, pDst) == false ) 
	{	return false; }
	return true;

	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }	

	size_t       i=0, j=0;
	size_t       srcIdx=0, dstIdx=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);

	if ( FLIP_X_AXIS == FlipMode )//對X軸翻轉
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = srcIdx+(ImageW*3)-3;
			for ( j=0; j<ImageW; j++ )
			{	
				pDst[dstIdx] = pImage[srcIdx];	
				pDst[dstIdx+1] = pImage[srcIdx+1];	
				pDst[dstIdx+2] = pImage[srcIdx+2];	

				srcIdx += 3;
				dstIdx -= 3;
			}
		}
	}

	if ( FLIP_Y_AXIS == FlipMode )//對Y軸翻轉
	{
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = (ImageH-i-1)*ImageStep;
			::memcpy(&(pDst[dstIdx]), &(pImage[srcIdx]), sizeof(unsigned char)*ImageStep);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MatchImage(IMAGE_SIZE PatW, IMAGE_SIZE PatH, IMAGE_SIZE PatStep, IMAGE_SIZE PatBit, const unsigned char *PatPtr, IMAGE_SIZE RoiW, IMAGE_SIZE RoiH, IMAGE_SIZE RoiStep, IMAGE_SIZE RoiBit, const unsigned char *RoiPtr, float &Score, float &PosX, float &PosY, float &Skew)
{
	if ( CImageAPI::CheckBitCount(PatBit)==false || CImageAPI::CheckBitCount(RoiBit)==false ) 
	{	return false; }
	if ( PatBit != RoiBit )
	{
		m_ErrorString.Format(_T("Error, Roi BitCount[%d] different Pat BitCount[%d]"), RoiBit, PatBit);
		return false;
	}
	if ( 8 == PatBit ) 
	{	return MatchGrayImage(PatW, PatH, PatStep, PatPtr, RoiW, RoiH, RoiStep, RoiPtr, Score, PosX, PosY, Skew); }
	if ( 24 == PatBit ) 
	{	return MatchColorImage(PatW, PatH, PatStep, PatPtr, RoiW, RoiH, RoiStep, RoiPtr, Score, PosX, PosY, Skew); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MatchGrayImage(IMAGE_SIZE PatW, IMAGE_SIZE PatH, IMAGE_SIZE PatStep, const unsigned char *PatPtr, IMAGE_SIZE RoiW, IMAGE_SIZE RoiH, IMAGE_SIZE RoiStep, const unsigned char *RoiPtr, float &Score, float &PosX, float &PosY, float &Skew)
{
	if ( CheckGrayImage(PatW, PatH, PatStep, PatPtr) == false ) { return false; }
	if ( CheckGrayImage(RoiW, RoiH, RoiStep, RoiPtr) == false ) { return false; }

	Score = 0.0;
	CJetMatch    Match;	//影像匹配
	IMAGE_SIZE   BitCount=8;	
	const bool   bRobustness = true;	
	const int    nMinReduceArea = 64;
	const int    nFinalReduction = 0;
	const bool   bAdvancedLearning = true;
	const bool   UseInterpolate = true;//CheckAlgPatternMatrchInterpolate();
	JET_MATCH_LIB_TYPE MatchLibType = AOIDataCollect.GetMatchLibType();
	if ( Match.SetMatchLibType(MatchLibType)==false )
	{	return false;	}

	//initial eMatch
	Match.SetMatchDefaultParam();
	Match.SetRobustness(bRobustness);
	Match.SetMinReducedArea(nMinReduceArea);
	Match.SetFinalReduction(nFinalReduction);
	if ( Match.LearnPattern(PatW, PatH, PatStep, BitCount, PatPtr, true) == false )
	{	return false; }
	
	Match.SetInterpolate(UseInterpolate);
	//Match.SetInterpolate(false);
	Match.SetMinScore(-1);//fMinScore
	if ( Match.Match(RoiW, RoiH, RoiStep, BitCount, RoiPtr, true) == false )
	{	return false; }

	const int NResults = Match.GetNumPositions();
	if ( 0 == NResults )
	{	return true; }

	const int idx = 0;
	const float ResultS = Match.GetResultScore(idx)*100.0;
	const float ResultX = Match.GetResultPosX(idx);
	const float ResultY = Match.GetResultPosY(idx);
	const float ResultA = Match.GetResultAngle(idx);		
	//const float ResultSX = Match.GetResultScaleX(idx);
	//const float ResultSY = Match.GetResultScaleY(idx);
	if ( ResultS < 0 ) 
	{	return true; }
	PosX = ResultX;
	PosY = ResultY;
	Skew = ResultA;
	Score = ResultS;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MatchColorImage(IMAGE_SIZE PatW, IMAGE_SIZE PatH, IMAGE_SIZE PatStep, const unsigned char *PatPtr, IMAGE_SIZE RoiW, IMAGE_SIZE RoiH, IMAGE_SIZE RoiStep, const unsigned char *RoiPtr, float &Score, float &PosX, float &PosY, float &Skew)
{
	if ( CheckColorImage(PatW, PatH, PatStep, PatPtr) == false ) { return false; }
	if ( CheckColorImage(RoiW, RoiH, RoiStep, RoiPtr) == false ) { return false; }

	Score = 0.0;
	CJetMatch    Match;	//影像匹配
	IMAGE_SIZE   BitCount=24;	
	const bool   bRobustness = true;	
	const int    nMinReduceArea = 64;
	const int    nFinalReduction = 0;
	const bool   bAdvancedLearning = true;
	const bool   UseInterpolate = true;//CheckAlgPatternMatrchInterpolate();
	JET_MATCH_LIB_TYPE MatchLibType = AOIDataCollect.GetMatchLibType();
	if ( Match.SetMatchLibType(MatchLibType)==false )
	{	return false;	}

	//initial eMatch
	Match.SetMatchDefaultParam();
	Match.SetRobustness(bRobustness);
	Match.SetMinReducedArea(nMinReduceArea);
	Match.SetFinalReduction(nFinalReduction);
	if ( Match.LearnPattern(PatW, PatH, PatStep, BitCount, PatPtr, true) == false )
	{	return false; }
	
	Match.SetInterpolate(UseInterpolate);
	//Match.SetInterpolate(false);
	Match.SetMinScore(-1);//fMinScore
	if ( Match.Match(RoiW, RoiH, RoiStep, BitCount, RoiPtr, true) == false )
	{	return false; }

	const int NResults = Match.GetNumPositions();
	if ( 0 == NResults )
	{	return true; }

	const int idx = 0;
	const float ResultS = Match.GetResultScore(idx)*100.0;
	const float ResultX = Match.GetResultPosX(idx);
	const float ResultY = Match.GetResultPosY(idx);
	const float ResultA = Match.GetResultAngle(idx);		
	//const float ResultSX = Match.GetResultScaleX(idx);
	//const float ResultSY = Match.GetResultScaleY(idx);				
	if ( ResultS < 0 ) 
	{	return true; }

	PosX = ResultX;
	PosY = ResultY;
	Skew = ResultA;
	Score = ResultS;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2Image(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage1, const unsigned char *pImage2, int nGridX, int nGridY, double &Score)
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return Compare2GrayImage(ImageW, ImageH, ImageStep, pImage1, pImage2, nGridX, nGridY, Score); }
	if ( 24 == BitCount ) 
	{	return Compare2ColorImage(ImageW, ImageH, ImageStep, pImage1, pImage2, nGridX, nGridY, Score); }
	return false;		
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2GrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nGridX, int nGridY, double &Score)
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( 0 >= nGridX ) { nGridX = 1; }
	if ( 0 >= nGridY ) { nGridY = 1; }
	int          n=0;
	int          s=0, t=0;	
	RECT         GridRect;
	int          i=0, j=0, k=0;	
	int          v1=0, v2=0;		
	double       xy=0, xx=0, yy=0;
	double       sum_xy=0, sum_x=0, sum_y=0;	
	double       sum_xx=0, sum_yy=0;
	const int nGridXY = nGridX*nGridY;
	const unsigned char *pImg1 = NULL;
	const unsigned char *pImg2 = NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const int    GridSizeX = (int)(ImageW/nGridX);
	const int    GridSizeY = (int)(ImageH/nGridY);
	const int    TotalGridSizeX = GridSizeX*nGridX;
	const int    TotalGridSizeY = GridSizeY*nGridY;
	const int    GridOffsetX = (ImageW-TotalGridSizeX)/2;
	const int    GridOffsetY = (ImageH-TotalGridSizeY)/2;
	std::vector<RECT>   GridList;
	std::vector<double> ScoreList;
	int          DummyCount=0;
	const int    DummyGray=8;
	const int    DummyGray2=2*DummyGray;
	const bool   AddDummyGray=true;
	//const int    MaxDummyCount = MIN(GridSizeX, GridSizeY);
	const int    MaxDummyCount = (GridSizeX*GridSizeY)/8;

	GridList.clear();
	for ( s=0; s<nGridY; s++ )
	{
		for ( t=0; t<nGridX; t++ )
		{
			GridRect.left = GridOffsetX+(t*GridSizeX);
			GridRect.top  = GridOffsetY+(s*GridSizeY);
			GridRect.right = GridRect.left+GridSizeX;			
			GridRect.bottom = GridRect.top+GridSizeY;
			GridList.push_back(GridRect);
		}
	}
	const int GridCount = (int)(GridList.size());

	for ( s=0; s<GridCount; s++ )
	{
		GridRect = GridList[s];
		if ( true == AddDummyGray )
		{	DummyCount = 0; }
		else
		{	DummyCount = MaxDummyCount+100; }

		n = 0;	
		sum_xx = sum_yy= 0;
		sum_xy = sum_x = sum_y = 0;	
		for ( j=GridRect.top; j<GridRect.bottom; j++ )
		{
			k = (j*ImageStep)+GridRect.left;
			pImg1 = pImage1+k;
			pImg2 = pImage2+k;
			for ( i=GridRect.left; i<GridRect.right; i++ )
			{
				v1 = *(pImg1++);
				v2 = *(pImg2++);

				if ( DummyCount < MaxDummyCount )
				{
					v1 += DummyGray;
					if ( v1 > 255 ) { v1 -= DummyGray2; }

					v2 += DummyGray;
					if ( v2 > 255 ) { v2 -= DummyGray2; }					
					DummyCount ++;
				}

				xx = v1*v1;
				yy = v2*v2;
				xy = v1*v2;
				sum_x  = sum_x+v1;
				sum_y  = sum_y+v2;
				sum_xy = sum_xy+xy;
				sum_xx = sum_xx+xx;
				sum_yy = sum_yy+yy;

				n ++;
			}
		}

		double r = 1.0;
		if ( n > 0 ) 
		{
			double r1 = (n*sum_xy)-(sum_x*sum_y);
			double r2a = ::sqrt((n*sum_xx)-(sum_x*sum_x));
			double r2b = ::sqrt((n*sum_yy)-(sum_y*sum_y));
			double r2ab = r2a*r2b;
			if ( fabs(r2ab) > 0.0001 )
			{	r = r1/(r2ab);	}
			if ( r > 1.0 ) { r = 1.0; }
			if ( r < 0.0 ) { r = 0.0; }
		}
		else 
		{	r = 0.0; }

		Score = r;
		if ( Score > 1.0 ) { Score = 1.0; }
		if ( Score < 0.0 ) { Score = 0.0; }	
		Score = 100.0*Score;
		ScoreList.push_back(Score);			
	}

	Score = 1000;
	const int nScoreCnt = (int)(ScoreList.size());
	for ( s=0; s<nScoreCnt; s++ )
	{
		if ( Score > ScoreList[s] ) 
		{	Score = ScoreList[s]; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nGridX, int nGridY, double &Score)
{
	return Compare2ColorImage_1(ImageW, ImageH, ImageStep, pImage1, pImage2, nGridX, nGridY, Score);
	//return Compare2ColorImage_2(ImageW, ImageH, ImageStep, pImage1, pImage2, nGridX, nGridY, Score);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImage_1(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nGridX, int nGridY, double &Score)
{
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( 0 >= nGridX ) { nGridX = 1; }
	if ( 0 >= nGridY ) { nGridY = 1; }

	int          n = 0;
	int          s=0, t=0;	
	RECT         GridRect;
	int          SpotIndex=0;
	int          i=0, j=0, k=0;
	int          R1=0, G1=0, B1=0;
	int          R2=0, G2=0, B2=0;
	int          dR=0, dG=0, dB=0;
	double       xy=0, xx=0, yy=0;	
	double       sum_xy=0, sum_x=0, sum_y=0;		
	double       sum_xx=0, sum_yy=0;
	const int nGridXY = nGridX*nGridY;
	const unsigned char *pImg1 = NULL;
	const unsigned char *pImg2 = NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const int    GridSizeX = (int)(ImageW/nGridX);
	const int    GridSizeY = (int)(ImageH/nGridY);
	const int    TotalGridSizeX = GridSizeX*nGridX;
	const int    TotalGridSizeY = GridSizeY*nGridY;
	const int    GridOffsetX = (ImageW-TotalGridSizeX)/2;
	const int    GridOffsetY = (ImageH-TotalGridSizeY)/2;	
	std::vector<RECT>   GridList;
	std::vector<double> ScoreList;
	int          DummyCount=0;
	const int    DummyGray=8;
	const int    DummyGray2=2*DummyGray;
	const bool   AddDummyGray=true;
	//const int    MaxDummyCount = MIN(GridSizeX, GridSizeY)*4;
	const int    MaxDummyCount = (GridSizeX*GridSizeY)/8;

	GridList.clear();
	for ( s=0; s<nGridY; s++ )
	{
		for ( t=0; t<nGridX; t++ )
		{
			GridRect.left = GridOffsetX+(t*GridSizeX);
			GridRect.top  = GridOffsetY+(s*GridSizeY);
			GridRect.right = GridRect.left+GridSizeX;			
			GridRect.bottom = GridRect.top+GridSizeY;
			GridList.push_back(GridRect);
		}
	}
	const int GridCount = (int)(GridList.size());
	
	for ( s=0; s<GridCount; s++ )
	{
		GridRect = GridList[s];		
		if ( true == AddDummyGray )
		{	DummyCount = 0; }
		else
		{	DummyCount = MaxDummyCount+100; }
		n = 0;
		xy = xx = yy = 0;
		sum_xy = sum_x = sum_y = 0;	
		sum_xx = sum_yy = 0;		
		for ( j=GridRect.top; j<GridRect.bottom; j++ )
		{
			k = (j*ImageStep)+(GridRect.left*3);
			pImg1 = pImage1+k;
			pImg2 = pImage2+k;
			for ( i=GridRect.left; i<GridRect.right; i++ )
			{
				B1 = *(pImg1++);
				G1 = *(pImg1++);
				R1 = *(pImg1++);

				B2 = *(pImg2++);
				G2 = *(pImg2++);
				R2 = *(pImg2++);

				if ( DummyCount < MaxDummyCount )
				{
					B1 += DummyGray;
					if ( B1 > 255 ) { B1 -= DummyGray2; }

					G1 += DummyGray;
					if ( G1 > 255 ) { G1 -= DummyGray2; }

					R1 += DummyGray;
					if ( R1 > 255 ) { R1 -= DummyGray2; }

					B2 += DummyGray;
					if ( B2 > 255 ) { B2 -= DummyGray2; }

					G2 += DummyGray;
					if ( G2 > 255 ) { G2 -= DummyGray2; }

					R2 += DummyGray;
					if ( R2 > 255 ) { R2 -= DummyGray2; }					 
					DummyCount ++; 
				}

				n  ++;
				xx = R1*R1;
				yy = R2*R2;
				xy = R1*R2;
				sum_x  = sum_x+R1;
				sum_y  = sum_y+R2;
				sum_xy = sum_xy+xy;
				sum_xx = sum_xx+xx;
				sum_yy = sum_yy+yy;

				n  ++;
				xx = G1*G1;
				yy = G2*G2;
				xy = G1*G2;
				sum_x  = sum_x+G1;
				sum_y  = sum_y+G2;
				sum_xy = sum_xy+xy;
				sum_xx = sum_xx+xx;
				sum_yy = sum_yy+yy;

				n  ++;
				xx = B1*B1;
				yy = B2*B2;
				xy = B1*B2;
				sum_x  = sum_x+B1;
				sum_y  = sum_y+B2;
				sum_xy = sum_xy+xy;
				sum_xx = sum_xx+xx;
				sum_yy = sum_yy+yy;
			}
		}

		double r = 1.0;
		if ( n > 0 ) 
		{
			double r1 = (n*sum_xy)-(sum_x*sum_y);
			double r2a = ::sqrt((n*sum_xx)-(sum_x*sum_x));
			double r2b = ::sqrt((n*sum_yy)-(sum_y*sum_y));
			double r2ab = r2a*r2b;
			if ( fabs(r2ab) > 0.0001 )
			{	r = r1/(r2ab);	}
			if ( r > 1.0 ) { r = 1.0; }
			if ( r < 0.0 ) { r = 0.0; }
		}
		else 
		{	r = 0.0; }
		Score = r;
		if ( Score > 1.0 ) { Score = 1.0; }
		if ( Score < 0.0 ) { Score = 0.0; }
		Score = 100.0*Score;
		ScoreList.push_back(Score);		
	}

	Score = 1000;
	const int nScoreCnt = (int)(ScoreList.size());
	for ( s=0; s<nScoreCnt; s++ )
	{
		if ( Score > ScoreList[s] ) 
		{	Score = ScoreList[s]; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImage_2(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nGridX, int nGridY, double &Score)
{
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( 0 >= nGridX ) { nGridX = 1; }
	if ( 0 >= nGridY ) { nGridY = 1; }

	int          n = 0;
	int          s=0, t=0;	
	RECT         GridRect;
	int          SpotIndex=0;
	int          i=0, j=0, k=0;
	int          R1=0, G1=0, B1=0;
	int          R2=0, G2=0, B2=0;
	int          dR=0, dG=0, dB=0;
	double       xy_R=0, xx_R=0, yy_R=0;
	double       xy_G=0, xx_G=0, yy_G=0;
	double       xy_B=0, xx_B=0, yy_B=0;
	double       sum_xy_R=0, sum_x_R=0, sum_y_R=0;
	double       sum_xy_G=0, sum_x_G=0, sum_y_G=0;
	double       sum_xy_B=0, sum_x_B=0, sum_y_B=0;
	double       sum_xx_R=0, sum_yy_R=0;
	double       sum_xx_G=0, sum_yy_G=0;
	double       sum_xx_B=0, sum_yy_B=0;
	const int nGridXY = nGridX*nGridY;
	const unsigned char *pImg1 = NULL;
	const unsigned char *pImg2 = NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const int    GridSizeX = (int)(ImageW/nGridX);
	const int    GridSizeY = (int)(ImageH/nGridY);
	const int    TotalGridSizeX = GridSizeX*nGridX;
	const int    TotalGridSizeY = GridSizeY*nGridY;
	const int    GridOffsetX = (ImageW-TotalGridSizeX)/2;
	const int    GridOffsetY = (ImageH-TotalGridSizeY)/2;	
	std::vector<RECT>   GridList;
	std::vector<double> ScoreList;
	int          DummyCount=0;
	const int    DummyGray=8;
	const int    DummyGray2=2*DummyGray;
	const bool   AddDummyGray=true;
	//const int    MaxDummyCount = MIN(GridSizeX, GridSizeY);
	const int    MaxDummyCount = (GridSizeX*GridSizeY)/8;

	GridList.clear();
	for ( s=0; s<nGridY; s++ )
	{
		for ( t=0; t<nGridX; t++ )
		{
			GridRect.left = GridOffsetX+(t*GridSizeX);
			GridRect.top  = GridOffsetY+(s*GridSizeY);
			GridRect.right = GridRect.left+GridSizeX;			
			GridRect.bottom = GridRect.top+GridSizeY;
			GridList.push_back(GridRect);
		}
	}
	const int GridCount = (int)(GridList.size());
	
	for ( s=0; s<GridCount; s++ )
	{
		GridRect = GridList[s];		
		if ( true == AddDummyGray )
		{	DummyCount = 0; }
		else
		{	DummyCount = MaxDummyCount+100; }
		n = 0;		
		sum_x_R = sum_y_R = 0.0;
		sum_xy_R = sum_xx_R = sum_yy_R = 0.0;
		sum_x_G = sum_y_G = 0.0;
		sum_xy_G = sum_xx_G = sum_yy_G = 0.0;
		sum_x_B = sum_y_B = 0.0;
		sum_xy_B = sum_xx_B = sum_yy_B = 0.0;
		for ( j=GridRect.top; j<GridRect.bottom; j++ )
		{
			k = (j*ImageStep)+(GridRect.left*3);
			pImg1 = pImage1+k;
			pImg2 = pImage2+k;
			for ( i=GridRect.left; i<GridRect.right; i++ )
			{
				B1 = *(pImg1++);
				G1 = *(pImg1++);
				R1 = *(pImg1++);

				B2 = *(pImg2++);
				G2 = *(pImg2++);
				R2 = *(pImg2++);

				if ( DummyCount < MaxDummyCount )
				{
					B1 += DummyGray;
					if ( B1 > 255 ) { B1 -= DummyGray2; }

					G1 += DummyGray;
					if ( G1 > 255 ) { G1 -= DummyGray2; }

					R1 += DummyGray;
					if ( R1 > 255 ) { R1 -= DummyGray2; }

					B2 += DummyGray;
					if ( B2 > 255 ) { B2 -= DummyGray2; }

					G2 += DummyGray;
					if ( G2 > 255 ) { G2 -= DummyGray2; }

					R2 += DummyGray;
					if ( R2 > 255 ) { R2 -= DummyGray2; }					 
					DummyCount ++; 
				}

				n  ++;
				xx_R = R1*R1;
				yy_R = R2*R2;
				xy_R = R1*R2;
				sum_x_R  = sum_x_R+R1;
				sum_y_R  = sum_y_R+R2;
				sum_xy_R = sum_xy_R+xy_R;
				sum_xx_R = sum_xx_R+xx_R;
				sum_yy_R = sum_yy_R+yy_R;

				xx_G = G1*G1;
				yy_G = G2*G2;
				xy_G = G1*G2;
				sum_x_G  = sum_x_G+G1;
				sum_y_G  = sum_y_G+G2;
				sum_xy_G = sum_xy_G+xy_G;
				sum_xx_G = sum_xx_G+xx_G;
				sum_yy_G = sum_yy_G+yy_G;

				xx_B = B1*B1;
				yy_B = B2*B2;
				xy_B = B1*B2;
				sum_x_B  = sum_x_B+B1;
				sum_y_B  = sum_y_B+B2;
				sum_xy_B = sum_xy_B+xy_B;
				sum_xx_B = sum_xx_B+xx_B;
				sum_yy_B = sum_yy_B+yy_B;
			}
		}

		double r_R = 1.0;
		double r_G = 1.0;
		double r_B = 1.0;
		if ( n > 0 ) 
		{
			double r1_R = (n*sum_xy_R)-(sum_x_R*sum_y_R);
			double r2a_R = ::sqrt((n*sum_xx_R)-(sum_x_R*sum_x_R));
			double r2b_R = ::sqrt((n*sum_yy_R)-(sum_y_R*sum_y_R));
			double r2ab_R = r2a_R*r2b_R;
			if ( fabs(r2ab_R) > 0.0001 )
			{	r_R = r1_R/(r2ab_R);	}
		
			double r1_G = (n*sum_xy_G)-(sum_x_G*sum_y_G);
			double r2a_G = ::sqrt((n*sum_xx_G)-(sum_x_G*sum_x_G));
			double r2b_G = ::sqrt((n*sum_yy_G)-(sum_y_G*sum_y_G));
			double r2ab_G = r2a_G*r2b_G;
			if ( fabs(r2ab_G) > 0.0001 )
			{	r_G = r1_G/(r2ab_G);	}
		
			double r1_B = (n*sum_xy_B)-(sum_x_B*sum_y_B);
			double r2a_B = ::sqrt((n*sum_xx_B)-(sum_x_B*sum_x_B));
			double r2b_B = ::sqrt((n*sum_yy_B)-(sum_y_B*sum_y_B));
			double r2ab_B = r2a_B*r2b_B;
			if ( fabs(r2ab_B) > 0.0001 )
			{	r_B = r1_B/(r2ab_B); }
		}
		else 
		{	r_R = r_G = r_B = 0.0;	}
		Score = r_R;
		if ( Score > r_G ) { Score = r_G; }
		if ( Score > r_B ) { Score = r_B; }
		if ( Score > 1.0 ) { Score = 1.0; }
		if ( Score < 0.0 ) { Score = 0.0; }
		Score = 100.0*Score;
		ScoreList.push_back(Score);		
	}

	Score = 1000;
	const int nScoreCnt = (int)(ScoreList.size());
	for ( s=0; s<nScoreCnt; s++ )
	{
		if ( Score > ScoreList[s] ) 
		{	Score = ScoreList[s]; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE &ScoreStep, unsigned char *&ScorePtr)
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return Compare2GrayImageRoi(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr); }
	if ( 24 == BitCount ) 
	{	return Compare2ColorImageRoi(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr); }
	return false;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ImageRoi3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE ScoreStep, unsigned char *ScorePtr)
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return Compare2GrayImageRoi3(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr); }
	if ( 24 == BitCount ) 
	{	return Compare2ColorImageRoi3(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr); }
	return false;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2GrayImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE &ScoreStep, unsigned char *&ScorePtr)
{
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( CheckRoiSize(ImageW, ImageH, nRoiSizeW, nRoiSizeH) == false ) 
	{	return false; }

	JetMemory.free_func(ScorePtr);
	ScoreStep = GetImageAlignedWidth(ImageW, 8, 4);
	const size_t BufferSize = CalcBufferSize(ScoreStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, ScorePtr, "CImageAPI::Compare2GrayImageRoi", "ScorePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( Compare2GrayImageRoi3(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2GrayImageRoi3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE ScoreStep, unsigned char *ScorePtr)
{
	if ( CheckGrayImage(ImageW, ImageH, ScoreStep, ScorePtr) == false )
	{	return false; }
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }	
	if ( CheckRoiSize(ImageW, ImageH, nRoiSizeW, nRoiSizeH) == false ) 
	{	return false; }

	size_t i=0, j=0;
	size_t s=0, t=0;
	size_t srcIdx=0, dstIdx=0;
	double r = 1.0;
	double r1 = 0.0;
	double r2a = 0.0;
	double r2b = 0.0;
	double r2ab = 0.0;
	double sum_x=0, sum_y=0, n=0;
	double sum_xy=0, sum_xx=0, sum_yy=0;
	int v1=0, v2=0;
	int xx=0, yy=0, xy=0;	
	const size_t uRoiSizeW2 = (size_t)(nRoiSizeW/2);
	const size_t uRoiSizeH2 = (size_t)(nRoiSizeH/2);	
	const size_t ScoreSize = CalcBufferSize(ScoreStep, ImageH);
	::memset(ScorePtr, 0xFF, sizeof(unsigned char)*ScoreSize);
	for ( i=uRoiSizeH2; i<ImageH-uRoiSizeH2; i++ )
	{		
		for ( j=uRoiSizeW2; j<ImageW-uRoiSizeW2; j++ )
		{
			sum_y = sum_x = n=0;
			sum_xy = sum_xx = sum_yy = 0;
			for ( s=i-uRoiSizeH2; s<=i+uRoiSizeH2; s++ )
			{
				srcIdx = (s*ImageStep)+(j-uRoiSizeW2);
				for ( t=j-uRoiSizeW2; t<=j+uRoiSizeW2; t++ )
				{
					v1 = pImage1[srcIdx];
					v2 = pImage2[srcIdx];
					xx = v1*v1;
					yy = v2*v2;
					xy = v1*v2;

					sum_x  = sum_x+v1;
					sum_y  = sum_y+v2;
					sum_xy = sum_xy+xy;
					sum_xx = sum_xx+xx;
					sum_yy = sum_yy+yy;

					n ++;

					srcIdx ++;
					dstIdx ++;
				}
			}
			r = 1.0;
			if ( n > 0 ) 
			{
				double r1 = (n*sum_xy)-(sum_x*sum_y);
				double r2a = ::sqrt((n*sum_xx)-(sum_x*sum_x));
				double r2b = ::sqrt((n*sum_yy)-(sum_y*sum_y));
				double r2ab = r2a*r2b;
				if ( fabs(r2ab) > 0.0001 )
				{	r = r1/(r2ab);	}
				if ( r > 1.0 ) { r = 1.0; }
				if ( r < 0.0 ) { r = 0.0; }
			}
			else 
			{	r = 0.0; }
			dstIdx = (i*ScoreStep)+j;
			ScorePtr[dstIdx] = (unsigned char)(r*255.0);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE &ScoreStep, unsigned char *&ScorePtr)
{
	if ( CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( CheckRoiSize(ImageW, ImageH, nRoiSizeW, nRoiSizeH) == false ) 
	{	return false; }

	JetMemory.free_func(ScorePtr);
	ScoreStep = GetImageAlignedWidth(ImageW, 8, 4);
	const size_t BufferSize = CalcBufferSize(ScoreStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, ScorePtr, "CImageAPI::Compare2ColorImageRoi", "ScorePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( Compare2ColorImageRoi3(ImageW, ImageH, ImageStep, pImage1, pImage2, nRoiSizeW, nRoiSizeH, ScoreStep, ScorePtr) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImageRoi3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, int nRoiSizeW, int nRoiSizeH, IMAGE_SIZE ScoreStep, unsigned char *ScorePtr)
{
	if ( CheckGrayImage(ImageW, ImageH, ScoreStep, ScorePtr) == false )
	{	return false; }
	if ( CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }
	if ( CheckRoiSize(ImageW, ImageH, nRoiSizeW, nRoiSizeH) == false ) 
	{	return false; }

	size_t i=0, j=0;
	size_t s=0, t=0;
	size_t srcIdx=0, dstIdx=0;
	double r = 1.0;
	double r1 = 0.0;
	double r2a = 0.0;
	double r2b = 0.0;
	double r2ab = 0.0;
	double sum_x=0, sum_y=0, n=0;
	double sum_xy=0, sum_xx=0, sum_yy=0;
	int R1=0, R2=0;
	int G1=0, G2=0;
	int B1=0, B2=0;
	double xx=0, yy=0, xy=0;	
	const size_t uRoiSizeW2 = (size_t)(nRoiSizeW/2);
	const size_t uRoiSizeH2 = (size_t)(nRoiSizeH/2);	
	const size_t ScoreSize = CalcBufferSize(ScoreStep, ImageH);
	::memset(ScorePtr, 0xFF, sizeof(unsigned char)*ScoreSize);
	for ( i=uRoiSizeH2; i<ImageH-uRoiSizeH2; i++ )
	{		
		for ( j=uRoiSizeW2; j<ImageW-uRoiSizeW2; j++ )
		{
			sum_y = sum_x = n=0;
			sum_xy = sum_xx = sum_yy = 0;
			for ( s=i-uRoiSizeH2; s<=i+uRoiSizeH2; s++ )
			{
				srcIdx = (s*ImageStep)+(j-uRoiSizeW2)*3;
				for ( t=j-uRoiSizeW2; t<=j+uRoiSizeW2; t++ )
				{
					B1 = pImage1[srcIdx];
					B2 = pImage2[srcIdx];
					xx = B1*B1;
					yy = B2*B2;
					xy = B1*B2;
					sum_x  = sum_x+B1;
					sum_y  = sum_y+B2;
					sum_xy = sum_xy+xy;
					sum_xx = sum_xx+xx;
					sum_yy = sum_yy+yy;

					n ++;
					srcIdx ++;

					G1 = pImage1[srcIdx];
					G2 = pImage2[srcIdx];
					xx = G1*G1;
					yy = G2*G2;
					xy = G1*G2;
					sum_x  = sum_x+G1;
					sum_y  = sum_y+G2;
					sum_xy = sum_xy+xy;
					sum_xx = sum_xx+xx;
					sum_yy = sum_yy+yy;

					n ++;
					srcIdx ++;


					R1 = pImage1[srcIdx];
					R2 = pImage2[srcIdx];
					xx = R1*R1;
					yy = R2*R2;
					xy = R1*R2;
					sum_x  = sum_x+R1;
					sum_y  = sum_y+R2;
					sum_xy = sum_xy+xy;
					sum_xx = sum_xx+xx;
					sum_yy = sum_yy+yy;

					n ++;
					srcIdx ++;

				}
			}
			r = 1.0;
			if ( n > 0 ) 
			{
				double r1 = (n*sum_xy)-(sum_x*sum_y);
				double r2a = ::sqrt((n*sum_xx)-(sum_x*sum_x));
				double r2b = ::sqrt((n*sum_yy)-(sum_y*sum_y));
				double r2ab = r2a*r2b;
				if ( fabs(r2ab) > 0.0001 )
				{	r = r1/(r2ab);	}
				if ( r > 1.0 ) { r = 1.0; }
				if ( r < 0.0 ) { r = 0.0; }
			}
			else 
			{	r = 0.0; }
			dstIdx = (i*ScoreStep)+j;
			ScorePtr[dstIdx] = (unsigned char)(r*255.0);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FilterComparePatMask(IMAGE_SIZE MaskW, IMAGE_SIZE MaskH, IMAGE_SIZE MaskStep, const unsigned char *pImage, const TPixelCompareParam &pcParam, unsigned char *pMask)//過濾樣板的遮罩圖
{
	if ( CheckGrayImage2(MaskW, MaskH, MaskStep, pImage, pMask) == false )
	{	return false; }	

	unsigned char *pTempBuffer=NULL;
	const size_t BufferSize=CalcBufferSize(MaskStep, MaskH);
	const int nPatOpenSize = pcParam.nPatOpenSize;
	const int nPatCloseSize = pcParam.nPatCloseSize;
	const int nPatErodeSize = pcParam.nPatErodeSize;
	if ( JetMemory.alloc_func(BufferSize, pTempBuffer, "CImageAPI::FilterComparePatMask", "pTempBuffer") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());		
		return false;
	}		
	
	unsigned char *pTempDst=pMask;	
	unsigned char *pTempSrc=pTempBuffer;
	::memcpy(pTempDst, pImage, sizeof(unsigned char)*BufferSize);	
	if ( nPatOpenSize > 0 )
	{			
		const int IterCount=1;
		const int KenSize=(int)(nPatOpenSize/2)*2+1;
		JetAPI::Swap(pTempSrc, pTempDst);
		if ( MorphGrayImage3(MaskW, MaskH, MaskStep, pTempSrc, MORPH_OPEN, MORPH_SHAPE_RECT, KenSize, IterCount, pTempDst) == false )
		{
			JetMemory.free_func(pTempBuffer);			
			return false;
		}
		
	}
	if ( nPatCloseSize > 0 )
	{			
		const int IterCount=1;
		const int KenSize=(int)(nPatCloseSize/2)*2+1;
		JetAPI::Swap(pTempSrc, pTempDst);
		if ( MorphGrayImage3(MaskW, MaskH, MaskStep, pTempSrc, MORPH_CLOSE, MORPH_SHAPE_RECT, KenSize, IterCount, pTempDst) == false )
		{
			JetMemory.free_func(pTempBuffer);
			return false;
		}
	}
	if ( nPatErodeSize > 0 )
	{			
		const int IterCount=1;
		const int KenSize=(int)(nPatErodeSize/2)*2+1;
		JetAPI::Swap(pTempSrc, pTempDst);
		if ( ErodeGrayImage3(MaskW, MaskH, MaskStep, pTempSrc, KenSize, IterCount, pTempDst) == false )
		{
			JetMemory.free_func(pTempBuffer);
			return false;
		}
	}
	if ( pTempDst != pMask )
	{	::memcpy(pMask, pTempDst, sizeof(unsigned char)*BufferSize);	}
	JetMemory.free_func(pTempBuffer);
	return true;
}
