bool CImageAPI::Compare2ImagePixel(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return Compare2GrayImagePixel(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList); }
	if ( 24 == BitCount ) 
	{	return Compare2ColorImagePixel(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList); }
	return false;		
}
