bool CImageAPI::Compare2GrayImagePixel(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{
	//return Compare2GrayImagePixel_v1(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList);
	return Compare2GrayImagePixel_v2(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2GrayImagePixel_v1(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)	
{
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }	
	
	size_t idx=0;
	size_t i=0, j=0;
	int Dif=0;
	int nV1=0, nV2=0;	
	unsigned char *pResMask = NULL;	
	const int nTolerance = pcParam.nCmpTolerance;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pResMask, "CImageAPI::Compare2GrayImagePixel", "pResMask") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}

	::memset(pResMask, 0x00, sizeof(unsigned char)*BufferSize);
	for ( i=0; i<ImageH; i++ )
	{
		for ( j=0; j<ImageW; j++ )
		{			
			idx = (i*ImageStep)+(j);
			pResMask[idx] =0;
			if ( NULL != pMask )
			{
				if ( 0 == pMask[idx] )
				{	continue;	}
			}

			nV1 = pImage1[idx];
			nV2 = pImage2[idx];

			Dif = ::abs(nV1-nV2)*1.5;
			if ( Dif > 255 ) { Dif = 255; }
			pResMask[idx] = (unsigned char)(Dif);
			continue;

			if ( Dif > nTolerance )
			{	pResMask[idx] = 255; }			
		}
	}		
	if ( Compare2ImagePixelBlob(ImageW, ImageH, ImageStep, pResMask, pcParam, RectList) == false )
	{	
		JetMemory.free_func(pResMask);
		return false; 
	}
	JetMemory.free_func(pResMask);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2GrayImagePixel_v2(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)	
{	
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }	
	
	size_t idx=0;
	size_t i=0, j=0;
	int Dif=0, nAve=0;
	int nV1=0, nV2=0;		
	unsigned char *pPatMask=NULL;	
	unsigned char *pResMask = NULL;		
	std::vector<unsigned char*> ReleasePtrList;	
	const int nDarkLevel = pcParam.nPatDarkLevel;	
	const int nLightLevel = pcParam.nPatLightLevel;	
	const float fCmpDarkGain = pcParam.fCmpDarkGain;
	const float	fCmpLightGain = pcParam.fCmpLightGain;
	const bool bPatPureColor = pcParam.bPatPureColor;
	unsigned char *pImgUsed1 = (unsigned char*)(pImage1);
	unsigned char *pImgUsed2 = (unsigned char*)(pImage2);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( pcParam.nImgBlurSize > 0 )
	{
		pImgUsed1 = pImgUsed2 = NULL;
		if ( JetMemory.alloc_func(BufferSize, pImgUsed1, "CImageAPI::Compare2GrayImagePixel", "pImgUsed1") == false ||
			 JetMemory.alloc_func(BufferSize, pImgUsed2, "CImageAPI::Compare2GrayImagePixel", "pImgUsed2") == false )
		{	
			JetMemory.free_func(pImgUsed1);
			JetMemory.free_func(pImgUsed2);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		ReleasePtrList.push_back(pImgUsed1);
		ReleasePtrList.push_back(pImgUsed2);
		const int KenSize=2*(abs(pcParam.nImgBlurSize)/2)+1;
		if ( SmoothGrayImage3(ImageW, ImageH, ImageStep, pImage1, KenSize, pImgUsed1) == false || 
			 SmoothGrayImage3(ImageW, ImageH, ImageStep, pImage2, KenSize, pImgUsed2) == false )
		{
			JetMemory.free_list(ReleasePtrList);
			return false;
		}
	}

	if ( JetMemory.alloc_func(BufferSize, pResMask, "CImageAPI::Compare2GrayImagePixel", "pResMask") == false ||
		 JetMemory.alloc_func(BufferSize, pPatMask, "CImageAPI::Compare2GrayImagePixel", "pPatMask") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(pResMask);
		JetMemory.free_func(pPatMask);
		JetMemory.free_list(ReleasePtrList);
		return false;
	}
	ReleasePtrList.push_back(pResMask);
	ReleasePtrList.push_back(pPatMask);
	for ( i=0; i<ImageH; i++ )
	{		
		for ( j=0; j<ImageW; j++ )
		{			
			idx = (i*ImageStep)+(j);				
			if ( NULL != pMask )
			{
				if ( 0 == pMask[idx] )
				{	continue;	}
			}				
			nV1 = pImgUsed1[idx];
			if ( nV1<nDarkLevel || nV1>nLightLevel )
			{	pResMask[idx] = 0; }
			else
			{	pResMask[idx] = 255; }
		}
	}
	if ( pcParam.CheckPatUseFilter() == true )
	{	
		if ( FilterComparePatMask(ImageW, ImageH, ImageStep, pResMask, pcParam, pPatMask) == false )
		{
			JetMemory.free_list(ReleasePtrList);
			return false;
		}
	}
	else
	{	::memcpy(pPatMask, pResMask, sizeof(unsigned char)*BufferSize);	}

	if ( true == bPatPureColor )
	{
		int   Count=0;
		float fSum=0.0f;
		for ( i=0; i<ImageH; i++ )
		{
			for ( j=0; j<ImageW; j++ )
			{			
				idx = (i*ImageStep)+(j);
				if ( 0 == pPatMask[idx] ) { continue; }

				nV1 = pImgUsed1[idx];
				fSum += nV1;
				Count ++;
			}
		}	
		if ( Count > 0 )
		{	nAve = fSum/Count;	}
	}

	::memset(pResMask, 0x00, sizeof(unsigned char)*BufferSize);
	for ( i=0; i<ImageH; i++ )
	{
		for ( j=0; j<ImageW; j++ )
		{			
			idx = (i*ImageStep)+(j);
			if ( 0 == pPatMask[idx] ) { continue; }

			if ( true == bPatPureColor )
			{	nV1 = nAve;	}
			else
			{	nV1 = pImgUsed1[idx]; }
			nV2 = pImgUsed2[idx];

			if ( nV1 > nV2 )
			{ Dif = (int)((nV1-nV2)*fCmpDarkGain); }
			else
			{ Dif = (int)((nV2-nV1)*fCmpLightGain); }
			if ( Dif > 255 ) { Dif = 255; }			
			pResMask[idx] = (unsigned char)(Dif);
		}
	}		
	if ( Compare2ImagePixelBlob(ImageW, ImageH, ImageStep, pResMask, pcParam, RectList) == false )
	{			
		JetMemory.free_list(ReleasePtrList);
		return false; 
	}	
	if ( 0 != RectList.size() )
	{	
	#ifdef _DEBUG
		CString str;
		CString DebugFolder=AOIDataCollect.GetAOITempDirectory();		
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2GrayImagePixelPatMask"));
		SaveImage(str, ImageW, ImageH, ImageStep, 8, pPatMask, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2GrayImagePixelMask"));
		SaveImage(str, ImageW, ImageH, ImageStep, 8, pResMask, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2GrayImagePixelImg1"));
		SaveImage(str, ImageW, ImageH, ImageStep, 24, pImgUsed1, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2GrayImagePixelImg2"));
		SaveImage(str, ImageW, ImageH, ImageStep, 24, pImgUsed2, true);
		str = _T("");
	#endif//_DEBUG
	}
	JetMemory.free_list(ReleasePtrList);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImagePixel(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{
	//return Compare2ColorImagePixel_v1(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList);
	return Compare2ColorImagePixel_v2(ImageW, ImageH, ImageStep, pImage1, pImage2, pMask, pcParam, RectList);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImagePixel_v1(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{
	if ( CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }	

	size_t idx=0;
	size_t MaskIdx=0;
	size_t i=0, j=0;
	int Dif=0;	
	int nDR=0, nDG=0, nDB=0, nDV=0, nDMax=0;
	int nR1=0, nG1=0, nB1=0, nV1=0, nSum1=0;
	int nR2=0, nG2=0, nB2=0, nV2=0, nSum2=0;	
	int Threshold =0;
	double BaseRatio=1.0;
	double DarkRatio=1.0;
	double ColorRatio = 5.0/BaseRatio;
	const int nTolerance = pcParam.nCmpTolerance;
	const int nDarkLevel = pcParam.nCmpDarkLevel*3;	
	const int nToleranceDark = MIN(nDarkLevel/2, nTolerance)*BaseRatio;
	const int nToleranceColor = nTolerance/2;
	unsigned char *pResMask=NULL;	
	IMAGE_SIZE MaskStep = GetImageAlignedWidth(ImageW, 8, 4);
	const size_t MaskBufferSize = CalcBufferSize(MaskStep, ImageH);
	if ( JetMemory.alloc_func(MaskBufferSize, pResMask, "CImageAPI::Compare2ColorImagePixel", "pResMask") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}

	DarkRatio = nTolerance*1.0/nToleranceDark;	
	::memset(pResMask, 0x00, sizeof(unsigned char)*MaskBufferSize);

#ifdef _DEBUG
	size_t ImageX=0, ImageY=0;
#endif//_DEBUG
	for ( i=0; i<ImageH; i++ )
	{
	#ifdef _DEBUG
		ImageY = i;
	#endif//_DEBUG
		for ( j=0; j<ImageW; j++ )
		{
		#ifdef _DEBUG
			ImageX = j;
		#endif//_DEBUG
			idx = (i*ImageStep)+(j*3);
			MaskIdx = (i*MaskStep)+(j);			
			if ( NULL != pMask )
			{
				if ( 0 == pMask[MaskIdx] )
				{	continue;	}
			}

			nB1 = pImage1[idx];
			nG1 = pImage1[idx+1];
			nR1 = pImage1[idx+2];
			nV1 = 0;

			nB2 = pImage2[idx];
			nG2 = pImage2[idx+1];
			nR2 = pImage2[idx+2];	
			nV2 = 0;					

		#ifdef _DEBUG
			if ( 105==ImageX && 38==ImageY )
			{
				nV1 = 0;
			}
		#endif//_DEBUG
			
			nSum1 = nR1+nG1+nB1;
			nSum2 = nR2+nG2+nB2;
			//直接相減無法驅離色偏與亮暗變化的差異
			if ( nSum1 > 0 ) 
			{	
				//nV1 = nSum1/3;//取平均
				nV1 = MAX(nR1, nG1);//取最亮
				nV1 = MAX(nV1, nB1);
				nR1=(int)(nR1*255/nSum1);
				nG1=(int)(nG1*255/nSum1);
				nB1=(int)(nB1*255/nSum1);				
			}
			if ( nSum2 > 0 ) 
			{	
				//nV2 = nSum2/3;//取平均
				nV2 = MAX(nR2, nG2);//取最亮
				nV2 = MAX(nV2, nB2);
				nR2=(int)(nR2*255/nSum2);
				nG2=(int)(nG2*255/nSum2);
				nB2=(int)(nB2*255/nSum2);
			}
			
			if ( nSum1<nDarkLevel || nSum2<nDarkLevel )
			//if ( nSum1<nDarkLevel && nSum2<nDarkLevel )
			{	
				nDR  = 0;
				nDG  = 0;
				nDB  = 0;				
				nDV  = (int)(::abs(nV1-nV2)*DarkRatio);				
				Threshold = nTolerance;//nToleranceDark;
				nDMax = nDV;
			}
			else
			{	
				nDR  = ::abs(nR1-nR2)*ColorRatio;
				nDG  = ::abs(nG1-nG2)*ColorRatio;
				nDB  = ::abs(nB1-nB2)*ColorRatio;				
				nDV  = (int)(::abs(nV1-nV2));
				Threshold = nTolerance; 

				nDMax = MAX(nDR, nDG);
				nDMax = MAX(nDB, nDMax);
				nDMax = MAX(nDV, nDMax);				
			}			
			if ( nDMax > 255 )
			{	nDMax = 255; }				
			pResMask[MaskIdx] = (unsigned char)(nDMax);//使用灰階, 這樣可以將深度轉成平面空間
			continue;

			
			if ( nDR>Threshold || nDG>Threshold || nDB>Threshold || nDV>Threshold )
			{	pResMask[MaskIdx] = 255; }

			//Dif = MAX(DR, DG);
			//Dif = MAX(Dif, DB);
			//TestMaskPtr[MaskIdx] = Dif;						
		}
	}		

	if ( Compare2ImagePixelBlob(ImageW, ImageH, MaskStep, pResMask, pcParam, RectList) == false )
	{		
		JetMemory.free_func(pResMask);
		return false; 
	}	
	JetMemory.free_func(pResMask);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ColorImagePixel_v2(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage1, const unsigned char *pImage2, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{	
	if ( CheckColorImage2(ImageW, ImageH, ImageStep, pImage1, pImage2) == false )
	{	return false; }	

	size_t idx=0;
	size_t MaskIdx=0;
	size_t i=0, j=0;
	int Dif=0;	
	int nAveR=0, nAveG=0, nAveB=0;	
	int nDR=0, nDG=0, nDB=0, nDV=0, nDMax=0;
	int nR1=0, nG1=0, nB1=0, nV1=0, nSum1=0;
	int nR2=0, nG2=0, nB2=0, nV2=0, nSum2=0;	
	unsigned char *pResMask=NULL;	
	unsigned char *pPatMask=NULL;		
	std::vector<unsigned char*> ReleasePtrList;	
	const int nDarkLevel = pcParam.nPatDarkLevel;	
	const int nLightLevel = pcParam.nPatLightLevel;					
	const float fCmpDarkGain = pcParam.fCmpDarkGain;
	const float	fCmpLightGain = pcParam.fCmpLightGain;
	const bool bPatPureColor = pcParam.bPatPureColor;
	unsigned char *pImgUsed1 = (unsigned char*)(pImage1);
	unsigned char *pImgUsed2 = (unsigned char*)(pImage2);	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( pcParam.nImgBlurSize > 0 )
	{
		pImgUsed1 = pImgUsed2 = NULL;
		if ( JetMemory.alloc_func(BufferSize, pImgUsed1, "CImageAPI::Compare2ColorImagePixel", "pImgUsed1") == false ||
			 JetMemory.alloc_func(BufferSize, pImgUsed2, "CImageAPI::Compare2ColorImagePixel", "pImgUsed2") == false )
		{	
			JetMemory.free_func(pImgUsed1);
			JetMemory.free_func(pImgUsed2);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		ReleasePtrList.push_back(pImgUsed1);
		ReleasePtrList.push_back(pImgUsed2);
		const int KenSize=2*(abs(pcParam.nImgBlurSize)/2)+1;
		if ( SmoothColorImage3(ImageW, ImageH, ImageStep, pImage1, KenSize, pImgUsed1) == false || 
			 SmoothColorImage3(ImageW, ImageH, ImageStep, pImage2, KenSize, pImgUsed2) == false )
		{
			JetMemory.free_list(ReleasePtrList);
			return false;
		}
		
	}	

	IMAGE_SIZE MaskStep = GetImageAlignedWidth(ImageW, 8, 4);
	const size_t MaskBufferSize = CalcBufferSize(MaskStep, ImageH);
	if ( JetMemory.alloc_func(MaskBufferSize, pResMask, "CImageAPI::Compare2ColorImagePixel", "pResMask") == false ||
		 JetMemory.alloc_func(MaskBufferSize, pPatMask, "CImageAPI::Compare2ColorImagePixel", "pPatMask") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());		
		JetMemory.free_func(pResMask);
		JetMemory.free_func(pPatMask);
		JetMemory.free_list(ReleasePtrList);		
		return false;
	}
	ReleasePtrList.push_back(pResMask);
	ReleasePtrList.push_back(pPatMask);
	for ( i=0; i<ImageH; i++ )
	{		
		for ( j=0; j<ImageW; j++ )
		{			
			idx = (i*ImageStep)+(j*3);
			MaskIdx = (i*MaskStep)+(j);	
			pResMask[MaskIdx] = 0;
			if ( NULL != pMask )
			{
				if ( 0 == pMask[MaskIdx] )
				{	continue;	}
			}
			nB1 = pImgUsed1[idx];
			nG1 = pImgUsed1[idx+1];
			nR1 = pImgUsed1[idx+2];
			nSum1 = nR1+nG1+nB1;
			nV1 = nSum1/3;
			if ( nV1<nDarkLevel || nV1>nLightLevel )
			{	pResMask[MaskIdx] = 0; }
			else
			{	pResMask[MaskIdx] = 255; }
		}
	}
	if ( pcParam.CheckPatUseFilter() == true )
	{	
		if ( FilterComparePatMask(ImageW, ImageH, MaskStep, pResMask, pcParam, pPatMask) == false )
		{
			JetMemory.free_list(ReleasePtrList);
			return false;
		}
	}
	else
	{	::memcpy(pPatMask, pResMask, sizeof(unsigned char)*MaskBufferSize);	}
	
	if ( true == bPatPureColor )
	{	
		int   Count=0;
		float fSumR=0.0f, fSumG=0.0, fSumB=0.0;		
		for ( i=0; i<ImageH; i++ )
		{		
			for ( j=0; j<ImageW; j++ )
			{
				idx = (i*ImageStep)+(j*3);
				MaskIdx = (i*MaskStep)+(j);
				if ( 0 == pPatMask[MaskIdx] ) { continue; }
				nB1 = pImgUsed1[idx];
				nG1 = pImgUsed1[idx+1];
				nR1 = pImgUsed1[idx+2];
				fSumR += nR1;
				fSumG += nG1;
				fSumB += nB1;
				Count ++;
			}
		}
		if ( Count > 0 ) 
		{
			nAveR = (int)(fSumR/Count);
			nAveG = (int)(fSumG/Count);
			nAveB = (int)(fSumB/Count);
		}
	}

	::memset(pResMask, 0x00, sizeof(unsigned char)*MaskBufferSize);
#ifdef _DEBUG
	size_t ImageX=0, ImageY=0;
#endif//_DEBUG	
	for ( i=0; i<ImageH; i++ )
	{
	#ifdef _DEBUG
		ImageY = i;
	#endif//_DEBUG
		for ( j=0; j<ImageW; j++ )
		{
		#ifdef _DEBUG
			ImageX = j;
		#endif//_DEBUG
			idx = (i*ImageStep)+(j*3);
			MaskIdx = (i*MaskStep)+(j);
			if ( 0 == pPatMask[MaskIdx] ) { continue; }

			if ( true == bPatPureColor )
			{
				nB1 = nAveB;
				nG1 = nAveG;
				nR1 = nAveR;
			}
			else
			{
				nB1 = pImgUsed1[idx];
				nG1 = pImgUsed1[idx+1];
				nR1 = pImgUsed1[idx+2];
			}
			nV1 = 0;			

			nB2 = pImgUsed2[idx];
			nG2 = pImgUsed2[idx+1];
			nR2 = pImgUsed2[idx+2];	
			nV2 = 0;
		#ifdef _DEBUG
			if ( 105==ImageX && 38==ImageY )
			{
				nV1 = 0;
			}
		#endif//_DEBUG
			
			nSum1 = nR1+nG1+nB1;
			nSum2 = nR2+nG2+nB2;

			nV1 = nSum1/3;
			nV2 = nSum2/3;

			if ( nR1 > nR2 )
			{ nDR = (int)((nR1-nR2)*fCmpDarkGain); }
			else
			{ nDR = (int)((nR2-nR1)*fCmpLightGain); }
			if ( nG1 > nG2 )
			{ nDG = (int)((nG1-nG2)*fCmpDarkGain); }
			else
			{ nDG = (int)((nG2-nG1)*fCmpLightGain); }
			if ( nB1 > nB2 )
			{ nDB = (int)((nB1-nB2)*fCmpDarkGain); }
			else
			{ nDB = (int)((nB2-nB1)*fCmpLightGain); }			
			//if ( nV1 > nV2 )
			//{ nDV = (int)((nV1-nV2)*fCmpDarkGain); }
			//else
			//{ nDV = (int)((nV2-nV1)*fCmpLightGain); }
			nDMax = (int)(sqrt((nDR*nDR)+(nDG*nDG)+(nDB*nDB))*0.578);//0.578=255/MAX
			if ( nDMax > 255 ) { nDMax = 255; }										
			pResMask[MaskIdx] = (unsigned char)(nDMax);
		}
	}		

	const bool bBlobOK=Compare2ImagePixelBlob(ImageW, ImageH, MaskStep, pResMask, pcParam, RectList);
	if ( 0 != RectList.size() )
	{	
	#ifdef _DEBUG
		CString str;
		CString DebugFolder=AOIDataCollect.GetAOITempDirectory();		
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2ColorImagePixelPatMask"));
		SaveImage(str, ImageW, ImageH, MaskStep, 8, pPatMask, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2ColorImagePixelMask"));
		SaveImage(str, ImageW, ImageH, MaskStep, 8, pResMask, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2ColorImagePixelImg1"));
		SaveImage(str, ImageW, ImageH, ImageStep, 24, pImgUsed1, true);
		str.Format(_T("%s\\%s.PNG"), DebugFolder, _T("Compare2ColorImagePixelImg2"));
		SaveImage(str, ImageW, ImageH, ImageStep, 24, pImgUsed2, true);
		str = _T("");
	#endif//_DEBUG
	}
	JetMemory.free_list(ReleasePtrList);	
	return bBlobOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2ImagePixelBlob(IMAGE_SIZE MaskW, IMAGE_SIZE MaskH, IMAGE_SIZE MaskStep, const unsigned char *pMask, TPixelCompareParam &pcParam, std::vector<RECT> &RectList)
{
	if ( CheckGrayImage(MaskW, MaskH, MaskStep, pMask) == false )
	{	return false; }	

	size_t i=0;
	int MorphMode = 0;
	int nMorphMode = 0;	
	MASK_PTR TempMask1=NULL;
	MASK_PTR TempMask2=NULL;
	MASK_PTR TempMaskSrc=NULL;
	MASK_PTR TempMaskDst=NULL;
	const int nGaussianSize = pcParam.nCmpGaussianSize;
	const int nOpenSize = pcParam.nCmpOpenSize;
	const int nCloseSize = pcParam.nCmpCloseSize;
	const size_t BufferSize = CalcBufferSize(MaskStep, MaskH);

#ifdef _DEBUG	
	CString  str;
	bool     bSave=false;
#endif//_DEBUG
	//計算需要幾個buffer指標
	nMorphMode = 0;
	if ( nGaussianSize > 0 ) { nMorphMode ++; }
	if ( nOpenSize > 0 ) { nMorphMode ++; }
	if ( nCloseSize > 0 ) { nMorphMode ++; }
	if ( nMorphMode > 0 )
	{
		if ( JetMemory.alloc_func(BufferSize, TempMask1, "CImageAPI::Compare2ImagePixelBlob", "TempMask1") == false )
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
	}
	if ( nMorphMode > 1 )
	{
		if ( JetMemory.alloc_func(BufferSize, TempMask2, "CImageAPI::Compare2ImagePixelBlob", "TempMask2") == false )
		{
			JetMemory.free_func(TempMask1);
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
	}

	TempMaskSrc = (MASK_PTR)pMask;
	TempMaskDst = TempMask1;
#ifdef _DEBUG
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_MaskSrc.PNG"));
		SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
	}
#endif//_DEBUG

	if ( nGaussianSize > 0 ) 
	{			
		if ( GaussianGrayImage3(MaskW, MaskH, MaskStep, TempMaskSrc, nGaussianSize, TempMaskDst) == false )
		{
			JetMemory.free_func(TempMask1);
			JetMemory.free_func(TempMask2);
			return false;	
		}
		TempMaskSrc = TempMaskDst;
		if ( TempMaskSrc == TempMask1 ) 
		{	TempMaskDst = TempMask2; }
		else 
		{	TempMaskDst = TempMask1; }
	#ifdef _DEBUG
		if ( true == bSave )
		{
			str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_Gaussian.PNG"));
			SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
		}
	#endif//_DEBUG
	}

	//Binary
	const int nThreshold = pcParam.nCmpTolerance;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( TempMaskSrc[i] < nThreshold ) { TempMaskSrc[i] = 0; }
		else { TempMaskSrc[i] = 255; }
	}
#ifdef _DEBUG
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_Binary.PNG"));
		SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
	}
#endif//_DEBUG

	if ( nMorphMode > 0 ) 
	{	
		const int ShapeMode = MORPH_SHAPE_ELLIPSE;//MORPH_SHAPE_RECT, MORPH_SHAPE_CROSS, MORPH_SHAPE_ELLIPSE;
		if ( nOpenSize > 0 )
		{
			MorphMode = MORPH_OPEN;
			if ( MorphGrayImage3(MaskW, MaskH, MaskStep, TempMaskSrc, MorphMode, ShapeMode, nOpenSize, 1, TempMaskDst) == false )
			{
				JetMemory.free_func(TempMask1);
				JetMemory.free_func(TempMask2);
				return false;	
			}
			TempMaskSrc = TempMaskDst;
			if ( TempMaskSrc == TempMask1 ) 
			{	TempMaskDst = TempMask2; }
			else 
			{	TempMaskDst = TempMask1; }
		#ifdef _DEBUG
			if ( true == bSave )
			{
				str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_MaskOpen.PNG"));
				SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
			}
		#endif//_DEBUG
		}
		if ( nCloseSize > 0 ) 
		{
			MorphMode = MORPH_CLOSE;
			if ( MorphGrayImage3(MaskW, MaskH, MaskStep, TempMaskSrc, MorphMode, ShapeMode, nCloseSize, 1, TempMaskDst) == false )
			{
				JetMemory.free_func(TempMask1);
				JetMemory.free_func(TempMask2);
				return false;	
			}
			TempMaskSrc = TempMaskDst;
			if ( TempMaskSrc == TempMask1 ) 
			{	TempMaskDst = TempMask2; }
			else 
			{	TempMaskDst = TempMask1; }
		#ifdef _DEBUG
			if ( true == bSave )
			{
				str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_MaskClose.PNG"));
				SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
			}
		#endif//_DEBUG
		}
	}	
	if ( NULL == TempMaskSrc )
	{
		JetMemory.free_func(TempMask1);
		JetMemory.free_func(TempMask2);
		return false;	
	}	

	//區塊分析
	RECT     RoiRect;
	CJetBlob BlobDetector;
	BlobDetector.InitialBlob();
	BlobDetector.SetBlobSortMode(BLOB_SORT_PIXELS);
	BlobDetector.SetBlobConnectivity(BLOB_CONNECTIVITY_8);//BLOB_CONNECTIVITY_4, BLOB_CONNECTIVITY_8
	RoiRect.left = 0; RoiRect.top = 0;
	RoiRect.right = MaskW; RoiRect.bottom = MaskH;
#ifdef _DEBUG	
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("Compare2ImagePixelBlob_Blob.PNG"));
		SaveImage(str, MaskW, MaskH, MaskStep, 8, TempMaskSrc, true);
	}
#endif//_DEBUG

	if ( BlobDetector.GrayImageRoiBlobDetect(MaskW, MaskH, MaskStep, TempMaskSrc, RoiRect, 128, 255) == false )
	{	
		JetMemory.free_func(TempMask1);
		JetMemory.free_func(TempMask2);
		m_ErrorString = _T("Error, Blob Fault");
		return false; 
	}
	JetMemory.free_func(TempMask1);
	JetMemory.free_func(TempMask2);
	
	RECT         BlobRect={0,0,0,0};	
	int          BlobW=0, BlobH=0, BlobD=0, BlobArea=0, ComponentIndex=0;
	const int    BlobMinW = pcParam.nBlobMinW;
	const int    BlobMinH = pcParam.nBlobMinH;
	const int    BlobMinD = pcParam.nBlobMinD;
	const int    BlobMinA = pcParam.nBlobMinArea;
	TBlobResult *BlobPtr=NULL;	
	const size_t BlobResCount = BlobDetector.GetBlobCount();
	//std::vector<TBlobResult> BlobList(BlobResCount);		
	
	for ( i=0; i<BlobResCount; i++ )
	{
		BlobPtr = BlobDetector.GetBlobPtr(i, false);
		if ( NULL == BlobPtr ) { continue; }		
		BlobRect = BlobPtr->m_BlobRect;		
		BlobW = BlobRect.right-BlobRect.left;
		BlobH = BlobRect.bottom-BlobRect.top;
		BlobD = (int)(sqrt((BlobW*BlobW)+(BlobH*BlobH))+0.5);//v1.01.03.234
		BlobArea = BlobPtr->m_BlobPixels;
		//BlobPos.x = (BlobRect.right+BlobRect.left)*0.5;
		//BlobPos.y = (BlobRect.top+BlobRect.bottom)*0.5;		
		if ( BlobW < BlobMinW ) { continue; }
		if ( BlobH < BlobMinH ) { continue; }
		if ( BlobD < BlobMinD ) { continue; }//v1.01.03.234
		if ( BlobArea < BlobMinA ) { continue; }
		RectList.push_back(BlobRect);		
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageStatistics(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, TImageStat &Statistics)//計算影像統計資料
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, Statistics.m_Rect) == false )
	{	return false; }
	
	int    i=0, j=0, gryIdx=0;
	int    TotalCount = 0;
	const  int TableSize = 256;
	int    CountTable[TableSize]={0};
	int    Gray=0;
	int    Max = 0;
	int    Min = (int)(TableSize);
	double dGray=0;
	double dSum=0;
	double Ave = 0;
	double Std = 0;
	double Cst = 0;

	::memset(CountTable, 0x00, sizeof(CountTable));
	for ( i=Statistics.m_Rect.top; i<Statistics.m_Rect.bottom; i++ )
	{
		gryIdx = (i*ImageStep)+Statistics.m_Rect.left;
		for ( j=Statistics.m_Rect.left; j<Statistics.m_Rect.right; j++ )
		{
			Gray = pImage[gryIdx];
			if ( Gray > Max ) { Max = Gray; }
			if ( Gray < Min ) { Min = Gray; }

			CountTable[Gray] ++;
			gryIdx ++;
		}
	}

	TotalCount = 0;
	for ( i=0; i<TableSize; i++ )
	{
		Ave += CountTable[i]*i;
		TotalCount += CountTable[i];
	}
	if ( TotalCount > 0 ) 
	{	Ave /= TotalCount;	}

	dSum=0;	
	for ( i=Statistics.m_Rect.top; i<Statistics.m_Rect.bottom; i++ )
	{
		gryIdx = (i*ImageStep)+Statistics.m_Rect.left;
		for ( j=Statistics.m_Rect.left; j<Statistics.m_Rect.right; j++ )
		{
			dGray = pImage[gryIdx];
			dGray = dGray-Ave;
			dGray = dGray*dGray;
			dSum += dGray;

			gryIdx ++;
		}
	}
	if ( TotalCount > 0 ) 
	{
		dSum = dSum/TotalCount;
		Std = ::sqrt(dSum);
	}

	//Constast - 對比值	
	int    CstH = 0;
	int    CstL = 0;
	const int CstNum = TotalCount/5;
	for ( i=0; i<TableSize; i++ )
	{
		CstL += CountTable[i];		
		if ( CstL > CstNum )
		{
			CstL = i;
			break;
		}
	}
	for ( i=TableSize-1; i!=-1; i-- )
	{
		CstH += CountTable[i];		
		if ( CstH > CstNum )
		{
			CstH = i;
			break;
		}
	}
	Cst = CstH-CstL;
	if ( (CstH+CstL) > 0 )
	{	Cst = Cst*100.0/(CstH+CstL); }
	else
	{	Cst = 0; }

	Statistics.m_Ave = Ave;
	Statistics.m_Max = Max;
	Statistics.m_Min = Min;
	Statistics.m_Std = Std;
	Statistics.m_Cst = Cst;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageGridStatistics(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, std::vector<TImageStat> &GridList)//計算影像格子統計資料
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	size_t i=0;
	const size_t GridCount = GridList.size();
	for ( i=0; i<GridCount; i++ )
	{
		if ( CImageAPI::CalcGrayImageStatistics(ImageW, ImageH, ImageStep, pImage, GridList[i]) == false )
		{	return false; }
	}
	
	int MaxGray = 0;
	int MinGray = 1024;
	size_t MaxIndex=0;
	size_t MinIndex=0;
	TImageStat *ImageStatPtr = NULL;
	for ( i=0; i<GridCount; i++ )
	{
		ImageStatPtr = &(GridList[i]);
		if ( NULL == ImageStatPtr ) { continue; }
		
		if ( (ImageStatPtr->m_State&OBJECT_STATE_MAXIMUM) == OBJECT_STATE_MAXIMUM )
		{	ImageStatPtr->m_State ^= OBJECT_STATE_MAXIMUM; }

		if ( (ImageStatPtr->m_State&OBJECT_STATE_MINIMUM) == OBJECT_STATE_MINIMUM )
		{	ImageStatPtr->m_State ^= OBJECT_STATE_MINIMUM; }		

		if ( MaxGray < ImageStatPtr->m_Ave ) 
		{	
			MaxGray = (int)(ImageStatPtr->m_Ave); 
			MaxIndex = i;
		}

		if ( MinGray > ImageStatPtr->m_Ave ) 
		{	
			MinGray = (int)(ImageStatPtr->m_Ave); 
			MinIndex = i;
		}
	}

	if ( MaxGray > 0 ) 
	{	
		if ( MinGray < 0 ) { MinGray = 0; }
		for ( i=0; i<GridCount; i++ )
		{
			ImageStatPtr = &(GridList[i]);
			if ( NULL == ImageStatPtr ) { continue; }			
			ImageStatPtr->m_Ratio = (ImageStatPtr->m_Ave*100.0)/MaxGray;

			if ( i == MaxIndex )
			{	ImageStatPtr->m_State |= OBJECT_STATE_MAXIMUM;	}			

			if ( i == MinIndex )
			{	ImageStatPtr->m_State |= OBJECT_STATE_MINIMUM;	}			
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageGridStatistics(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE NRows, IMAGE_SIZE NCols, std::vector<TImageStat> &GridList)//計算影像格子統計資料
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( (0==NRows) || (0==NCols) ) 
	{
		this->m_ErrorString.Format(_T("Error, Grid Count Excepton (NRows:%d, NCols:%d)"), NRows, NCols);
		return false;
	}
	
	IMAGE_SIZE PitchW = ImageW/NCols;
	IMAGE_SIZE PitchH = ImageH/NRows;
	if ( (0==PitchW) || (0==PitchH) ) 
	{
		this->m_ErrorString.Format(_T("Error, Grid Count Excepton (NRows:%d, NCols:%d)"), NRows, NCols);
		return false;
	}

	unsigned int i=0, j=0;
	TImageStat Grid;
	for ( i=0; i<NRows; i++ )
	{
		for ( j=0; j<NCols; j++ )
		{
			Grid.m_Rect.left = j*PitchW;
			Grid.m_Rect.top = i*PitchH;
			Grid.m_Rect.right = Grid.m_Rect.left+PitchW;
			Grid.m_Rect.bottom = Grid.m_Rect.top+PitchH;
			GridList.push_back(Grid);
		}
	}
	if ( CImageAPI::CalcGrayImageGridStatistics(ImageW, ImageH, ImageStep, pImage, GridList) == false )
	{	return false;	}
	return true;
}
