//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcFloatGrayImageStatistics(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const SPACE_PTR pImage, TImageStat &Statistics)//計算影像統計資料
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, Statistics.m_Rect) == false )
	{	return false; }
	
	int    i=0, j=0, gryIdx=0;
	int    Count=0;
	double dMax =0;	
	double dMin =0;
	double dGray=0;
	double dSum=0;		

	Count= 0;
	dSum = 0.0;
	dMin = FLT_MAX;
	dMax =-FLT_MAX;
	for ( i=Statistics.m_Rect.top; i<Statistics.m_Rect.bottom; i++ )
	{
		gryIdx = (i*ImageStep)+Statistics.m_Rect.left;
		for ( j=Statistics.m_Rect.left; j<Statistics.m_Rect.right; j++ )
		{
			dGray = pImage[gryIdx];
			if ( dGray > dMax ) { dMax = dGray; }
			if ( dGray < dMin ) { dMin = dGray; }			
			Count ++;
			gryIdx ++;
			dSum += dGray;			
		}
	}
	if ( 0 == Count )
	{	return true; }

	double dStd = 0;
	double dCst = 0;
	const double dAve = dSum/Count;	
	dSum = 0.0;
	for ( i=Statistics.m_Rect.top; i<Statistics.m_Rect.bottom; i++ )
	{
		gryIdx = (i*ImageStep)+Statistics.m_Rect.left;
		for ( j=Statistics.m_Rect.left; j<Statistics.m_Rect.right; j++ )
		{
			dGray = pImage[gryIdx];
			dGray = dGray-dAve;
			dGray = dGray*dGray;
			dSum += dGray;

			gryIdx ++;
		}
	}
	if ( Count > 0 ) 
	{
		dSum = dSum/Count;
		dStd = ::sqrt(dSum);
	}

	//Constast - 對比值	
	Statistics.m_Ave = dAve;
	Statistics.m_Max = dMax;
	Statistics.m_Min = dMin;
	Statistics.m_Std = dStd;
	Statistics.m_Cst = dCst;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_Amplitude(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0;	
	double Sum=0.0, Ave=0.0, Gry=0.0;

	val = 0.0;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			Sum += pImage[idx];
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}

	Ave = Sum/Count;
	Sum = 0.0;
	Count = 0;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			Gry = pImage[idx];
			Sum += ::fabs(Gry-Ave);
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Ave = Sum/Count;
	val = Ave;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_Variance(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0;	
	double Sum=0.0, Ave=0.0, Gry=0.0;

	val = 0.0;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			Sum += pImage[idx];
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}

	Ave = Sum/Count;
	Sum = 0.0;
	Count = 0;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			Gry = pImage[idx];
			Gry = ::fabs(Gry-Ave);
			Sum += (Gry*Gry);
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Ave = Sum/(Count);
	val = ::sqrt(Ave);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_SumModulesDifference(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0;	
	double Gry=0.0;
	double SmdX=0.0, SmdY=0.0;
	double GryX=0.0, GryY=0.0;	

	val = 0.0;
	for ( i=RoiRect.top; i<RoiRect.bottom-1; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right-1; j++ )
		{
			idx = (i*ImageStep)+j;
			Gry  = pImage[idx];
			GryX = pImage[idx+1];
			GryY = pImage[idx+ImageStep];
			SmdX += fabs(Gry-GryX);
			SmdY += fabs(Gry-GryY);			
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	val = (SmdX+SmdY)/Count;	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_SquaredGradient(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0;	
	double Gry=0.0;
	double Smd=0.0;
	double SmdX=0.0, SmdY=0.0;
	double GryX=0.0, GryY=0.0;	

	val = 0.0;
	for ( i=RoiRect.top; i<RoiRect.bottom-1; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right-1; j++ )
		{
			idx = (i*ImageStep)+j;
			Gry  = pImage[idx];
			GryX = pImage[idx+1];
			GryY = pImage[idx+ImageStep];
			GryX = Gry-GryX;
			GryY = Gry-GryY;
			SmdX += GryX*GryX;
			SmdY += GryY*GryY;
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Smd = (SmdX+SmdY)/Count;
	val = sqrt(Smd);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_Tenengrad(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0, idx2=0;	
	double Gry=0.0;
	double Sum=0.0;	
	double SobelX=0.0;
	double SobelY=0.0;	

	val = 0.0;
	for ( i=RoiRect.top+1; i<RoiRect.bottom-1; i++ )
	{
		for ( j=RoiRect.left+1; j<RoiRect.right-1; j++ )
		{	
			SobelX = SobelY = 0;
			idx = (i*ImageStep)+j;
			//X              Y
			//-1  0  1       1   2   1
			//-2  0  2       0   0   0  
			//-1  0  1      -1  -2  -1

			//(-1, -1)
			idx2 = idx-ImageStep-1;
			Gry  = pImage[idx2];	
			SobelX -=  Gry;
			SobelY +=  Gry;

			//(+0, -1)
			idx2 = idx-ImageStep;
			Gry  = pImage[idx2];				
			SobelY +=  2*Gry;

			//(+1, -1)
			idx2 = idx-ImageStep+1;
			Gry  = pImage[idx2];	
			SobelX +=  Gry;
			SobelY +=  Gry;

			//(-1, +0)
			idx2 = idx-1;
			Gry  = pImage[idx2];	
			SobelX += -2*Gry;

			//(+0, +0)
			
			
			//(+1, +0)
			idx2 = idx+1;
			Gry  = pImage[idx2];	
			SobelX +=  2*Gry;			

			//(-1, +1)
			idx2 = idx+ImageStep-1;
			Gry  = pImage[idx2];	
			SobelX -=  Gry;
			SobelY -=  Gry;

			//(+0, +1)
			idx2 = idx+ImageStep;
			Gry  = pImage[idx2];
			SobelY += -2*Gry;

			//(+1, +1)
			idx2 = idx+ImageStep+1;
			Gry  = pImage[idx2];	
			SobelX +=  Gry;
			SobelY -=  Gry;

			Sum += (fabs(SobelX)+fabs(SobelY));
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Gry = Sum/Count;
	val = sqrt(Gry);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_Laplacian(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0, idx2=0;	
	double Gry=0.0;
	double Sum=0.0;	
	double Lap=0.0;	

	val = 0.0;
	for ( i=RoiRect.top+1; i<RoiRect.bottom-1; i++ )
	{
		for ( j=RoiRect.left+1; j<RoiRect.right-1; j++ )
		{	
			Lap = 0;
			idx = (i*ImageStep)+j;

			//1   4  1
			//4 -20  4
			//1   4  1

			//(-1, -1)
			idx2 = idx-ImageStep-1;
			Gry  = pImage[idx2];	
			Lap +=  Gry;			

			//(+0, -1)
			idx2 = idx-ImageStep;
			Gry  = pImage[idx2];				
			Lap +=  4*Gry;

			//(+1, -1)
			idx2 = idx-ImageStep+1;
			Gry  = pImage[idx2];	
			Lap +=  Gry;			

			//(-1, +0)
			idx2 = idx-1;
			Gry  = pImage[idx2];	
			Lap += 4*Gry;

			//(+0, +0)
			idx2 = idx;
			Gry  = pImage[idx2];	
			Lap += -20*Gry;
			
			//(+1, +0)
			idx2 = idx+1;
			Gry  = pImage[idx2];	
			Lap +=  4*Gry;			

			//(-1, +1)
			idx2 = idx+ImageStep-1;
			Gry  = pImage[idx2];	
			Lap +=  Gry;			

			//(+0, +1)
			idx2 = idx+ImageStep;
			Gry  = pImage[idx2];
			Lap += 4*Gry;

			//(+1, +1)
			idx2 = idx+ImageStep+1;
			Gry  = pImage[idx2];	
			Lap +=  Gry;			

			Sum += fabs(Lap);
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Gry = Sum/Count;
	val = sqrt(Gry);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageFocusValue_PixelDifference(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR pImage, const IMAGE_PTR pDst, const RECT &RoiRect, double &val)//計算影像對焦數據
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    Count=0;
	int    i=0, j=0, idx=0;	
	double Gry=0.0;
	double Smd=0.0;
	double GryD=0.0;	

	val = 0.0;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			Gry  = pImage[idx];
			GryD = pDst[idx];
			GryD = Gry-GryD;
			Smd += GryD*GryD;
			Count ++;
		}
	}
	if ( 0 == Count ) 
	{	return true;	}
	Gry = Smd/Count;
	val = sqrt(Gry);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ScaleImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, double Scale, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//縮放影像
{
	const char fnName[] = "CImageAPI::ScaleImage";
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }		
	
	if ( CalcScaleSize(ImageW, ImageH, ImageStep, BitCount, Scale, DstW, DstH, DstStep) == false ) 
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->ScaleImage3(ImageW, ImageH, ImageStep, BitCount, pImage, Scale, DstW, DstH, DstStep, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ScaleImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, double Scale, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//縮放影像
{
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }		
	if ( this->CheckImage(DstW, DstH, DstStep, BitCount, pDst) == false )
	{	return false; }		

	IMAGE_SIZE DstW2=0;
	IMAGE_SIZE DstH2=0;
	IMAGE_SIZE DstStep2=0;
	if ( CalcScaleSize(ImageW, ImageH, ImageStep, BitCount, Scale, DstW2, DstH2, DstStep2) == false ) 
	{	return false; }

	if ( DstW2!=DstW || DstH2!=DstH || DstStep2>DstStep ) //比較記憶體尺寸
	{	return false; }
	
#ifndef OPENCV_DISABLE
	try
	{	
		const size_t DstBufferSize = CalcBufferSize(DstStep, DstH);
		const size_t ImageBufferSize = CalcBufferSize(ImageStep, ImageH);	
		if ( DstBufferSize == ImageBufferSize )
		{	::memcpy(pDst, pImage, sizeof(unsigned char)*DstBufferSize);	}
		else
		{
			cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
			cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);		
			if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
			{	return false;	}
			//INTER_NEAREST=CV_INTER_NN=0, //!< nearest neighbor interpolation
			//INTER_LINEAR=CV_INTER_LINEAR=1, //!< bilinear interpolation
			//INTER_CUBIC=CV_INTER_CUBIC=2, //!< bicubic interpolation
			//INTER_AREA=CV_INTER_AREA=3, //!< area-based (or super) interpolation
			cv::resize(MatSrc, MatDst, cv::Size((int)DstW, (int)DstH), 0.0, 0.0, cv::INTER_LINEAR);
			if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst) == false )
			{	return false;	}
		}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcScaleSize(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, double Scale, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep)//計算縮放尺寸
{
	if ( fabs(Scale) < 0.0001 )
	{
		DstW = ImageW;
		DstH = ImageH;		
		DstStep = ImageStep;
	}
	else
	{
		DstW = Ceil(ImageW*Scale);
		DstH = Ceil(ImageH*Scale);
		DstStep = GetImageAlignedWidth(DstW, BitCount, 4);
	}		
	return true;
}
