bool CImageAPI::ScaleMask3(IMAGE_SIZE MaskW, IMAGE_SIZE MaskH, IMAGE_SIZE MaskStep, const unsigned char *MaskPtr, double Scale, IMAGE_SIZE DstW, IMAGE_SIZE DstH, IMAGE_SIZE DstStep, unsigned char *pDst)//縮放遮罩
{
	if ( this->CheckGrayImage(MaskW, MaskH, MaskStep, MaskPtr) == false )
	{	return false; }		
	if ( this->CheckGrayImage(DstW, DstH, DstStep, pDst) == false )
	{	return false; }		

	IMAGE_SIZE DstW2=0;
	IMAGE_SIZE DstH2=0;
	IMAGE_SIZE DstStep2=0;
	const IMAGE_SIZE BitCount = 8;
	if ( CalcScaleSize(MaskW, MaskH, MaskStep, BitCount, Scale, DstW2, DstH2, DstStep2) == false ) 
	{	return false; }

	if ( DstW2!=DstW || DstH2!=DstH || DstStep2>DstStep ) //比較記憶體尺寸
	{	return false; }
	
#ifndef OPENCV_DISABLE
	try
	{	
		const size_t DstBufferSize = CalcBufferSize(DstStep, DstH);
		const size_t ImageBufferSize = CalcBufferSize(MaskStep, MaskH);
		if ( DstBufferSize == ImageBufferSize )
		{	::memcpy(pDst, MaskPtr, sizeof(unsigned char)*DstBufferSize);	}
		else
		{
			cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
			cv::Mat MatSrc=CreateMat(MaskW, MaskH, MaskStep, BitCount, MaskPtr);		
			if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
			{	return false;	}
			//INTER_NEAREST=CV_INTER_NN=0, //!< nearest neighbor interpolation
			//INTER_LINEAR=CV_INTER_LINEAR=1, //!< bilinear interpolation
			//INTER_CUBIC=CV_INTER_CUBIC=2, //!< bicubic interpolation
			//INTER_AREA=CV_INTER_AREA=3, //!< area-based (or super) interpolation
			cv::resize(MatSrc, MatDst, cv::Size((int)DstW, (int)DstH), 0.0, 0.0, cv::INTER_NEAREST);
			if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst) == false )
			{	return false;	}
		}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
