bool CImageAPI::FastScaleImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE NPixels, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//快速縮小影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return FastScaleGrayImage(ImageW, ImageH, ImageStep, pImage, NPixels, DstW, DstH, DstStep, pDst); }
	if ( 24 == BitCount ) 
	{	return FastScaleColorImage(ImageW, ImageH, ImageStep, pImage, NPixels, DstW, DstH, DstStep, pDst); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FastScaleImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE NPixels, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *pDst)//快速縮小影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return FastScaleGrayImage3(ImageW, ImageH, ImageStep, pImage, NPixels, DstW, DstH, DstStep, pDst); }
	if ( 24 == BitCount ) 
	{	return FastScaleColorImage3(ImageW, ImageH, ImageStep, pImage, NPixels, DstW, DstH, DstStep, pDst); }
	return false;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FastScaleGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE NPixels, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//快速縮小灰階影像
{
	const char fnName[] = "CImageAPI::FastScaleGrayImage";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( NPixels == 0 ) { return false; }
	
	DstW = ImageW/NPixels;
	DstH = ImageH/NPixels;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, 4);
	const size_t BufferSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FastScaleGrayImage3(ImageW, ImageH, ImageStep, pImage, NPixels, DstW, DstH, DstStep, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FastScaleGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE NPixels, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *pDst)//快速縮小灰階影像
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	if ( NPixels == 0 ) { return false; }

	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	DstW = ImageW/NPixels;
	DstH = ImageH/NPixels;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 8, 4);

	for ( i=0; i<DstH; i++ )
	{
		DstIdx = i*DstStep;
		SrcIdx = i*NPixels*ImageStep;
		for ( j=0; j<DstW; j++ )
		{
			pDst[DstIdx] = pImage[SrcIdx];
			DstIdx ++;
			SrcIdx += NPixels;
		}
	}
	return true;
}
