//-------------------------------------------------------------------------------------//
bool CImageAPI::FastScaleColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE NPixels, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *pDst)//快速縮小彩色影像
{
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }
	if ( NPixels == 0 ) { return false; }

	size_t i=0, j=0;
	size_t SrcIdx=0, DstIdx=0;
	DstW = ImageW/NPixels;
	DstH = ImageH/NPixels;
	const size_t ColrIdxShift = (NPixels-1)*3;
	DstStep = CImageAPI::GetImageAlignedWidth(DstW, 24, 4);
	for ( i=0; i<DstH; i++ )
	{
		DstIdx = i*DstStep;
		SrcIdx = i*NPixels*ImageStep;
		for ( j=0; j<DstW; j++ )
		{
			pDst[DstIdx++] = pImage[SrcIdx++];//B
			pDst[DstIdx++] = pImage[SrcIdx++];//G
			pDst[DstIdx++] = pImage[SrcIdx++];//R
			SrcIdx += ColrIdxShift;
		}
	}
	return true;
}
