bool CImageAPI::SharpnessGausImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int Radius, int ThL, int Amount, unsigned char *&pDst)//灰階影像銳利化-高斯比較
{
	const char fnName[] = "CImageAPI::SharpnessGausImage";
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false )
	{	return false; }	
	
	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->SharpnessGausImage3(ImageW, ImageH, ImageStep, BitCount, pImage, Radius, ThL, Amount, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SharpnessGausImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int Radius, int ThL, int Amount, unsigned char *pDst)//灰階影像銳利化-高斯比較
{	
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }

#ifndef OPENCV_DISABLE
	try
	{		
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);		
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;		}
		//先行平滑
		const int KerSize=(2*Radius)+1;
		cv::GaussianBlur(MatSrc, MatDst, cv::Size(KerSize, KerSize), 0);		
		
		//合併	
		size_t i=0, j=0;
		size_t srcidx=0, dstidx=0;		
		int    nSrc=0, nBlur=0, nDif=0, nGry=0;
		unsigned char *SrcPtr=MatSrc.data;
		unsigned char *DstPtr=MatDst.data;
		const size_t srcStep=MatSrc.step1();
		const size_t dstStep=MatDst.step1();
		const size_t nRows = MatDst.rows;
		const size_t nCols = MatDst.cols;
		const size_t nChannels = GetImageChannels(BitCount);
		const size_t nColChannels=nCols*nChannels;
		const size_t LineSize = sizeof(unsigned char)*ImageW;		
		for ( i=0; i<nRows; i++ )
		{
			srcidx = i*srcStep;
			dstidx = i*dstStep;
			for ( j=0; j<nColChannels; j++ )
			{
				nSrc = (unsigned char)(SrcPtr[srcidx+j]);
				nBlur = (unsigned char)(DstPtr[dstidx+j]);
				nDif = nSrc-nBlur;
				if ( abs(nDif) > ThL )
				{	
					nGry = (nDif*Amount/100) + nSrc;	
					if ( nGry < 0 ) { DstPtr[dstidx+j] = 0; }
					else if ( nGry > 255 ) { DstPtr[dstidx+j] = 255; }
					else {	DstPtr[dstidx+j] = (unsigned char)(nGry);	}
				}
				else
				{	DstPtr[dstidx+j] = (unsigned char)(SrcPtr[srcidx+j]);	}				
			}
		}		
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
