//-------------------------------------------------------------------------------------//
bool CImageAPI::SharpnessLaps2Image3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *pDst, int KerSize)//灰階影像銳利化-拉普拉斯2
{
	const char fnName[] = "CImageAPI::SharpnessLaps2Image3";
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }

#ifndef OPENCV_DISABLE
	short *BufferPtr=NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr")==false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	try
	{		
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);		
		cv::Mat MatLab=CreateMat(ImageW, ImageH, ImageStep, BitCount, BufferPtr);		
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false || CheckMatIsValid(MatLab)==false )
		{
			JetMemory.free_func(BufferPtr);
			return false;
		}
		//先行平滑
		const int GausKerSize=(((KerSize/2)+1)*3)+1;		
		cv::GaussianBlur(MatSrc, MatDst, cv::Size(GausKerSize, GausKerSize), 0);		
		
		//2階微分		
		cv::Laplacian(MatDst, MatLab, CV_16S, KerSize);

		//合併	
		int    i=0, j=0;
		size_t srcidx=0, dstidx=0, labidx=0;		
		int    nSrc=0, nLaps=0, nGry=0;
		unsigned char *SrcPtr=MatSrc.data;
		unsigned char *DstPtr=MatDst.data;
		short         *LapPtr=(short*)(MatLab.data);
		const int srcStep=MatSrc.step1();
		const int labStep=MatLab.step1();
		const int dstStep=MatDst.step1();
		const int nRows = MatDst.rows;
		const int nCols = MatDst.cols;
		const int nChannels = GetImageChannels(BitCount);
		const int nColChannels=nCols*nChannels;
		size_t LineSize = sizeof(unsigned char)*ImageW;		
		for ( i=0; i<nRows; i++ )
		{
			srcidx = i*srcStep;
			labidx = i*labStep;
			dstidx = i*dstStep;
			for ( j=0; j<nColChannels; j++ )
			{
				nLaps = (short)(LapPtr[labidx+j]);
				nSrc = (unsigned char)(SrcPtr[srcidx+j]);
				if ( nLaps < 0 ) { nLaps = -nLaps; }
				nGry = nSrc+nLaps;				
				if ( nGry < 0 ) { nGry = 0; }
				else if ( nGry > 255 ) { nGry = 255; }
				DstPtr[dstidx+j] = (unsigned char)(nGry);				
			}
		}		
		JetMemory.free_func(BufferPtr);
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);
		JetMemory.free_func(BufferPtr);
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Sharpness4GrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int ThL, int Amount, unsigned char *&pDst)//灰階影像銳利化-4鄰近
{
	const char fnName[] = "CImageAPI::Sharpness4GrayImage";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t   BufferSize = CalcBufferSize(ImageStep, ImageH);	
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->Sharpness4GrayImage3(ImageW, ImageH, ImageStep, pImage, ThL, Amount, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Sharpness4GrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int ThL, int Amount, unsigned char *pDst)//灰階影像銳利化-4鄰近
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }	

	//0    -1    0
	//-1   4+r    -1
	//0    -1    0
	int gray = 0;
	int i=0, j=0, srcIdx=0, dstIdx=0;
	RECT Roi={0,0,0,0};	
	Roi.right = ImageW;
	Roi.bottom = ImageH;
	for ( i=Roi.top+1; i<Roi.bottom-1; i++ )
	{
		srcIdx = (i*ImageStep)+Roi.left+1;
		dstIdx = (i-Roi.top)*ImageStep+1;
		for ( j=Roi.left+1; j<Roi.right-1; j++ )
		{
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 4;				
				gray -= pImage[srcIdx-ImageStep];				
				gray -= pImage[srcIdx-1];
				gray -= pImage[srcIdx+1];				
				gray -= pImage[srcIdx+ImageStep];				
				if ( abs(gray) >= ThL )
				{
					gray = (gray*Amount/100) + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx];	}
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);

			srcIdx ++;
			dstIdx ++;
		}
	}	
	return true;
}
