bool CImageAPI::Sharpness8GrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int ThL, int Amount, unsigned char *pDst)//灰階影像銳利化-8鄰近
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }	

	//-1    -1    -1
	//-1   8+r    -1
	//-1    -1    -1
	int gray = 0;
	int i=0, j=0, srcIdx=0, dstIdx=0;
	RECT Roi={0,0,0,0};	
	Roi.right = ImageW;
	Roi.bottom = ImageH;
	for ( i=Roi.top+1; i<Roi.bottom-1; i++ )
	{
		srcIdx = (i*ImageStep)+Roi.left+1;
		dstIdx = (i-Roi.top)*ImageStep+1;
		for ( j=Roi.left+1; j<Roi.right-1; j++ )
		{
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 8;
				gray -= pImage[srcIdx-ImageStep-1];
				gray -= pImage[srcIdx-ImageStep];
				gray -= pImage[srcIdx-ImageStep+1];
				gray -= pImage[srcIdx-1];
				gray -= pImage[srcIdx+1];
				gray -= pImage[srcIdx+ImageStep-1];
				gray -= pImage[srcIdx+ImageStep];
				gray -= pImage[srcIdx+ImageStep+1];

				if ( abs(gray) >= ThL )
				{
					gray = (gray*Amount/100) + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx];	}
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);

			srcIdx ++;
			dstIdx ++;
		}
	}	
	return true;
}
