//-------------------------------------------------------------------------------------//
bool CImageAPI::SharpnessLapsGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int ThL, int Amount, unsigned char *pDst)//灰階影像銳利化-拉普拉斯
{
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }

	//Raw + (Raw-Blur(LAPS))
	// -1, -4, -7, -4, -1,   
    // -4, -16, -26, -16, -4,   
    // -7, -26, 232+r, -26, -7,  
    // -4, -16, -26, -16, -4,   
    //  -1, -4, -7, -4, -1 }; 
	int gray = 0;
	const int PixelPitch = 1;
	const int PixelPitch2 = PixelPitch*2;
	const int PixelOffset = 2;	
	const int RowPitch = ImageStep;
	const int RowPitch2 = RowPitch*2;
	int i=0, j=0, srcIdx=0, dstIdx=0;
	RECT Roi={0,0,0,0};	
	Roi.right = ImageW;
	Roi.bottom = ImageH;
	for ( i=Roi.top+PixelOffset; i<Roi.bottom-PixelOffset; i++ )
	{
		srcIdx = (i*ImageStep)+(Roi.left+PixelOffset)*PixelPitch;
		dstIdx = (i-Roi.top)*ImageStep+(PixelOffset*PixelPitch);
		for ( j=Roi.left+PixelOffset; j<Roi.right-PixelOffset; j++ )
		{
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 232;
				gray -=   pImage[srcIdx-RowPitch2-PixelPitch2];
				gray -= 4*pImage[srcIdx-RowPitch2-PixelPitch];
				gray -= 7*pImage[srcIdx-RowPitch2];
				gray -= 4*pImage[srcIdx-RowPitch2+PixelPitch];
				gray -=   pImage[srcIdx-RowPitch2+PixelPitch2];

				gray -=  4*pImage[srcIdx-RowPitch-PixelPitch2];
				gray -= 16*pImage[srcIdx-RowPitch-PixelPitch];
				gray -= 26*pImage[srcIdx-RowPitch];
				gray -= 16*pImage[srcIdx-RowPitch+PixelPitch];
				gray -=  4*pImage[srcIdx-RowPitch+PixelPitch2];

				gray -=  7*pImage[srcIdx-PixelPitch2];
				gray -= 26*pImage[srcIdx-PixelPitch];				
				gray -= 26*pImage[srcIdx+PixelPitch];
				gray -=  7*pImage[srcIdx+PixelPitch2];

				gray -=  4*pImage[srcIdx+RowPitch-PixelPitch2];
				gray -= 16*pImage[srcIdx+RowPitch-PixelPitch];
				gray -= 26*pImage[srcIdx+RowPitch];
				gray -= 16*pImage[srcIdx+RowPitch+PixelPitch];
				gray -=  4*pImage[srcIdx+RowPitch+PixelPitch2];
				
				gray -=   pImage[srcIdx+RowPitch2-PixelPitch2];
				gray -= 4*pImage[srcIdx+RowPitch2-PixelPitch];
				gray -= 7*pImage[srcIdx+RowPitch2];
				gray -= 4*pImage[srcIdx+RowPitch2+PixelPitch];
				gray -=   pImage[srcIdx+RowPitch2+PixelPitch2];

				gray = (gray/273);
				if ( abs(gray) >= ThL )
				{	
					gray = (gray*Amount/100);					
					gray = gray + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx]; }
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);

			srcIdx ++;
			dstIdx ++;
		}
	}	
	return true;
}
