//-------------------------------------------------------------------------------------//
bool CImageAPI::Sharpness4ColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, int ThL, int Amount, unsigned char *pDst)//灰階影像銳利化-4鄰近
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }	

	//0    -1    0
	//-1   4+r    -1
	//0    -1    0
	int gray = 0;
	const int PixelPitch = 3;
	int i=0, j=0, srcIdx=0, dstIdx=0;
	RECT Roi={0,0,0,0};	
	Roi.right = ImageW;
	Roi.bottom = ImageH;
	for ( i=Roi.top+1; i<Roi.bottom-1; i++ )
	{
		srcIdx = (i*ImageStep)+(Roi.left+1)*PixelPitch;
		dstIdx = (i-Roi.top)*ImageStep+PixelPitch;
		for ( j=Roi.left+1; j<Roi.right-1; j++ )
		{
			//Blue
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 4;				
				gray -= pImage[srcIdx-ImageStep];				
				gray -= pImage[srcIdx-PixelPitch];
				gray -= pImage[srcIdx+PixelPitch];				
				gray -= pImage[srcIdx+ImageStep];		
				if ( abs(gray) >= ThL )
				{
					gray = (gray*Amount/100) + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx];	}
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);
			srcIdx ++;
			dstIdx ++;

			//Green
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 4;				
				gray -= pImage[srcIdx-ImageStep];				
				gray -= pImage[srcIdx-PixelPitch];
				gray -= pImage[srcIdx+PixelPitch];				
				gray -= pImage[srcIdx+ImageStep];		
				if ( abs(gray) >= ThL )
				{
					gray = (gray*Amount/100) + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx];	}
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);
			srcIdx ++;
			dstIdx ++;

			//Red
			gray  = pImage[srcIdx];
			//if ( gray >= ThL )
			{
				gray *= 4;				
				gray -= pImage[srcIdx-ImageStep];				
				gray -= pImage[srcIdx-PixelPitch];
				gray -= pImage[srcIdx+PixelPitch];				
				gray -= pImage[srcIdx+ImageStep];						
				if ( abs(gray) >= ThL )
				{
					gray = (gray*Amount/100) + pImage[srcIdx];
					if ( gray < 0 ) { gray = 0; }
					else if ( gray > 255 ) { gray = 255; }
				}
				else
				{	gray = pImage[srcIdx];	}
			}
			pDst[dstIdx] = static_cast<unsigned char>(gray);
			srcIdx ++;
			dstIdx ++;
		}
	}	
	return true;
}
