bool CImageAPI::CalcPhaseImageOTSUThreshold(IMAGE_SIZE PhaseW, IMAGE_SIZE PhaseH, IMAGE_SIZE PhaseStep, const PHASE_PTR PhasePtr, const MASK_PTR MaskPtr, const RECT &Roi, int &Threshold)//計算灰階的OTSU閥值
{
	if ( this->CheckGrayImage2(PhaseW, PhaseH, PhaseStep, PhasePtr, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(PhaseW, PhaseH, Roi) == false )
	{	return false; }

	int i=0, j=0, idx=0;
	int value = 0;
	double  sum = 0;
	const size_t TableSize = PHASE_PERIOD+1;
	int   Table[TableSize] = {0};
	const size_t BufferSize = CalcBufferSize(PhaseStep, PhaseH);
	size_t Total = (Roi.bottom-Roi.top)*(Roi.right-Roi.left);	

	//build historgram
	sum = 0;
	Total = 0;
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*PhaseStep);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }
			value = PhasePtr[idx+j];
			//if ( value < 0 )
			//{	continue; }
			sum += value;
			Total ++;
			Table[value] ++;			
		}	
	}

	int    threashold1 = 0;
	int    threashold2 = 0;	
	double max=0;
	double between = 0;
	double wB=0, wF=0;
	double mB=0, mF=0;
	double sumB=0, sumF=0;
	
	for ( i=0; i<TableSize; i++ )
	{
		wB += Table[i];
		if ( 0 == wB ) 
		{	continue; }
		wF = Total-wB;
		if ( 0 == wF ) 
		{	continue; }

		sumB += i*Table[i];
		sumF  = sum-sumB;
		mB = sumB/wB;
		mF = sumF/wF;

		between = wB*wF*(mB-mF)*(mB-mF);
		if ( between >= max )
		{
			threashold1 = i;
			if ( between > max )
			{
				threashold2 = i;	
			}
			max = between;
		}
	}
	Threshold = (int)(((threashold1+threashold2)/2)+0.5);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceImageOTSUThreshold(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const RECT &Roi, SPACE_DATA &Threshold)//計算灰階的OTSU閥值
{
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(SpaceW, SpaceH, Roi) == false )
	{	return false; }


	//CalcSpaceImageOTSUThreshold
	int    nCount = 0;
	int    nValue = 0;
	double dValue = 0;	
	int i=0, j=0, idx=0;
	double sum = 0;
	SPACE_DATA value=0;
	size_t TableSize2 = PHASE_PERIOD+1;
	const size_t TableSize = PHASE_PERIOD+1;
	int   Table[TableSize] = {0};
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	const size_t Total = (Roi.bottom-Roi.top)*(Roi.right-Roi.left);	
	SPACE_DATA SpaceMax=0;
	SPACE_DATA SpaceMin=0;
#if SPACE_TYPE == DATA_FLOAT
	SpaceMax = -FLT_MAX;
	SpaceMin =  FLT_MAX;
#else
	SpaceMax = -INT_MAX;
	SpaceMin =  INT_MAX;
#endif//SPACE_TYPE

	//calc Scale
	nCount = 0;
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*SpaceStep);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }			
			nCount ++;
			value = SpacePtr[idx+j];
			if ( SpaceMax < value ) { SpaceMax = value; }
			if ( SpaceMin > value ) { SpaceMin = value; }			
		}	
	}
	if ( 0 == nCount )
	{
		Threshold = 0;
		return true;
	}
	const SPACE_DATA SpaceRange = SpaceMax-SpaceMin;
	const int nSpaceRange = (int)(SpaceRange);
	if ( nSpaceRange == 0 ) 
	{
		Threshold = SpaceMin;
		return true;
	}
	double SpaceScale = 1.0;
	if ( SpaceRange > (TableSize-1) )
	{
		SpaceScale = (TableSize-1)/SpaceRange;
		TableSize2 = TableSize;
	}
	else
	{
		SpaceScale = 1.0;
		TableSize2 = (size_t)(SpaceRange);
	}

	//build historgram
	sum = 0;
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*SpaceStep);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }

			value = SpacePtr[idx+j];
			value -= SpaceMin;
			nValue = (int)(SpaceScale*value);
			if ( nValue >= TableSize )
			{
				nValue = nValue;
				continue;
			}
			//if ( value < 0 )
			//{	continue; }
			sum += nValue;
			Table[nValue] ++;			
		}	
	}

	int    threashold1 = 0;
	int    threashold2 = 0;	
	double max=0;
	double between = 0;
	double wB=0, wF=0;
	double mB=0, mF=0;
	double sumB=0, sumF=0;
	
	for ( i=0; i<TableSize2; i++ )
	{
		wB += Table[i];
		if ( 0 == wB ) 
		{	continue; }
		wF = Total-wB;
		if ( 0 == wF ) 
		{	continue; }

		sumB += i*Table[i];
		sumF  = sum-sumB;
		mB = sumB/wB;
		mF = sumF/wF;

		between = wB*wF*(mB-mF)*(mB-mF);
		if ( between >= max )
		{
			threashold1 = i;
			if ( between > max )
			{
				threashold2 = i;	
			}
			max = between;
		}
	}
	dValue = (threashold1+threashold2)*0.5;
	dValue = dValue/SpaceScale+SpaceMin;
	Threshold = (SPACE_DATA)(dValue);
	//Threshold = (threashold1+threashold2)/2;	 
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageIsoDataThreshold(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int &Threshold)//計算灰階的IsoData閥值
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )
	{	return false; }

	int i=0, j=0, idx=0;
	unsigned int value=0;
	double sum = 0;
	double max=0;
	double between = 0;
	double wB=0, wF=0;
	double mB=0, mF=0;
	double sumB=0, sumF=0;	
	const size_t TableSize = 256;
	int   Table[TableSize] = {0};
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	const int    Total = (Roi.bottom-Roi.top)*(Roi.right-Roi.left);	

	//build historgram
	sum = 0;
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*ImageStep)+Roi.left;
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			value = pImage[idx];
			sum += value;
			Table[value] ++;
			idx ++;			
		}	
	}	
	Threshold = 0;
	for ( i=0; i<TableSize; i++ )
	{
		if ( 254 == i )
		{
			i = i;
		}
		wB += Table[i];
		if ( 0 == wB ) 
		{	continue; }
		wF = Total-wB;
		if ( 0 == wF ) 
		{	continue; }

		sumB += i*Table[i];
		sumF  = sum-sumB;
		mB = sumB/wB;
		mF = sumF/wF;

		between = (mB+mF)/2;
		if ( i == between )
		{				
			Threshold = i;
			break;
		}
	}	
	return true;
}
