bool CImageAPI::CalcSpaceImageIsoDataThreshold(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const RECT &Roi, SPACE_DATA &Threshold)//計算灰階的IsoData閥值	
{
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(SpaceW, SpaceH, Roi) == false )
	{	return false; }

	int    nValue = 0;
	double dValue = 0;	
	int i=0, j=0, idx=0;
	double  sum = 0;
	SPACE_DATA value=0;		
	double    max=0;
	double    between = 0;
	double    wB=0, wF=0;
	double    mB=0, mF=0;
	double    sumB=0, sumF=0;	
	int    nThreshold = 0;
	size_t TableSize2 = PHASE_PERIOD+1;
	const size_t TableSize = PHASE_PERIOD+1;
	int   Table[TableSize] = {0};
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	int   Total = (Roi.bottom-Roi.top)*(Roi.right-Roi.left);	
	SPACE_DATA SpaceMax=0;
	SPACE_DATA SpaceMin=0;
#if SPACE_TYPE == DATA_FLOAT
	SpaceMax = -FLT_MAX;
	SpaceMin =  FLT_MAX;
#else
	SpaceMax = -INT_MAX;
	SpaceMin =  INT_MAX;
#endif//SPACE_TYPE

	//calc Scale
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*SpaceStep);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }			
			value = SpacePtr[idx+j];
			if ( SpaceMax < value ) { SpaceMax = value; }
			if ( SpaceMin > value ) { SpaceMin = value; }			
		}	
	}
	const SPACE_DATA SpaceRange = SpaceMax-SpaceMin;
	const int nSpaceRange = (int)(SpaceRange);
	if ( nSpaceRange == 0 ) 
	{
		Threshold = SpaceMin;
		return true;
	}
	double SpaceScale = 1.0;
	if ( SpaceRange > (TableSize-1) )
	{
		SpaceScale = (TableSize-1)/SpaceRange;
		TableSize2 = TableSize;
	}
	else
	{
		SpaceScale = 1.0;
		TableSize2 = (size_t)(SpaceRange);
	}

	//build historgram
	sum = 0;
	Total = 0;	
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idx = (i*SpaceStep);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }
			
			value = SpacePtr[idx+j];
			value -= SpaceMin;
			nValue = (int)(SpaceScale*value);
			if ( nValue >=  TableSize )
			{
				nValue = nValue;
				continue;
			}
			//value -= PHASE_MIN;
			//if ( value < 0 ) 
			//{	continue; }
			Total ++;
			sum += nValue;
			Table[nValue] ++;
		}	
	}	
	nThreshold = 0;
	for ( i=0; i<TableSize2; i++ )
	//for ( i=TableSize-1; i!=-1; i-- )
	{
		wB += Table[i];
		if ( 0 == wB ) 
		{	continue; }
		wF = Total-wB;
		if ( 0 == wF ) 
		{	continue; }

		sumB += i*Table[i];
		sumF  = sum-sumB;
		mB = sumB/wB;
		mF = sumF/wF;

		between = (mB+mF)/2;
		if ( i == between )
		{				
			nThreshold = i;
			//Threshold += PHASE_MIN;
			break;
		}
	}	

	dValue = nThreshold;
	dValue /= SpaceScale;
	dValue += SpaceMin;
	Threshold = (SPACE_DATA)(dValue);
	return true;
}
