//-------------------------------------------------------------------------------------//
bool CImageAPI::RangeGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, IMAGE_SIZE StepMask, unsigned char *&pMask, int ThL, int ThH)//灰階影像範圍化
{
	const char fnName[] = ("CImageAPI::RangeGrayImage");
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGraySize(ImageW, ImageH, StepMask) == false )
	{	return false; }

	JetMemory.free_func(pMask);
	const size_t BufferSize = CalcBufferSize(StepMask, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pMask, fnName, "pMask") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( RangeGrayImage3(ImageW, ImageH, ImageStep, pImage, Roi, StepMask, pMask, ThL, ThH) == false )
	{
		JetMemory.free_func(pMask);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RangeGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, IMAGE_SIZE StepMask, unsigned char *pMask, int ThL, int ThH)//灰階影像範圍化
{
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( CImageAPI::CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGrayImage(ImageW, ImageH, StepMask, pMask) == false )
	{	return false; }

	size_t i=0, j=0;
	size_t srcIdx=0;
	size_t destIdx=0;

	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		srcIdx = (i*ImageStep);
		destIdx = (i*StepMask);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( pImage[srcIdx+j] < ThL )
			{	pMask[destIdx+j] = ThL;	}
			else if ( pImage[srcIdx+j] > ThH )
			{	pMask[destIdx+j] = ThH;	}
			else
			{	pMask[destIdx+j] = pImage[srcIdx+j];	}
		}
	}
	return true;
}
