//-------------------------------------------------------------------------------------//
bool CImageAPI::BinaryGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int StepMask, unsigned char *pMask, int ThL, int ThH)//灰階影像2值化
{
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( CImageAPI::CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGrayImage(ImageW, ImageH, StepMask, pMask) == false )
	{	return false; }

	int i=0, j=0;
	int srcIdx=0;
	int destIdx=0;

	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		srcIdx = (i*ImageStep);
		destIdx = (i*StepMask);
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			if ( pImage[srcIdx+j]<ThL || pImage[srcIdx+j]>ThH )
			{
				pMask[destIdx+j] = 0;
				continue;
			}
			pMask[destIdx+j] = 255;
		}
	}
	return true;
}
