//-------------------------------------------------------------------------------------//
bool CImageAPI::AdaptiveBinarySpaceImage3_Integral(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *pSpace, const RECT &Roi, int StepMask, unsigned char *pMask, int CalcSize, int Gap)//高度影像適應性2值化
{
	const char fnName[] = "CImageAPI::AdaptiveBinarySpaceImage3_Integral";
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pSpace) == false )
	{	return false; }

	if ( CImageAPI::CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGrayImage(ImageW, ImageH, StepMask, pMask) == false )
	{	return false; }

	int i=0, j=0;
	int u=0, v=0;
	int Count=0;
	int index=0;
	int srcIdx=0;
	int destIdx=0;
	int  idx1=0, idx2=0, idx3=0, idx4=0;

	double Th=0.0;
	double Height=0;
	double Sum=0.0, Ave=0.0;	
	float  Sum1=0, Sum2=0, Sum3=0, Sum4=0;	
	const int KerSize2 = CalcSize/2;
	const int KerSizeFull = KerSize2*2+1;
	const int TotalSize= KerSizeFull*KerSizeFull;

	float *IntegralPtr = NULL;//積分圖//上限3.4x10^38
	const size_t RoiW=Roi.right-Roi.left;
	const size_t RoiH=Roi.bottom-Roi.top;
	const size_t RoiStep = JetAPI::GetBMPImagePixelsPerLine(RoiW, 8, 4);
	const size_t RoiSize = CalcBufferSize(RoiStep, RoiH);
	//if ( RoiW<KerSizeFull || RoiH<KerSizeFull )
	//{	return true; }
	if ( JetMemory.alloc_func(RoiSize, IntegralPtr, fnName, "IntegralPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}		
	if ( BuildIntegralGrayImage3(ImageW, ImageH, ImageStep, pSpace, Roi, RoiStep, IntegralPtr) == false )
	{
		JetMemory.free_func(IntegralPtr);
		return false;
	}	
	int   MaskRoiW=0;
	int   MaskRoiH=0;
	int   TmpY1=0, TmpY2=0;
	int   TmpX1=0, TmpX2=0;
	int   MaskRoiIdxY1=0, MaskRoiIdxY2=0;
	int   MaskRoiIdxX1=0, MaskRoiIdxX2=0;
	const int MaskRoiT=Roi.top+KerSize2;
	const int MaskRoiB=Roi.bottom-KerSize2;
	const int MaskRoiL=Roi.left+KerSize2;
	const int MaskRoiR=Roi.right-KerSize2;
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{	
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			MaskRoiIdxY1 = i-KerSize2;
			MaskRoiIdxY2 = i+KerSize2;
			MaskRoiIdxX1 = j-KerSize2;
			MaskRoiIdxX2 = j+KerSize2;
			if ( MaskRoiIdxY1 < Roi.top ) 
			{	MaskRoiIdxY1 = Roi.top; }
			if ( MaskRoiIdxY2 >= Roi.bottom 	) 
			{	MaskRoiIdxY2 = Roi.bottom-1; }			

			if ( MaskRoiIdxX1 < Roi.left ) 
			{	MaskRoiIdxX1 = Roi.left; }
			if ( MaskRoiIdxX2 >= Roi.right 	) 
			{	MaskRoiIdxX2 = Roi.right-1; }			
			MaskRoiH = MaskRoiIdxY2-MaskRoiIdxY1+1;
			MaskRoiW = MaskRoiIdxX2-MaskRoiIdxX1+1;

			TmpY1 = (MaskRoiIdxY1-Roi.top-1)*RoiStep;
			TmpY2 = (MaskRoiIdxY2-Roi.top)*RoiStep;
			TmpX1 = (MaskRoiIdxX1-Roi.left-1);
			TmpX2 = (MaskRoiIdxX2-Roi.left);
			idx1 = TmpY1+TmpX1;
			idx2 = TmpY1+TmpX2;
			idx3 = TmpY2+TmpX1;
			idx4 = TmpY2+TmpX2;
			if ( (MaskRoiIdxY1-1) < Roi.top )
			{
				idx1 = RoiSize;
				idx2 = RoiSize;
			}
			if ( (MaskRoiIdxX1-1) < Roi.left )
			{	
				idx1 = RoiSize;	
				idx3 = RoiSize;	
			}

			if ( idx1<0 || idx1>=RoiSize )
			{	Sum1 = 0;	}
			else
			{	Sum1 = IntegralPtr[idx1]; }

			if ( idx2<0 || idx2>=RoiSize )
			{	Sum2 = 0;	}
			else
			{	Sum2 = IntegralPtr[idx2]; }

			if ( idx3<0 || idx3>=RoiSize )
			{	Sum3 = 0;	}
			else
			{	Sum3 = IntegralPtr[idx3]; }
			
			if ( idx4<0 || idx4>=RoiSize )
			{	Sum4 = 0;	}
			else
			{	Sum4 = IntegralPtr[idx4]; }

			//Count = TotalSize;
			Count = MaskRoiW*MaskRoiH;
			Sum = Sum4+Sum1-Sum2-Sum3;
			Ave = Sum/Count;
			
			srcIdx = (i*ImageStep);
			destIdx = (i*StepMask);
			Height = pSpace[srcIdx+j];
			Th = Ave+Gap;
			if ( Height > Th )
			{
				pMask[destIdx+j] = 255;
				continue;
			}
			pMask[destIdx+j] = 0;
		}
	}		
	JetMemory.free_func(IntegralPtr);
	return true;
}
