bool CImageAPI::BuildIntegralGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, float *&IntegralPtr)//建立灰階的積分圖
{
	RECT Roi={0, 0, 0, 0};
	Roi.right = (int)(ImageW);
	Roi.bottom= (int)(ImageH);
	return BuildIntegralGrayImage(ImageW, ImageH, ImageStep, pImage, Roi, ImageStep, IntegralPtr);	
}
