{
	RECT Roi={0, 0, 0, 0};
	Roi.right = (int)(ImageW);
	Roi.bottom= (int)(ImageH);
	return BuildIntegralGrayImage3(ImageW, ImageH, ImageStep, pImage, Roi, ImageStep, IntegralPtr);	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildIntegralGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int RoiStep, float *&IntegralPtr)//建立灰階的積分圖
{
	const char fnName[] = ("CImageAPI::BuildIntegralGrayImage-UCHAR");
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	JetMemory.free_func(IntegralPtr);
	const size_t RoiH = Roi.bottom-Roi.top;
	const size_t BufferSize = CalcBufferSize(RoiStep, RoiH);
	if ( JetMemory.alloc_func(BufferSize, IntegralPtr, fnName, "IntegralPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( CImageAPI::BuildIntegralGrayImage3(ImageW, ImageH, ImageStep, pImage, Roi, RoiStep, IntegralPtr) == false )
	{
		JetMemory.free_func(IntegralPtr);
		return false;
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildIntegralGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int RoiStep, float *IntegralPtr)//建立灰階的積分圖
{
	if ( CImageAPI::CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, IntegralPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	int       i=0, j=0;
	float     Sum=0.0f;
	size_t    srcIdx=0;
	size_t    dstIdx=0;
	size_t    lstIdx=0;	
	const int RoiW=Roi.right-Roi.left;
	const int RoiH=Roi.bottom-Roi.top;	
	for ( i=0; i<RoiH; i++ )	
	{
		Sum=0.0f;
		dstIdx = (i*RoiStep);
		lstIdx = dstIdx-RoiStep;
		srcIdx = ((i+Roi.top)*ImageStep)+Roi.left;				
		for ( j=0; j<RoiW; j++ )
		{
			Sum += pImage[srcIdx++];
			if ( 0 == i ) 
			{	IntegralPtr[dstIdx++] = Sum;	}
			else
			{	IntegralPtr[dstIdx++] = IntegralPtr[lstIdx++]+Sum;	}
		}
	}
	return true;
}
