//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildIntegralColorImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int RoiStep, float *IntegralPtr)//建立彩色的積分圖
{
	if ( CImageAPI::CheckColorImage2(ImageW, ImageH, ImageStep, pImage, IntegralPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	int       i=0, j=0;
	float     SumR=0.0f;
	float     SumG=0.0f;
	float     SumB=0.0f;
	size_t    srcIdx = 0;
	size_t    dstIdx = 0;
	size_t    lstIdx = 0;	
	const int RoiW=Roi.right-Roi.left;
	const int RoiH=Roi.bottom-Roi.top;	
	for ( i=0; i<RoiH; i++ )	
	{
		dstIdx = (i*RoiStep);
		lstIdx = (dstIdx-RoiStep);
		srcIdx = ((i+Roi.top)*ImageStep)+(Roi.left)*3;			
		SumR=SumG=SumB=0.0f;
		for ( j=0; j<RoiW; j++ )
		{	
			SumB += pImage[srcIdx++];
			SumG += pImage[srcIdx++];
			SumR += pImage[srcIdx++];
			if ( 0 == i ) 
			{	
				IntegralPtr[dstIdx++] = SumB;
				IntegralPtr[dstIdx++] = SumG;
				IntegralPtr[dstIdx++] = SumR;
			}
			else
			{	
				IntegralPtr[dstIdx++] = IntegralPtr[lstIdx++]+SumB;
				IntegralPtr[dstIdx++] = IntegralPtr[lstIdx++]+SumG;
				IntegralPtr[dstIdx++] = IntegralPtr[lstIdx++]+SumR;
			}
		}
	}
	return true;
}
