{
	RECT Roi={0, 0, 0, 0};
	Roi.right = (int)(ImageW);
	Roi.bottom= (int)(ImageH);
	return BuildIntegralGrayImage(ImageW, ImageH, ImageStep, pImage, Roi, ImageStep, IntegralPtr);	
}
