bool CImageAPI::Intersection2MaskImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *SrcMaskPtr1, const unsigned char *SrcMaskPtr2, const RECT &RoiRect, IMAGE_SIZE RoiStep, unsigned char *DstMaskPtr, unsigned char High, unsigned char Low, bool FullSize)//合併兩個遮罩-交集
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, SrcMaskPtr1, SrcMaskPtr2, DstMaskPtr) == false )
	{	return false; }

	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )	
	{	return false;	}

	const IMAGE_SIZE RoiW = RoiRect.right-RoiRect.left;
	const IMAGE_SIZE RoiH = RoiRect.bottom-RoiRect.top;		
	if ( true == FullSize )
	{
		if ( this->CheckGraySize(ImageW, ImageH, RoiStep) == false )
		{	return false; }		
	}
	else
	{	
		if ( this->CheckGraySize(RoiW, RoiH, RoiStep) == false )
		{	return false; }		
	}

	size_t i=0, j=0;
	size_t srcIdx=0, dstIdx=0;
	size_t RoiL = RoiRect.left;
	size_t RoiT = RoiRect.top;
	size_t RoiR = RoiRect.right;
	size_t RoiB = RoiRect.bottom;

	for ( i=RoiT; i<RoiB; i++ )
	{
		srcIdx = i*ImageStep+RoiL;
		if ( true == FullSize )
		{	dstIdx = (i*RoiStep)+RoiL;	}
		else
		{	dstIdx = (i-RoiT)*RoiStep;	}
		for ( j=RoiL; j<RoiR; j++ )
		{
			if ( SrcMaskPtr1[srcIdx]<=Low || SrcMaskPtr2[srcIdx]<=Low )
			{	DstMaskPtr[dstIdx] = Low;	}
			else
			{	DstMaskPtr[dstIdx] = High;	}
			srcIdx ++;
			dstIdx ++;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcLineEquation2D(const std::vector<POINT> &List, TLineEquation2D &Line)//取得灰階影像的線段方程式ax+by+c=0
{	
	const int N = 2;
	size_t i=0, j=0, k=0, idx=0;
	const size_t PtCount=List.size();
	if ( PtCount < N ) 
	{	return false; }
	double MinX=0, MinY=0, MaxX=0, MaxY=0;
	for ( k=0; k<PtCount; k++ )
	{
		const POINT &rPt=List[k];
		if ( 0 == k )
		{
			MinX = MaxX = rPt.x;
			MinY = MaxY = rPt.y;
			continue;
		}
		if ( MinX > rPt.x ) { MinX = rPt.x; }
		else if ( MaxX < rPt.x ) { MaxX = rPt.x; }
		if ( MinY > rPt.y ) { MinY = rPt.y; }
		else if ( MaxY < rPt.y ) { MaxY = rPt.y; }
	}
	bool bVerLine=false;
	const double RangeX = MaxX - MinX;
	const double RangeY = MaxY - MinY;
	double RangeR = RangeX;
	if ( RangeY > 0.0001 ) { RangeR /= RangeY; }
	if ( RangeR < 0.3 )//Vertical Line
	{	bVerLine = true;	}
	else
	{	bVerLine = false;	}

	cv::Mat B=cv::Mat::zeros(N, 1, CV_64FC1);
	cv::Mat A=cv::Mat::zeros(N, N, CV_64FC1);
	for ( int row=0; row<A.rows; row ++ )
	{
		for ( int col=0; col<A.cols; col ++ )
		{
			if ( false == bVerLine )
			{
				for ( k=0; k<PtCount; k++ )
				{	A.at<double>(row, col) += pow(List[k].x, row+col);	}
			}
			else
			{
				for ( k=0; k<PtCount; k++ )
				{	A.at<double>(row, col) += pow(List[k].y, row+col);	}
			}
			
		}
	}
	for ( int row=0; row<B.rows; row ++ )
	{
		if ( false == bVerLine )
		{
			for ( k=0; k<PtCount; k++ )
			{	B.at<double>(row, 0) += pow(List[k].x, row)*List[k].y;	}
		}
		else
		{
			for ( k=0; k<PtCount; k++ )
			{	B.at<double>(row, 0) += pow(List[k].y, row)*List[k].x;	}
		}
	}

	//A*X=B, Solve X
	cv::Mat X;
	cv::solve(A, B, X, cv::DECOMP_NORMAL);//DECOMP_LU, DECOMP_NORMAL
	//double y=X.at<double>(0, 0)+X.at<double>(1,0)*x//y=mx+b
	const double rb=X.at<double>(0, 0);
	const double rm=X.at<double>(1, 0);
	if ( false == bVerLine )
	{
		Line.a = rm;
		Line.b = -1;
		Line.c = rb;
	}
	else
	{
		Line.a = -1;
		Line.b = rm;
		Line.c = rb;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
double CImageAPI::CalcLineIncludedAngle(const TLineEquation2D &L1, const TLineEquation2D &L2) const//計算2線段夾角
{		
	double val1 = fabs((L1.a*L2.a)+(L1.b*L2.b));
	double val2 = sqrt((L1.a*L1.a)+(L1.b*L1.b))*sqrt((L2.a*L2.a)+(L2.b*L2.b));	
	if ( fabs(val2) < 0.00001 )
	{	return 0.00; }
	double COS = val1/val2;
	return ::acos(COS)*180/PI_RAD;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageLineEquation2D(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *ImagePtr, const RECT &RoiRect, TLineEquation2D &Line)//取得灰階影像的線段方程式ax+by+c=0
{
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, ImagePtr) == false )
	{	return false; }
	if ( CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	POINT Pt;	
	size_t i=0, j=0, idx=0;
	IMAGE_DATA Threshold=51;
	std::vector<POINT> PtList;
	const int nImageH = (int)(ImageH);
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			idx = (i*ImageStep)+j;
			if ( ImagePtr[idx] < Threshold ) { continue; }
			Pt.x = (int)(j);
			Pt.y = (int)(i);
			//Pt.y = nImageH-(int)(i)-1;
			PtList.push_back(Pt);
		}
	}
	if ( CalcLineEquation2D(PtList, Line) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageLineEquation2D_v2(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char * ImagePtr, const RECT & RoiRect, TLineEquation2D & Line)
{
	if (CheckGrayImage(ImageW, ImageH, ImageStep, ImagePtr) == false)
	{
		return false;
	}
	if (CheckRoiRect(ImageW, ImageH, RoiRect) == false)
	{
		return false;
	}
	const IMAGE_SIZE RoiImageW = RoiRect.right - RoiRect.left;
	const IMAGE_SIZE RoiImageH = RoiRect.bottom - RoiRect.top;
	const IMAGE_SIZE BitCount = 8;
	const IMAGE_SIZE RoiImageStep = JetAPI::GetBMPImagePixelsPerLine(RoiImageW, BitCount, 4);
	IMAGE_PTR RoiImagePtr = NULL;
	if (ExtractRoiImage(ImageW, ImageH, ImageStep, BitCount, ImagePtr, RoiRect, RoiImageStep, RoiImagePtr, false) == false) {
		return false;
	}
#ifdef _DEBUG
#define DEBUG_SHOW_IMAGE(winName, img) \
	cv::imshow(winName, img);          \
	cv::waitKey(0);                    \
	cv::destroyAllWindows();
#else
#define DEBUG_SHOW_IMAGE(winName, img)
#endif
	//==============================================================
	// 0. 建立 ROI Mat
	//==============================================================
	cv::Mat src = CreateMat(RoiImageW, RoiImageH, RoiImageStep, 8, RoiImagePtr);
	if (src.empty()) { return false; }
	DEBUG_SHOW_IMAGE("src", src);
	//==============================================================
	// 1. 準備灰階影像
	//==============================================================
	cv::Mat gray;
	gray = src.clone();
	DEBUG_SHOW_IMAGE("gray", gray);
	//==============================================================
	// 2. 影像增強
	//
	// 目的：
	// 1. 增加暗部與邊界對比
	// 2. 強化高低差造成的 sharp edge
	// 3. 降低雜訊
	//==============================================================
	//------------------------------
	// 2-1. 輕微降噪
	//------------------------------
	cv::Mat denoise;
	cv::GaussianBlur(gray, denoise, cv::Size(3, 3), 0);
	DEBUG_SHOW_IMAGE("denoise", denoise);
	//------------------------------
	// 2-2. CLAHE 局部對比增強
	//------------------------------
	cv::Mat claheImg;
	cv::Ptr<cv::CLAHE> clahe = cv::createCLAHE(
		3.0,            // clipLimit，越大對比越強，但雜訊也越明顯
		cv::Size(8, 8)  // tileGridSize
	);
	clahe->apply(denoise, claheImg);
	DEBUG_SHOW_IMAGE("claheImg", claheImg);
	//------------------------------
	// 2-3. Unsharp Mask 銳化
	// enhanced = claheImg * 1.6 - blurForSharp * 0.6
	//------------------------------
	cv::Mat blurForSharp;
	cv::GaussianBlur(claheImg, blurForSharp, cv::Size(0, 0), 2.0);
	cv::Mat enhanced;
	cv::addWeighted(
		claheImg,
		1.6,
		blurForSharp,
		-0.6,
		0,
		enhanced
	);
	// 銳化後稍微平滑，避免雜訊太碎
	cv::GaussianBlur(enhanced, enhanced, cv::Size(3, 3), 0);
	DEBUG_SHOW_IMAGE("enhanced", enhanced);
	//==============================================================
	// 3. 計算 X / Y 方向 Sobel
	//
	// absSobelX 高：代表垂直邊可能性高
	// absSobelY 高：代表水平邊可能性高
	//==============================================================
	cv::Mat sobelX32;
	cv::Mat sobelY32;

	cv::Sobel(enhanced, sobelX32, CV_32F, 1, 0, 3);
	cv::Sobel(enhanced, sobelY32, CV_32F, 0, 1, 3);

	cv::Mat absSobelX;
	cv::Mat absSobelY;

	cv::convertScaleAbs(sobelX32, absSobelX);
	cv::convertScaleAbs(sobelY32, absSobelY);

	DEBUG_SHOW_IMAGE("absSobelX", absSobelX);
	DEBUG_SHOW_IMAGE("absSobelY", absSobelY);

	//==============================================================
	// 4. 建立方向性 Edge Score
	//
	// 不使用 Laplacian * Sobel，避免表面紋理被放大。
	// 改用方向優勢判斷：
	//
	// 水平邊：absSobelY > absSobelX * dominanceRatio
	// 垂直邊：absSobelX > absSobelY * dominanceRatio
	//==============================================================
	cv::Mat scoreHorizontal = cv::Mat::zeros(enhanced.size(), CV_8U);
	cv::Mat scoreVertical = cv::Mat::zeros(enhanced.size(), CV_8U);

	double dominanceRatio = 1.2;   // 越大越嚴格，建議 1.1 ~ 1.5

	for (int y = 0; y < enhanced.rows; ++y)
	{
		const uchar* pX = absSobelX.ptr<uchar>(y);
		const uchar* pY = absSobelY.ptr<uchar>(y);

		uchar* pH = scoreHorizontal.ptr<uchar>(y);
		uchar* pV = scoreVertical.ptr<uchar>(y);

		for (int x = 0; x < enhanced.cols; ++x)
		{
			// 水平邊：Y 方向變化比較強
			if (static_cast<double>(pY[x]) > static_cast<double>(pX[x]) * dominanceRatio)
			{
				pH[x] = pY[x];
			}

			// 垂直邊：X 方向變化比較強
			if (static_cast<double>(pX[x]) > static_cast<double>(pY[x]) * dominanceRatio)
			{
				pV[x] = pX[x];
			}
		}
	}

	DEBUG_SHOW_IMAGE("scoreHorizontal", scoreHorizontal);
	DEBUG_SHOW_IMAGE("scoreVertical", scoreVertical);

	//==============================================================
	// 5. 二值化
	//
	// 先用 Otsu 找自動門檻，再加上最低門檻保護。
	//==============================================================
	cv::Mat binHorizontal;
	cv::Mat binVertical;

	double otsuH = cv::threshold(
		scoreHorizontal,
		binHorizontal,
		0,
		255,
		cv::THRESH_BINARY | cv::THRESH_OTSU
	);

	double otsuV = cv::threshold(
		scoreVertical,
		binVertical,
		0,
		255,
		cv::THRESH_BINARY | cv::THRESH_OTSU
	);

	// 最低門檻保護，避免太弱紋理也進來
	double minEdgeThreshold = 25.0;

	double thH = std::max(otsuH, minEdgeThreshold);
	double thV = std::max(otsuV, minEdgeThreshold);

	cv::threshold(scoreHorizontal, binHorizontal, thH, 255, cv::THRESH_BINARY);
	cv::threshold(scoreVertical, binVertical, thV, 255, cv::THRESH_BINARY);

	binHorizontal.convertTo(binHorizontal, CV_8U);
	binVertical.convertTo(binVertical, CV_8U);

	DEBUG_SHOW_IMAGE("binHorizontal", binHorizontal);
	DEBUG_SHOW_IMAGE("binVertical", binVertical);


	//==============================================================
	// 6. 建立 Debug 顯示用 result
	//==============================================================
	cv::Mat result;

	if (src.channels() == 1) { cv::cvtColor(src, result, cv::COLOR_GRAY2BGR); }
	else { result = src.clone(); }

	//==============================================================
	// 7. 建立只保留最高分線段的灰階輸出圖
	//
	// bestLineImage：
	// 0   = 背景
	// 255 = 最高分線段
	//==============================================================
	cv::Mat bestLineImage = cv::Mat::zeros(enhanced.size(), CV_8U);

	double bestLineScore = 0.0;
	cv::Point bestPt1;
	cv::Point bestPt2;
	bool bHasBestLine = false;


	//==============================================================
	// 8. 水平線：Row Projection
	//
	// 將每一列的水平邊緣分數加總。
	// 有缺角也沒關係，只要同一個 y 上還有足夠邊緣，
	// 就會形成 projection peak。
	//==============================================================
	cv::Mat rowProjection;
	cv::reduce(scoreHorizontal, rowProjection, 1, cv::REDUCE_SUM, CV_32F);

	// 平滑 projection，避免雜訊造成太多峰值
	int smoothLenY = enhanced.rows / 30;
	if (smoothLenY < 5)	smoothLenY = 5;
	if (smoothLenY > 31)smoothLenY = 31;
	if ((smoothLenY % 2) == 0)	smoothLenY++;

	cv::GaussianBlur(rowProjection, rowProjection, cv::Size(1, smoothLenY), 0);
	// 計算 row projection 統計值
	cv::Scalar rowMean;
	cv::Scalar rowStd;
	cv::meanStdDev(rowProjection, rowMean, rowStd);

	// rowPeakThreshold 越高，候選線越少
	double rowPeakThreshold = rowMean[0] + rowStd[0] * 1.0;


	//==============================================================
	// 9. 找水平 projection peak
	//==============================================================
	struct Candidate1D
	{
		int pos;
		double score;
	};

	std::vector<Candidate1D> horizontalCandidates;

	int nmsDistanceY = enhanced.rows / 40;

	if (nmsDistanceY < 5)
		nmsDistanceY = 5;

	if (nmsDistanceY > 20)
		nmsDistanceY = 20;

	for (int y = 1; y < enhanced.rows - 1; ++y)
	{
		float prevScore = rowProjection.at<float>(y - 1, 0);
		float currScore = rowProjection.at<float>(y, 0);
		float nextScore = rowProjection.at<float>(y + 1, 0);

		if (currScore < rowPeakThreshold)
			continue;

		if (currScore >= prevScore && currScore >= nextScore)
		{
			Candidate1D c;
			c.pos = y;
			c.score = currScore;
			horizontalCandidates.push_back(c);
		}
	}

	// 分數由大到小排序
	std::sort(
		horizontalCandidates.begin(),
		horizontalCandidates.end(),
		[](const Candidate1D& a, const Candidate1D& b)
	{
		return a.score > b.score;
	}
	);

	// NMS：避免同一條線附近出現很多候選
	std::vector<Candidate1D> selectedHorizontal;

	int maxHorizontalLineCount = 10;

	for (size_t i = 0; i < horizontalCandidates.size(); ++i)
	{
		bool tooClose = false;

		for (size_t j = 0; j < selectedHorizontal.size(); ++j)
		{
			if (abs(horizontalCandidates[i].pos - selectedHorizontal[j].pos) < nmsDistanceY)
			{
				tooClose = true;
				break;
			}
		}

		if (tooClose)
			continue;

		selectedHorizontal.push_back(horizontalCandidates[i]);

		if (static_cast<int>(selectedHorizontal.size()) >= maxHorizontalLineCount)
			break;
	}


	//==============================================================
	// 10. 對每個水平候選 y，用附近的 edge points 做 fitLine
	//==============================================================
	int fitBandY = 4;  // 在候選 y 上下幾個 pixel 收集點
	double minHorizontalCoverageRatio = 0.15; // 至少覆蓋寬度的 15%

	for (size_t i = 0; i < selectedHorizontal.size(); ++i)
	{
		int centerY = selectedHorizontal[i].pos;

		std::vector<cv::Point2f> fitPts;

		int minX = INT_MAX;
		int maxX = INT_MIN;

		std::vector<int> usedX(enhanced.cols, 0);

		int yStart = centerY - fitBandY;
		int yEnd = centerY + fitBandY;

		if (yStart < 0)
			yStart = 0;

		if (yEnd >= enhanced.rows)
			yEnd = enhanced.rows - 1;

		for (int y = yStart; y <= yEnd; ++y)
		{
			const uchar* pBin = binHorizontal.ptr<uchar>(y);

			for (int x = 0; x < enhanced.cols; ++x)
			{
				if (pBin[x] == 0)
					continue;

				fitPts.push_back(cv::Point2f(static_cast<float>(x), static_cast<float>(y)));

				if (x < minX)
					minX = x;

				if (x > maxX)
					maxX = x;

				usedX[x] = 1;
			}
		}

		if (fitPts.size() < 10)
			continue;

		int coveredXCount = 0;

		for (int x = 0; x < enhanced.cols; ++x)
		{
			if (usedX[x] != 0)
				coveredXCount++;
		}

		double coverageRatio =
			static_cast<double>(coveredXCount) /
			static_cast<double>(enhanced.cols);

		// 覆蓋太少代表可能只是局部紋理，不是真正長邊
		if (coverageRatio < minHorizontalCoverageRatio)
			continue;

		cv::Vec4f fitLineParam;

		cv::fitLine(
			fitPts,
			fitLineParam,
			cv::DIST_L2,
			0,
			0.01,
			0.01
		);

		float vx = fitLineParam[0];
		float vy = fitLineParam[1];
		float x0 = fitLineParam[2];
		float y0 = fitLineParam[3];

		if (fabs(vx) < 1e-6f)
			continue;

		// 檢查角度是否接近水平
		double angle = atan2(static_cast<double>(vy), static_cast<double>(vx)) * 180.0 / CV_PI;
		double absAngle = fabs(angle);

		bool isHorizontal =
			absAngle <= 10.0 ||
			absAngle >= 170.0;

		if (!isHorizontal)
			continue;

		int drawX1 = minX;
		int drawX2 = maxX;

		int drawY1 = static_cast<int>(y0 + (drawX1 - x0) * vy / vx + 0.5f);
		int drawY2 = static_cast<int>(y0 + (drawX2 - x0) * vy / vx + 0.5f);

		if (drawY1 < -10 || drawY1 > result.rows + 10)
			continue;

		if (drawY2 < -10 || drawY2 > result.rows + 10)
			continue;

		//==========================================================
		// 計算水平線分數
		//
		// projection score 越高越好
		// coverageRatio 越高越好
		// lineLength 越長越好
		//==========================================================
		double lineLength = sqrt(
			static_cast<double>(
			(drawX2 - drawX1) * (drawX2 - drawX1) +
				(drawY2 - drawY1) * (drawY2 - drawY1)
				)
		);

		double lineScore =
			selectedHorizontal[i].score *
			coverageRatio *
			lineLength;

		if (lineScore > bestLineScore)
		{
			bestLineScore = lineScore;
			bestPt1 = cv::Point(drawX1, drawY1);
			bestPt2 = cv::Point(drawX2, drawY2);
			bHasBestLine = true;
		}

#ifdef _DEBUG
		// Debug：畫出所有水平候選線
		cv::line(
			result,
			cv::Point(drawX1, drawY1),
			cv::Point(drawX2, drawY2),
			cv::Scalar(0, 255, 255),
			2
		);

		CString strInfo;
		strInfo.Format(_T("H %.2f S %.0f"), coverageRatio, lineScore);

		CT2A strInfoA(strInfo);

		cv::putText(
			result,
			std::string(strInfoA),
			cv::Point(drawX1, drawY1 - 3),
			cv::FONT_HERSHEY_SIMPLEX,
			0.4,
			cv::Scalar(0, 255, 255),
			1
		);
#endif
	}


	//==============================================================
	// 11. 垂直線：Column Projection
	//==============================================================
	cv::Mat colProjection;
	cv::reduce(scoreVertical, colProjection, 0, cv::REDUCE_SUM, CV_32F);

	// colProjection 是 1 x cols，做水平方向平滑
	int smoothLenX = enhanced.cols / 30;

	if (smoothLenX < 5)
		smoothLenX = 5;

	if (smoothLenX > 31)
		smoothLenX = 31;

	if ((smoothLenX % 2) == 0)
		smoothLenX++;

	cv::GaussianBlur(colProjection, colProjection, cv::Size(smoothLenX, 1), 0);

	// 計算 column projection 統計值
	cv::Scalar colMean;
	cv::Scalar colStd;
	cv::meanStdDev(colProjection, colMean, colStd);

	double colPeakThreshold = colMean[0] + colStd[0] * 1.0;


	//==============================================================
	// 12. 找垂直 projection peak
	//==============================================================
	std::vector<Candidate1D> verticalCandidates;

	int nmsDistanceX = enhanced.cols / 40;

	if (nmsDistanceX < 5)
		nmsDistanceX = 5;

	if (nmsDistanceX > 20)
		nmsDistanceX = 20;

	for (int x = 1; x < enhanced.cols - 1; ++x)
	{
		float prevScore = colProjection.at<float>(0, x - 1);
		float currScore = colProjection.at<float>(0, x);
		float nextScore = colProjection.at<float>(0, x + 1);

		if (currScore < colPeakThreshold)
			continue;

		if (currScore >= prevScore && currScore >= nextScore)
		{
			Candidate1D c;
			c.pos = x;
			c.score = currScore;
			verticalCandidates.push_back(c);
		}
	}

	// 分數由大到小排序
	std::sort(
		verticalCandidates.begin(),
		verticalCandidates.end(),
		[](const Candidate1D& a, const Candidate1D& b)
	{
		return a.score > b.score;
	}
	);

	// NMS
	std::vector<Candidate1D> selectedVertical;

	int maxVerticalLineCount = 10;

	for (size_t i = 0; i < verticalCandidates.size(); ++i)
	{
		bool tooClose = false;

		for (size_t j = 0; j < selectedVertical.size(); ++j)
		{
			if (abs(verticalCandidates[i].pos - selectedVertical[j].pos) < nmsDistanceX)
			{
				tooClose = true;
				break;
			}
		}

		if (tooClose)
			continue;

		selectedVertical.push_back(verticalCandidates[i]);

		if (static_cast<int>(selectedVertical.size()) >= maxVerticalLineCount)
			break;
	}


	//==============================================================
	// 13. 對每個垂直候選 x，用附近的 edge points 做 fitLine
	//==============================================================
	int fitBandX = 4;
	double minVerticalCoverageRatio = 0.15;

	for (size_t i = 0; i < selectedVertical.size(); ++i)
	{
		int centerX = selectedVertical[i].pos;

		std::vector<cv::Point2f> fitPts;

		int minY = INT_MAX;
		int maxY = INT_MIN;

		std::vector<int> usedY(enhanced.rows, 0);

		int xStart = centerX - fitBandX;
		int xEnd = centerX + fitBandX;

		if (xStart < 0)
			xStart = 0;

		if (xEnd >= enhanced.cols)
			xEnd = enhanced.cols - 1;

		for (int y = 0; y < enhanced.rows; ++y)
		{
			const uchar* pBin = binVertical.ptr<uchar>(y);

			for (int x = xStart; x <= xEnd; ++x)
			{
				if (pBin[x] == 0)
					continue;

				fitPts.push_back(cv::Point2f(static_cast<float>(x), static_cast<float>(y)));

				if (y < minY)
					minY = y;

				if (y > maxY)
					maxY = y;

				usedY[y] = 1;
			}
		}

		if (fitPts.size() < 10)
			continue;

		int coveredYCount = 0;

		for (int y = 0; y < enhanced.rows; ++y)
		{
			if (usedY[y] != 0)
				coveredYCount++;
		}

		double coverageRatio =
			static_cast<double>(coveredYCount) /
			static_cast<double>(enhanced.rows);

		if (coverageRatio < minVerticalCoverageRatio)
			continue;

		cv::Vec4f fitLineParam;

		cv::fitLine(
			fitPts,
			fitLineParam,
			cv::DIST_L2,
			0,
			0.01,
			0.01
		);

		float vx = fitLineParam[0];
		float vy = fitLineParam[1];
		float x0 = fitLineParam[2];
		float y0 = fitLineParam[3];

		if (fabs(vy) < 1e-6f)
			continue;

		double angle = atan2(static_cast<double>(vy), static_cast<double>(vx)) * 180.0 / CV_PI;
		double absAngle = fabs(angle);

		bool isVertical = fabs(absAngle - 90.0) <= 10.0;

		if (!isVertical)
			continue;

		int drawY1 = minY;
		int drawY2 = maxY;

		int drawX1 = static_cast<int>(x0 + (drawY1 - y0) * vx / vy + 0.5f);
		int drawX2 = static_cast<int>(x0 + (drawY2 - y0) * vx / vy + 0.5f);

		if (drawX1 < -10 || drawX1 > result.cols + 10)
			continue;

		if (drawX2 < -10 || drawX2 > result.cols + 10)
			continue;

		//==========================================================
		// 計算垂直線分數
		//==========================================================
		double lineLength = sqrt(
			static_cast<double>(
			(drawX2 - drawX1) * (drawX2 - drawX1) +
				(drawY2 - drawY1) * (drawY2 - drawY1)
				)
		);

		double lineScore =
			selectedVertical[i].score *
			coverageRatio *
			lineLength;

		if (lineScore > bestLineScore)
		{
			bestLineScore = lineScore;
			bestPt1 = cv::Point(drawX1, drawY1);
			bestPt2 = cv::Point(drawX2, drawY2);
			bHasBestLine = true;
		}

#ifdef _DEBUG
		// Debug：畫出所有垂直候選線
		cv::line(
			result,
			cv::Point(drawX1, drawY1),
			cv::Point(drawX2, drawY2),
			cv::Scalar(255, 0, 255),
			2
		);

		CString strInfo;
		strInfo.Format(_T("V %.2f S %.0f"), coverageRatio, lineScore);

		CT2A strInfoA(strInfo);

		cv::putText(
			result,
			std::string(strInfoA),
			cv::Point(drawX1 + 3, drawY1),
			cv::FONT_HERSHEY_SIMPLEX,
			0.4,
			cv::Scalar(255, 0, 255),
			1
		);
#endif
	}


	//==============================================================
	// 14. 只把最高分線段畫到灰階圖 bestLineImage
	//==============================================================
	if (bHasBestLine)
	{
		int lineThickness = 2;

		cv::line(
			bestLineImage,
			bestPt1,
			bestPt2,
			cv::Scalar(255),
			lineThickness
		);
	}


	//==============================================================
	// 15. Debug 顯示結果
	//==============================================================
#ifdef _DEBUG
	std::cout << "Horizontal Candidate Count = " << selectedHorizontal.size() << std::endl;
	std::cout << "Vertical Candidate Count   = " << selectedVertical.size() << std::endl;
	std::cout << "Best Line Score            = " << bestLineScore << std::endl;

	if (bHasBestLine)
	{
		std::cout << "Best Line Pt1 = (" << bestPt1.x << ", " << bestPt1.y << ")" << std::endl;
		std::cout << "Best Line Pt2 = (" << bestPt2.x << ", " << bestPt2.y << ")" << std::endl;
	}
	else
	{
		std::cout << "No valid best line found." << std::endl;
	}

	DEBUG_SHOW_IMAGE("all_candidate_lines", result);
	DEBUG_SHOW_IMAGE("bestLineImage", bestLineImage);
#endif
	if (bHasBestLine) { bestLineImage.copyTo(src); }
	else {
		// 如果沒找到線，回填全黑圖
		bestLineImage.setTo(0);
		bestLineImage.copyTo(src);
	}
	IMAGE_PTR  LineImage = NULL;
	JetMemory.free_func(LineImage);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if (JetMemory.alloc_func(BufferSize, LineImage, "CalcGrayImageLineEquation2D_V2", " LineImage") == false)
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if (false == PasteRoiImage3(ImageW, ImageH, ImageStep, BitCount, LineImage, RoiRect, RoiImageStep, RoiImagePtr, false, false)) {
		JetMemory.free_func(RoiImagePtr);
		JetMemory.free_func(LineImage);
		return false;
	}
	if (false == CalcGrayImageLineEquation2D(ImageW, ImageH, ImageStep, LineImage, RoiRect, Line)) {
		JetMemory.free_func(RoiImagePtr);
		JetMemory.free_func(LineImage);
		return false;
	}
	JetMemory.free_func(RoiImagePtr);
	JetMemory.free_func(LineImage);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcImageProfile(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, const POINT &pt1, const POINT &pt2, std::vector<TPIXEL_GRY> &Profile)//取得影像的Profile
{
	if ( this->CheckBitCount(BitCount) == false ) { return false; }
	if ( 8 == BitCount )
	{	return CalcGrayImageProfile(ImageW, ImageH, ImageStep, pImage, pt1, pt2, Profile); }
	if ( 24 == BitCount )
	{	return CalcColorImageProfile(ImageW, ImageH, ImageStep, pImage, pt1, pt2, Profile); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageProfile(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const POINT &pt1, const POINT &pt2, std::vector<TPIXEL_GRY> &Profile)//取得灰階影像的Profile
{
	Profile.clear();
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckPoint2(ImageW, ImageH, pt1, pt2) == false )	
	{	return false;	}

	int i=0;	
	int idx=0;
	TPIXEL_GRY pt;
	double stepw=pt2.x-pt1.x;
	double steph=pt2.y-pt1.y;
	double stepl=::sqrt((stepw*stepw)+(steph*steph));
	double stepx=stepw/stepl, stepy=steph/stepl;
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);
	const int ProfileSize = this->Round(stepl);
	for ( i=0; i<ProfileSize; i++ )
	{
		pt.x = this->Round(i*stepx)+pt1.x;
		pt.y = this->Round(i*stepy)+pt1.y;

		if ( (pt.x>=nImageW) || (pt.y>=nImageH) )
		{	continue; }

		idx = (pt.y*ImageStep)+pt.x;
		pt.gray = pImage[idx];
		Profile.push_back(pt);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcColorImageProfile(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const POINT &pt1, const POINT &pt2, std::vector<TPIXEL_GRY> &Profile)//取得彩色影像的Profile
{
	Profile.clear();
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckPoint2(ImageW, ImageH, pt1, pt2) == false )	
	{	return false;	}

	int i=0;	
	int idx=0;
	TPIXEL_GRY pt;
	double stepw=pt2.x-pt1.x;
	double steph=pt2.y-pt1.y;
	double stepl=::sqrt((stepw*stepw)+(steph*steph));
	double stepx=stepw/stepl, stepy=steph/stepl;
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);
	const int ProfileSize = this->Round(stepl);
	for ( i=0; i<ProfileSize; i++ )
	{
		pt.x = this->Round(i*stepx)+pt1.x;
		pt.y = this->Round(i*stepy)+pt1.y;

		if ( (pt.x>=nImageW) || (pt.y>=nImageH) )
		{	continue; }

		idx = (pt.y*ImageStep)+(pt.x*3);
		pt.gray  = pImage[idx];
		pt.gray += pImage[idx+1];
		pt.gray += pImage[idx+2];
		pt.gray /= 3;
		Profile.push_back(pt);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcColorImageProfile(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const POINT &pt1, const POINT &pt2, std::vector<TPIXEL_RGB> &Profile)//取得彩色影像的Profile
{
	Profile.clear();
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	if ( this->CheckPoint2(ImageW, ImageH, pt1, pt2) == false )	
	{	return false;	}

	int i=0;	
	int idx=0;
	TPIXEL_RGB pt;
	double stepw=pt2.x-pt1.x;
	double steph=pt2.y-pt1.y;
	double stepl=::sqrt((stepw*stepw)+(steph*steph));
	double stepx=stepw/stepl, stepy=steph/stepl;
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);
	const int ProfileSize = this->Round(stepl);
	for ( i=0; i<ProfileSize; i++ )
	{
		pt.x = this->Round(i*stepx)+pt1.x;
		pt.y = this->Round(i*stepy)+pt1.y;

		if ( (pt.x>=nImageW) || (pt.y>=nImageH) )
		{	continue; }

		idx = (pt.y*ImageStep)+(pt.x*3);
		pt.b = pImage[idx];
		pt.g = pImage[idx+1];
		pt.r = pImage[idx+2];
		Profile.push_back(pt);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcRGBImageProfile(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, const POINT &pt1, const POINT &pt2, std::vector<TPIXEL_RGB> &Profile)//取得彩色影像的Profile
{	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	
	if ( this->CheckPoint2(ImageW, ImageH, pt1, pt2) == false )	
	{	return false;	}

	int i=0;	
	int idx=0;
	TPIXEL_RGB pt;
	double stepw=pt1.x-pt2.x;
	double steph=pt1.y-pt2.y;
	double stepl=::sqrt((stepw*stepw)+(steph*steph));
	double stepx=stepw/stepl, stepy=steph/stepl;

	const int ProfileSize = this->Round(stepl);
	for ( i=0; i<ProfileSize; i++ )
	{
		pt.x = this->Round(i*stepx);
		pt.y = this->Round(i*stepy);

		idx = (pt.y*ImageStep)+pt.x;

		pt.r = pR[idx];
		pt.g = pG[idx];
		pt.b = pB[idx];
		
		Profile.push_back(pt);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGammaBySineProfile(const std::vector<unsigned char> &Profile, float LowRatio, int PeriodGap, int &SineCount, double &Gamma)
{
	int   Gray=0;
	int   Count=0;	
	int   idx=0, idx2=0;
	int   i=0, j=0, k=0;	
	double Sum=0, Ave=0;
	double Max=0, Min=0;
	double Range=0;
	const size_t ProfileSize=Profile.size();
	const size_t ProfileSize2=ProfileSize/2;

#ifdef _DEBUG
	CString str;
	FILE *pfile=NULL;
	str.Format(_T("R:\\%s"), _T("MyProfile.TXT"));
	pfile = ::_tfopen(str, _T("w+"));
	if ( NULL != pfile )
	{
		for ( i=0; i<ProfileSize; i++ )
		{	::_ftprintf(pfile, _T("%d, %d\n"), i, Profile[i]);	}
		::fclose(pfile); pfile=NULL;
	}
#endif//_DEBUG

	//尋找黑點位置	
	for ( i=0; i<ProfileSize; i++ )
	{
		if ( 0==i ) 
		{
			Max = Min = Profile[i];
			continue;
		}
		if ( Min > Profile[i] ) { Min = Profile[i]; }
		if ( Max < Profile[i] ) { Max = Profile[i]; }
	}
	Range = Max-Min;
	std::vector<int> DarkList;
	const int ThreadLow = (int)(Min+(Range*LowRatio));
	for ( i=0; i<ProfileSize; i++ )
	{
		Gray = Profile[i];
		if ( Gray > ThreadLow ) { continue; }
		DarkList.push_back(i);
	}
	const size_t DarkCount=DarkList.size();	
	if ( 0 == DarkCount )
	{		
		Gamma = 1.0; 
		SineCount = 0;
		return true;
	}

	//尋找分割位置
	int First=0, EndPos=0;	
	const int IdxGap = PeriodGap;	
	std::vector<int> SegmentList;
	First = EndPos = -1;
	for ( i=0; i<DarkCount-1; i++ )
	{
		idx = DarkList[i];
		idx2 = DarkList[i+1];
		if ( -1 == First )
		{	
			First = EndPos = idx;	
			continue;
		}
		if ( (idx2-idx) < IdxGap ) { continue; }
		EndPos = idx;		
		SegmentList.push_back((First+EndPos)/2);
		First = idx2;
	}
	EndPos = idx2;
	SegmentList.push_back((First+EndPos)/2);
	const size_t SegmentCount=SegmentList.size();

	//計算Gamma	
	double A=0;//振幅
	double V=0;//中心位置
	double Step=0;	
	double Error=0.0;
	double Theata=0.0;
	double Theory=0.0;
	double GammaGray=0.0;
	double MinError=0.0;
	double SumError=0.0;
	double MinErrorGamma=0.0;	
	double MinGray=0, MaxGray=0;	
	const double fPI=3.14159;
	std::vector<double> GrayList;
	std::vector<double> GammaList;
	std::vector<double> SineCPList;
	std::vector<double> SinePtList;	
	SineCount=(int)(SegmentCount-1);
	for ( i=0; i<SineCount; i++ )
	{
		MinGray=-1;
		MaxGray=-1;
		First  = SegmentList[i];
		EndPos = SegmentList[i+1];
		Range = EndPos-First;
		Step = fPI*2/Range;
		for ( j=First; j<EndPos; j++ )
		{
			Gray = Profile[j];
			if ( -1 == MaxGray ) 
			{	
				MaxGray = MinGray = Gray; 
				continue;
			}
			if ( MinGray > Gray ) { MinGray = Gray; }
			if ( MaxGray < Gray ) { MaxGray = Gray; }			
		}		
		GrayList.clear();
		SinePtList.clear();
		A = (MaxGray-MinGray)/2;
		V = (MaxGray+MinGray)/2;		
		for ( j=First; j<EndPos; j++ )
		{			
			Gray = Profile[j];

			Theata = ((j-First)*Step)-(fPI*0.5);
			Theory = sin(Theata);
			Theory = Theory*A;
			Theory = Theory+V;
			Error = Gray-Theory;
			Error = Error;
			GrayList.push_back(Gray);
			SinePtList.push_back(Theory);
		}

		//計算Gamma
		MinError = -1;
		MinErrorGamma = 1.0;
		const size_t GrayCount=GrayList.size();
		for ( k=0; k<401; k++ )
		{
			SumError = 0.0;
			Gamma = 0.80+(k*0.001);
			for ( j=0; j<GrayCount; j++ )
			{
				Theory = SinePtList[j];
				GammaGray = GrayList[j];
				GammaGray = GammaGray/255.0;
				GammaGray = ::pow(GammaGray, Gamma);
				GammaGray = GammaGray*255.0;
				Error = GammaGray-Theory;
				if ( Error < 0 ) { Error = -Error; }
				//if ( SumError < Error ) { SumError = Error; }
				SumError += Error;
			}
			if ( -1==MinError || MinError>SumError ) 
			{	
				MinError = SumError; 
				MinErrorGamma = Gamma;
			}
		}		
		GammaList.push_back(MinErrorGamma);
		SineCPList.push_back((First+EndPos)*0.5);
	}
	
	Count = 0;
	Gamma = 0;
	const size_t GammaCount = GammaList.size();
	for ( i=0; i<GammaCount; i++ )
	{	Gamma += GammaList[i];	}
	if ( GammaCount > 0 ) 
	{	
		//找平均的
		Gamma = Gamma/GammaCount;  

		//找最接近FOV中間的
		MinError = -1;
		for ( i=0; i<GammaCount; i++ )
		{
			Error = abs(SineCPList[i]-ProfileSize2);
			if ( -1==MinError || MinError>Error )
			{	
				MinError = Error;
				Gamma = GammaList[i];
			}
		}
	}
	else
	{	Gamma = 1.0; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageGammaBySine(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, bool bVer, int nBand, float LowRatio, int PeriodGap, int &SineCount, double &Gamma)
{
	bool IsOK = true;
	if ( false == bVer )
	{	IsOK = CalcGrayImageGammaBySine_H(ImageW, ImageH, ImageStep, pImage, nBand, LowRatio, PeriodGap, SineCount, Gamma);	}
	else
	{	IsOK = CalcGrayImageGammaBySine_V(ImageW, ImageH, ImageStep, pImage, nBand, LowRatio, PeriodGap, SineCount, Gamma);	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageGammaBySine_H(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, int nBand, float LowRatio, int PeriodGap, int &SineCount, double &Gamma)
{
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);	
	if ( nBand > nImageW ) 
	{	return false; }
	
	RECT  Roi;
	int   idx=0;
	int   Gray=0;
	int   Count=0;		
	int   i=0, j=0;	
	double Sum=0, Ave=0;	
	const int ImageCpX = nImageW/2;
	const int ImageCpY = nImageH/2;
	std::vector<unsigned char> Profile;

	Roi.left   = ImageCpX-(nBand/2);
	Roi.right  = ImageCpX+(nBand/2);
	Roi.top    = 0;
	Roi.bottom = nImageH;
	
	//計算投影曲線	
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		Count = 0;
		Sum = Ave = 0.0;
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			idx = (i*ImageStep)+(j);
			Gray = pImage[idx];
			Sum += Gray;
			Count += 1;
		}
		if ( Count > 0 ) 
		{	Ave = Sum/Count; }
		else
		{	Ave = 0.0; }		
		Profile.push_back((unsigned char)(Ave));
	}
	if ( CalcGammaBySineProfile(Profile, LowRatio, PeriodGap, SineCount, Gamma) == false )
	{	return false; }
	return true;

	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcGrayImageGammaBySine_V(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, int nBand, float LowRatio, int PeriodGap, int &SineCount, double &Gamma)
{
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	
	const int nImageW = (int)(ImageW);
	const int nImageH = (int)(ImageH);	
	if ( nBand > nImageH ) 
	{	return false; }
	
	RECT  Roi;
	int   idx=0;
	int   Gray=0;
	int   Count=0;		
	int   i=0, j=0;	
	double Sum=0, Ave=0;	
	const int ImageCpX = nImageW/2;
	const int ImageCpY = nImageH/2;
	std::vector<unsigned char> Profile;

	Roi.left   = 0;
	Roi.right  = nImageW;
	Roi.top    = ImageCpY-(nBand/2);
	Roi.bottom = ImageCpY+(nBand/2);
	
	//計算投影曲線	
	for ( i=Roi.left; i<Roi.right; i++ )
	{
		Count = 0;
		Sum = Ave = 0.0;
		for ( j=Roi.top; j<Roi.bottom; j++ )
		{
			idx = (j*ImageStep)+(i);
			Gray = pImage[idx];
			Sum += Gray;
			Count += 1;
		}
		if ( Count > 0 ) 
		{	Ave = Sum/Count; }
		else
		{	Ave = 0.0; }		
		Profile.push_back((unsigned char)(Ave));
	}
	if ( CalcGammaBySineProfile(Profile, LowRatio, PeriodGap, SineCount, Gamma) == false )
	{	return false; }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ThinningGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int MaskStep, unsigned char *&pMask, int ThL, int ThH)
{
	const char fnName[] = ("CImageAPI::ThinningGrayImage");
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
	{	return false; }

	JetMemory.free_func(pMask);
	const size_t BufferSize = CalcBufferSize(MaskStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pMask, fnName, "pMask") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->ThinningGrayImage3(ImageW, ImageH, ImageStep, pImage, Roi, MaskStep, pMask, ThL, ThH) == false )
	{
		JetMemory.free_func(pMask);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ThinningGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const RECT &Roi, int MaskStep, unsigned char *pMask, int ThL, int ThH)
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	if ( this->CheckGrayImage(ImageW, ImageH, MaskStep, pMask) == false )
	{	return false; }

	size_t i=0, j=0, k=0;
	size_t srcIdx=0;
	size_t destIdx=0, destIdx2=0;
	
	for( i=0; i<ImageH; i++ )
    {  
		srcIdx = (i*ImageStep);
		destIdx = (i*MaskStep);
		for ( j=0; j<ImageW; j++ )
		{  
			if ( pImage[srcIdx+j]<ThL || pImage[srcIdx+j]>ThH ) 
			{
				pMask[destIdx+j] = 0;
				continue;  
			}
			pMask[destIdx+j] = 255;
		}
	}	

	if ( this->ThinningGrayImageKernel(ImageW, ImageH, MaskStep, pMask, Roi) == false )
	{	return false; }	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ThinningGrayImageKernel(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &Roi)
{
	const char fnName[] = "CImageAPI::ThinningGrayImageKernel";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	if ( this->CheckRoiRect(ImageW, ImageH, Roi) == false )	
	{	return false;	}

	int i=0, j=0, k=0;
	int srcIdx=0;
	int destIdx=0, destIdx2=0;

	int sp=0;
	int markNum=0;	
	int neighbor[8];	
	BOOL loop=TRUE;
    unsigned char *mark=NULL;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, mark, fnName, "mark") == false )	
	{	return false;	}

	//                                        p3  p2  p1  
	//**********使用zhang並行快速算法進行細化 p4  p   p0  
	//                                        p5  p6  p7  

	loop=TRUE;
	::memset(mark, 0x00,BufferSize);	
	while ( loop==TRUE )  
	{  
		loop=FALSE;  		
		//第一步  
		markNum=0;  
		for( i=Roi.top+1; i<Roi.bottom-1; i++ )
		{  
			destIdx = (i*ImageStep);
			for ( j=Roi.left+1; j<Roi.right-1; j++ )
			{  
				//條件1：p必須是前景點  
				if ( pImage[destIdx+j]==0 ) 
				{	continue;	}
   
				destIdx2 = destIdx+j;
				neighbor[0]= pImage[destIdx2+1] ;  
				neighbor[1]= pImage[destIdx2+1-ImageStep];  
				neighbor[2]= pImage[destIdx2-ImageStep];  
				neighbor[3]= pImage[destIdx2-1-ImageStep];  
				neighbor[4]= pImage[destIdx2-1];  
				neighbor[5]= pImage[destIdx2-1+ImageStep];  
				neighbor[6]= pImage[destIdx2+ImageStep];  
				neighbor[7]= pImage[destIdx2+1+ImageStep];  
   
				//條件2：2<=N(p）<=6  
				int np=(neighbor[0]+neighbor[1]+neighbor[2]+neighbor[3]+neighbor[4]+neighbor[5]+neighbor[6]+neighbor[7])/255;  
				if(np<2 || np>6) 
				{	continue; }
   
				//條件3：S(p）=1  
				sp=0;  
				for(k=1;k<8;k++)  
				{  
					if(neighbor[k]-neighbor[k-1]==255)  
					{	sp++; }
				}  
				if(neighbor[0]-neighbor[7]==255)
				{	sp++; }
				if(sp!=1)
				{	continue; }
   
				//條件4：p2*p0*p6=0  
				if(neighbor[2]&&neighbor[0]&&neighbor[6]!=0)
				{	continue; }

				//條件5：p0*p6*p4=0  
				if(neighbor[0]&&neighbor[6]&&neighbor[4]!=0)  
				{	continue; }
   
				//標記刪除  
				mark[destIdx2]=1;     
				markNum++;  
				loop=TRUE;  
			}  
		}  
   
		//將標記刪除的點置為背景色  
		if(markNum>0)  
		{  
			for( i=Roi.top; i<Roi.bottom; i++ )
			{  
				destIdx = (i*ImageStep);
				for ( j=Roi.left; j<Roi.right; j++ )
				{                
					if ( mark[destIdx+j]==1 ) 
					{	pImage[destIdx+j] = 0;	}
				}
			}
		}  
        if ( this->GetCallBackWnd() != NULL )
		{	::SendMessage(m_hWnd, WM_PAINT, NULL, NULL);	}

   
		//第二步  
		markNum=0;  
		for( i=Roi.top+1; i<Roi.bottom-1; i++ )
		{  
			destIdx = (i*ImageStep);
			for ( j=Roi.left+1; j<Roi.right-1; j++ )
			{  
				//條件1：p必須是前景點  
				if ( pImage[destIdx+j]==0 ) 
				{	continue;	}
   
				destIdx2 = destIdx+j;
   
				neighbor[0]= pImage[destIdx2+1] ;  
				neighbor[1]= pImage[destIdx2+1-ImageStep];  
				neighbor[2]= pImage[destIdx2-ImageStep];  
				neighbor[3]= pImage[destIdx2-1-ImageStep];  
				neighbor[4]= pImage[destIdx2-1];  
				neighbor[5]= pImage[destIdx2-1+ImageStep];  
				neighbor[6]= pImage[destIdx2+ImageStep];  
				neighbor[7]= pImage[destIdx2+1+ImageStep];
   
				//條件2：<=N(p)<=6  
				int np=(neighbor[0]+neighbor[1]+neighbor[2]+neighbor[3]+neighbor[4]+neighbor[5]+neighbor[6]+neighbor[7])/255;  
				if(np<2 || np>6)
				{	continue; }
   
				//條件3：S(p)=1  
				sp=0;  
				for(k=1;k<8;k++)  
				{  
					if(neighbor[k]-neighbor[k-1]==255)  
					{	sp++; }
				}  
				if(neighbor[0]-neighbor[7]==255)
				{	sp++; }
				if(sp!=1) 
				{	continue;  }
   
				//條件4：p2*p0*p4==0  
				if(neighbor[2]&&neighbor[0]&&neighbor[4]!=0)  
				{	continue; }
				//條件5：p2*p6*p4==0  
				if(neighbor[2]&&neighbor[6]&&neighbor[4]!=0)
				{	continue; }
   
				//標記刪除  
				mark[destIdx2]=1;     
				markNum++;  
				loop=TRUE;  
           }  
		}  
   
		//將標記刪除的點置為背景色  
		if(markNum>0)  
		{  
			for( i=Roi.top; i<Roi.bottom; i++ )
			{  
				destIdx = (i*ImageStep);
				for ( j=Roi.left; j<Roi.right; j++ )
				{                
					if ( mark[destIdx+j]==1 ) 
					{	pImage[destIdx+j] = 0;	}
				}
			}
		}

		if ( this->GetCallBackWnd() != NULL )
		{	::SendMessage(m_hWnd, WM_PAINT, NULL, NULL);	}
    }
	JetMemory.free_func(mark);	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::EdgeSearchImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BOX_TOWARD Toward, const RECT &Limit, int Threshold, int &Pos, int &Range)//影像邊緣搜尋
{
	RECT RoiRect;
	JetAPI::SizeToRect(ImageW, ImageH, RoiRect);
	return EdgeSearchImageRoi(ImageW, ImageH, ImageStep, pImage, Toward, RoiRect, Limit, Threshold, Pos, Range);
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::EdgeSearchImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BOX_TOWARD Toward, const RECT &RoiRect, const RECT &Limit, int Threshold, int &Pos, int &Range)//影像邊緣搜尋
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false ) 
	{	return false; }	
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int    i=0, j=0, k=0;
	int    XIdx=0, YIdx=0;
	int    XPos=0, YPos=0;
	int    XCount=0, YCount=0;	
	const int MinW = Limit.left;
	const int MinH = Limit.top;
	const int MaxW = Limit.right;
	const int MaxH = Limit.bottom;
	const int nImageW=(int)(ImageW);
	const int nImageH=(int)(ImageH);
	const int nImageStep=(int)(ImageStep);	
	if ( BOX_TOWARD_DOWN==Toward || BOX_TOWARD_UP==Toward )
	{
		YPos = -1;		
		for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
		{	
			if ( BOX_TOWARD_UP == Toward )
			{	YIdx = RoiRect.bottom-i-1+RoiRect.top;	}
			else
			{	YIdx = i; }
			XCount = 0;
			for ( j=RoiRect.left; j<RoiRect.right; j++ )
			{
				k = (YIdx*nImageStep)+j;
				if ( pImage[k] < Threshold ) 
				{	continue;	}
				XCount ++;
			}
			if ( XCount<MinW || XCount>MaxW ) 
			{				
				if ( YCount<MinH || YCount>MaxH)
				{
					YPos = -1;
					YCount = 0;
					continue;
				}
				break;
			}
			if ( -1 == YPos ) 
			{	YPos = YIdx; }
			YCount ++;			
		}		
		Pos = YPos;
		Range = YCount;
	}

	if ( BOX_TOWARD_RIGHT==Toward || BOX_TOWARD_LEFT==Toward )
	{
		XPos = -1;
		for ( i=RoiRect.left; i<RoiRect.right; i++ )
		{	
			if ( BOX_TOWARD_LEFT == Toward )
			{	XIdx = RoiRect.right-i-1+RoiRect.left;	}
			else
			{	XIdx = i; }
			YCount = 0;
			for ( j=RoiRect.top; j<RoiRect.bottom; j++ )
			{
				k = (j*nImageStep)+XIdx;
				if ( pImage[k] < Threshold ) 
				{	continue;	}
				YCount ++;
			}
			if ( YCount<MinH || YCount>MaxH ) 
			{
				if ( XCount<MinW || XCount>MaxW )
				{
					XPos = -1;
					XCount = 0;
					continue;
				}
				break; 
			}
			if ( -1 == XPos ) 
			{	XPos = XIdx; }
			XCount ++;			
		}
		Pos = XPos;
		Range = XCount;
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SobelImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *&pDst)//影像邊緣強化-Sobel
{
	const char fnName[] = "CImageAPI::SobelImage";
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false ) 
	{	return false; }	
	
	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->SobelImage3(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SobelImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *pDst)//影像邊緣強化-Sobel
{
	const char fnName[] = "CImageAPI::SobelImage3";
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }	
#ifndef OPENCV_DISABLE
	short *XPtr=NULL;
	short *YPtr=NULL;	
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, XPtr, fnName, "XPtr") == false ||
		 JetMemory.alloc_func(BufferSize, YPtr, fnName, "YPtr") == false )
	{
		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	try
	{	
		
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);			
		cv::Mat MatTmpX=CreateMat(ImageW, ImageH, ImageStep, BitCount, XPtr);
		cv::Mat MatTmpY=CreateMat(ImageW, ImageH, ImageStep, BitCount, YPtr);
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false || CheckMatIsValid(MatTmpX)==false || CheckMatIsValid(MatTmpY)==false)
		{
			JetMemory.free_func(XPtr);
			JetMemory.free_func(YPtr);
			return false;	
		}
		const int KerSize=3;
		cv::Sobel(MatSrc, MatTmpX, CV_16S, 1, 0, KerSize);
		cv::Sobel(MatSrc, MatTmpY, CV_16S, 0, 1, KerSize);
		
		//轉成ABS, 並且轉成Sobel	
		int   i=0, j=0, Gray=0;
		size_t srcidx=0, dstidx=0;
		short *MPtrX=(short*)(MatTmpX.data);
		short *MPtrY=(short*)(MatTmpY.data);
		const int XStep=MatTmpX.step1();
		const int YStep=MatTmpY.step1();
		const int SobleRows=MatTmpX.rows;
		const int SobleCols=MatTmpX.cols;
		const int nChannels = GetImageChannels(BitCount);
		const int SobleColChannels=SobleCols*nChannels;
		const int SobelSize = SobleRows*SobleCols;
		for ( i=0; i<SobleRows; i++ )
		{
			srcidx = i*XStep;
			dstidx = i*ImageStep;
			for ( j=0; j<SobleColChannels; j++ )
			{
				if ( MPtrX[srcidx] < 0 ) 
				{	MPtrX[srcidx] = -MPtrX[srcidx]; }

				if ( MPtrY[srcidx] < 0 ) 
				{	MPtrY[srcidx] = -MPtrY[srcidx]; }

				Gray  = XPtr[srcidx];
				Gray += YPtr[srcidx];	
				if ( Gray > 255 ) { Gray = 255; }
				pDst[dstidx] = static_cast<unsigned char>(Gray);
				//pDst[dstidx] = static_cast<unsigned char>(Gray>>1);//不用取平均

				srcidx ++;
				dstidx ++;
			}
		}

		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);		
		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
