//-------------------------------------------------------------------------------------//
bool CImageAPI::EdgeImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *pDst, int Mode)//影像邊緣強化-Sobel-單邊
{
	const char fnName[] = "CImageAPI::EdgeImage3";
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }	
#ifndef OPENCV_DISABLE		
	try
	{			
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);					
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		const int KerSize=3;
		switch ( Mode )
		{
		case SOBEL_DARK_TOP: cv::Sobel(MatSrc, MatDst, -1, 0, 1, KerSize,  1);	break;
		case SOBEL_DARK_BOT: cv::Sobel(MatSrc, MatDst, -1, 0, 1, KerSize, -1);	break;

		case SOBEL_DARK_LEFT: cv::Sobel(MatSrc, MatDst, -1, 1, 0, KerSize, 1);	break;
		case SOBEL_DARK_RIGHT: cv::Sobel(MatSrc, MatDst, -1, 1, 0, KerSize, -1);	break;
		}
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();	
	return true;
}
