//-------------------------------------------------------------------------------------//
bool CImageAPI::ScharrImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, unsigned char *pDst)//影像邊緣強化-Scharr
{
	const char fnName[] = "CImageAPI::ScharrImage3";
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }	
#ifndef OPENCV_DISABLE
	short *XPtr=NULL;
	short *YPtr=NULL;	
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, XPtr, fnName, "XPtr") == false ||
		 JetMemory.alloc_func(BufferSize, YPtr, fnName, "YPtr") == false )
	{
		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	try
	{	
		
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);			
		cv::Mat MatTmpX=CreateMat(ImageW, ImageH, ImageStep, BitCount, XPtr);
		cv::Mat MatTmpY=CreateMat(ImageW, ImageH, ImageStep, BitCount, YPtr);
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false || CheckMatIsValid(MatTmpX)==false || CheckMatIsValid(MatTmpY)==false)
		{
			JetMemory.free_func(XPtr);
			JetMemory.free_func(YPtr);
			return false;	
		}		
		cv::Scharr(MatSrc, MatTmpX, CV_16S, 1, 0);
		cv::Scharr(MatSrc, MatTmpY, CV_16S, 0, 1);
		
		//轉成ABS, 並且轉成Sobel	
		int   i=0, j=0, Gray=0;
		size_t srcidx=0, dstidx=0;
		short *MPtrX=(short*)(MatTmpX.data);
		short *MPtrY=(short*)(MatTmpY.data);
		const int XStep=MatTmpX.step1();
		const int YStep=MatTmpY.step1();
		const int SobleRows=MatTmpX.rows;
		const int SobleCols=MatTmpX.cols;
		const int nChannels = GetImageChannels(BitCount);
		const int SobleColChannels=SobleCols*nChannels;
		const int SobelSize = SobleRows*SobleCols;
		for ( i=0; i<SobleRows; i++ )
		{
			srcidx = i*XStep;
			dstidx = i*ImageStep;
			for ( j=0; j<SobleColChannels; j++ )
			{
				if ( MPtrX[srcidx] < 0 ) 
				{	MPtrX[srcidx] = -MPtrX[srcidx]; }

				if ( MPtrY[srcidx] < 0 ) 
				{	MPtrY[srcidx] = -MPtrY[srcidx]; }

				Gray  = XPtr[srcidx];
				Gray += YPtr[srcidx];	
				if ( Gray > 255 ) { Gray = 255; }
				pDst[dstidx] = static_cast<unsigned char>(Gray);
				//pDst[dstidx] = static_cast<unsigned char>(Gray>>1);//不用取平均

				srcidx ++;
				dstidx ++;
			}
		}

		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{			
		CatchOpenCVException(e);		
		JetMemory.free_func(XPtr);
		JetMemory.free_func(YPtr);
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
