bool CImageAPI::SmoothImageByIntegral3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *pDst)//單張影像平均濾波
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount )
	{	return CImageAPI::SmoothGrayImageByIntegral3(ImageW, ImageH, ImageStep, pImage, KerSize, pDst);	}
	if ( 24 == BitCount )
	{	return CImageAPI::SmoothColorImageByIntegral3(ImageW, ImageH, ImageStep, pImage, KerSize, pDst);	}	
	return false;
}
