//-------------------------------------------------------------------------------------//
bool CImageAPI::SmoothColorImageByIntegral3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *pDst)//單張彩色影像平均濾波
{
	const char fnName[] = "CImageAPI::SmoothColorImageByIntegral3-UCHAR";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false ) 
	{	return false; }			
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }

	float       *IntegralPtr=NULL;
	const size_t IntegralSize=CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(IntegralSize, IntegralPtr, fnName, "IntegralPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( BuildIntegralColorImage3(ImageW, ImageH, ImageStep, pImage, IntegralPtr) == false )
	{
		JetMemory.free_func(IntegralPtr);
		return false;
	}

	size_t   i=0, j=0, k=0;
	RECT     Roi={0,0,0,0};
	int    idx1=0, idx2=0, idx3=0, idx4=0;		
	float  SumR=0.0, AveR=0.0;
	float  SumG=0.0, AveG=0.0;
	float  SumB=0.0, AveB=0.0;
	float  Sum1R=0, Sum2R=0, Sum3R=0, Sum4R=0;
	float  Sum1G=0, Sum2G=0, Sum3G=0, Sum4G=0;
	float  Sum1B=0, Sum2B=0, Sum3B=0, Sum4B=0;	
	const int KerSize2 = KerSize/2;
	const int KerSizeFull = KerSize2*2+1;
	const int TotalSize= KerSizeFull*KerSizeFull;
	
	int   Count=0;
	int   MaskRoiW=0;
	int   MaskRoiH=0;
	int   TmpY1=0, TmpY2=0;
	int   TmpX1=0, TmpX2=0;
	int   MaskRoiIdxY1=0, MaskRoiIdxY2=0;
	int   MaskRoiIdxX1=0, MaskRoiIdxX2=0;

	Roi.right = ImageW;
	Roi.bottom = ImageH;	
	const int nChannel=3;
	const int RoiStep=(int)(ImageStep);
	const int RoiSize=(int)(IntegralSize);
	const int MaskRoiT=Roi.top+KerSize2;
	const int MaskRoiB=Roi.bottom-KerSize2;
	const int MaskRoiL=Roi.left+KerSize2;
	const int MaskRoiR=Roi.right-KerSize2;
	for ( i=0; i<ImageH; i++ )
	{			
		k=(i*ImageStep);
		for ( j=0; j<ImageW; j++ )
		{	
			MaskRoiIdxY1 = i-KerSize2;
			MaskRoiIdxY2 = i+KerSize2;
			MaskRoiIdxX1 = j-KerSize2;
			MaskRoiIdxX2 = j+KerSize2;
			if ( MaskRoiIdxY1 < Roi.top ) 
			{	MaskRoiIdxY1 = Roi.top; }
			if ( MaskRoiIdxY2 >= Roi.bottom 	) 
			{	MaskRoiIdxY2 = Roi.bottom-1; }			

			if ( MaskRoiIdxX1 < Roi.left ) 
			{	MaskRoiIdxX1 = Roi.left; }
			if ( MaskRoiIdxX2 >= Roi.right 	) 
			{	MaskRoiIdxX2 = Roi.right-1; }			
			MaskRoiH = MaskRoiIdxY2-MaskRoiIdxY1+1;
			MaskRoiW = MaskRoiIdxX2-MaskRoiIdxX1+1;

			TmpY1 = (MaskRoiIdxY1-Roi.top-1)*RoiStep;
			TmpY2 = (MaskRoiIdxY2-Roi.top)*RoiStep;
			TmpX1 = (MaskRoiIdxX1-Roi.left-1)*nChannel;
			TmpX2 = (MaskRoiIdxX2-Roi.left)*nChannel;
			idx1 = TmpY1+TmpX1;
			idx2 = TmpY1+TmpX2;
			idx3 = TmpY2+TmpX1;
			idx4 = TmpY2+TmpX2;
			if ( (MaskRoiIdxY1-1) < Roi.top )
			{
				idx1 = RoiSize;
				idx2 = RoiSize;
			}
			if ( (MaskRoiIdxX1-1) < Roi.left )
			{	
				idx1 = RoiSize;	
				idx3 = RoiSize;	
			}

			//if ( idx1<0 || idx1>=RoiSize )
			if ( idx1>=RoiSize )
			{	Sum1R = Sum1G = Sum1B = 0;	}
			else
			{	
				Sum1B = IntegralPtr[idx1++]; 
				Sum1G = IntegralPtr[idx1++]; 
				Sum1R = IntegralPtr[idx1++]; 
			}

			//if ( idx2<0 || idx2>=RoiSize )
			if ( idx2>=RoiSize )
			{	Sum2R = Sum2G = Sum2B = 0;	}
			else
			{	
				Sum2B = IntegralPtr[idx2++]; 
				Sum2G = IntegralPtr[idx2++]; 
				Sum2R = IntegralPtr[idx2++]; 
			}

			//if ( idx3<0 || idx3>=RoiSize )
			if ( idx3>=RoiSize )
			{	Sum3R = Sum3G = Sum3B = 0;	}
			else
			{	
				Sum3B = IntegralPtr[idx3++]; 
				Sum3G = IntegralPtr[idx3++]; 
				Sum3R = IntegralPtr[idx3++]; 
			}
			
			//if ( idx4<0 || idx4>=RoiSize )
			if ( idx4>=RoiSize )
			{	Sum4R = Sum4G = Sum4B = 0;	}
			else
			{	
				Sum4B = IntegralPtr[idx4++]; 
				Sum4G = IntegralPtr[idx4++]; 
				Sum4R = IntegralPtr[idx4++]; 
			}
			SumR = Sum4R+Sum1R-Sum2R-Sum3R;
			SumG = Sum4G+Sum1G-Sum2G-Sum3G;
			SumB = Sum4B+Sum1B-Sum2B-Sum3B;
			
			//Count = TotalSize;
			Count = MaskRoiW*MaskRoiH;
			//if ( 0 == Count ) 
			//{	AveR = AveG = AveB = 0.0f; }
			//else
			{	
				AveR = SumR/Count; 
				AveG = SumG/Count; 
				AveB = SumB/Count; 
			}
			/*
			if ( AveR < 0 ) { AveR = 0.0f; }
			else if ( AveR > 255.0f ) { AveR = 255.0f; }
			if ( AveG < 0 ) { AveG = 0.0f; }
			else if ( AveG > 255.0f ) { AveG = 255.0f; }
			if ( AveB < 0 ) { AveB = 0.0f; }
			else if ( AveB > 255.0f ) { AveB = 255.0f; }
			//*/
			//k=(i*ImageStep)+(j*3);//*/
			pDst[k++]=(unsigned char)(AveB);
			pDst[k++]=(unsigned char)(AveG);
			pDst[k++]=(unsigned char)(AveR);
		}
	}
	JetMemory.free_func(IntegralPtr);
	return true;	
}
