//-------------------------------------------------------------------------------------//
bool CImageAPI::SmoothShortGrayImageByIntegral3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned short *pImage, IMAGE_SIZE KerSize, unsigned short *pDst)//單張灰階影像平均濾波
{
	const char fnName[] = "CImageAPI::SmoothGrayImageByIntegral3-USHRT";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false ) 
	{	return false; }			
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }

	float       *IntegralPtr=NULL;
	const size_t IntegralSize=CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(IntegralSize, IntegralPtr, fnName, "IntegralPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	
	if ( BuildIntegralGrayImage3(ImageW, ImageH, ImageStep, pImage, IntegralPtr) == false )
	{
		JetMemory.free_func(IntegralPtr);
		return false;
	}

	size_t   i=0, j=0, k=0;
	RECT     Roi={0,0,0,0};
	int    idx1=0, idx2=0, idx3=0, idx4=0;	
	float  Sum1=0, Sum2=0, Sum3=0, Sum4=0;
	double Sum=0.0, Ave=0.0;		
	const int KerSize2 = KerSize/2;
	const int KerSizeFull = KerSize2*2+1;
	const int TotalSize= KerSizeFull*KerSizeFull;
	
	int   Count=0;
	int   MaskRoiW=0;
	int   MaskRoiH=0;
	int   TmpY1=0, TmpY2=0;
	int   TmpX1=0, TmpX2=0;
	int   MaskRoiIdxY1=0, MaskRoiIdxY2=0;
	int   MaskRoiIdxX1=0, MaskRoiIdxX2=0;

	Roi.right = ImageW;
	Roi.bottom = ImageH;	
	const int RoiStep=(int)(ImageStep);
	const int RoiSize=(int)(IntegralSize);
	const int MaskRoiT=Roi.top+KerSize2;
	const int MaskRoiB=Roi.bottom-KerSize2;
	const int MaskRoiL=Roi.left+KerSize2;
	const int MaskRoiR=Roi.right-KerSize2;
	for ( i=0; i<ImageH; i++ )
	{
		k=(i*ImageStep);
		for ( j=0; j<ImageW; j++ )
		{	
			MaskRoiIdxY1 = i-KerSize2;
			MaskRoiIdxY2 = i+KerSize2;
			MaskRoiIdxX1 = j-KerSize2;
			MaskRoiIdxX2 = j+KerSize2;
			if ( MaskRoiIdxY1 < Roi.top ) 
			{	MaskRoiIdxY1 = Roi.top; }
			if ( MaskRoiIdxY2 >= Roi.bottom 	) 
			{	MaskRoiIdxY2 = Roi.bottom-1; }			

			if ( MaskRoiIdxX1 < Roi.left ) 
			{	MaskRoiIdxX1 = Roi.left; }
			if ( MaskRoiIdxX2 >= Roi.right 	) 
			{	MaskRoiIdxX2 = Roi.right-1; }			
			MaskRoiH = MaskRoiIdxY2-MaskRoiIdxY1+1;
			MaskRoiW = MaskRoiIdxX2-MaskRoiIdxX1+1;

			TmpY1 = (MaskRoiIdxY1-Roi.top-1)*RoiStep;
			TmpY2 = (MaskRoiIdxY2-Roi.top)*RoiStep;
			TmpX1 = (MaskRoiIdxX1-Roi.left-1);
			TmpX2 = (MaskRoiIdxX2-Roi.left);
			idx1 = TmpY1+TmpX1;
			idx2 = TmpY1+TmpX2;
			idx3 = TmpY2+TmpX1;
			idx4 = TmpY2+TmpX2;
			if ( (MaskRoiIdxY1-1) < Roi.top )
			{
				idx1 = RoiSize;
				idx2 = RoiSize;
			}
			if ( (MaskRoiIdxX1-1) < Roi.left )
			{	
				idx1 = RoiSize;	
				idx3 = RoiSize;	
			}

			//if ( idx1<0 || idx1>=RoiSize )
			if ( idx1 >= RoiSize )
			{	Sum1 = 0;	}
			else
			{	Sum1 = IntegralPtr[idx1]; }

			//if ( idx2<0 || idx2>=RoiSize )
			if ( idx2 >= RoiSize )
			{	Sum2 = 0;	}
			else
			{	Sum2 = IntegralPtr[idx2]; }

			//if ( idx3<0 || idx3>=RoiSize )
			if ( idx3 >= RoiSize )
			{	Sum3 = 0;	}
			else
			{	Sum3 = IntegralPtr[idx3]; }
			
			//if ( idx4<0 || idx4>=RoiSize )
			if ( idx4 >= RoiSize )
			{	Sum4 = 0;	}
			else
			{	Sum4 = IntegralPtr[idx4]; }
			Sum = Sum4+Sum1-Sum2-Sum3;
			
			//Count = TotalSize;
			Count = MaskRoiW*MaskRoiH;
			//if ( 0 == Count ) 
			//{	Ave = 0.0f; }
			//else
			{	Ave = Sum/Count; }
			
			//if ( Ave < 0 ) { Ave = 0; }
			//else if ( Ave > USHRT_MAX ) { Ave = USHRT_MAX; }
			//k=(i*ImageStep)+j;
			pDst[k++]=(short)(Ave);			
		}
	}
	JetMemory.free_func(IntegralPtr);	
	return true;	
}
