bool CImageAPI::DilateNoiseMaskImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const MASK_PTR MaskPtr, unsigned int KenSize, unsigned int IterCount, MASK_PTR &DstPtr)//遮罩影像膨脹濾波
{
	const char fnName[] = "CImageAPI::DilateNoiseMaskImage";
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, MaskPtr) == false ) 
	{	return false; }		
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(DstPtr);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	
	if ( DilateNoiseMaskImage3(ImageW, ImageH, ImageStep, MaskPtr, KenSize, IterCount, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		return false; 
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DilateNoiseMaskImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const MASK_PTR MaskPtr, unsigned int KenSize, unsigned int IterCount, MASK_PTR DstPtr)//遮罩影像膨脹濾波
{
	const char fnName[] = "CImageAPI::DilateNoiseMaskImage3";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, MaskPtr, DstPtr) == false ) 
	{	return false; }	

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( KenSize < 3 || IterCount < 1 )
	{
		if ( MaskPtr != DstPtr )
		{	::memcpy(DstPtr, MaskPtr, sizeof(MASK_DATA)*BufferSize); }
		return true;
	}

	size_t i=0;
	unsigned char *SrcT = NULL;
	unsigned char *DstT = NULL;
	const unsigned char NoiseMask = 0xFF;	
	if ( JetMemory.alloc_func(BufferSize, SrcT, fnName, "SrcT") == false ||
		 JetMemory.alloc_func(BufferSize, DstT, fnName, "DstT") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(SrcT);
		JetMemory.free_func(DstT);
		return false; 
	}
	for ( i=0; i<BufferSize; i++ )
	{	
		if ( CheckSpaceMaskValid(MaskPtr[i]) == true ) 
		{	SrcT[i] = 0; }
		else
		{	SrcT[i] = NoiseMask; }
	}

	if ( DilateGrayImage3(ImageW, ImageH, ImageStep, SrcT, KenSize, IterCount, DstT) == false )
	{
		JetMemory.free_func(SrcT);
		JetMemory.free_func(DstT);
		return false;
	}
	for ( i=0; i<BufferSize; i++ )
	{
		if ( 0 == DstT[i] )
		{
			DstPtr[i] = MaskPtr[i];
			if ( CheckSpaceMaskValid(MaskPtr[i]) == false )
			{	DstPtr[i] = PHASE_MASK_VALID; }
			continue; 
		}		
		if ( CheckSpaceMaskValid(MaskPtr[i]) == true ) 
		{	DstPtr[i] = PHASE_MASK_EXTEND_VOID; }
		else
		{	DstPtr[i] = MaskPtr[i]; }
	}
	JetMemory.free_func(SrcT);
	JetMemory.free_func(DstT);
	return true;
}
