//-------------------------------------------------------------------------------------//
bool CImageAPI::MorphImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, int MorphMode, int ShpaeMode, unsigned int KenSize, unsigned int IterCount, unsigned char *pDst)//單張影像形態操作
{
	if ( this->CheckImage2(ImageW, ImageH, ImageStep, BitCount, pImage, pDst) == false ) 
	{	return false; }
	if ( this->CheckPtrNoRepeat2(pImage, pDst) == false )//確認指標重複
	{	return false; }

#ifndef OPENCV_DISABLE
	try
	{
		const int cvMorphMode = GetCVMorphMode(MorphMode);
		const int cvShapeMode = GetCVMorphShapeMode(ShpaeMode);
		if ( cvMorphMode == 0 ) 
		{	return false; }
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);			
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}
		KenSize = GetKernelSize(KenSize);//確保奇數
		cv::Mat kernel = cv::getStructuringElement(cvShapeMode, cv::Size(KenSize,KenSize));
		cv::morphologyEx(MatSrc, MatDst, cvMorphMode, kernel);		
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, BitCount, pDst) == false )
		{	return false;	}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);		
		return false;
	}		
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
