bool CImageAPI::AverageGrayImage2Frame(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, unsigned char *&pDst)//多張灰階影像平均濾波
{	
	const char fnName[] = "CImageAPI::AverageGrayImage2Frame";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, Ptr1, Ptr2) == false ) 
	{	return false; }	

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->AverageGrayImage2Frame3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::AverageGrayImage2Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, unsigned char *pDst)//多張灰階影像平均濾波
{	
	//Image Size (4000 , 3000)=>15 ms 
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false ) 
	{	return false; }

	size_t i=0;
	size_t Ave=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<BufferSize; i++ )
	{
		Ave = Ptr1[i];
		Ave += Ptr2[i];
		pDst[i] = (unsigned char)(Ave>>1);
	}
	return true;
}
