bool CImageAPI::AverageColorImage4Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, unsigned char *pDst)//4張彩色影像平均濾波
{
	//Image Size (4000 , 3000)=>85 ms 
	if ( this->CheckColorImage5(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, pDst) == false ) 
	{	return false; }

	size_t i=0, j=0, idx=0;
	size_t Ave=0;		
	
	//94 ms for 4000x3000
	/*
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<BufferSize; i++ )
	{
		Ave  = Ptr1[i];
		Ave += Ptr2[i];
		Ave += Ptr3[i];
		Ave += Ptr4[i];
		pDst[i] = (unsigned char)(Ave>>2);
	}
	*/
	
	//80 ms for 4000x3000
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{
			//Blue
			Ave  = Ptr1[idx];
			Ave += Ptr2[idx];
			Ave += Ptr3[idx];
			Ave += Ptr4[idx];
			pDst[idx] = (unsigned char)(Ave>>2);
			idx++;

			//Green
			Ave  = Ptr1[idx];
			Ave += Ptr2[idx];
			Ave += Ptr3[idx];
			Ave += Ptr4[idx];
			pDst[idx] = (unsigned char)(Ave>>2);
			idx++;

			//Red
			Ave  = Ptr1[idx];
			Ave += Ptr2[idx];
			Ave += Ptr3[idx];
			Ave += Ptr4[idx];
			pDst[idx] = (unsigned char)(Ave>>2);
			idx++;
		}
	}
	return true;
}
