//-------------------------------------------------------------------------------------//
bool CImageAPI::MaxValueGrayImage2Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, unsigned char *pDst)//2張灰階影像平均濾波
{	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false ) 
	{	return false; }

	size_t i=0;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<BufferSize; i++ )
	{
		if ( Ptr1[i] > Ptr2[i] )
		{	pDst[i] = Ptr1[i]; }
		else
		{	pDst[i] = Ptr2[i]; }
	}
	return true;
}
