bool CImageAPI::MaxValueColorImage4Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, unsigned char *pDst)//4張彩色影像最高亮度
{
	if ( this->CheckColorImage5(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, pDst) == false ) 
	{	return false; }

	size_t v1=0, v2=0, v3=0, v4=0;
	size_t i=0, j=0, idx=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{			
			v1  = Ptr1[idx];
			v1  += Ptr1[idx+1];
			v1  += Ptr1[idx+2];

			v2  = Ptr2[idx];
			v2  += Ptr2[idx+1];
			v2  += Ptr2[idx+2];

			v3  = Ptr3[idx];
			v3  += Ptr3[idx+1];
			v3  += Ptr3[idx+2];

			v4  = Ptr4[idx];
			v4  += Ptr4[idx+1];
			v4  += Ptr4[idx+2];

			if ( v1>v2 && v1>v3 && v1>v4 )
			{
				pDst[idx] = Ptr1[idx]; idx ++;
				pDst[idx] = Ptr1[idx]; idx ++;
				pDst[idx] = Ptr1[idx]; idx ++;
			}
			else if ( v2>v1 && v2>v3 && v2>v4)
			{
				pDst[idx] = Ptr2[idx]; idx ++;
				pDst[idx] = Ptr2[idx]; idx ++;
				pDst[idx] = Ptr2[idx]; idx ++;
			}
			else if ( v3>v1 && v3>v2 && v3>v4 )
			{
				pDst[idx] = Ptr3[idx]; idx ++;
				pDst[idx] = Ptr3[idx]; idx ++;
				pDst[idx] = Ptr3[idx]; idx ++;
			}
			else
			{
				pDst[idx] = Ptr4[idx]; idx ++;
				pDst[idx] = Ptr4[idx]; idx ++;
				pDst[idx] = Ptr4[idx]; idx ++;
			}
		}
	}
	return true;
}
