	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->MergeGrayImage2Frame3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
