//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage2Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, unsigned char *pDst)//合併2張灰階影像
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false ) 
	{	return false; }
	
	size_t i=0, j=0, idx=0;
	unsigned int val=0;
	unsigned char v1=0, v2=0, v=0;
	const size_t OverSaturated = 250;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{			
			v1  = Ptr1[idx];			
			v2  = Ptr2[idx];

			val = v1+v2;
			val = val/2;			
			pDst[idx] = (unsigned char)(val);
			idx ++;
			continue;
			
			if ( v1 > OverSaturated )
			{	v = v2;	}
			else if ( v2 > OverSaturated )
			{	v = v1;	}
			else
			{
				if ( v1 > v2 )
				{	v = v1; }
				else
				{	v = v2; }
			}
			pDst[idx] = v;			
			idx ++;
		}
	}
	return true;
}
