//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage3Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, unsigned char *pDst)//合併3張灰階影像
{
	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, pDst) == false ) 
	{	return false; }
	
	size_t i=0, j=0, idx=0;	
	unsigned int  val = 0;
	unsigned char vRank[3]={0};
	unsigned char v1=0, v2=0, v3=0, v=0;
	const size_t OverSaturated = 250;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{			
			v1  = Ptr1[idx];			
			v2  = Ptr2[idx];
			v3  = Ptr3[idx];

			val = v1+v2+v3;
			val = val/3;
			pDst[idx] = (unsigned char)(val);
			idx ++;
			continue;

			if ( v1 > v2 )
			{
				if ( v1 > v3 )
				{
					vRank[0] = v1;
					if ( v2 > v3 )
					{	vRank[1] = v2;	}
					else
					{	vRank[2] = v3;	}
				}
				else
				{
					vRank[0] = v3;
					vRank[1] = v1;
					vRank[2] = v2;
				}
			}
			else
			{
				if ( v2 > v3 )
				{
					vRank[0] = v2;
					if ( v1 > v3 )
					{	vRank[1] = v1;	}
					else
					{	vRank[2] = v3;	}
				}
				else
				{
					vRank[0] = v3;
					vRank[1] = v2;
					vRank[2] = v1;
				}
			}

			if ( vRank[0] < OverSaturated )
			{	v = vRank[0];	}
			else if ( vRank[1] < OverSaturated )
			{	v = vRank[1];	}
			else 
			{	v = vRank[2]; }			
			pDst[idx] = v;			
			idx ++;
		}
	}
	return true;
}
