	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4) == false ) 
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->MergeGrayImage4Frame3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
