//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage4Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, unsigned char *pDst)//合併4張灰階影像
{
	if ( this->CheckGrayImage5(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, pDst) == false ) 
	{	return false; }

	size_t i=0, j=0, idx=0;	
	size_t iMax=0, iMin=0;
	unsigned int  val=0;
	unsigned char vRank[4]={0};
	unsigned char v1=0, v2=0, v3=0, v4=0, v=0;	
	const size_t OverSaturated = 250;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{			
			vRank[0] = v1  = Ptr1[idx];			
			vRank[1] = v2  = Ptr2[idx];
			vRank[2] = v3  = Ptr3[idx];
			vRank[3] = v4  = Ptr4[idx];

			val = v1+v2+v3+v4;
			val = val/4;
			pDst[idx] = (unsigned char)(val);
			idx ++;
			continue;

			iMax = iMin = 1;			
			if ( v1>v2 && v1>v3 && v1>v4 )
			{	iMax = 1;	}
			if ( v2>v1 && v2>v3 && v2>v4 )
			{	iMax = 2;	}
			if ( v3>v1 && v3>v2 && v3>v4 )
			{	iMax = 3;	}
			if ( v4>v1 && v4>v2 && v4>v1 )
			{	iMax = 4;	}

			if ( iMax != 1 )
			{
				if ( v1<v2 && v1<v3 && v1<v4 )
				{	iMin = 1;	}
			}
			if ( iMax != 2 )
			{
				if ( v2<v1 && v2<v3 && v2<v4 )
				{	iMin = 2;	}
			}
			if ( iMax != 3 )
			{
				if ( v3<v1 && v3<v2 && v3<v4 )
				{	iMin = 3;	}
			}
			if ( iMax != 4 )
			{
				if ( v4<v1 && v4<v2 && v4<v3 )
				{	iMin = 4;	}
			}
			
			switch ( iMax )
			{
			case 1:
				vRank[0] = v1;
				switch ( iMin )
				{
				case 2:
					vRank[3] = v2;
					if ( v3 > v4 )
					{	vRank[1] = v3;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v3;	}
					break;
				case 3:
					vRank[3] = v3;
					if ( v2 > v4 )
					{	vRank[1] = v2;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v2;	}
					break;
				case 4:
					vRank[3] = v4;
					if ( v3 > v2 )
					{	vRank[1] = v3;	vRank[2] = v2;	}
					else
					{	vRank[1] = v2; 	vRank[2] = v3;	}
					break;
				default:					
					vRank[1] = v2;	vRank[2] = v3;	vRank[3] = v4;
					break;
				}
				break;
			case 2:
				vRank[0] = v2;
				switch ( iMin )
				{
				case 1:
					vRank[3] = v1;
					if ( v3 > v4 )
					{	vRank[1] = v3;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v3;	}
					break;
				case 3:
					vRank[3] = v3;
					if ( v1 > v4 )
					{	vRank[1] = v1;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v1;	}
					break;
				case 4:
					vRank[3] = v4;
					if ( v3 > v1 )
					{	vRank[1] = v3;	vRank[2] = v1;	}
					else
					{	vRank[1] = v1; 	vRank[2] = v3;	}
					break;
				default:					
					vRank[1] = v1;	vRank[2] = v3;	vRank[3] = v4;
					break;
				}
				break;
			case 3:
				vRank[0] = v3;
				switch ( iMin )
				{
				case 2:
					vRank[3] = v2;
					if ( v1 > v4 )
					{	vRank[1] = v1;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v1;	}
					break;
				case 1:
					vRank[3] = v1;
					if ( v2 > v4 )
					{	vRank[1] = v2;	vRank[2] = v4;	}
					else
					{	vRank[1] = v4; 	vRank[2] = v2;	}
					break;
				case 4:
					vRank[3] = v4;
					if ( v1 > v2 )
					{	vRank[1] = v1;	vRank[2] = v2;	}
					else
					{	vRank[1] = v2; 	vRank[2] = v1;	}
					break;
				default:					
					vRank[1] = v2;	vRank[2] = v1;	vRank[3] = v4;
					break;
				}
				break;
			case 4:
				vRank[0] = v4;
				switch ( iMin )
				{
				case 2:
					vRank[3] = v2;
					if ( v3 > v1 )
					{	vRank[1] = v3;	vRank[2] = v1;	}
					else
					{	vRank[1] = v1; 	vRank[2] = v3;	}
					break;
				case 3:
					vRank[3] = v3;
					if ( v2 > v1 )
					{	vRank[1] = v2;	vRank[2] = v1;	}
					else
					{	vRank[1] = v1; 	vRank[2] = v2;	}
					break;
				case 1:
					vRank[3] = v1;
					if ( v3 > v2 )
					{	vRank[1] = v3;	vRank[2] = v2;	}
					else
					{	vRank[1] = v2; 	vRank[2] = v3;	}
					break;
				default:					
					vRank[1] = v2;	vRank[2] = v3;	vRank[3] = v1;
					break;
				}
				break;
			}

			if ( vRank[0] < OverSaturated )
			{	v = vRank[0];	}
			else if ( vRank[1] < OverSaturated )
			{	v = vRank[1];	}
			else if ( vRank[2] < OverSaturated )
			{	v = vRank[2];	}
			else 
			{	v = vRank[3]; }			
			pDst[idx] = v;
			idx ++;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage8Frame(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, const unsigned char *Ptr5, const unsigned char *Ptr6, const unsigned char *Ptr7, const unsigned char *Ptr8, unsigned char *&pDst)//合併8張灰階影像
{
	const char fnName[] = "CImageAPI::MergeGrayImage8Frame";
	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4) == false ) 
	{	return false; }

	JetMemory.free_func(pDst);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->MergeGrayImage8Frame3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, Ptr5, Ptr6, Ptr7, Ptr8, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage8Frame3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *Ptr1, const unsigned char *Ptr2, const unsigned char *Ptr3, const unsigned char *Ptr4, const unsigned char *Ptr5, const unsigned char *Ptr6, const unsigned char *Ptr7, const unsigned char *Ptr8, unsigned char *pDst)//合併8張灰階影像
{
	if ( this->CheckGrayImage9(ImageW, ImageH, ImageStep, Ptr1, Ptr2, Ptr3, Ptr4, Ptr5, Ptr6, Ptr7, Ptr8, pDst) == false ) 
	{	return false; }

	size_t i=0, j=0, idx=0;	
	size_t iMax=0, iMin=0;
	unsigned int  val=0;
	unsigned char vRank[8]={0};
	unsigned char v1=0, v2=0, v3=0, v4=0, v5=0, v6=0, v7=0, v8=0, v=0;	
	const size_t OverSaturated = 250;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for (i=0;i<ImageH; i++ )
	{
		idx = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{			
			vRank[0] = v1  = Ptr1[idx];			
			vRank[1] = v2  = Ptr2[idx];
			vRank[2] = v3  = Ptr3[idx];
			vRank[3] = v4  = Ptr4[idx];
			vRank[4] = v5  = Ptr5[idx];			
			vRank[5] = v6  = Ptr6[idx];
			vRank[6] = v7  = Ptr7[idx];
			vRank[7] = v8  = Ptr8[idx];

			val = v1+v2+v3+v4+v5+v6+v7+v8;
			val = val/8;
			pDst[idx] = (unsigned char)(val);
			idx ++;			
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeImage2FrameByFocus(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_SIZE FocusStep, const IMAGE_PTR FocusPtr1, const IMAGE_PTR FocusPtr2, IMAGE_PTR &pDst)//合併2張影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return MergeGrayImage2FrameByFocus(ImageW, ImageH, ImageStep, Ptr1, Ptr2, FocusStep, FocusPtr1, FocusPtr2, pDst); }
	if ( 24 == BitCount ) 
	{	return MergeColorImage2FrameByFocus(ImageW, ImageH, ImageStep, Ptr1, Ptr2, FocusStep, FocusPtr1, FocusPtr2, pDst); }
	return false;		
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeImage2FrameByFocus3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_SIZE FocusStep, const IMAGE_PTR FocusPtr1, const IMAGE_PTR FocusPtr2, IMAGE_PTR pDst)//合併2張影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount ) 
	{	return MergeGrayImage2FrameByFocus3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, FocusStep, FocusPtr1, FocusPtr2, pDst); }
	if ( 24 == BitCount ) 
	{	return MergeColorImage2FrameByFocus3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, FocusStep, FocusPtr1, FocusPtr2, pDst); }
	return false;		
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage2FrameByFocus(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_SIZE FocusStep, const IMAGE_PTR FocusPtr1, const IMAGE_PTR FocusPtr2, IMAGE_PTR &pDst)//合併2張灰階影像
{
	const char fnName[] = "CImageAPI::MergeGrayImage2FrameByFocus";	
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, Ptr1, Ptr2) == false )
	{	return false; }		
	if ( this->CheckGrayImage2(ImageW, ImageH, FocusStep, FocusPtr1, FocusPtr2) == false )
	{	return false; }

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->MergeGrayImage2FrameByFocus3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, FocusStep, FocusPtr1, FocusPtr2, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::MergeGrayImage2FrameByFocus3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_SIZE FocusStep, const IMAGE_PTR FocusPtr1, const IMAGE_PTR FocusPtr2, IMAGE_PTR pDst)//合併2張灰階影像
{	
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, pDst) == false )
	{	return false; }		
	if ( this->CheckGrayImage2(ImageW, ImageH, FocusStep, FocusPtr1, FocusPtr2) == false )
	{	return false; }

	bool         bInter=false;
	size_t       i=0, j=0;	
	double       v1=0, v2=0, val=0;
	double       w1=0, w2=0, wSum=0;
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);

	if ( ImageStep == FocusStep )
	{
		for ( i=0; i<BufferSize; i++ )
		{
			v1 = Ptr1[i];
			v2 = Ptr2[i];
			w1 = FocusPtr1[i];
			w2 = FocusPtr2[i];
			wSum = w1+w2;
			if ( wSum > 0.00001 )
			{	
				w1 /= wSum;	w2 /= wSum;	
				if ( fabs(w1-w2) < 0.3 )
				{	bInter = true;	}
				else if ( w2 > w1 )
				{	w1 = 0.0; w2 = 1.0; }
				else
				{	w1 = 1.0; w2 = 0.0; }			
			}
			else
			{	w1 = 1.0;	w2 = 0.0; }			
			val = ((v1*w1)+(v2*w2));
			pDst[i] = static_cast<IMAGE_DATA>(val);
		}
	}
	else
	{
		size_t srcIdx=0, mskIdx=0;
		for ( i=0; i<ImageH; i++ )
		{
			mskIdx = i*FocusStep;
			srcIdx = i*ImageStep;			
			for ( j=0; j<ImageW; j++ )
			{				
				v1 = Ptr1[srcIdx];
				v2 = Ptr2[srcIdx];
				w1 = FocusPtr1[mskIdx];
				w2 = FocusPtr2[mskIdx];
				wSum = w1+w2;
				if ( wSum > 0.00001 )
				{	
					w1 /= wSum;	w2 /= wSum;	
					if ( fabs(w1-w2) < 0.3 )
					{	bInter = true;	}
					else if ( w2 > w1 )
					{	w1 = 0.0; w2 = 1.0; }
					else
					{	w1 = 1.0; w2 = 0.0; }			
				}
				else
				{	w1 = 1.0;	w2 = 0.0; }
				val = ((v1*w1)+(v2*w2));
				pDst[srcIdx] = static_cast<IMAGE_DATA>(val);

				mskIdx ++;
				srcIdx ++;
			}
		}
	}	
	return true;
}
