bool CImageAPI::PyramidDownImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const unsigned char *pImage, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//圖像金字塔變小
{	
	const char fnName[] = "CImageAPI::PyramidDownImage";
	if ( this->CheckImage(ImageW, ImageH, ImageStep, BitCount, pImage) == false ) 
	{	return false; }
#ifndef OPENCV_DISABLE
	try
	{
		DstW = Floor((ImageW+1)/2);
		DstH = Floor((ImageH+1)/2);
		if ( CheckImageSize(DstW, DstH) == false )
		{	return false; }
		DstStep = GetImageAlignedWidth(DstW, BitCount, 4);
		const size_t DstSize=CalcBufferSize(DstStep, DstH);
		JetMemory.free_func(pDst);
		if ( JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false )
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		cv::Mat MatDst=CreateMat(DstW, DstH, DstStep, BitCount, pDst);
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, BitCount, pImage);		
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	
			JetMemory.free_func(pDst);
			return false; 
		}
		cv::pyrDown(MatSrc, MatDst);	
		if ( CloneMatData(MatDst, DstW, DstH, DstStep, BitCount, pDst)==false)
		{
			JetMemory.free_func(pDst);
			return false; 
		}
		return true;
	}
	catch ( cv::Exception& e )
	{	
		JetMemory.free_func(pDst);
		CatchOpenCVException(e);		
		return false;
	}	
#endif//OPENCV_DISABLE	
	return ReturnOpenCVDisableException();
	return true;
}
