bool CImageAPI::PyramidUpSpace(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, SPACE_PTR &pDst, bool UsingOpenCV)//空間金字塔變大
{
	const char fnName[] = "CImageAPI::PyramidUpSpace";
	if (this->CheckImage(SpaceW, SpaceH, SpaceStep, 8, pSpace) == false)
	{
		return false;
	}
	if (UsingOpenCV)
	{
#ifndef OPENCV_DISABLE
		try
		{
			DstW = SpaceW * 2;
			DstH = SpaceH * 2;
			if (CheckImageSize(DstW, DstH) == false)
			{
				return false;
			}
			DstStep = GetImageAlignedWidth(DstW, 8, 4);
			const size_t DstSize = CalcBufferSize(DstStep, DstH);
			JetMemory.free_func(pDst);
			if (JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false)
			{
				SetErrorString(JetMemory.GetErrorString());
				return false;
			}
			cv::Mat MatDst = CreateMat(DstW, DstH, DstStep, 8, pDst);
			cv::Mat MatSrc = CreateMat(SpaceW, SpaceH, SpaceStep, 8, pSpace);
			if (CheckMatIsValid(MatSrc) == false || CheckMatIsValid(MatDst) == false)
			{
				JetMemory.free_func(pDst);
				return false;
			}
			cv::pyrUp(MatSrc, MatDst);
			if (CloneMatData(MatDst, DstW, DstH, DstStep, 8, pDst) == false)
			{
				JetMemory.free_func(pDst);
				return false;
			}
			return true;
		}
		catch (cv::Exception& e)
		{
			JetMemory.free_func(pDst);
			CatchOpenCVException(e);
			return false;
		}
#endif//OPENCV_DISABLE	
		return ReturnOpenCVDisableException();
	}
	else
	{
		DstW = SpaceW * 2;
		DstH = SpaceH * 2;
		if (CheckImageSize(DstW, DstH) == false)
		{
			return false;
		}
		DstStep = DstW;
		const size_t DstSize = CalcBufferSize(DstStep, DstH);
		JetMemory.free_func(pDst);
		if (JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false)
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		size_t idx_Dst = 0;
		size_t coordinateLU = 0;
		size_t coordinateRU = 0;
		size_t coordinateLD = 0;
		size_t coordinateRD = 0;
		for (int y = 0; y < SpaceH; y++)
		{
			for (int x = 0; x < SpaceW; x++)
			{
				coordinateLU = x + y * SpaceStep;
				coordinateRU = x < SpaceW ? (x + 1) + y * SpaceStep : coordinateLU;
				coordinateLD = y < SpaceH ? x + (y + 1) * SpaceStep : coordinateLU;
				if(x < SpaceW && y < SpaceH)
					coordinateRD = (x + 1) + (y + 1) * SpaceStep;
				else
				{
					if (x < SpaceW)
						coordinateRD = coordinateRU;
					else if (y < SpaceH)
						coordinateRD = coordinateLD;
				}

				idx_Dst = (x * 2) + (y * 2) * DstStep;
				pDst[idx_Dst] = pSpace[coordinateLU];
				pDst[idx_Dst + 1] = (pSpace[coordinateLU] + pSpace[coordinateRU]) / 2;
				pDst[idx_Dst + DstStep] = (pSpace[coordinateLU] + pSpace[coordinateLD]) / 2;
				pDst[idx_Dst + DstStep + 1] = (pSpace[coordinateLU] + pSpace[coordinateRU] + pSpace[coordinateRD]) / 3;
			}
		}
		return true;
	}
}
bool CImageAPI::PyramidDownSpace(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR pSpace, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, SPACE_PTR &pDst, bool UsingOpenCV)//圖像金字塔變小
{
	const char fnName[] = "CImageAPI::PyramidDownSpace";
	if (this->CheckImage(SpaceW, SpaceH, SpaceStep, 8, pSpace) == false)
	{
		return false;
	}
	if (UsingOpenCV)
	{
#ifndef OPENCV_DISABLE
		try
		{
			DstW = Floor((SpaceW + 1) / 2);
			DstH = Floor((SpaceH + 1) / 2);
			if (CheckImageSize(DstW, DstH) == false)
			{
				return false;
			}
			DstStep = GetImageAlignedWidth(DstW, 8, 4);
			//DstStep = DstW;
			const size_t DstSize = CalcBufferSize(DstStep, DstH);
			JetMemory.free_func(pDst);
			if (JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false)
			{
				SetErrorString(JetMemory.GetErrorString());
				return false;
			}
			cv::Mat MatDst = CreateMat(DstW, DstH, DstStep, 8, pDst);
			cv::Mat MatSrc = CreateMat(SpaceW, SpaceH, SpaceStep, 8, pSpace);
			if (CheckMatIsValid(MatSrc) == false || CheckMatIsValid(MatDst) == false)
			{
				JetMemory.free_func(pDst);
				return false;
			}
			cv::pyrDown(MatSrc, MatDst);
			if (CloneMatData(MatDst, DstW, DstH, DstStep, 8, pDst) == false)
			{
				JetMemory.free_func(pDst);
				return false;
			}
			return true;
		}
		catch (cv::Exception& e)
		{
			JetMemory.free_func(pDst);
			CatchOpenCVException(e);
			return false;
		}
#endif//OPENCV_DISABLE	
		return ReturnOpenCVDisableException();
		return true;
	}
	else
	{
		DstW = Floor((SpaceW + 1) / 2);
		DstH = Floor((SpaceH + 1) / 2);
		if (CheckImageSize(DstW, DstH) == false)
		{
			return false;
		}
		DstStep = DstW;
		const size_t DstSize = CalcBufferSize(DstStep, DstH);
		if (pDst != NULL) JetMemory.free_func(pDst);
		if (JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false)
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		size_t ImageX = 0;
		size_t ImageY = 0;
		for (int i = 0; i < DstSize; i++)
		{
			ImageX = i >= DstW ? i % DstW * 2 : i * 2;
			ImageY = i / DstStep * 2;
			pDst[i] = pSpace[ImageX + ImageY * SpaceStep];
		}
		return true;
	}
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::PyramidDownSpace(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR pSpace, const MASK_PTR pMask, const MASK_PTR pMaskC, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, SPACE_PTR &pDst, MASK_PTR &pDstM, MASK_PTR &pDstMC)//空間金字塔變小 - Joe, 20191024
{
	const char fnName[] = "CImageAPI::PyramidDownSpace";
	if (this->CheckImage(SpaceW, SpaceH, SpaceStep, 8, pSpace) == false)
	{
		return false;
	}

	DstW = Floor((SpaceW + 1) / 2);
	DstH = Floor((SpaceH + 1) / 2);
	if (CheckImageSize(DstW, DstH) == false)
	{
		return false;
	}
	DstStep = DstW;
	const size_t DstSize = CalcBufferSize(DstStep, DstH);
	JetMemory.free_func(pDst);
	JetMemory.free_func(pDstM);
	JetMemory.free_func(pDstMC);
	if (JetMemory.alloc_func(DstSize, pDst, fnName, "pDst") == false ||
		JetMemory.alloc_func(DstSize, pDstM, fnName, "pDstM") == false ||
		JetMemory.alloc_func(DstSize, pDstMC, fnName, "pDstMC") == false)
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	size_t ImageX = 0;
	size_t ImageY = 0;
	size_t coordinate_1 = 0, coordinate_2 = 0, coordinate_3 = 0, coordinate_4 = 0;
	int SampleSize = 2;
	for (int i = 0; i < DstSize; i++)
	{
		ImageX = i >= DstW ? i % DstW * SampleSize : i * SampleSize;
		ImageY = i / DstStep * SampleSize;

		coordinate_1 = ImageX + ImageY * SpaceStep;
		coordinate_2 = (ImageX + 1) < DstW ? (ImageX + 1) + ImageY * SpaceStep : 0;
		coordinate_3 = (ImageY + 1) < DstH ? ImageX + (ImageY + 1) * SpaceStep : 0;
		coordinate_4 = ((ImageX + 1) < DstW && (ImageY + 1) < DstH) ? (ImageX + 1) + (ImageY + 1) * SpaceStep : 0;

		if (pMask[coordinate_1] == PHASE_MASK_VALID_BEST) { pDst[i] = pSpace[coordinate_1];	pDstM[i] = pMask[coordinate_1];	pDstMC[i] = pMaskC[coordinate_1]; continue; }
		if (coordinate_2 > 0 && pMask[coordinate_2] == PHASE_MASK_VALID_BEST) { pDst[i] = pSpace[coordinate_2]; pDstM[i] = pMask[coordinate_2];	pDstMC[i] = pMaskC[coordinate_2]; continue; }
		if (coordinate_3 > 0 && pMask[coordinate_3] == PHASE_MASK_VALID_BEST) { pDst[i] = pSpace[coordinate_3]; pDstM[i] = pMask[coordinate_3];	pDstMC[i] = pMaskC[coordinate_3]; continue; }
		if (coordinate_4 > 0 && pMask[coordinate_4] == PHASE_MASK_VALID_BEST) { pDst[i] = pSpace[coordinate_4]; pDstM[i] = pMask[coordinate_4];	pDstMC[i] = pMaskC[coordinate_4]; continue; }

		pDst[i] = pSpace[coordinate_1];
		pDstM[i] = pMask[coordinate_1];
		pDstMC[i] = pMaskC[coordinate_1];
	}
	return true;
}
