bool CImageAPI::BuildSpaceObjectList(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, int KenSize, std::vector<RECT> &ObjList, std::vector<float> &ObjHList)
{
	const char fnName[] = "CImageAPI::BuildSpaceObjectList";

	ObjList.clear();
	ObjHList.clear();	
	
	float Threshold=0;
	RECT  ModelRect={0};	
	JetAPI::SizeToRect(SpaceW, SpaceH, ModelRect);
	if ( CalcSpaceImageOTSUThreshold(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, ModelRect, Threshold) == false )
	{	return false; }

	//CString      str;	
	size_t       i=0, j=0;
	MASK_PTR     BinPtr=NULL;
	IMAGE_SIZE   BitCount = 8;
	const size_t BufferSize=CalcBufferSize(SpaceStep, SpaceH);
	//CString      strFolder = AOIDataCollect.GetAOITempDirectory();
	if ( JetMemory.alloc_func(BufferSize, BinPtr, fnName, "BinPtr") == false )
	{	return false; }
	for ( i=0; i<BufferSize; i++ )
	{
		if ( CheckSpaceMaskValid(MaskPtr[i]) == false ) 
		{	BinPtr[i] = 0;	}
		else
		{
			if ( SpacePtr[i] < Threshold ) { BinPtr[i] = 0; }
			else { BinPtr[i] = 255; }
		}
	}

	//str.Format(_T("%s\\%s"), strFolder, _T("CalcObj_Mask.PNG"));
	//SaveImage(str, SpaceW, SpaceH, SpaceStep, BitCount, MaskPtr, true);

	//str.Format(_T("%s\\%s"), strFolder, _T("CalcObj_Binary.PNG"));
	//SaveImage(str, SpaceW, SpaceH, SpaceStep, BitCount, BinPtr, true);
	
	if ( KenSize > 1 )
	{		
		MASK_PTR  TempPtr=NULL;
		const int IterCount = 1;		
		const int MorphMode = MORPH_OPEN;
		const int ShpaeMode = MORPH_SHAPE_RECT;

		KenSize /= 2; 
		KenSize *= 2;
		KenSize += 1;
		if ( ErodeImage(SpaceW, SpaceH, SpaceStep, BitCount, BinPtr, KenSize, IterCount, TempPtr) == false )		
		{
			JetMemory.free_func(BinPtr);
			return false; 
		}
		JetMemory.free_func(BinPtr);
		BinPtr = TempPtr;

		//str.Format(_T("%s\\%s"), strFolder, _T("CalcObj_Binary.PNG"));
		//SaveImage(str, SpaceW, SpaceH, SpaceStep, BitCount, BinPtr, true);
	}	

	CJetBlob BlobDetector;
	BlobDetector.InitialBlob();
	BlobDetector.SetBlobSortMode(BLOB_SORT_PIXELS);
	BlobDetector.SetBlobConnectivity(BLOB_CONNECTIVITY_4);	
	if ( BlobDetector.GrayImageRoiBlobDetect(SpaceW, SpaceH, SpaceStep, BinPtr, ModelRect, 128, 255) == false )
	{	
		JetMemory.free_func(BinPtr);
		return false; 
	}

	TBlobResult *BlobPtr=NULL;
	const size_t BlobCount = BlobDetector.GetBlobCount();
	for ( j=0; j<BlobCount; j++ )
	{
		BlobPtr=BlobDetector.GetBlobPtr(j, false);
		if ( NULL == BlobPtr ) { continue; }
		if ( BlobDetector.GetBlobImage(BlobPtr, SpaceW, SpaceH, SpaceStep, BitCount, BinPtr) == false )
		{	continue;	}

		//str.Format(_T("%s\\%s#%02d.PNG"), strFolder, _T("CalcObj_Blob"), j+1);
		//SaveImage(str, SpaceW, SpaceH, SpaceStep, BitCount, BinPtr, true);

		int    Cnt = 0;
		double H = 0.0;
		double Sum=0.0;
		for ( i=0; i<BufferSize; i++ )
		{
			if ( BinPtr[i] < 128 ) { continue; }
			Cnt ++;
			H = SpacePtr[i];		
			Sum += H;
		}
		if ( Cnt > 0 )
		{	Sum /= Cnt; }
		ObjList.push_back(BlobPtr->m_BlobRect);
		ObjHList.push_back(static_cast<float>(Sum));		
	}
	JetMemory.free_func(BinPtr);	
	return true;
}
