bool CImageAPI::BuildFocusPixelImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR ImagePtr, int BlurSize, int RoiSize, IMAGE_PTR &DstPtr)	
{
	const char fnName[] = "CImageAPI::BuildFocusPixelImage";
	if ( CheckGrayImage(ImageW, ImageH, ImageStep, ImagePtr) == false ) { return false; }
	if ( 24 == BitCount )
	{	return false;	}
	JetMemory.free_func(DstPtr);		
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( BuildFocusPixelImage3(ImageW, ImageH, ImageStep, BitCount, ImagePtr, BlurSize, RoiSize, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildFocusPixelImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR ImagePtr, int BlurSize, int RoiSize, IMAGE_PTR DstPtr)
{	
	const char fnName[] = "CImageAPI::BuildFocusPixelImage3";
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, ImagePtr, DstPtr) == false ) { return false; }
	if ( 24 == BitCount )
	{	return false;	}

	size_t    i=0;
	IMAGE_PTR BlurPtr=NULL;	
	IMAGE_PTR DiffPtr=NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, BlurPtr, fnName, "BlurPtr") == false || 
		 JetMemory.alloc_func(BufferSize, DiffPtr, fnName, "DiffPtr") == false  )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(BlurPtr);
		JetMemory.free_func(DiffPtr);		
		return false;
	}

	if ( BlurSize > 1 )
	{	
		if ( GaussianImage3(ImageW, ImageH, ImageStep, BitCount, ImagePtr, BlurSize, BlurPtr) == false)
		{
			JetMemory.free_func(BlurPtr);
			JetMemory.free_func(DiffPtr);
			return false;
		}
	}
	else
	{	::memcpy(BlurPtr, ImagePtr, sizeof(IMAGE_DATA)*BufferSize);	}
	
	for ( i=0; i<BufferSize; i++ )
	{
		int v1 = BlurPtr[i];
		int v2 = ImagePtr[i];		
		int vd = v1-v2;
		if ( vd < 0 ) { vd = -vd; }
		DiffPtr[i] = static_cast<IMAGE_DATA>(vd);
	}
	
	if ( RoiSize > 1 )
	{
		if ( SmoothImage3(ImageW, ImageH, ImageStep, BitCount, DiffPtr, RoiSize, DstPtr) == false)
		{
			JetMemory.free_func(BlurPtr);
			JetMemory.free_func(DiffPtr);
			return false;
		}
	}
	else
	{	::memcpy(DstPtr, DiffPtr, sizeof(IMAGE_DATA)*BufferSize);	}	
	JetMemory.free_func(BlurPtr);
	JetMemory.free_func(DiffPtr);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2FocusPixelImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_DATA v1, IMAGE_DATA v2, IMAGE_PTR &DstPtr)
{
	const char fnName[] = "CImageAPI::Compare2FocusPixelImage";
	if ( CheckGrayImage2(ImageW, ImageH, ImageStep, Ptr1, Ptr2) == false ) { return false; }
	if ( 24 == BitCount )
	{	return false;	}
	JetMemory.free_func(DstPtr);		
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( Compare2FocusPixelImage3(ImageW, ImageH, ImageStep, BitCount, Ptr1, Ptr2, v1, v2, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::Compare2FocusPixelImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, const IMAGE_PTR Ptr1, const IMAGE_PTR Ptr2, IMAGE_DATA v1, IMAGE_DATA v2, IMAGE_PTR DstPtr)
{	
	if ( CheckGrayImage3(ImageW, ImageH, ImageStep, Ptr1, Ptr2, DstPtr) == false ) { return false; }
	if ( 24 == BitCount )
	{	return false;	}

	size_t    i=0;
	IMAGE_PTR BlurPtr=NULL;	
	IMAGE_PTR DiffPtr=NULL;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	for ( i=0; i<BufferSize; i++ )
	{
		if ( Ptr2[i] > Ptr1[i] ) { DstPtr[i] = v2; }
		else { DstPtr[i] = v1; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BlendImage(IMAGE_SIZE W1, IMAGE_SIZE H1, IMAGE_SIZE Step1, IMAGE_SIZE Bit1, const unsigned char *Ptr1, IMAGE_SIZE W2, IMAGE_SIZE H2, IMAGE_SIZE Step2, IMAGE_SIZE Bit2, const unsigned char *Ptr2, IMAGE_SIZE Wm, IMAGE_SIZE Hm, IMAGE_SIZE Stepm, const unsigned char *PtrM, const RECT &Roi, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//兩張影像混色
{
	if ( Bit1 != Bit2 )
	{
		this->m_ErrorString.Format(_T("Error, Bit Count Exception (%d, %d)"), Bit1, Bit2);
		return false;
	}
	IMAGE_SIZE BitCount = Bit1;
	if ( CImageAPI::CheckBitCount(BitCount) == false ) 
	{	return false; }
	if ( 8 == BitCount )
	{	return CImageAPI::BlendGrayImage(W1, H1, Step1, Ptr1, W2, H2, Step2, Ptr2, Wm, Hm, Stepm, PtrM, Roi, DstW, DstH, DstStep, pDst);	}
	else if ( 24 == BitCount )
	{	return CImageAPI::BlendColorImage(W1, H1, Step1, Ptr1, W2, H2, Step2, Ptr2, Wm, Hm, Stepm, PtrM, Roi, DstW, DstH, DstStep, pDst);	}	
	return false;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BlendGrayImage(IMAGE_SIZE W1, IMAGE_SIZE H1, IMAGE_SIZE Step1, const unsigned char *Ptr1, IMAGE_SIZE W2, IMAGE_SIZE H2, IMAGE_SIZE Step2, const unsigned char *Ptr2, IMAGE_SIZE Wm, IMAGE_SIZE Hm, IMAGE_SIZE Stepm, const unsigned char *PtrM, const RECT &Roi, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//兩張影像混色
{
	const char fnName[] = "CImageAPI::BlendGrayImage";
	if ( this->CheckGrayImage(W1, H1, Step1, Ptr1) == false ) 
	{	return false; }
	if ( this->CheckGrayImage(W2, H2, Step2, Ptr2) == false ) 
	{	return false; }
	if ( this->CheckGrayImage(Wm, Hm, Stepm, PtrM) == false ) 
	{	return false; }
	if ( this->CheckRoiRect(W1, H1, Roi) == false )
	{	return false; }
	if ( this->CheckRoiRect(W2, H2, Roi) == false )
	{	return false; }
	if ( this->CheckRoiRect(Wm, Hm, Roi) == false )
	{	return false; }

	int i=0, j=0;
	float w1=1.0f, w2=1.0f;
	int idx1=0, idx2=0, idxM=0, idxD=0;	
	const int TmpW=Roi.right-Roi.left;
	const int TmpH=Roi.bottom-Roi.top;
	const int TmpStep=GetImageAlignedWidth(TmpW, 8, 4);
	const size_t TempSize=CalcBufferSize(TmpStep, TmpH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(TempSize, pDst, fnName, "pDst") == false )
	{	return false;	}
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idxD = (i-Roi.top)*TmpStep;
		idx1 = (i*Step1)+(Roi.left);
		idx2 = (i*Step2)+(Roi.left);
		idxM = (i*Stepm)+(Roi.left);		
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			w1=PtrM[idxM]/255.0f;
			w2=1.0f-w1;
			pDst[idxD]=(w1*Ptr1[idx1])+(w2*Ptr2[idx2]);			
			idxM ++;
			idx1 ++;
			idx2 ++;
			idxD ++;
		}
	}
	DstW = TmpW;
	DstH = TmpH;
	DstStep = TmpStep;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BlendColorImage(IMAGE_SIZE W1, IMAGE_SIZE H1, IMAGE_SIZE Step1, const unsigned char *Ptr1, IMAGE_SIZE W2, IMAGE_SIZE H2, IMAGE_SIZE Step2, const unsigned char *Ptr2, IMAGE_SIZE Wm, IMAGE_SIZE Hm, IMAGE_SIZE Stepm, const unsigned char *PtrM, const RECT &Roi, IMAGE_SIZE &DstW, IMAGE_SIZE &DstH, IMAGE_SIZE &DstStep, unsigned char *&pDst)//兩張影像混色
{
	const char fnName[] = "CImageAPI::BlendColorImage";
	if ( this->CheckColorImage(W1, H1, Step1, Ptr1) == false ) 
	{	return false; }
	if ( this->CheckColorImage(W2, H2, Step2, Ptr2) == false ) 
	{	return false; }
	if ( this->CheckGrayImage(Wm, Hm, Stepm, PtrM) == false ) 
	{	return false; }
	if ( this->CheckRoiRect(W1, H1, Roi) == false )
	{	return false; }
	if ( this->CheckRoiRect(W2, H2, Roi) == false )
	{	return false; }
	if ( this->CheckRoiRect(Wm, Hm, Roi) == false )
	{	return false; }

	int i=0, j=0;
	float w1=1.0f, w2=1.0f;
	int idx1=0, idx2=0, idxM=0, idxD=0;	
	const int TmpW=Roi.right-Roi.left;
	const int TmpH=Roi.bottom-Roi.top;
	const int TmpStep=GetImageAlignedWidth(TmpW, 24, 4);
	const size_t TempSize=CalcBufferSize(TmpStep, TmpH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(TempSize, pDst, fnName, "pDst") == false )
	{	return false;	}
	for ( i=Roi.top; i<Roi.bottom; i++ )
	{
		idxD = (i-Roi.top)*TmpStep;
		idx1 = (i*Step1)+(Roi.left*3);
		idx2 = (i*Step2)+(Roi.left*3);
		idxM = (i*Stepm)+(Roi.left);		
		for ( j=Roi.left; j<Roi.right; j++ )
		{
			w1=PtrM[idxM]/255.0f;
			w2=1.0f-w1;
			pDst[idxD]=(w1*Ptr1[idx1])+(w2*Ptr2[idx2]);
			pDst[idxD+1]=(w1*Ptr1[idx1+1])+(w2*Ptr2[idx2+1]);
			pDst[idxD+2]=(w1*Ptr1[idx1+2])+(w2*Ptr2[idx2+2]);
			idxM ++;
			idx1 +=3;
			idx2 +=3;
			idxD +=3;
		}
	}
	DstW = TmpW;
	DstH = TmpH;
	DstStep = TmpStep;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageCreateCosPattern(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *&pImage, int NPixelPeriod, double PhaseShift, bool bVer)//建立灰階sin樣板圖像
{
	const char fnName[] = "CImageAPI::GrayImageCreateCosPattern";
	if ( this->CheckGraySize(ImageW, ImageH, ImageStep) == false ) 
	{	return false; }

	JetMemory.free_func(pImage);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, pImage, fnName, "pImage") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	if ( this->GrayImageCreateCosPattern3(ImageW, ImageH, ImageStep, pImage, NPixelPeriod, PhaseShift, bVer) == false )
	{
		JetMemory.free_func(pImage);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageCreateCosPattern3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, int NPixelPeriod, double PhaseShift, bool bVer)//建立灰階sin樣板圖像
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false ) 
	{	return false; }

	//每個一個像素代表360/256度
	//NPixelPeriod::周期, 多少像素為一個週期
	//PhaseShift::像位偏移, 表示起始的相位
	const int MinPixelPeriod =    8;
	const int MaxPixelPeriod = 1024;
	if ( NPixelPeriod<MinPixelPeriod || NPixelPeriod>MaxPixelPeriod )
	{
		this->m_ErrorString.Format(_T("Error, Pixels Periode Exception (%d ~ %d)"), MinPixelPeriod, MaxPixelPeriod);
		return false; 
	}

	unsigned char PatternBuffer[MaxPixelPeriod]={0};	
	int    Gray = 0;
	unsigned int i=0, j=0, idx=0, PatternIdx=0;
	double GrayDbl=0;
	double Phase_DegUnit = 360.0/NPixelPeriod;//每個像素為3度
	double Phase_Deg=0;
	double Phase_Rad=0;
	const bool   bCosMode=true;
	const int    PERIODE_UNSIGNED_CHAR = 256;
	const double DEG_TO_UNSIGNED_CHAR = 256.0/360.0;
	const double DEG_STEP = Phase_DegUnit;

	for ( i=0; i<NPixelPeriod; i++ )
	{
		Phase_Deg = (i*DEG_STEP)+PhaseShift;
		Phase_Rad = Phase_Deg*DEG_TO_RAD_DBL;
		if ( true == bCosMode )
		{	GrayDbl = ::cos(Phase_Rad);	}
		else
		{	GrayDbl = ::sin(Phase_Rad);	}
		//-1 ~ 1, signed char = -127 ~ 127
		GrayDbl += 1.0;//移至0 ~ 2, unsigned char = 0 ~ 255			
		Gray = (int)(GrayDbl*255/2.0);
		PatternBuffer[i] = static_cast<unsigned char>(Gray);
	}

	if ( true == bVer )
	{
		for ( i=0; i<ImageH; i++ )
		{
			idx = i*ImageStep;
			for ( j=0; j<ImageW; j++ )
			{			
				PatternIdx = j%NPixelPeriod;			
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
			}
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			idx = i*ImageStep;
			PatternIdx = i%NPixelPeriod;			
			for ( j=0; j<ImageW; j++ )
			{
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
			}
		}
	}
	return true;
}
