//-------------------------------------------------------------------------------------//
bool CImageAPI::GrayImageCreateSinPatternII3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, int NPixelPeriod, double PhaseShift, bool bVer)//建立灰階sin樣板圖像
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false ) 
	{	return false; }

	int DLP_Width = (int)(ImageW);
	int DLP_Height = (int)(ImageH);
	int size = DLP_Width*DLP_Height;	
	const int CyclePixels = NPixelPeriod;
	const double DEG2RAD = DEG_TO_RAD_DBL;
	int *CycleData = new int[CyclePixels];

	int Data_Max = 255;

	double PhaseDelta_deg = 360.0/(double)CyclePixels;

	double PhaseDelta_rad = PhaseDelta_deg*DEG2RAD;
	double Phase_rad = 0.0;
	double Start_deg = 0;
	double Start_rad = 0;
	int PixelData = 0;
	int i=0, j=0, k=0, p=0;
	
	int CycleIndex = 0;
	int DestData = 0;
	unsigned char *pDestImage = NULL;
	double PhaseDegList[4] = { 90.0,0.0,270.0,180.0};
	Start_deg=90;

	//Start_deg = p*90;
	Start_deg = PhaseDegList[p];		//chia aoi 1070713

	Start_deg = PhaseShift;	
	//Start_rad = Start_deg*DEG2RAD;
	for( k=0 ; k<CyclePixels ; k++ )
	{
		//Phase_rad = Start_rad+k*PhaseDelta_rad;
		//PixelData = Data_Max*(sin(Phase_rad)+1)*0.5+0.5;	//sin -1~+1 ==> 0~1

		//PixelData = 128+127*(sin((Start_deg+k*PhaseDelta_deg)*DEG2RAD))+0.5;
		PixelData = 127+128*(sin((Start_deg+k*PhaseDelta_deg)*DEG2RAD))+0.5;
		CycleData[k] = PixelData;
	}

	pDestImage = pImage;
	if( false == bVer )
	{
		CycleIndex = 0;
		for( i=0 ; i<DLP_Height ; i++ )
		{
			PixelData = CycleData[CycleIndex++];
			if( CycleIndex >= CyclePixels ) { CycleIndex = 0; }
			DestData = PixelData;
			::memset(pDestImage, DestData, sizeof(unsigned char)*DLP_Width);
			pDestImage = pDestImage+ImageStep;
		}
	}
	else
	{	
		for( i=0 ; i<DLP_Height ; i++ )
		{
			CycleIndex = 0;
			for( j=0 ; j<DLP_Width ; j++ )
			{
				PixelData = CycleData[CycleIndex++];
				if( CycleIndex >= CyclePixels ) { CycleIndex = 0; }
				DestData = PixelData;
				*pDestImage = DestData;
				pDestImage = pDestImage+1;
			}
			for ( j=DLP_Width; j<ImageStep; j++ )
			{	pDestImage++; }
		}
	}
	delete []CycleData; CycleData=NULL;	
	return true;
}
