bool CImageAPI::ColorImageCreateSinPattern3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, int NPixelPeriod, double PhaseShift, bool bVer)//建立彩色sin樣板圖像
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false ) 
	{	return false; }

	//每個一個像素代表360/256度
	//NPixelPeriod::周期, 多少像素為一個週期
	//PhaseShift::像位偏移, 表示起始的相位
	const int MinPixelPeriod =   8;
	const int MaxPixelPeriod = 128;
	if ( NPixelPeriod<MinPixelPeriod || NPixelPeriod>MaxPixelPeriod )
	{
		this->m_ErrorString.Format(_T("Error, Pixels Periode Exception (%d ~ %d)"), MinPixelPeriod, MaxPixelPeriod);
		return false; 
	}

	unsigned char PatternBuffer[MaxPixelPeriod]={0};	
	int    Gray = 0;
	unsigned int i=0, j=0, idx=0, PatternIdx=0;
	double GrayDbl=0;
	double Phase_DegUnit = 360.0/NPixelPeriod;//每個像素為3度
	double Phase_Deg=0;
	double Phase_Rad=0;
//	const int    PERIODE_UNSIGNED_CHAR = 256;
//	const double DEG_TO_UNSIGNED_CHAR = 256.0/360.0;
	const double DEG_STEP = Phase_DegUnit;

	for ( i=0; i<NPixelPeriod; i++ )
	{
		Phase_Deg = (i*DEG_STEP)+PhaseShift;
		Phase_Rad = Phase_Deg*DEG_TO_RAD_DBL;
		GrayDbl = ::sin(Phase_Rad);//-1 ~ 1, signed char = -127 ~ 127
		GrayDbl += 1.0;//移至0 ~ 2, unsigned char = 0 ~ 255			
		Gray = (int)(GrayDbl*255/2.0);
		PatternBuffer[i] = static_cast<unsigned char>(Gray);
	}

	if ( true == bVer )
	{
		for ( i=0; i<ImageH; i++ )
		{
			idx = i*ImageStep;
			for ( j=0; j<ImageW; j++ )
			{			
				PatternIdx = j%NPixelPeriod;			
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
			}
		}
	}
	else
	{
		for ( i=0; i<ImageH; i++ )
		{
			idx = i*ImageStep;
			PatternIdx = i%NPixelPeriod;
			for ( j=0; j<ImageW; j++ )
			{
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
				pImage[idx] = PatternBuffer[PatternIdx];
				idx ++;
			}
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
unsigned int CImageAPI::DecimaltoGrayCode(unsigned int x)//10進位轉GrayCode
{	//根據二進位制轉換成格雷碼的法則，可以得到以下的程式碼：
	//二進位:B3B2B1B0
	//GrayCode:G3G2G1G0
	//最高位保留:G3=B3
	//其餘位元Gi=(Bi+1) + (Bi)
	//G2=B3 + B2
	//G1=B2 + B1
	//G0=B1 + B0
	return x^(x>>1);
}
//-------------------------------------------------------------------------------------//
unsigned int CImageAPI::GrayCodetoDecimal(unsigned int x)//GrayCode轉10進位
{	//根據二進位制格雷碼轉換成自然二進位制碼的法則，可以得到以下的方式
	//二進位:B3B2B1B0
	//GrayCode:G3G2G1G0
	//最高位保留:B3=G3
	//其餘位元Bi-1=(Gi-1) + (Bi)
	//B2=G2 + B3
	//B1=G1 + B2
	//B0=G0 + B1
	unsigned int y = x;
	while ( x>>=1 )
	{	y ^= x;	};
	return y;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildGrayCodeMapTable(int Order, std::vector<int> &List)//取得GrayCode的映射表
{
	if ( Order < 1 ) 
	{
		m_ErrorString.Format(_T("Error, Gray Code Order Exception[%d]"), Order);
		return false;
	}

	unsigned int Value=0;
	unsigned int GrayCode=0;
	const size_t Count=(size_t)(::pow(2, Order));	
	List.resize(Count, 0);
	for ( int i=0; i<Count; i++ )
	{
		Value = GrayCodetoDecimal(GrayCode);		
		List[GrayCode] = Value;
		GrayCode ++;
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildGrayCodeMapTable(int Order, std::vector<unsigned char> &List)//取得GrayCode的映射表	
{
	if ( Order < 1 ) 
	{
		m_ErrorString.Format(_T("Error, Gray Code Order Exception[%d]"), Order);
		return false;
	}

	unsigned int Value=0;
	unsigned int GrayCode=0;
	const size_t Count=(size_t)(::pow(2, Order));	
	List.resize(Count, 0);
	for ( int i=0; i<Count; i++ )
	{
		Value = GrayCodetoDecimal(GrayCode);
		if ( Value > 0xFF ) 
		{
			m_ErrorString.Format(_T("Error, Gray Code Value Exception[%u]"), Value);
			return false; 
		}		
		List[GrayCode] = Value;
		GrayCode ++;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SwapImagePtr(IMAGE_PTR Ptr[], IMAGE_SIZE Count, bool bCheck)//指標反轉, 1->5, 2->4, 注意因部分指標為NULL, 反轉後須跳過NULL指標
{
	size_t i=0, j=0;
	const size_t MaxCount = 15;
	IMAGE_PTR TempPtr[MaxCount]={NULL};
	IMAGE_PTR SwapPtr[MaxCount]={NULL};
	if ( MaxCount < Count )
	{
		this->m_ErrorString.Format(_T("Error, SwapImagePtr Buffer Size less than used (%d/%d)"), Count, MaxCount);
		return false;
	}
	for ( i=0; i<Count; i++ )
	{	SwapPtr[i] = Ptr[Count-i-1];	}

	if ( true == bCheck )
	{
		j = 0;
		for ( i=0; i<Count; i++ )
		{
			if ( NULL == SwapPtr[i] ) { continue; }
			TempPtr[j] = SwapPtr[i];
			j++;
		}
		for ( i=0; i<Count; i++ )
		{	Ptr[i] = TempPtr[i];	}
	}
	else
	{
		for ( i=0; i<Count; i++ )
		{	Ptr[i] = SwapPtr[i];	}		
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::SwapImagePtr5(IMAGE_PTR &Ptr1, IMAGE_PTR &Ptr2, IMAGE_PTR &Ptr3, IMAGE_PTR &Ptr4, IMAGE_PTR &Ptr5, bool bCheck)//指標反轉, 1->5, 2->4, 注意因部分指標為NULL, 反轉後須跳過NULL指標
{
	size_t i=0, j=0;
	const size_t Count = 5;
	IMAGE_PTR Ptr[Count] = {NULL};
	IMAGE_PTR SwapPtr[Count]={Ptr5, Ptr4, Ptr3, Ptr2, Ptr1};

	if ( true == bCheck )
	{
		j = 0;
		for ( i=0; i<Count; i++ )
		{
			if ( NULL == SwapPtr[i] ) { continue; }
			Ptr[j] = SwapPtr[i];
			j++;
		}
		Ptr1 = Ptr[0];
		Ptr2 = Ptr[1];
		Ptr3 = Ptr[2];
		Ptr4 = Ptr[3];
		Ptr5 = Ptr[4];
	}
	else
	{
		Ptr1 = SwapPtr[0];
		Ptr2 = SwapPtr[1];
		Ptr3 = SwapPtr[2];
		Ptr4 = SwapPtr[3];
		Ptr5 = SwapPtr[4];
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceDataByGroundEquation(const CJetGroundEquation &GroundEquation, IMAGE_SIZE DataW, IMAGE_SIZE DataH, IMAGE_SIZE DataStep, SPACE_PTR &SpacePtr)//依照面參數建立空間資料
{
	const char fnName[] = "CImageAPI::BuildSpaceDataByGroundEquation";
	JetMemory.free_func(SpacePtr);	
	const size_t BufferSize = CalcBufferSize(DataStep, DataH);
	if ( JetMemory.alloc_func(BufferSize, SpacePtr, fnName, "SpacePtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(SpacePtr);		
		return false;
	}

	if ( BuildSpaceDataByGroundEquation3(GroundEquation, DataW, DataH, DataStep, SpacePtr) == false )	
	{
		JetMemory.free_func(SpacePtr);		
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceDataByGroundEquation3(const CJetGroundEquation &GroundEquation, IMAGE_SIZE DataW, IMAGE_SIZE DataH, IMAGE_SIZE DataStep, SPACE_PTR SpacePtr)//依照面參數建立空間資料
{
	if ( this->CheckGrayImage(DataW, DataH, DataStep, SpacePtr) == false ) 
	{	return false; }

	int i=0, j=0, idx=0;
	double x=0, y=0, z=0;
	const int nW=(int)(DataW);
	const int nH=(int)(DataH);
	const int nStep=(int)(DataStep);

	for ( i=0; i<nH; i++ )
	{
		for ( j=0; j<nW; j++ )
		{
			x = j;
			y = i;
			z = GroundEquation.CalcGroundValue(x, y);

			idx = (i*nStep)+j;
			SpacePtr[idx] = (SPACE_DATA)(z);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildDataModel(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, SPACE_PTR SpacePtr, MASK_PTR MaskPtr, const TDataModelParam &ModelParam)//建立資料模型
{
	const char fnName[] = "CImageAPI::BuildDataModel";
	if ( CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	cv::Mat    Img;
	IplImage  *pImg = NULL;
	IMAGE_PTR  ShapeMaskPtr=NULL;
	IMAGE_PTR  PlaneMaskPtr=NULL;	
	const bool bUseMat=true;
	const IMAGE_SIZE BitCount = 8;	
	const size_t BufferSize=CalcBufferSize(SpaceStep, SpaceH);
	int        CreateMode=CREATE_OPENCV_IMAGE_NULL;
	if ( JetMemory.alloc_func(BufferSize, ShapeMaskPtr, fnName, "ShapeMaskPtr") == false ||
		 JetMemory.alloc_func(BufferSize, PlaneMaskPtr, fnName, "PlaneMaskPtr") == false )
	{	
		JetMemory.free_func(ShapeMaskPtr);
		JetMemory.free_func(PlaneMaskPtr);
		return false; 
	}	
	if ( true == bUseMat )
	{
		Img = CreateMat(SpaceW, SpaceH, SpaceStep, BitCount, ShapeMaskPtr);
		if ( CheckMatIsValid(Img) == false )
		{
			JetMemory.free_func(ShapeMaskPtr);
			JetMemory.free_func(PlaneMaskPtr);
			return false;
		}
	}
	else
	{
		if ( 24 == BitCount )
		{	pImg = ColorImageToCVImage(SpaceW, SpaceH, SpaceStep, ShapeMaskPtr, false, CreateMode);	}
		else
		{	pImg = GrayImageToCVImage(SpaceW, SpaceH, SpaceStep, ShapeMaskPtr, false, CreateMode);	}		
		if ( pImg == NULL )
		{
			JetMemory.free_func(ShapeMaskPtr);
			JetMemory.free_func(PlaneMaskPtr);
			return false;	
		}		
	}
	
	size_t i=0;
	int   Radius=0;
	int   RectW=0, RectH=0;	
	unsigned char BKClr   = 0x00;
	const int MarginW = 5;
	const int MarginH = 5;
	const unsigned char FillClr = 0xFF;			
	const unsigned char MaskClr = 0x00;
	const BOX_TOWARD BoxToward = BOX_TOWARD_NULL;	
	const int      PosX=ModelParam.PosX;
	const int      PosY=ModelParam.PosY;
	const int      SizeX=ModelParam.SizeX;
	const int      SizeY=ModelParam.SizeY;
	const double   SizeZ=ModelParam.SizeZ;
	const double   BoxShapeParam=ModelParam.ShapeParam;
	const double   BoxShapeParam2=ModelParam.ShapeParam2;
	BOX_SHAPE_MODE BoxShapeMode=ModelParam.ShapeMode;
	 
	RECT  MainRect={0,0,0,0};
	RECT  MaskRect={0,0,0,0};
	
	CvScalar color;
	CvScalar bkcolor;
	
	MainRect.left   = MarginW;
	MainRect.right  = SpaceW-MarginW-1;
	MainRect.top    = MarginH;
	MainRect.bottom = SpaceH-MarginH-1;
	
	bkcolor.val[0] = BKClr;
	bkcolor.val[1] = BKClr;
	bkcolor.val[2] = BKClr;
	bkcolor.val[3] =   0;	
	::memset(ShapeMaskPtr, BKClr, sizeof(unsigned char)*BufferSize);	

	color.val[0] = FillClr;
	color.val[1] = FillClr;
	color.val[2] = FillClr;
	color.val[3] =   0;	

	MaskRect.left = PosX-(SizeX/2);
	MaskRect.top  = PosY-(SizeY/2);
	MaskRect.right = MaskRect.left+SizeX;
	MaskRect.bottom = MaskRect.top+SizeY;
	JetAPI::BoundaryRect(MainRect, MaskRect);	
	
	//因為OpenCV繪製該位置上
	//MaskRect.right = MaskRect.right + 1;
	//MaskRect.bottom = MaskRect.bottom +1;
	switch ( BoxShapeMode )
	{
	case BOX_SHAPE_ROUND_RECT:			
		Radius = CAOIBox::CalcRoundRectRectRadius(MaskRect, BoxShapeParam);
		if ( true == bUseMat )
		{	DrawBoxImage_RroundRect(Img, color, bkcolor, BoxToward, MaskRect, Radius);	}
		else
		{	DrawBoxImage_RroundRect(pImg, color, bkcolor, BoxToward, MaskRect, Radius);	}
		break;
	case BOX_SHAPE_ELLIPSE:
		if ( true == bUseMat )
		{	DrawBoxImage_Ellipse(Img, color, bkcolor, BoxToward, MaskRect);	}
		else
		{	DrawBoxImage_Ellipse(pImg, color, bkcolor, BoxToward, MaskRect);	}						
		break;
	case BOX_SHAPE_CAPSULE:
		if ( true == bUseMat )
		{	DrawBoxImage_Capsule(Img, color, bkcolor, BoxToward, MaskRect);	}
		else
		{	DrawBoxImage_Capsule(pImg, color, bkcolor, BoxToward, MaskRect);	}
		break;
	case BOX_SHAPE_BULLET:
		if ( true == bUseMat )
		{	DrawBoxImage_Bullet(Img, color, bkcolor, BoxToward, MaskRect);	}
		else
		{	DrawBoxImage_Bullet(pImg, color, bkcolor, BoxToward, MaskRect);	}
		break;
	case BOX_SHAPE_HALF_ROUND_RECT:			
		Radius = CAOIBox::CalcHalfRoundRectRectRadius(MaskRect, BoxShapeParam, BoxToward);			
		if ( true == bUseMat )
		{	DrawBoxImage_HalfRroundRect(Img, color, bkcolor, BoxToward, MaskRect, Radius);	}
		else
		{	DrawBoxImage_HalfRroundRect(pImg, color, bkcolor, BoxToward, MaskRect, Radius);	}
		break;
	case BOX_SHAPE_T_SHAPE:
		if ( true == bUseMat )
		{	DrawBoxImage_TShapeRect(Img, color, bkcolor, BoxToward, MaskRect, BoxShapeParam, BoxShapeParam2);	}
		else
		{	DrawBoxImage_TShapeRect(pImg, color, bkcolor, BoxToward, MaskRect, BoxShapeParam, BoxShapeParam2);	}			
		break;
	default://BOX_SHAPE_RECTANGLE
		if ( true == bUseMat )
		{	DrawBoxImage_Rect(Img, color, bkcolor, BoxToward, MaskRect);	}
		else
		{	DrawBoxImage_Rect(pImg, color, bkcolor, BoxToward, MaskRect);	}
		break;
	}

	//SaveImage(_T("R:\\Dummy.PNG"), SpaceW, SpaceH, SpaceStep, BitCount, ShapeMaskPtr, true);	
	const int DataModel_Lv1 = 1;
	const int DataModel_Lv2 = 2;
	const int DataModel_Lv3 = 3;
	const int DataModel_Lv4 = 4;
	const int DataModel_Lv5 = 5;
	const int DataModel_Lv = ModelParam.DataLevel;

	bool bUseErode=false;//使用侵蝕內縮
	if ( DataModel_Lv1 != DataModel_Lv )
	{	bUseErode = true; }
	if ( true == bUseErode )
	{
		if ( true == bUseMat )
		{
			const int IterCnt = 1;
			const int KenSize = 5;
			IMAGE_PTR ErodePtr = NULL;
			if ( ErodeGrayImage(SpaceW, SpaceH, SpaceStep, ShapeMaskPtr, KenSize, IterCnt, ErodePtr) == true )
			{	::memcpy(ShapeMaskPtr, ErodePtr, sizeof(unsigned char)*BufferSize);	}
			JetMemory.free_func(ErodePtr);	
			if ( DataModel_Lv4 == DataModel_Lv )
			{
				if ( ErodeGrayImage(SpaceW, SpaceH, SpaceStep, ShapeMaskPtr, KenSize+4, IterCnt, ErodePtr) == true )
				{	::memcpy(PlaneMaskPtr, ErodePtr, sizeof(unsigned char)*BufferSize);	}
				else
				{	::memcpy(PlaneMaskPtr, ShapeMaskPtr, sizeof(unsigned char)*BufferSize);	}
				JetMemory.free_func(ErodePtr);					
			}
		}
		//SaveImage(_T("R:\\DummyErode.PNG"), SpaceW, SpaceH, SpaceStep, BitCount, ShapeMaskPtr, true);	
	}	

	size_t SpaceCnt=0;
	double SpaceAve=0.0;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( 0 == ShapeMaskPtr[i] ) { continue; }
		if ( CheckSpaceMaskValidBest(MaskPtr[i]) == false ) 
		{	continue; }
		SpaceCnt ++;
		SpaceAve += SpacePtr[i];		
	}
	if ( 0 == SpaceCnt )
	{	SpaceAve = SizeZ;	}
	else
	{	SpaceAve /= SpaceCnt;	}
	if ( DataModel_Lv1 == DataModel_Lv )//全修正
	{
		for ( i=0; i<BufferSize; i++ )
		{
			if ( 0 == ShapeMaskPtr[i] ) { continue; }			
			SpacePtr[i] = SizeZ;
			if ( CheckSpaceMaskValid(MaskPtr[i]) == false )
			{	MaskPtr[i] = PHASE_MASK_VALID;}		
		}
	}
	if ( DataModel_Lv2 == DataModel_Lv )//最佳遮罩不修正
	{
		for ( i=0; i<BufferSize; i++ )
		{
			if ( 0 == ShapeMaskPtr[i] ) { continue; }
			if ( CheckSpaceMaskValidBest(MaskPtr[i]) == true ) 
			{	continue; }

			SpacePtr[i] = SizeZ;
			if ( CheckSpaceMaskValid(MaskPtr[i]) == false )
			{	MaskPtr[i] = PHASE_MASK_VALID;}		
		}
	}
	if ( DataModel_Lv3 == DataModel_Lv )//最佳遮罩不修正, 使用平均
	{
		for ( i=0; i<BufferSize; i++ )
		{
			if ( 0 == ShapeMaskPtr[i] ) { continue; }
			if ( CheckSpaceMaskValidBest(MaskPtr[i]) == true ) 
			{	continue; }

			SpacePtr[i] = SpaceAve;
			if ( CheckSpaceMaskValid(MaskPtr[i]) == false )
			{	MaskPtr[i] = PHASE_MASK_VALID;}		
		}
	}		

	if ( DataModel_Lv4 == DataModel_Lv )//找出誤差最小切平面
	{	
		const bool bSucc=BuildDataModel_MinErrPlane(SpaceW, SpaceH, SpaceStep, PlaneMaskPtr, ShapeMaskPtr, SpacePtr, MaskPtr);		
		if ( false == bSucc )
		{
			JetMemory.free_func(PlaneMaskPtr);
			JetMemory.free_func(ShapeMaskPtr);
			return false;
		}
	}

	if ( DataModel_Lv5 == DataModel_Lv )//找出誤差最小切平面
	{	
		const bool bSucc=BuildDataModel_SurfaceFitting_Jun(SpaceW, SpaceH, SpaceStep, MaskRect, SpacePtr, MaskPtr);		
		if ( false == bSucc )
		{
			JetMemory.free_func(PlaneMaskPtr);
			JetMemory.free_func(ShapeMaskPtr);
			return false;
		}
	}

	JetMemory.free_func(PlaneMaskPtr);
	JetMemory.free_func(ShapeMaskPtr);

	//Smooth Space
	const bool bFilter=true;
	if ( true == bFilter )
	{
		const int nOpenMPCnt = 1;		
		SPACE_PTR SpacePtr2=NULL;
		IMAGE_PTR CalcMaskBuffer = NULL;
		IMAGE_PTR GuidedImagePtr = NULL;	
		if ( JetMemory.alloc_func(BufferSize, SpacePtr2, fnName, "SpacePtr2") == false ||
			 JetMemory.alloc_func(BufferSize, CalcMaskBuffer, fnName, "CalcMaskBuffer") == false )
		{
			JetMemory.free_func(SpacePtr2);
			JetMemory.free_func(CalcMaskBuffer);
		}
		else
		{
			TImageFilterParam  FilterParam;
			FilterParam.FilterMode = DATA_NF_FAST_AVERAGE;
			FilterParam.FilterSize = 5;	
			::memcpy(SpacePtr2, SpacePtr, sizeof(SPACE_DATA)*BufferSize);
			::memset(CalcMaskBuffer, 0xFF, sizeof(unsigned char)*BufferSize);
			if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpacePtr2, MaskPtr, CalcMaskBuffer, nOpenMPCnt, FilterParam, SpacePtr, GuidedImagePtr) == false )
			{
				JetMemory.free_func(SpacePtr2);
				JetMemory.free_func(CalcMaskBuffer);
				return false; 
			}
			JetMemory.free_func(SpacePtr2);
			JetMemory.free_func(CalcMaskBuffer);
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildDataModel_MinErrPlane(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const MASK_PTR PlanePtr, const MASK_PTR ShapePtr, SPACE_PTR SpacePtr, MASK_PTR MaskPtr)//建立資料模型-最小誤差平面
{
	if ( this->CheckGrayImage4(SpaceW, SpaceH, SpaceStep, PlanePtr, ShapePtr, SpacePtr, MaskPtr) == false ) 
	{	return false; }

	unsigned int i=0, j=0;
	unsigned int idx1=0, idx2=0;	
	double x=0.0, y=0.0, z=0.0;	
	double Height=0.0;
	const size_t SpaceSize=CalcBufferSize(SpaceStep, SpaceH);

	//Calc Average Height
	j = 0;
	for ( i=0; i<SpaceSize; i++ )
	{
		if ( 0 == PlanePtr[i] ) { continue; }
		if ( CheckSpaceMaskValidBest(MaskPtr[i]) == false ) 
		{	continue; }
		Height += (SpacePtr[i]);
		j ++;
	}
	if ( 0 != j )
	{	Height /= j;	}
	const float HeightLow=(float)(Height*0.50);//1/2

	CJetGroundEquation GroundEquation;
	GroundEquation.InitGroundParam(GROUND_EQUATION_PLANE);
	for ( i=0; i<SpaceH; i++ )
	{
		idx1 = i*SpaceStep;
		for ( j=0; j<SpaceW; j++ )
		{
			idx2 = idx1+j;
			//if ( (MaskPtr[idx2]&PHASE_MASK_LEVELING) == NULL ) { continue; }
			//if ( 0 == ShapePtr[idx2] ) { continue; }
			if ( 0 == PlanePtr[idx2] ) { continue; }
			//if ( CheckSpaceMaskValid(MaskPtr[idx2]) == false ) 
			//{	continue; }
			if ( CheckSpaceMaskValidBest(MaskPtr[idx2]) == false ) 
			{	continue; }
			if ( SpacePtr[idx2] < HeightLow ) { continue; }

			z = SpacePtr[idx2];
			x = j;
			y = i;
			GroundEquation.AddGroundValue(x, y, z);	
		}
	}
	GroundEquation.CalcGroundParam();

	double d=0;
	double z2=0;	
	bool   bBest=false;
	bool   bValid=false;
	const double MaxD=0;
	const double ratio1=0.50;
	const double ratio2=1.0-ratio1;
	for( i=0 ; i<SpaceH ; i++ )
	{
		y = (double)i;
		idx1 = i*SpaceStep;
		for( j=0 ; j<SpaceW ; j++ )
		{
			idx2 = idx1+j;
			if ( 0 == ShapePtr[idx2] ) { continue; }
			bValid = CheckSpaceMaskValid(MaskPtr[idx2]);
			bBest = CheckSpaceMaskValidBest(MaskPtr[idx2]);
			//if ( true==bValid && SpacePtr[idx2]<HeightLow )
			if ( true==bBest && SpacePtr[idx2]<HeightLow )
			{	continue; }

			x = (double)j;			
			z = GroundEquation.CalcGroundValue(x, y);
			z2= SpacePtr[idx2];
			d = z2-z;
			if ( fabs(z) > MaxD )
			{	SpacePtr[idx2] = z;	}
			else
			{	SpacePtr[idx2] = (float)((z*ratio1)+(z2*ratio2));	}
			
			if ( CheckSpaceMaskValid(MaskPtr[idx2]) == false )
			{	MaskPtr[idx2] = PHASE_MASK_VALID;}	
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildDataModel_SurfaceFitting_Jun(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const RECT &RoiRect, SPACE_PTR SpacePtr, MASK_PTR MaskPtr)//建立資料模型-表面擬合
{
	const char fnName[]="CImageAPI::BuildDataModel_SurfaceFitting_Jun";
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	SPACE_PTR DstPtr=NULL;
	JET::alg::SSurfaceParam sParam;
	JET::alg::SSurfaceResult sResult;	
	JET::alg::CSurfaceFitting fitting;
	const int nImageW=(int)(SpaceW);
	const int nImageH=(int)(SpaceH);
	const int nImageStep=(int)(SpaceStep);	
	const size_t BufferSize=CalcBufferSize(SpaceStep, SpaceH);	
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		return false;
	}
	sParam.bCreateSurface = true;
	const int nResult=fitting.SurfaceFitting(nImageH, nImageStep, RoiRect, SpacePtr, DstPtr, sParam, sResult);
	const bool bSucc=fitting.CheckIsExecption(nResult);
	if ( false == bSucc )
	{	m_ErrorString = _T("Error, Exec CSurfaceFitting::SurfaceFitting Fault");	}
	else
	{	
		for ( int i=RoiRect.top; i<RoiRect.bottom; i++ )
		{
			for ( int j=RoiRect.left; j<RoiRect.right; j++ )
			{
				const int idx=(i*nImageStep)+j;
				SpacePtr[idx] = DstPtr[idx];
				if ( CheckSpaceMaskValid(MaskPtr[idx]) == false )
				{	MaskPtr[idx] = PHASE_MASK_VALID;}	
			}
		}		
	}
	JetMemory.free_func(DstPtr);
	return bSucc;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceData(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const MASK_PTR Mask2DPtr, int nOpenMPCnt, TNoiseFilterParam &NoiseParam, SPACE_PTR &DstPtr, MASK_PTR &DstMaskPtr, const IMAGE_PTR GuidedImagePtr)//建立空間資料
{
	const char fnName[] = "CImageAPI::BuildSpaceData";
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	JetMemory.free_func(DstPtr);
	JetMemory.free_func(DstMaskPtr);	
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false ||
		 JetMemory.alloc_func(BufferSize, DstMaskPtr, fnName, "DstMaskPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(DstPtr);
		JetMemory.free_func(DstMaskPtr);
		return false;
	}

	if ( BuildSpaceData3(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, Mask2DPtr, nOpenMPCnt, NoiseParam, DstPtr, DstMaskPtr, GuidedImagePtr) == false )
	//if ( BuildSpaceData3_Backup(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, Mask2DPtr, nOpenMPCnt, NoiseParam, DstPtr, DstMaskPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		JetMemory.free_func(DstMaskPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceData3(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const MASK_PTR Mask2DPtr, int nOpenMPCnt, TNoiseFilterParam &NoiseParam, SPACE_PTR DstPtr, MASK_PTR DstMaskPtr, const IMAGE_PTR GuidedImagePtr)//建立空間資料
{
	bool  IsOK = true;		
	BASE_PLANE_PROC_TYPE Type = NoiseParam.BasePlaneParam.BasePlaneProcType;

	SPACE_PTR SpaceUsd=(SPACE_PTR)(SpacePtr);	
	if ( HEIGHT_DATA_CORRECT_ENABLE == NoiseParam.DataCorrectMode )
	{
		const size_t BufferSize=CalcBufferSize(SpaceStep, SpaceH);
		const char fnName[]="CImageAPI::BuildSpaceData3";
		if ( JetMemory.alloc_func(BufferSize, SpaceUsd, fnName, "SpaceUsd") == false )
		{	SpaceUsd=(SPACE_PTR)(SpacePtr);	}
		else
		{	glHeightCorrectModel.RefineMap(SpacePtr, SpaceUsd, SpaceStep, SpaceH);	}
	}	
	
	if ( BASE_PLANE_PROC_TYPE_2 == Type )
	{	IsOK = BuildSpaceData3_II(SpaceW, SpaceH, SpaceStep, SpaceUsd, MaskPtr, Mask2DPtr, nOpenMPCnt, NoiseParam, DstPtr, DstMaskPtr, GuidedImagePtr); }
	else//BASE_PLANE_PROC_TYPE_1
	{	IsOK = BuildSpaceData3_I(SpaceW, SpaceH, SpaceStep, SpaceUsd, MaskPtr, Mask2DPtr, nOpenMPCnt, NoiseParam, DstPtr, DstMaskPtr, GuidedImagePtr); }

	if ( SpaceUsd != SpacePtr )
	{	JetMemory.free_func(SpaceUsd);	}

	if ( true == IsOK )
	{
		TBasePlaneParam &BasePlaneParam=NoiseParam.BasePlaneParam;
		CJetGroundEquation &GroupEquation=BasePlaneParam.GroundEquation;
		GroupEquation.GetGroundNormal(BasePlaneParam.NormalX, BasePlaneParam.NormalY, BasePlaneParam.NormalZ);		
	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceData3_I(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const MASK_PTR Mask2DPtr, int nOpenMPCnt, TNoiseFilterParam &NoiseParam, SPACE_PTR DstPtr, MASK_PTR DstMaskPtr, const IMAGE_PTR GuidedImagePtr)//建立空間資料
{
	const char fnName[] = "CImageAPI::BuildSpaceData3_I";
	if ( this->CheckGrayImage4(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, DstPtr, DstMaskPtr) == false ) 
	{	return false; }

	//扣除Level
	CString str;	
	size_t i=0, j=0, k=0, idx=0;	
	size_t ImageX=0, ImageY=0;	
	LARGE_INTEGER   nStartTime;
	LARGE_INTEGER   nEndTime;
	MASK_PTR   MaskBuffer = NULL;	
	MASK_PTR   MaskBuffer2 = NULL;	
	MASK_PTR   CalcMaskBuffer = NULL;
	SPACE_PTR  SpaceBuffer = NULL;
	SPACE_PTR  LevelBuffer = NULL;
	SPACE_PTR  SpaceBufferTemp = NULL;
	SPACE_PTR  SrcPtr = NULL;
	TImageFilterParam  FilterParam;
	TBasePlaneParam    BasePlaneParam;
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);		
	BasePlaneParam = NoiseParam.BasePlaneParam;

#ifdef _DEBUG	
	CString strFolder;
	bool    bSave=false;
	strFolder.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BuildSpaceData"));
	if ( true == bSave )
	{	::CreateDirectory(strFolder, NULL); }
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("Mask2D.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, Mask2DPtr, true);
		str.Format(_T("%s\\%s"), strFolder, _T("GuiddedImage.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, GuidedImagePtr, true);
	}
#endif//_DEBUG

	if ( JetMemory.alloc_func(BufferSize, MaskBuffer, fnName, "MaskBuffer") == false ||		 
		 JetMemory.alloc_func(BufferSize, MaskBuffer2, fnName, "MaskBuffer2") == false ||		 
		 JetMemory.alloc_func(BufferSize, LevelBuffer, fnName, "LevelBuffer") == false ||
		 JetMemory.alloc_func(BufferSize, CalcMaskBuffer, fnName, "CalcMaskBuffer") == false ||		
		 JetMemory.alloc_func(BufferSize, SpaceBufferTemp, fnName, "SpaceBufferTemp") == false ||		 
		 JetMemory.alloc_func(BufferSize, SpaceBuffer, fnName, "SpaceBuffer") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);		
		JetMemory.free_func(LevelBuffer);
		JetMemory.free_func(SpaceBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false;
	}	

	//::memset(MaskBuffer, 0x00, sizeof(MASK_DATA)*BufferSize);//20170412
	//::memset(LevelBuffer, 0x00, sizeof(SPACE_DATA)*BufferSize);//20170412
	//::memset(SpaceBuffer, 0xFF, sizeof(SPACE_DATA)*BufferSize);//20170412

	//無效點外擴
	NoiseParam.DataVoidExpandSpentTime = 0.0;
	if ( true == NoiseParam.DataVoidExpandEnabled )
	{
		const int ExtSize = NoiseParam.DataVoidExpandSize;
		const int IterCount = NoiseParam.DataVoidExpandIterCount;
		QueryPerformanceCounter(&nStartTime);
		if ( DilateNoiseMaskImage3(SpaceW, SpaceH, SpaceStep, MaskPtr, ExtSize, IterCount, MaskBuffer) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataVoidExpandSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
	}
	else
	{	::memcpy(MaskBuffer, MaskPtr, sizeof(MASK_DATA)*BufferSize);	}

	//修正空間資料-剃除雜訊		
	FilterParam.SkipValidPixel = true;
	FilterParam.FilterMode = NoiseParam.BasePlaneParam.FilterMode;
	FilterParam.FilterUseSize = NoiseParam.BasePlaneParam.FilterUseSize;	
	FilterParam.FilterSize = NoiseParam.BasePlaneParam.FilterKerSize;
	FilterParam.FilterIterCount = NoiseParam.BasePlaneParam.FilterIterCount;

	NoiseParam.BasePlaneParam.SpentTime = 0.0;
	QueryPerformanceCounter(&nStartTime);
	::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);	
	if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, LevelBuffer, GuidedImagePtr) == false )
	{
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);
		JetMemory.free_func(LevelBuffer);
		JetMemory.free_func(SpaceBuffer);
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false;	
	}

	//找出基準面
	CJetGroundEquation GroundEquation;
	if ( CImageAPI::CalcSpaceLevelPlane(SpaceW, SpaceH, SpaceStep, LevelBuffer, MaskBuffer, BasePlaneParam, Mask2DPtr, GroundEquation) == false )
	{	
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);
		JetMemory.free_func(LevelBuffer);
		JetMemory.free_func(SpaceBuffer);
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false; 
	}

	//扣除基準面-原始資料扣除基準面
	BasePlaneParam.GroundEquation = GroundEquation;	
	NoiseParam.BasePlaneParam.GroundEquation = GroundEquation;	

	const double OffsetZ = NoiseParam.BasePlaneParam.OffsetZ;
	const double OverHigh = NoiseParam.BasePlaneParam.OverHighFilter;
	const double OverLow = NoiseParam.BasePlaneParam.OverLowFilter;
	if ( CImageAPI::ExecSpaceImageLeveling3(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskBuffer, GroundEquation, OffsetZ, OverHigh, OverLow, SpaceBuffer) == false ||
		 CImageAPI::ExecSpaceImageLeveling3(SpaceW, SpaceH, SpaceStep, LevelBuffer, MaskBuffer, GroundEquation, OffsetZ, OverHigh, OverLow, LevelBuffer) == false )
	{
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);
		JetMemory.free_func(LevelBuffer);
		JetMemory.free_func(SpaceBuffer);
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false; 
	}
	QueryPerformanceCounter(&nEndTime);
	NoiseParam.BasePlaneParam.SpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms	
	
	bool bAllClose = NoiseParam.DataFirstFilterMode == DATA_NF_DISABLE
		&& NoiseParam.DataHeightFTMode == DATA_NF_DISABLE
		//&& NoiseParam.DataFinalFilterMode == DATA_NF_DISABLE
		//&& NoiseParam.DataFinalFilterMode2 == DATA_NF_DISABLE
		;
	if (false == bAllClose || AOIDataCollect.GetSystemParameterPtr()->m_SpaceNoiseCastFilterMode == CAST_SPACE_FILTER_MODE_DEFAULT) {
		//將相位雜訊設定為零
		for ( i=0; i<BufferSize; i++ )
		{
			if ( CheckSpaceMaskValid(MaskBuffer[i]) == true ) 
			{	continue; }
			SpaceBuffer[i] = 0;
			LevelBuffer[i] = 0;
		}
	}

	::memcpy(DstPtr, SpaceBuffer, sizeof(SPACE_DATA)*BufferSize);	
	::memcpy(SpaceBufferTemp, SpaceBuffer, sizeof(SPACE_DATA)*BufferSize);		
	
	//首次雜訊剃除, 無效點外擴, 奇異點濾除, 平滑處理			
	NoiseParam.DataFirstFilterSpentTime = 0;
	if ( DATA_NF_DISABLE != NoiseParam.DataFirstFilterMode )
	{		
		//將過低的設定為雜訊狀態	
		if ( DATA_NF_DISABLE != NoiseParam.DataOverLowFTMode )
		{
			const SPACE_DATA OverLower = NoiseParam.DataOverLowFTRange;
			for ( i=0; i<BufferSize; i++ )
			{	
				if ( SpaceBufferTemp[i] < OverLower )
				{	
					if ( CheckSpaceMaskValid(MaskBuffer[i]) == true ) 
					{	MaskBuffer[i] = PHASE_MASK_OVER_LOW; }					
				}				
			}			
		}
	#ifdef _DEBUG
		if ( true == bSave )
		{
			str.Format(_T("%s\\%s"), strFolder, _T("FirstFilterMask.PNG"));
			SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, MaskBuffer, true);
		}		
	#endif//_DEBUG

		FilterParam.SkipValidPixel = true;
		FilterParam.FilterMode = NoiseParam.DataFirstFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFirstFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFirstFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFirstFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;
		FilterParam.FilterAlphaF = NoiseParam.DataFirstFilterAlphaF;
		FilterParam.FilterAlphaS = NoiseParam.DataFirstFilterAlphaS;
		FilterParam.FilterAlphaM = NoiseParam.DataFirstFilterAlphaM;
		FilterParam.FilterAlphaI = NoiseParam.DataFirstFilterAlphaI;
		FilterParam.FilterSearchOn = NoiseParam.DataFirstFilterSearchOn;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFirstFilterThresdhold_Outlier;
		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);		
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false)
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;	
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFirstFilterSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	
	
	//將過低的雜訊給設定為0		
	NoiseParam.DataOverLowSpentTime = 0.0;
	if ( DATA_NF_DISABLE != NoiseParam.DataOverLowFTMode )
	{
		FilterParam.SkipValidPixel = true;
		FilterParam.FilterMode = NoiseParam.DataFirstFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFirstFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFirstFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFirstFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;

		const SPACE_DATA OverLower = NoiseParam.DataOverLowFTRange;		
		const SPACE_DATA OverLowerLimit = NoiseParam.DataOverLowFTLimit;
		QueryPerformanceCounter(&nStartTime);		
		for ( i=0; i<BufferSize; i++ )//定義要濾除的資料
		{		
			if ( SpaceBufferTemp[i] < OverLower )
			{	CalcMaskBuffer[i] = 0xFF;	}
			else
			{	CalcMaskBuffer[i] = 0x00;	}			
		}		
	#ifdef _DEBUG
		if ( true == bSave )
		{
			str.Format(_T("%s\\%s"), strFolder, _T("OverLowMask.PNG"));
			SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, CalcMaskBuffer, true);
		}		
	#endif//_DEBUG
		/*
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, bOpenMP, FilterParam, DstPtr) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;	
		}*/
		bool bUsedOverLowerLimit=false;
		if ( fabs(OverLowerLimit) > 0.01 ) { bUsedOverLowerLimit=true; }
		else { bUsedOverLowerLimit = false; }
		for ( i=0; i<BufferSize; i++ )
		{	
		#ifdef _DEBUG
			ImageX = i%SpaceStep;
			ImageY = i/SpaceStep;
			if ( 66==ImageX && 134==ImageY )
			{	i = i; }
			
		#endif//_DEBUG		
			if ( 0x00 == CalcMaskBuffer[i] ) { continue; }			
			//if ( CheckSpaceMaskValid(MaskBuffer[i]) == false ) //非有效點
			//{	continue;	}

			if ( true == bUsedOverLowerLimit )
			{
				//過低刪除			
				if ( SpaceBufferTemp[i]<OverLowerLimit )
				{
					LevelBuffer[i] = SpaceBuffer[i] = DstPtr[i] = 0;				
					continue; 
				}			
				//較低縮小
				if ( SpaceBufferTemp[i]<OverLower )
				{
					SpaceBufferTemp[i] = SpaceBufferTemp[i]*0.5;
					LevelBuffer[i] = SpaceBuffer[i] = DstPtr[i] = SpaceBufferTemp[i];
				}
			}
			/*
			LevelBuffer[i] = SpaceBuffer[i] = SpaceBufferTemp[i] = DstPtr[i];
			if ( SpaceBufferTemp[i] < OverLowerLimit )
			{	
				//MaskBuffer[i] = PHASE_MASK_OVER_LOW; 				
				if ( CheckSpaceMaskValid(MaskBuffer[i]) == true ) 
				{	MaskBuffer[i] = PHASE_MASK_OVER_LOW; }
				LevelBuffer[i] = SpaceBuffer[i] = SpaceBufferTemp[i] = DstPtr[i]=0;
			}
			else
			{				
				if ( PHASE_MASK_OVER_LOW == MaskBuffer[i] )
				{	MaskBuffer[i] = PHASE_MASK_VALID; }
			}*/
			//SpaceBuffer[i] = DstPtr[i] = LevelBuffer[i];//未處理資料
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataOverLowSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}

	//剃除異常高度
	NoiseParam.DataHeightFTSpentTime = 0.0;
	const int nRepeatCount = NoiseParam.DataHeightFTRepeatCnt;
	if ( DATA_NF_DISABLE!=NoiseParam.DataHeightFTMode && nRepeatCount>0 )
	{	
		size_t MaxSrcIdx=0;
		size_t MaxDstIdx=0;
		float HeightMaxSrc = 0;
		float HeightMaxDst = 0;
		float HeightDif = 0;
		float MaxDifRange = (float)(NoiseParam.DataHeightFTRange);

		TImageFilterParam FilterParam2;
		FilterParam2.SkipValidPixel = true;
		FilterParam2.FilterMode = DATA_NF_AVERAGE;
		FilterParam2.FilterSize = NoiseParam.DataHeightFTChkSize;		
		FilterParam2.FilterUseSize = 1;		
		FilterParam2.FilterIterCount = 1;

		FilterParam.SkipValidPixel = true;		
		FilterParam.FilterMode = NoiseParam.DataHeightFTMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataHeightFTPitch;
		FilterParam.FilterSize = NoiseParam.DataHeightFTKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataHeightFTUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;		
	//	FilterParam = NoiseParam;
		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);				
		if ( NoiseParam.DataHeightFTChkSize > 0 )
		{
			if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam2, DstPtr, GuidedImagePtr) == false )
			{
				JetMemory.free_func(MaskBuffer);
				JetMemory.free_func(MaskBuffer2);
				JetMemory.free_func(LevelBuffer);
				JetMemory.free_func(SpaceBuffer);
				JetMemory.free_func(CalcMaskBuffer);
				JetMemory.free_func(SpaceBufferTemp);		
				return false;	
			}
			for ( i=0; i<BufferSize; i++ )
			{	
			#ifdef _DEBUG
				ImageX = i%SpaceStep;
				ImageY = i/SpaceStep;			
			#endif//_DEBUG
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == false ) //非有效點
				//{	continue;	}
				HeightDif = SpaceBufferTemp[i]-DstPtr[i];				
				HeightDif = fabs(HeightDif);
				if ( HeightDif < 0 ) 
				{	
					//是否只考慮過高的, 不考慮低的
					CalcMaskBuffer[i] = 0x00;
					continue;
					HeightDif = -HeightDif; 
				}
				if ( HeightDif < MaxDifRange )//未超過範圍
				{	
					CalcMaskBuffer[i] = 0x00;
					continue;	
				}			
				CalcMaskBuffer[i] = 0xFF;
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == true )
				//{	MaskBuffer[i] = PHASE_MASK_HEIGHT_UNEXPECTED; }				
			}	
		#ifdef _DEBUG
			if ( true == bSave )
			{
				str.Format(_T("%s\\%s"), strFolder, _T("HeightExceptionMask.PNG"));
				SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, CalcMaskBuffer, true);
			}		
		#endif//_DEBUG
		}
		
		//跑多次		
		::memset(MaskBuffer2, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);//全部使用
		for ( i=0; i<BufferSize; i++ )
		{	
			if ( CheckSpaceMaskValidBest(MaskBuffer[i]) == false ) 
			{	continue; }
			MaskBuffer2[i] = PHASE_MASK_VALID_BEST;
		}
		for ( k=0; k<nRepeatCount; k++ )
		{	
			switch ( NoiseParam.DataHeightFTMode )
			{
			case DATA_NF_AVERAGE:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_SmoothFilterShiftEnabled )
				{
					if ( FilterParam.FilterPitch > nRepeatCount )
					{	FilterParam.FilterShift = (k*FilterParam.FilterPitch/nRepeatCount)%FilterParam.FilterPitch; }
					else
					{	FilterParam.FilterShift = k%FilterParam.FilterPitch;	}
				}
				break;
			case DATA_NF_MEDIAN:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
				{
					if ( FilterParam.FilterPitch > nRepeatCount )
					{	FilterParam.FilterShift = (k*FilterParam.FilterPitch/nRepeatCount)%FilterParam.FilterPitch; }
					else
					{	FilterParam.FilterShift = k%FilterParam.FilterPitch;	}
				}
				break;
			case DATA_NF_3LEVEL:				
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_LevelFilterShiftEnabled )
				{
					if ( FilterParam.FilterPitch > nRepeatCount )
					{	FilterParam.FilterShift = (k*FilterParam.FilterPitch/nRepeatCount)%FilterParam.FilterPitch; }
					else
					{	FilterParam.FilterShift = k%FilterParam.FilterPitch;	}
				}
				break;
			case DATA_NF_MEDIAN_2:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
				{
					if ( FilterParam.FilterPitch > nRepeatCount )
					{	FilterParam.FilterShift = (k*FilterParam.FilterPitch/nRepeatCount)%FilterParam.FilterPitch; }
					else
					{	FilterParam.FilterShift = k%FilterParam.FilterPitch;	}
				}
				break;
			case DATA_NF_PYRAMID_MEDIAN:
				if (FN_ENABLE == AOIDataCollect.GetSystemParameter().m_PyramidMedianFilterShiftEnabled)
				{
					if (FilterParam.FilterPitch > nRepeatCount)
					{
						FilterParam.FilterShift = (k*FilterParam.FilterPitch / nRepeatCount) % FilterParam.FilterPitch;
					}
					else
					{
						FilterParam.FilterShift = k%FilterParam.FilterPitch;
					}
				}
				break;
			}
			
			if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer2, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false )
			{
				JetMemory.free_func(MaskBuffer);
				JetMemory.free_func(MaskBuffer2);
				JetMemory.free_func(LevelBuffer);
				JetMemory.free_func(SpaceBuffer);
				JetMemory.free_func(CalcMaskBuffer);
				JetMemory.free_func(SpaceBufferTemp);		
				return false;	
			}
		
			for ( i=0; i<BufferSize; i++ )
			{	
			#ifdef _DEBUG
				ImageX = i%SpaceStep;
				ImageY = i/SpaceStep;
				if ( 69==ImageX && 85==ImageY )
				{	i = i; }					
			#endif//_DEBUG
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == false )//非有效點
				//{	continue;	}
				HeightDif = DstPtr[i]-SpaceBufferTemp[i];			
				if ( HeightDif < 0 ) 
				{	HeightDif = -HeightDif; }
				if ( NoiseParam.DataHeightFTChkSize > 0 ) 
				{
					if ( 0x00 == CalcMaskBuffer[i] ) { continue; }
				}	
				if ( HeightDif < MaxDifRange )//未超過範圍
				{					
					LevelBuffer[i] = SpaceBuffer[i] = DstPtr[i] = SpaceBufferTemp[i];					
					continue;	
				}			
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == true )
				//{	MaskBuffer[i] = PHASE_MASK_HEIGHT_UNEXPECTED; }
				LevelBuffer[i] = SpaceBuffer[i] = DstPtr[i];
			}
			SrcPtr = DstPtr;			
			::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
		}		
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataHeightFTSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
	}

	//雜訊重建
	//NoiseParam.DataVoidReContructed = true;
	//NoiseParam.DataVoidReContructedExtSize = 5;	
	NoiseParam.DataVoidRecontructedSpentTime = 0;
	if ( true == NoiseParam.DataVoidReContructed ) 
	{
		const int ExtSize = NoiseParam.DataVoidReContructedExtSize ;
		const int IterCount = 1;
		MASK_PTR MaskBufferT = NULL;
		QueryPerformanceCounter(&nStartTime);
		if ( DilateNoiseMaskImage(SpaceW, SpaceH, SpaceStep, MaskBuffer, ExtSize, IterCount, MaskBufferT) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		if ( ReContructVoidData3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBufferT, DstPtr) == false )
		{			
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(MaskBufferT);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		JetMemory.free_func(MaskBuffer);	MaskBuffer=NULL;
		MaskBuffer = MaskBufferT;
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataVoidRecontructedSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}
	::memcpy(DstMaskPtr, MaskBuffer, sizeof(MASK_DATA)*BufferSize);		
	//::memcpy(DstPtr, SpaceBuffer, sizeof(SPACE_DATA)*BufferSize);	
	
	//是否重新回填!?
	//雜訊剃除, 無效點外擴, 奇異點濾除, 平滑處理			
	NoiseParam.DataFinalFilterSpentTime = 0;
	if ( DATA_NF_DISABLE != NoiseParam.DataFinalFilterMode )
	{
		//DataFinalFilterPitch = 4;//平滑滑移步進
		FilterParam.SkipValidPixel = false;
		FilterParam.FilterMode = NoiseParam.DataFinalFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFinalFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFinalFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFinalFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;
		FilterParam.FilterAlphaF = NoiseParam.DataFinalFilterAlphaF;
		FilterParam.FilterAlphaS = NoiseParam.DataFinalFilterAlphaS;
		FilterParam.FilterAlphaM = NoiseParam.DataFinalFilterAlphaM;
		FilterParam.FilterAlphaI = NoiseParam.DataFinalFilterAlphaI;
		FilterParam.FilterSearchOn = NoiseParam.DataFinalFilterSearchOn;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFinalFilterThresdhold_Outlier;
		if ( DATA_NF_3LEVEL == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_LevelFilterShiftEnabled )
			{	
				if ( DATA_NF_3LEVEL == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}		
		if ( DATA_NF_MEDIAN == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
			{
				if ( DATA_NF_MEDIAN == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
			{
				if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if ( DATA_NF_AVERAGE == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = false;				
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_SmoothFilterShiftEnabled )
			{
				if ( DATA_NF_AVERAGE == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFinalFilterMode)
		{
			FilterParam.SkipValidPixel = true;
			if (FN_ENABLE == AOIDataCollect.GetSystemParameter().m_PyramidMedianFilterShiftEnabled)
			{
				if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFirstFilterMode)
				{
					FilterParam.FilterShift = FilterParam.FilterShift / 2;
				}
			}
		}
		if ( DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode) {
			FilterParam.SkipValidPixel = false;
		}
		if (DATA_NF_FAST_MEDIAN == NoiseParam.DataFinalFilterMode) {
			FilterParam.SkipValidPixel = false;
		}
		if (DATA_NF_FAST_AVERAGE == NoiseParam.DataFinalFilterMode) {
			FilterParam.SkipValidPixel = false;
		}

		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);
		::memset(MaskBuffer, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);		
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFinalFilterSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	

	//雜訊剃除, 無效點外擴, 奇異點濾除, 平滑處理-2
	NoiseParam.DataFinalFilterSpentTime2 = 0;
	if ( DATA_NF_DISABLE != NoiseParam.DataFinalFilterMode2 )
	{
		//DataFinalFilterPitch2;//平滑滑移步進
		FilterParam.SkipValidPixel = false;

		FilterParam.FilterMode = NoiseParam.DataFinalFilterMode2;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFinalFilterPitch2;
		FilterParam.FilterSize = NoiseParam.DataFinalFilterKerSize2;
		FilterParam.FilterUseSize = NoiseParam.DataFinalFilterUseSize2;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;		
		FilterParam.FilterAlphaF = NoiseParam.DataFinalFilterAlphaF2;
		FilterParam.FilterAlphaS = NoiseParam.DataFinalFilterAlphaS2;
		FilterParam.FilterAlphaM = NoiseParam.DataFinalFilterAlphaM2;
		FilterParam.FilterAlphaI = NoiseParam.DataFinalFilterAlphaI2;
		FilterParam.FilterSearchOn = NoiseParam.DataFinalFilterSearchOn2;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFinalFilterThresdhold_Outlier2;
		if ( DATA_NF_3LEVEL == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_MEDIAN == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_AVERAGE == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = false;	}
		if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFinalFilterMode2) { FilterParam.SkipValidPixel = true; }
		if (DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode2) { FilterParam.SkipValidPixel = false; }
		if (DATA_NF_FAST_MEDIAN == NoiseParam.DataFinalFilterMode2) { FilterParam.SkipValidPixel = false; }
		if (DATA_NF_FAST_AVERAGE == NoiseParam.DataFinalFilterMode2) { FilterParam.SkipValidPixel = false; }


		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);
		::memset(MaskBuffer, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);		
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(LevelBuffer);
			JetMemory.free_func(SpaceBuffer);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFinalFilterSpentTime2 = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	

	JetMemory.free_func(MaskBuffer);
	JetMemory.free_func(MaskBuffer2);
	JetMemory.free_func(LevelBuffer);
	JetMemory.free_func(SpaceBuffer);
	JetMemory.free_func(CalcMaskBuffer);
	JetMemory.free_func(SpaceBufferTemp);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::BuildSpaceData3_II(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const MASK_PTR Mask2DPtr, int nOpenMPCnt, TNoiseFilterParam &NoiseParam, SPACE_PTR DstPtr, MASK_PTR DstMaskPtr, const IMAGE_PTR GuidedImagePtr)//建立空間資料-II
{
	const char fnName[] = "CImageAPI::BuildSpaceData3_II";
	if ( this->CheckGrayImage4(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, DstPtr, DstMaskPtr) == false ) 
	{	return false; }

	//扣除Level
	CString str;	
	size_t i=0, j=0, k=0, idx=0;	
	size_t ImageX=0, ImageY=0;	
	LARGE_INTEGER   nStartTime;
	LARGE_INTEGER   nEndTime;
	MASK_PTR   MaskBuffer = NULL;	
	MASK_PTR   MaskBuffer2 = NULL;	
	MASK_PTR   CalcMaskBuffer = NULL;		
	SPACE_PTR  SpaceBufferTemp = NULL;	
	TImageFilterParam  FilterParam;
	TBasePlaneParam    BasePlaneParam;
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);		
	BasePlaneParam = NoiseParam.BasePlaneParam;

#ifdef _DEBUG	
	CString strFolder;
	bool    bSave=false;
	strFolder.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BuildSpaceData"));
	if ( true == bSave )
	{	::CreateDirectory(strFolder, NULL); }
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("Mask2D.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, Mask2DPtr, true);
		str.Format(_T("%s\\%s"), strFolder, _T("GuiddedImage.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, GuidedImagePtr, true);
	}
#endif//_DEBUG

	if ( JetMemory.alloc_func(BufferSize, MaskBuffer, fnName, "MaskBuffer") == false ||		 
		 JetMemory.alloc_func(BufferSize, MaskBuffer2, fnName, "MaskBuffer2") == false ||
		 JetMemory.alloc_func(BufferSize, CalcMaskBuffer, fnName, "CalcMaskBuffer") == false ||		
		 JetMemory.alloc_func(BufferSize, SpaceBufferTemp, fnName, "SpaceBufferTemp") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);		
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false;
	}

	//無效點外擴
	NoiseParam.DataVoidExpandSpentTime = 0.0;
	if ( true == NoiseParam.DataVoidExpandEnabled )
	{
		const int ExtSize = NoiseParam.DataVoidExpandSize;
		const int IterCount = NoiseParam.DataVoidExpandIterCount;
		QueryPerformanceCounter(&nStartTime);
		if ( DilateNoiseMaskImage3(SpaceW, SpaceH, SpaceStep, MaskPtr, ExtSize, IterCount, MaskBuffer) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataVoidExpandSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
	}
	else
	{	::memcpy(MaskBuffer, MaskPtr, sizeof(MASK_DATA)*BufferSize);	}
	
#ifdef _DEBUG
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("FirstMask.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, MaskBuffer, true);
	}		
#endif//_DEBUG

	//首次雜訊剃除	
	NoiseParam.DataFirstFilterSpentTime = 0;	
	::memcpy(SpaceBufferTemp, SpacePtr, sizeof(SPACE_DATA)*BufferSize);
	if ( DATA_NF_DISABLE != NoiseParam.DataFirstFilterMode )
	{
		FilterParam.SkipValidPixel = true;
		FilterParam.FilterMode = NoiseParam.DataFirstFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFirstFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFirstFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFirstFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;
		FilterParam.FilterAlphaF = NoiseParam.DataFirstFilterAlphaF;
		FilterParam.FilterAlphaS = NoiseParam.DataFirstFilterAlphaS;
		FilterParam.FilterAlphaM = NoiseParam.DataFirstFilterAlphaM;
		FilterParam.FilterAlphaI = NoiseParam.DataFirstFilterAlphaI;
		FilterParam.FilterSearchOn = NoiseParam.DataFirstFilterSearchOn;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFirstFilterThresdhold_Outlier;

		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);		
		if (RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false)
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;	
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFirstFilterSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	
	
	//剃除異常高度
	NoiseParam.DataHeightFTSpentTime = 0.0;
	const int nRepeatCount = NoiseParam.DataHeightFTRepeatCnt;
	if ( DATA_NF_DISABLE!=NoiseParam.DataHeightFTMode && nRepeatCount>0 )
	{	
		size_t MaxSrcIdx=0;
		size_t MaxDstIdx=0;
		float HeightMaxSrc = 0;
		float HeightMaxDst = 0;
		float HeightDif = 0;
		float MaxDifRange = (float)(NoiseParam.DataHeightFTRange);

		TImageFilterParam FilterParam2;
		FilterParam2.SkipValidPixel = true;
		FilterParam2.FilterMode = DATA_NF_AVERAGE;
		FilterParam2.FilterSize = NoiseParam.DataHeightFTChkSize;		
		FilterParam2.FilterUseSize = 1;		
		FilterParam2.FilterIterCount = 1;

		FilterParam.SkipValidPixel = true;		
		FilterParam.FilterMode = NoiseParam.DataHeightFTMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataHeightFTPitch;
		FilterParam.FilterSize = NoiseParam.DataHeightFTKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataHeightFTUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;		
	//	FilterParam = NoiseParam;
		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);				
		if ( NoiseParam.DataHeightFTChkSize > 0 )
		{
			if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam2, DstPtr, GuidedImagePtr) == false)
			{
				JetMemory.free_func(MaskBuffer);
				JetMemory.free_func(MaskBuffer2);
				JetMemory.free_func(CalcMaskBuffer);
				JetMemory.free_func(SpaceBufferTemp);		
				return false;	
			}
			for ( i=0; i<BufferSize; i++ )
			{	
			#ifdef _DEBUG
				ImageX = i%SpaceStep;
				ImageY = i/SpaceStep;			
			#endif//_DEBUG
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == false ) //非有效點
				//{	continue;	}
				HeightDif = SpaceBufferTemp[i]-DstPtr[i];				
				HeightDif = fabs(HeightDif);
				if ( HeightDif < 0 ) 
				{	
					//是否只考慮過高的, 不考慮低的
					CalcMaskBuffer[i] = 0x00;
					continue;
					HeightDif = -HeightDif; 
				}
				if ( HeightDif < MaxDifRange )//未超過範圍
				{	
					CalcMaskBuffer[i] = 0x00;
					continue;	
				}			
				CalcMaskBuffer[i] = 0xFF;
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == true )
				//{	MaskBuffer[i] = PHASE_MASK_HEIGHT_UNEXPECTED; }				
			}	
		#ifdef _DEBUG
			if ( true == bSave )
			{
				str.Format(_T("%s\\%s"), strFolder, _T("HeightExceptionMask.PNG"));
				SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, CalcMaskBuffer, true);
			}		
		#endif//_DEBUG
		}
		
		//跑多次		
		::memset(MaskBuffer2, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);//全部使用
		for ( i=0; i<BufferSize; i++ )
		{	
			if ( CheckSpaceMaskValidBest(MaskBuffer[i]) == false ) 
			{	continue; }
			MaskBuffer2[i] = PHASE_MASK_VALID_BEST;
		}
		for ( k=0; k<nRepeatCount; k++ )
		{	
			switch ( NoiseParam.DataHeightFTMode )
			{
			case DATA_NF_AVERAGE:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_SmoothFilterShiftEnabled )
				{	FilterParam.CalcFilterShift(k, nRepeatCount);	}
				break;
			case DATA_NF_MEDIAN:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
				{	FilterParam.CalcFilterShift(k, nRepeatCount);	}
				break;
			case DATA_NF_3LEVEL:				
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_LevelFilterShiftEnabled )
				{	FilterParam.CalcFilterShift(k, nRepeatCount);	}
				break;
			case DATA_NF_MEDIAN_2:
				if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
				{	FilterParam.CalcFilterShift(k, nRepeatCount);	}
				break;
			case DATA_NF_PYRAMID_MEDIAN:
				if (FN_ENABLE == AOIDataCollect.GetSystemParameter().m_PyramidMedianFilterShiftEnabled)
				{	FilterParam.CalcFilterShift(k, nRepeatCount);	}
				break;
			}			
			if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer2, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false )
			{
				JetMemory.free_func(MaskBuffer);
				JetMemory.free_func(MaskBuffer2);
				JetMemory.free_func(CalcMaskBuffer);
				JetMemory.free_func(SpaceBufferTemp);		
				return false;	
			}		
			for ( i=0; i<BufferSize; i++ )
			{	
			#ifdef _DEBUG
				ImageX = i%SpaceStep;
				ImageY = i/SpaceStep;
				if ( 69==ImageX && 85==ImageY )
				{	i = i; }					
			#endif//_DEBUG
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == false )//非有效點
				//{	continue;	}
				HeightDif = DstPtr[i]-SpaceBufferTemp[i];			
				if ( HeightDif < 0 ) 
				{	HeightDif = -HeightDif; }
				if ( NoiseParam.DataHeightFTChkSize > 0 ) 
				{
					if ( 0x00 == CalcMaskBuffer[i] ) { continue; }
				}	
				if ( HeightDif < MaxDifRange )//未超過範圍
				{					
					DstPtr[i] = SpaceBufferTemp[i];					
					continue;	
				}			
				//if ( CheckSpaceMaskValid(MaskBuffer[i]) == true )
				//{	MaskBuffer[i] = PHASE_MASK_HEIGHT_UNEXPECTED; }				
			}
			::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
		}		
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataHeightFTSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
	}

	//雜訊重建	
	NoiseParam.DataVoidRecontructedSpentTime = 0;
	if ( true == NoiseParam.DataVoidReContructed ) 
	{
		const int IterCount = 1;
		const int ExtSize = NoiseParam.DataVoidReContructedExtSize;
		QueryPerformanceCounter(&nStartTime);
	#ifdef _DEBUG
		if ( true == bSave )
		{
			str.Format(_T("%s\\%s"), strFolder, _T("FinalMaskBef.PNG"));
			SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, MaskBuffer, true);
		}		
	#endif//_DEBUG
		if ( DilateNoiseMaskImage3(SpaceW, SpaceH, SpaceStep, MaskBuffer, ExtSize, IterCount, MaskBuffer2) == false )
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		if ( ReContructVoidData3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer2, DstPtr) == false )
		{			
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}		
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataVoidRecontructedSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
		::memset(MaskBuffer, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);
	}
	::memcpy(DstMaskPtr, MaskBuffer, sizeof(MASK_DATA)*BufferSize);		
	//::memcpy(DstPtr, SpaceBuffer, sizeof(SPACE_DATA)*BufferSize);	
#ifdef _DEBUG
	if ( true == bSave )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("FinalMask.PNG"));
		SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, DstMaskPtr, true);
	}		
#endif//_DEBUG

	//是否重新回填!?
	//最終濾波-1
	NoiseParam.DataFinalFilterSpentTime = 0;
	if ( DATA_NF_DISABLE != NoiseParam.DataFinalFilterMode )
	{
		//DataFinalFilterPitch = 4;//平滑滑移步進
		FilterParam.SkipValidPixel = false;
		FilterParam.FilterMode = NoiseParam.DataFinalFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFinalFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFinalFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFinalFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;
		FilterParam.FilterAlphaF = NoiseParam.DataFinalFilterAlphaF;
		FilterParam.FilterAlphaS = NoiseParam.DataFinalFilterAlphaS;
		FilterParam.FilterAlphaM = NoiseParam.DataFinalFilterAlphaM;
		FilterParam.FilterAlphaI = NoiseParam.DataFinalFilterAlphaI;
		FilterParam.FilterSearchOn = NoiseParam.DataFinalFilterSearchOn;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFinalFilterThresdhold_Outlier;
		if ( DATA_NF_3LEVEL == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_LevelFilterShiftEnabled )
			{	
				if ( DATA_NF_3LEVEL == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}		
		if ( DATA_NF_MEDIAN == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
			{
				if ( DATA_NF_MEDIAN == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = true;			
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_MedianFilterShiftEnabled )
			{
				if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if ( DATA_NF_AVERAGE == NoiseParam.DataFinalFilterMode )
		{	
			FilterParam.SkipValidPixel = false;				
			if ( FN_ENABLE == AOIDataCollect.GetSystemParameter().m_SmoothFilterShiftEnabled )
			{
				if ( DATA_NF_AVERAGE == NoiseParam.DataFirstFilterMode )
				{	FilterParam.FilterShift = FilterParam.FilterShift/2; }
			}
		}
		if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFinalFilterMode)
		{
			FilterParam.SkipValidPixel = true;
			if (FN_ENABLE == AOIDataCollect.GetSystemParameter().m_PyramidMedianFilterShiftEnabled)
			{
				if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFirstFilterMode)
				{	FilterParam.FilterShift = FilterParam.FilterShift/2;	}
			}
		}
		if (DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode)
		{
			FilterParam.SkipValidPixel = false;
		}
		if (DATA_NF_FAST_MEDIAN == NoiseParam.DataFinalFilterMode) { FilterParam.SkipValidPixel = false; }
		if (DATA_NF_FAST_AVERAGE == NoiseParam.DataFinalFilterMode) { FilterParam.SkipValidPixel = false; }

		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);
		::memset(MaskBuffer, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);		
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false)
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFinalFilterSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	

	//最終濾波-2
	NoiseParam.DataFinalFilterSpentTime2 = 0;
	if ( DATA_NF_DISABLE != NoiseParam.DataFinalFilterMode2 )
	{
		//DataFinalFilterPitch2;//平滑滑移步進
		FilterParam.SkipValidPixel = false;

		FilterParam.FilterMode = NoiseParam.DataFinalFilterMode2;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFinalFilterPitch2;
		FilterParam.FilterSize = NoiseParam.DataFinalFilterKerSize2;
		FilterParam.FilterUseSize = NoiseParam.DataFinalFilterUseSize2;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;		
		FilterParam.FilterAlphaF = NoiseParam.DataFinalFilterAlphaF2;
		FilterParam.FilterAlphaS = NoiseParam.DataFinalFilterAlphaS2;
		FilterParam.FilterAlphaM = NoiseParam.DataFinalFilterAlphaM2;
		FilterParam.FilterAlphaI = NoiseParam.DataFinalFilterAlphaI2;
		FilterParam.FilterSearchOn = NoiseParam.DataFinalFilterSearchOn2;
		FilterParam.FilterThresdhold_Outlier = NoiseParam.DataFinalFilterThresdhold_Outlier2;
		if ( DATA_NF_3LEVEL == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_MEDIAN == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_MEDIAN_2 == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = true;	}
		if ( DATA_NF_AVERAGE == NoiseParam.DataFinalFilterMode2 )
		{	FilterParam.SkipValidPixel = false;	}
		if (DATA_NF_PYRAMID_MEDIAN == NoiseParam.DataFinalFilterMode2)
		{	FilterParam.SkipValidPixel = true; }
		if (DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode2)
		{	FilterParam.SkipValidPixel = false;	}
		if (DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode2)
		{	FilterParam.SkipValidPixel = false;	}
		if (DATA_NF_CONTENTAWARE == NoiseParam.DataFinalFilterMode2)
		{	FilterParam.SkipValidPixel = false;	}

		QueryPerformanceCounter(&nStartTime);
		::memset(CalcMaskBuffer, 0xFF, sizeof(MASK_DATA)*BufferSize);
		::memset(MaskBuffer, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);		
		if ( RefineSpaceImage3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, CalcMaskBuffer, nOpenMPCnt, FilterParam, DstPtr, GuidedImagePtr) == false)
		{
			JetMemory.free_func(MaskBuffer);
			JetMemory.free_func(MaskBuffer2);
			JetMemory.free_func(CalcMaskBuffer);
			JetMemory.free_func(SpaceBufferTemp);		
			return false;
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataFinalFilterSpentTime2 = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}	

	//修正空間資料-剃除雜訊
	FilterParam.SkipValidPixel = true;
	FilterParam.FilterMode = NoiseParam.BasePlaneParam.FilterMode;
	FilterParam.FilterUseSize = NoiseParam.BasePlaneParam.FilterUseSize;	
	FilterParam.FilterSize = NoiseParam.BasePlaneParam.FilterKerSize;
	FilterParam.FilterIterCount = NoiseParam.BasePlaneParam.FilterIterCount;

	NoiseParam.BasePlaneParam.SpentTime = 0.0;
	QueryPerformanceCounter(&nStartTime);

	//找出基準面, MaskBuffer, MaskPtr
	CJetGroundEquation GroundEquation;
	if ( CImageAPI::CalcSpaceLevelPlane(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskPtr, BasePlaneParam, Mask2DPtr, GroundEquation) == false )
	{	
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false; 
	}

	//扣除基準面-原始資料扣除基準面
	BasePlaneParam.GroundEquation = GroundEquation;	
	NoiseParam.BasePlaneParam.GroundEquation = GroundEquation;

	const double OffsetZ = NoiseParam.BasePlaneParam.OffsetZ;
	const double OverHigh = NoiseParam.BasePlaneParam.OverHighFilter;
	const double OverLow = NoiseParam.BasePlaneParam.OverLowFilter;
	if ( CImageAPI::ExecSpaceImageLeveling3(SpaceW, SpaceH, SpaceStep, SpaceBufferTemp, MaskBuffer, GroundEquation, OffsetZ, OverHigh, OverLow, SpaceBufferTemp) == false )
	{
		JetMemory.free_func(MaskBuffer);
		JetMemory.free_func(MaskBuffer2);		
		JetMemory.free_func(CalcMaskBuffer);
		JetMemory.free_func(SpaceBufferTemp);		
		return false; 
	}
	QueryPerformanceCounter(&nEndTime);
	NoiseParam.BasePlaneParam.SpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
	
	//將相位雜訊設定為零
	for ( i=0; i<BufferSize; i++ )
	{	
		if ( CheckSpaceMaskValid(MaskBuffer[i]) == true ) 
		{	continue; }		
		SpaceBufferTemp[i] = 0;
	}	
	::memcpy(DstPtr, SpaceBufferTemp, sizeof(SPACE_DATA)*BufferSize);

	//將過低的雜訊給設定為0		
	NoiseParam.DataOverLowSpentTime = 0.0;
	if ( DATA_NF_DISABLE != NoiseParam.DataOverLowFTMode )
	{
		FilterParam.SkipValidPixel = true;
		FilterParam.FilterMode = NoiseParam.DataFirstFilterMode;
		FilterParam.FilterShift = 0;
		FilterParam.FilterPitch = NoiseParam.DataFirstFilterPitch;
		FilterParam.FilterSize = NoiseParam.DataFirstFilterKerSize;
		FilterParam.FilterUseSize = NoiseParam.DataFirstFilterUseSize;
		FilterParam.FilterTolCount = 4;
		FilterParam.FilterTolerance = 50;
		FilterParam.FilterIterCount = 1;

		const SPACE_DATA OverLower = NoiseParam.DataOverLowFTRange;		
		const SPACE_DATA OverLowerLimit = NoiseParam.DataOverLowFTLimit;
		QueryPerformanceCounter(&nStartTime);		
		for ( i=0; i<BufferSize; i++ )//定義要濾除的資料
		{		
			if ( SpaceBufferTemp[i] < OverLower )
			{	CalcMaskBuffer[i] = 0xFF;	}
			else
			{	CalcMaskBuffer[i] = 0x00;	}			
		}		
	#ifdef _DEBUG
		if ( true == bSave )
		{
			str.Format(_T("%s\\%s"), strFolder, _T("OverLowMask.PNG"));
			SaveImage(str, SpaceW, SpaceH, SpaceStep, 8, CalcMaskBuffer, true);
		}		
	#endif//_DEBUG		
		bool bUsedOverLowerLimit=false;
		if ( fabs(OverLowerLimit) > 0.01 ) { bUsedOverLowerLimit=true; }
		else { bUsedOverLowerLimit = false; }
		for ( i=0; i<BufferSize; i++ )
		{			
			if ( 0x00 == CalcMaskBuffer[i] ) { continue; }
			if ( true == bUsedOverLowerLimit )
			{
				//過低刪除			
				if ( SpaceBufferTemp[i]<OverLowerLimit )
				{
					DstPtr[i] = 0;				
					continue; 
				}			
				//較低縮小
				if ( SpaceBufferTemp[i]<OverLower )
				{
					SpaceBufferTemp[i] = SpaceBufferTemp[i]*0.5;
					DstPtr[i] = SpaceBufferTemp[i];
				}
			}			
		}
		QueryPerformanceCounter(&nEndTime);
		NoiseParam.DataOverLowSpentTime = (nEndTime.QuadPart - nStartTime.QuadPart)*1000.0/AOIDataCollect.m_SystemFreq.QuadPart;//ms		
		::memcpy(SpaceBufferTemp, DstPtr, sizeof(SPACE_DATA)*BufferSize);
	}
	//::memset(DstMaskPtr, PHASE_MASK_VALID, sizeof(MASK_DATA)*BufferSize);		
	JetMemory.free_func(MaskBuffer);
	JetMemory.free_func(MaskBuffer2);
	JetMemory.free_func(CalcMaskBuffer);
	JetMemory.free_func(SpaceBufferTemp);		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ReContructVoidData(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, SPACE_PTR &DstPtr)//重建雜訊資料
{
	const char fnName[] = "CImageAPI::ReContructVoidData";
	if ( this->CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	JetMemory.free_func(DstPtr);	
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )		 
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(DstPtr);		
		return false;
	}

	if ( ReContructVoidData3(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);		
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ReContructVoidData3(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, SPACE_PTR DstPtr)//重建雜訊資料
{	
	if ( this->CheckGrayImage3(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, DstPtr) == false ) 
	{	return false; }
	
	size_t     i=0, j=0, k=0, idx=0;
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);	
	size_t     idxOffset=1;
	size_t     idxNext=0, idxCur=0, idxTmp=0;
	size_t     StartIdx=0, EndIdx=0;
	SPACE_DATA StartValue=0, EndValue=0, RatioValue=0;

	for ( i=0; i<BufferSize; i++ )
	{
		if ( (MaskPtr[i]&PHASE_MASK_NOISE) != 0 )
		{	DstPtr[i] = 0; }
		else
		{	DstPtr[i] = SpacePtr[i]; }
	}
	//十字回補 - 水平回補	
	for ( i=0; i<SpaceH; i++ )
	{
		idx = i*SpaceStep;		
		EndIdx=-1;
		StartIdx=-1;
		for ( j=0; j<SpaceW-idxOffset; j++ )
		{
			idxCur = idx+j;			
			idxNext = idxCur+idxOffset;
			if ( -1 == StartIdx )
			{
				if ( (MaskPtr[idxCur]&PHASE_MASK_NOISE)==NULL && (MaskPtr[idxNext]&PHASE_MASK_NOISE)!=NULL )
				{	
					StartIdx = j;	
					StartValue = DstPtr[idxCur];					
					continue;
				}
			}
			else if ( -1 == EndIdx )
			{
				if ( (MaskPtr[idxCur]&PHASE_MASK_NOISE)!=NULL && (MaskPtr[idxNext]&PHASE_MASK_NOISE)==NULL )
				{
					EndIdx = j+idxOffset;	
					EndValue = DstPtr[idxNext];
					RatioValue = (EndValue-StartValue)/(EndIdx-StartIdx);
					idxCur = idx+StartIdx+1;
					for ( k=StartIdx+1; k<EndIdx; k++ )
					{
						DstPtr[idxCur] = StartValue+((k-StartIdx)*RatioValue);
						//DstPtr[idxCur] = 10000;
						idxCur ++;
					}
					EndIdx=-1;
					StartIdx=-1;
				}
			}			
		}

		if ( -1 != StartIdx )
		{	
			idxCur = idx+StartIdx+1;
			for ( k=StartIdx+1; k<SpaceW; k++ )
			{
				DstPtr[idxCur] = StartValue;
				//DstPtr[idxCur] = 10000;
				idxCur ++;
			}
			EndIdx=-1;
			StartIdx=-1;
		}		
	}
	
	//十字回補 - 垂直回補
	for ( i=0; i<SpaceW; i++ )
	{	
		EndIdx=-1;
		StartIdx=-1;
		for ( j=0; j<SpaceH-idxOffset; j++ )
		{
			idx = j*SpaceStep;		
			idxCur = idx+i;			
			idxNext = idxCur+(idxOffset*SpaceStep);
			if ( -1 == StartIdx )
			{
				if ( (MaskPtr[idxCur]&PHASE_MASK_NOISE)==NULL && (MaskPtr[idxNext]&PHASE_MASK_NOISE)!=NULL )
				{	
					StartIdx = j;	
					StartValue = DstPtr[idxCur];					
					continue;
				}
			}
			else if ( -1 == EndIdx )
			{
				if ( (MaskPtr[idxCur]&PHASE_MASK_NOISE)!=NULL && (MaskPtr[idxNext]&PHASE_MASK_NOISE)==NULL )
				{
					EndIdx = j+idxOffset;	
					EndValue = DstPtr[idxNext];
					RatioValue = (EndValue-StartValue)/(EndIdx-StartIdx);					
					for ( k=StartIdx+1; k<EndIdx; k++ )
					{
						//continue;
						idxCur = (k*SpaceStep)+i;
						if ( fabs(DstPtr[idxCur]) < 0.001 )
						{	DstPtr[idxCur] = StartValue+((k-StartIdx)*RatioValue); }
						else
						{
							DstPtr[idxCur] += StartValue+((k-StartIdx)*RatioValue);
							DstPtr[idxCur] *= 0.5f;
						}
						//DstPtr[idxCur] = 10000;
						//idxCur ++;
					}
					EndIdx=-1;
					StartIdx=-1;
				}
			}			
		}

		if ( -1 != StartIdx )
		{	
			for ( k=StartIdx+1; k<SpaceH; k++ )
			{
				idxCur = (k*SpaceStep)+i;
				if ( fabs(DstPtr[idxCur]) < 0.001 )
				{	DstPtr[idxCur] = StartValue; }
				else
				{
					DstPtr[idxCur] += StartValue;
					DstPtr[idxCur] *= 0.5f;
				}				
				//DstPtr[idxCur] = 10000;
				idxCur ++;
			}
			EndIdx=-1;
			StartIdx=-1;
		}
	}
	/*
	//3x3平均, 以下非正式的平均濾波, 因為都修改道原來的資料
	size_t SmoothW = SpaceW-1;
	size_t SmoothH = SpaceH-1;
	size_t RowLast=0, RowNext=0, RowCur=0;
	size_t ColLast=0, ColNext=0, ColCur=0;
	SPACE_DATA Space=0;
	for ( i=0; i<BufferSize; i++ )
	{
		if ( (MaskPtr[i]&PHASE_MASK_NOISE) == NULL )
		{	continue; }
		
		RowCur = i/SpaceStep;
		ColCur = i%SpaceStep;
		if ( 1>=RowCur || (SmoothH<=RowCur) || 1>=ColCur || (SmoothW<=ColCur) )
		{	continue; }
		Space = DstPtr[i-SpaceStep-1]+DstPtr[i-SpaceStep]+DstPtr[i-SpaceStep+1]+
			    DstPtr[i-1]+DstPtr[i]+DstPtr[i+1]+
				DstPtr[i+SpaceStep-1]+DstPtr[i+SpaceStep]+DstPtr[i+SpaceStep+1];		
		DstPtr[i] = Space/9.0f;
	}*/
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const int *SpacePtr, const MASK_PTR MaskPtr, int *&DstPtr)//計算空間切平面
{
	const char fnName[] = "CImageAPI::CalcSpaceLevelPlane";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	JetMemory.free_func(DstPtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());				
		return false;
	}

	if ( CalcSpaceLevelPlane3(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const int *SpacePtr, const MASK_PTR MaskPtr, int *DstPtr)//計算空間切平面
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr, DstPtr) == false ) 
	{	return false; }

	unsigned int i=0, j=0;
	unsigned int idx1=0, idx2=0;
	double x=0.0, y=0.0, z=0.0;	
	CJetGroundEquation GroundEquation;
	GroundEquation.InitGroundParam(GROUND_EQUATION_PLANE);
	for ( i=0; i<ImageH; i++ )
	{
		idx1 = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{
			idx2 = idx1+j;
			//if ( (MaskPtr[idx2]&PHASE_MASK_LEVELING) == NULL ) { continue; }			
			z = SpacePtr[idx2];
			x = j;
			y = i;
			GroundEquation.AddGroundValue(x, y, z);
		}
	}
	GroundEquation.CalcGroundParam();

	for( i=0 ; i<ImageH ; i++ )
	{
		y = (double)i;
		idx1 = i*ImageStep;
		for( j=0 ; j<ImageW ; j++ )
		{
			idx2 = idx1+j;
			x = (double)j;			
			z = GroundEquation.CalcGroundValue(x, y);
			DstPtr[idx2] = (int)(z);			
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *SpacePtr, const MASK_PTR MaskPtr, float *&DstPtr)//計算空間切平面
{
	const char fnName[] = "CImageAPI::CalcSpaceLevelPlane";
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }
	
	JetMemory.free_func(DstPtr);
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());				
		return false;
	}

	if ( CalcSpaceLevelPlane3(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr, DstPtr) == false )
	{
		JetMemory.free_func(DstPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const float *SpacePtr, const MASK_PTR MaskPtr, float *DstPtr)//計算空間切平面
{
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, SpacePtr, MaskPtr, DstPtr) == false ) 
	{	return false; }

	unsigned int i=0, j=0;
	unsigned int idx1=0, idx2=0;	
	double x=0.0, y=0.0, z=0.0;
	CJetGroundEquation GroundEquation;
	GroundEquation.InitGroundParam(GROUND_EQUATION_PLANE);	
	for ( i=0; i<ImageH; i++ )
	{
		idx1 = i*ImageStep;
		for ( j=0; j<ImageW; j++ )
		{
			idx2 = idx1+j;
			//if ( (MaskPtr[idx2]&PHASE_MASK_LEVELING) == NULL ) { continue; }			
			z = SpacePtr[idx2];
			x = j;
			y = i;
			GroundEquation.AddGroundValue(x, y, z);
		}
	}
	GroundEquation.CalcGroundParam();

	for( i=0 ; i<ImageH ; i++ )
	{
		y = (double)i;
		idx1 = i*ImageStep;
		for( j=0 ; j<ImageW ; j++ )
		{
			idx2 = idx1+j;
			x = (double)j;
			z = GroundEquation.CalcGroundValue(x, y);
			DstPtr[idx2] = (float)z;
		}
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR  SpacePtr, const MASK_PTR MaskPtr, const TBasePlaneParam &CalcParam, const MASK_PTR Mask2DPtr, CJetGroundEquation &GroudEquation)//計算空間切平面	
{
	const char fnName[] = "CImageAPI::CalcSpaceLevelPlane";
	if ( CImageAPI::CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false ) 
	{	return false; }

	int i=0, j=0, idx=0;
	SPACE_DATA PlaneL = 0;
	SPACE_DATA PlaneH = 0;
	bool  bIsOK = false;
	const size_t BufferSize = CalcBufferSize(SpaceStep, SpaceH);
	double x=0.0, y=0.0, z=0.0;	
	double MaxTileAngle = 1;//3度
	double TanTile = 1.0;	
	MASK_PTR Mask2DPtrOpen = NULL;
	MASK_PTR Mask2DPtrUsed = NULL;	
	MASK_PTR MaskRotatedPtr = NULL;
	const int nSpaceW = (int)(SpaceW);
	const int nSpaceH = (int)(SpaceH);		
	const CALC_BASE_PLANE_MODE PlaneMode=CalcParam.CalcBasePlaneMode;
	const BASE_PLANE_TOWARD_MODE TowardMode=CalcParam.BasePlaneToward;	
	const bool   RotatedClip  = CalcParam.RotatedClip;
	const double RotatedAngle = CalcParam.RotatedAngle;
	const int    RotatedSizeW = CalcParam.RotatedSizeW;
	const int    RotatedSizeH = CalcParam.RotatedSizeH;
	const bool   bIsExceptionAngle = JetAPI::CheckIsExceptionAngle(RotatedAngle);
	if ( CALC_BASE_PLANE_LOCAL == PlaneMode )
	{
		GroudEquation = CalcParam.LocalGroundEquation;		
		if ( BASE_PLANE_TOWARD_VERTICAL == TowardMode )
		{	GroudEquation.VerticalPlane();	}
		return true;
	}
	//Open Base Mask
	if ( NULL != Mask2DPtr )
	{
		Mask2DPtrUsed = (MASK_PTR)Mask2DPtr;
		int MorphMode = 0;
		const int MorphModeDisable=0;
		const int KernelSize=CalcParam.FilterKerSize2D;
		switch ( CalcParam.FilterMode2D )
		{
		case NOISE_FILTER_OPEN:  MorphMode = MORPH_OPEN;	break;
		case NOISE_FILTER_CLOSE: MorphMode = MORPH_CLOSE;	break;
		default:
			MorphMode = MorphModeDisable;
			break;
		}
		if ( MorphModeDisable==MorphMode || 0==KernelSize )
		{	Mask2DPtrUsed = (MASK_PTR)Mask2DPtr;	}
		else
		{
			if ( JetMemory.alloc_func(BufferSize, Mask2DPtrOpen, fnName, "Mask2DPtrOpen") == true )
			{
				//const int OpenSize = 9;
				//const int MorphMode = MORPH_CLOSE;//MORPH_OPEN, MORPH_CLOSE 
				if ( MorphGrayImage3(SpaceW, SpaceH, SpaceStep, Mask2DPtr, MorphMode, MORPH_SHAPE_RECT, KernelSize, 1, Mask2DPtrOpen) == true )
				{	Mask2DPtrUsed = Mask2DPtrOpen;	}
				else
				{
					JetMemory.free_func(Mask2DPtrOpen);	
					Mask2DPtrOpen = NULL;
				}
			}
		}
	}
	if ( true==RotatedClip && true==bIsExceptionAngle )
	{
		if ( JetMemory.alloc_func(BufferSize, MaskRotatedPtr, fnName, "MaskRotatedPtr") == true )
		{	
			cv::Mat    Img;
			IMAGE_SIZE ImgBitCnt=8;
			Img = CreateMat(SpaceW, SpaceH, SpaceStep, ImgBitCnt, MaskRotatedPtr);
			if ( CheckMatIsValid(Img) == false )
			{	JetMemory.free_func(MaskRotatedPtr);	}
			else
			{					
				RECT       MaskRect;
				cv::Rect   cvRect;
				const int  SpaceCpX=SpaceW/2;
				const int  SpaceCpY=SpaceH/2;
				CvScalar   bkcolor = cvScalar(0.0, 0.0, 0.0); // black
				CvScalar   color = cvScalar(255.0, 255.0, 255.0); // white
				//cv::Scalar bkcolor = cv::Scalar(0.0, 0.0, 0.0); // black
				//cv::Scalar color = cv::Scalar(255.0, 255.0, 255.0); // white
				cvRect.x=cvRect.y = 0;
				cvRect.width = SpaceW;
				cvRect.height = SpaceH;
				MaskRect.left   = SpaceCpX-(RotatedSizeW/2);
				MaskRect.top    = SpaceCpY-(RotatedSizeH/2);
				MaskRect.right  = MaskRect.left+RotatedSizeW;
				MaskRect.bottom = MaskRect.top+RotatedSizeH;
				cv::rectangle(Img, cvRect, bkcolor, CV_FILLED);	
				DrawBoxImage_RotatedRect(Img, color, bkcolor, BOX_TOWARD_NULL, -RotatedAngle, MaskRect);
				if ( CloneMatData(Img, SpaceW, SpaceH, SpaceStep, ImgBitCnt, MaskRotatedPtr) == false )
				{	JetMemory.free_func(MaskRotatedPtr);	}
				else
				{	
					if ( NULL == Mask2DPtrUsed )
					{	Mask2DPtrUsed = MaskRotatedPtr;		}
					else
					{	
						//合併在一起
						for ( i=0; i<BufferSize; i++ )
						{
							if ( 0 == MaskRotatedPtr[i] ) 
							{	Mask2DPtrUsed[i] = 0; }
						}
						JetMemory.free_func(MaskRotatedPtr);
					}					
				}
			}			
		}
	}
	else
	{	bIsOK = false; }


	bool                  UseLocakRange=false;
	RECT                  CalcRect={0,0,0,0};	
	TRECT6I               CalcRect6I;	
	std::vector<TRECT6I>  CalcRectList;
	JetAPI::SizeToRect(SpaceW, SpaceH, CalcRect);		
	CalcRect6I = CalcRect;
	CalcRectList.push_back(CalcRect);	
	switch ( PlaneMode )
	{
	case CALC_BASE_PLANE_DISABLE:
		bIsOK = true;
		UseLocakRange=false;
		PlaneL = PlaneH = 0;
		break;
	case CALC_BASE_PLANE_PANEL:		
		bIsOK = CalcSpaceLevelPlane_Panel(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH, CalcRectList);
		break;
	case CALC_BASE_PLANE_AVERAGE:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_Average(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH);
		break;
	case CALC_BASE_PLANE_CORNER:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_Corner(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH);
		break;
	case CALC_BASE_PLANE_ISO_DATA:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_IsoData(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH);
		break;
	case CALC_BASE_PLANE_OTSU:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_OTSU(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH);
		break;
	case CALC_BASE_PLANE_CORNER_ONLY:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_CornerOnly(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH, CalcRectList);
		break;
	case CALC_BASE_PLANE_SURROUND:
		UseLocakRange=false;
		bIsOK = CalcSpaceLevelPlane_Surround(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, PlaneL, PlaneH, CalcRectList);
		break;
	case CALC_BASE_PLANE_AUTO_LOWER:
		UseLocakRange=true;
		bIsOK = CalcSpaceLevelPlane_AutoLower(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, CalcParam, Mask2DPtrUsed, UseLocakRange, PlaneL, PlaneH, CalcRectList);		
		break;
	case CALC_BASE_PLANE_LOCAL:
		bIsOK = true;
		CalcRectList.clear();
		break;
	}
#ifdef _DEBUG
	CString  UsedFilename;
	bool     bSaveMask=true;
	MASK_PTR UsedMaskPtr=NULL;
#endif//_DEBUG	
	if ( true == bIsOK )
	{
	#ifdef _DEBUG
		//bSaveMask = true;
		const size_t UsedMaskSize=CalcBufferSize(SpaceStep, SpaceH);
		if ( true == bSaveMask )
		{
			if ( JetMemory.alloc_func(UsedMaskSize, UsedMaskPtr, fnName, "UsedMaskPtr") == true )
			{	::memset(UsedMaskPtr, 0x00, sizeof(MASK_DATA)*UsedMaskSize);	}		
			LockThread();
			if ( NULL != Mask2DPtr )
			{
				UsedFilename.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BasePlane2DMask.PNG"));				
				SaveImage(UsedFilename, SpaceW, SpaceH, SpaceStep, 8, Mask2DPtr, true);			
			}
			if ( NULL != Mask2DPtrOpen )
			{
				UsedFilename.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BasePlane2DMaskOpen.PNG"));				
				SaveImage(UsedFilename, SpaceW, SpaceH, SpaceStep, 8, Mask2DPtrOpen, true);			
			}			
			if ( NULL != MaskRotatedPtr )
			{
				UsedFilename.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BasePlane2DMaskRotated.PNG"));				
				SaveImage(UsedFilename, SpaceW, SpaceH, SpaceStep, 8, MaskRotatedPtr, true);			
			}			
			if ( NULL != Mask2DPtrUsed )
			{
				UsedFilename.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BasePlane2DMaskUsed.PNG"));				
				SaveImage(UsedFilename, SpaceW, SpaceH, SpaceStep, 8, Mask2DPtrUsed, true);			
			}			
			UnlockThread();		
		}
	#endif//_DEBUG		
		size_t k=0;		
		size_t nTop=0, nBot=0, nLeft=0, nRight=0;
		const int XYPitch = CalcParam.BasePlaneXYPitch;
		const size_t CalcRectCount = CalcRectList.size();
		GROUND_EQUATION_MODE GroundEqMode=GROUND_EQUATION_NONE;
		switch ( CalcParam.BasePlaneEqMode )
		{
		case BASE_PLANE_EQUATION_CURVE:		GroundEqMode=GROUND_EQUATION_CURVE;	break;
		default:
		case BASE_PLANE_EQUATION_PLANE:		GroundEqMode=GROUND_EQUATION_PLANE;	break;
		}
		GroudEquation.InitGroundParam(GroundEqMode);
		for ( k=0; k<CalcRectCount; k++ )
		{
			//k = 1;
			CalcRect6I = CalcRectList[k];
			nTop = (size_t)(CalcRect6I.top);
			nBot = (size_t)(CalcRect6I.bottom);
			nLeft = (size_t)(CalcRect6I.left);
			nRight = (size_t)(CalcRect6I.right);
			if ( true == UseLocakRange )
			{
				PlaneH = CalcRect6I.maxZ;
				PlaneL = CalcRect6I.minZ;
			}
			//for ( i=0; i<nSpaceH; i++ )
			//for ( i=nTop; i<nBot; i++ )
			for ( i=nTop; i<nBot; i+=XYPitch )
			{
				idx = i*SpaceStep;
				//for ( j=0; j<nSpaceW; j++ )
				//for ( j=nLeft; j<nRight; j++ )
				for ( j=nLeft; j<nRight; j+=XYPitch )
				{
					if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }
					if ( NULL!=Mask2DPtrUsed && 0==Mask2DPtrUsed[idx+j] )		{	continue;	}
					if ( SpacePtr[idx+j] > PlaneH ) { continue; }
					if ( SpacePtr[idx+j] < PlaneL ) { continue; }
				#ifdef _DEBUG
					if ( NULL != UsedMaskPtr )
					{	UsedMaskPtr[idx+j] = 0xFF; }
				#endif//_DEBUG

					z = SpacePtr[idx+j];				
					x = j;
					y = i;
					GroudEquation.AddGroundValue(x, y, z);			
				}
			}			
		}
		//norm==0.0 -> nZ = (PlaneH+PlaneL)*0.5;
		GroudEquation.CalcGroundParam();
		if ( BASE_PLANE_TOWARD_VERTICAL == TowardMode )
		{	GroudEquation.VerticalPlane();	}

	#ifdef _DEBUG
		if ( NULL != UsedMaskPtr )
		{
			UsedFilename.Format(_T("%s\\%s"), AOIDataCollect.GetAOITempDirectory(), _T("BasePlaneCalcMask.PNG"));
			LockThread();
			SaveImage(UsedFilename, SpaceW, SpaceH, SpaceStep, 8, UsedMaskPtr, true);			
			UnlockThread();
		}
	#endif//_DEBUG
	}
	Mask2DPtrUsed = NULL;
	JetMemory.free_func(Mask2DPtrOpen);
	JetMemory.free_func(MaskRotatedPtr);	
#ifdef _DEBUG
	if ( NULL != UsedMaskPtr )
	{	JetMemory.free_func(UsedMaskPtr);	}
#endif//_DEBUG	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane_Panel(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const TBasePlaneParam &CalcParam, const MASK_PTR Mask2DPtr, float &PlaneL, float &PlaneH, std::vector<TRECT6I> &CalcRectList)//計算空間切平面-整板
{	
	int          RoiSizeCx=0;
	int          RoiSizeCy=0;
	RECT         Rect;	
	RECT         ImageRect={0};
	std::vector<RECT> RectList;	
	const int    SpaceW2 = SpaceW/2;
	const int    SpaceH2 = SpaceH/2;
	const int    SpaceSizeMax = MAX(SpaceW, SpaceH);
	const int    SpaceSizeMin = MIN(SpaceW, SpaceH);
	const int    SpaceCellW = SpaceW/4;
	const int    SpaceCellH = SpaceH/4;
	const int    MinSize = 5;//pixel, 避免框出太小的檢測框
	const DWORD  UseSideMode=CalcParam.UseSideMode;
	const bool   UseSideTop = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_UP);
	const bool   UseSideLeft = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_LEFT);
	const bool   UseSideBottom = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_DOWN);
	const bool   UseSideRight = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_RIGHT);

	RoiSizeCx = SpaceCellW;
	RoiSizeCy = SpaceCellH;
	RoiSizeCx = (int)(MAX(MinSize, RoiSizeCx));
	RoiSizeCy = (int)(MAX(MinSize, RoiSizeCy));	
	JetAPI::SizeToRect(SpaceW, SpaceH, ImageRect);
	if ( false==UseSideTop || false==UseSideLeft || false==UseSideBottom || false==UseSideRight )
	{
		if ( true == UseSideTop )
		{
			if ( true == UseSideLeft )
			{	Rect.left = 0; }
			else
			{	Rect.left = RoiSizeCx; }
			if ( true == UseSideRight )
			{	 Rect.right = SpaceW; }
			else
			{	 Rect.right = SpaceW-RoiSizeCx; }
			Rect.top  = 0; Rect.bottom = Rect.top+SpaceH2;
			JetAPI::BoundaryRect(ImageRect, Rect);
			if ( Rect.right > Rect.left )
			{	RectList.push_back(Rect); }
		}
		if ( true == UseSideLeft )
		{
			if ( true == UseSideTop )
			{	Rect.top = 0; }
			else
			{	Rect.top = RoiSizeCy; }
			if ( true == UseSideBottom )
			{	Rect.bottom = SpaceH; }
			else
			{	Rect.bottom = SpaceH-RoiSizeCy; }
			Rect.left = 0; Rect.right = Rect.left+SpaceW2;			
			JetAPI::BoundaryRect(ImageRect, Rect);
			if ( Rect.bottom > Rect.top )
			{	RectList.push_back(Rect); }
		}
		if ( true == UseSideBottom )
		{
			if ( true == UseSideLeft )
			{	Rect.left = 0; }
			else
			{	Rect.left = RoiSizeCx; }
			if ( true == UseSideRight )
			{	 Rect.right = SpaceW; }
			else
			{	 Rect.right = SpaceW-RoiSizeCx; }
			Rect.bottom = SpaceH; Rect.top = Rect.bottom-SpaceH2;
			JetAPI::BoundaryRect(ImageRect, Rect);
			if ( Rect.right > Rect.left )
			{	RectList.push_back(Rect); }
		}

		if ( true == UseSideRight )
		{
			if ( true == UseSideTop )
			{	Rect.top = 0; }
			else
			{	Rect.top = RoiSizeCy; }
			if ( true == UseSideBottom )
			{	Rect.bottom = SpaceH; }
			else
			{	Rect.bottom = SpaceH-RoiSizeCy; }
			Rect.right = SpaceW; Rect.left = Rect.right-SpaceW2;
			JetAPI::BoundaryRect(ImageRect, Rect);
			if ( Rect.bottom > Rect.top )
			{	RectList.push_back(Rect); }
		}				
	}
	const size_t Count=RectList.size();
	if ( 0 == Count )
	{	RectList.push_back(ImageRect);	}

	const double PanelBasePlane=CalcParam.PanelBasePlane;
	const double SysNoise = CalcParam.SystemNoiseRange;//Kai-20170313-因軟板修正-原來為30->60	
	PlaneL = (SPACE_DATA)(PanelBasePlane-SysNoise);
	PlaneH = (SPACE_DATA)(PanelBasePlane+SysNoise);	
	
	size_t       i=0;
	TRECT6I      Rect6I;
	const size_t RectCount=RectList.size();
	CalcRectList.clear();
	for ( i=0; i<RectCount; i++ )
	{
		Rect6I = RectList[i];
		Rect6I.maxZ = PlaneH;
		Rect6I.minZ = PlaneL;
		CalcRectList.push_back(Rect6I);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane_Average(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const TBasePlaneParam &CalcParam, const MASK_PTR Mask2DPtr, float &PlaneL, float &PlaneH)//計算空間切平面		
{
	if ( CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false )
	{	return false; }

	size_t    idx=0;
	size_t    i=0, j=0;
	size_t    Count=0;
	double    Average=0;		
	SPACE_DATA SpaceMax=(SPACE_DATA)(INT_MIN);
	SPACE_DATA SpaceMin=(SPACE_DATA)(INT_MAX);
	for ( i=0; i<SpaceH; i++ )
	{
		idx = i*SpaceStep;
		for ( j=0; j<SpaceW; j++ )
		{
			
			if ( (MaskPtr[idx]&PHASE_MASK_NOISE) != NULL ) 
			{
				idx ++;
				continue; 
			}
			if ( NULL!=Mask2DPtr && 0==Mask2DPtr[idx] )
			{	
				idx ++;
				continue;
			}
			Count ++;
			Average += SpacePtr[idx];
			if ( SpaceMax < SpacePtr[idx] ) { SpaceMax = SpacePtr[idx]; }
			if ( SpaceMin > SpacePtr[idx] ) { SpaceMin = SpacePtr[idx]; }
		idx ++;
		}
	}
	const double SpaceRange = SpaceMax-SpaceMin;
	const double PlaneRange = SpaceRange*1/5;//20%
	PlaneL     = (SPACE_DATA)(SpaceMin);
	PlaneH     = (SPACE_DATA)(SpaceMin+PlaneRange);		
	if ( Count > 0 )
	{
		Average /= Count;			
		PlaneH   = (SPACE_DATA)(Average);
		PlaneL   = (SPACE_DATA)(PlaneH-PlaneRange);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane_Corner(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const TBasePlaneParam &CalcParam, const MASK_PTR Mask2DPtr, float &PlaneL, float &PlaneH)//計算空間切平面-端點
{
	if ( CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false )
	{	return false; }

	size_t idx=0;
	size_t i=0, j=0;	
	RECT   Rect={0};
	RECT   RectLT={0,0,0,0};
	RECT   RectLB={0,0,0,0};
	RECT   RectRT={0,0,0,0};
	RECT   RectRB={0,0,0,0};
	RECT   ImageRect={0,0,0,0};
	size_t Count = 0;
	int RoiSizeCx = 0;
	int RoiSizeCy = 0;
	double MinCorner= DBL_MAX;
	double MaxCorner=-DBL_MAX;
	double Sum=0, Average=0;		
	double SumLT=0, SumLB=0, SumRT=0, SumRB=0;
	size_t CountLT=0, CountLB=0, CountRT=0, CountRB=0;
	double AverageLT=0, AverageLB=0, AverageRT=0, AverageRB=0;
	const double SpaceSizeMax = MAX(SpaceW, SpaceH);
	const double SpaceSizeMin = MIN(SpaceW, SpaceH);
	const double SpaceCellW = SpaceW/8;//4->8
	const double SpaceCellH = SpaceH/8;//4->8
	const double MinSize = 5;//pixel, 避免框出太小的檢測框		
	const double MaxSize = 200;//pixel, 避免框出太大的檢測框
	const DWORD  UseSideMode=CalcParam.UseSideMode;
	const bool   UseSideTop = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_UP);
	const bool   UseSideLeft = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_LEFT);
	const bool   UseSideBottom = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_DOWN);
	const bool   UseSideRight = JetAPI::BitMask_Check(UseSideMode, BOX_TOWARD_RIGHT);
	const double ImageResolution = AOIDataCollect.GetFovResolutionValue();	

	RoiSizeCx = SpaceCellW;
	RoiSizeCy = SpaceCellH;
	RoiSizeCx = (int)(MAX(MinSize, RoiSizeCx));
	RoiSizeCy = (int)(MAX(MinSize, RoiSizeCy));
	RoiSizeCx = (int)(MIN(MaxSize, RoiSizeCx));
	RoiSizeCy = (int)(MIN(MaxSize, RoiSizeCy));
	bool  UseLT=false, UseRT=false, UseLB=false, UseRB=false;

	JetAPI::SizeToRect(SpaceW, SpaceH, ImageRect);

	//Left Top
	if ( true==UseSideTop || true==UseSideLeft )
	{
		Rect.left = 0; Rect.right = Rect.left+RoiSizeCx;
		Rect.top  = 0; Rect.bottom = Rect.top+RoiSizeCy;
		JetAPI::BoundaryRect(ImageRect, Rect);
		for ( i=Rect.top; i<Rect.bottom; i++ )
		{
			idx = i*SpaceStep;
			for ( j=Rect.left; j<Rect.right; j++ )
			{
				if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }			
				if ( NULL!=Mask2DPtr && 0==Mask2DPtr[idx+j] )	{	continue;	}

				CountLT ++;
				SumLT += SpacePtr[idx+j];
			}
		}
		RectLT = Rect;
		if ( 0 != CountLT )
		{	
			AverageLT = SumLT/CountLT;	
			if ( MinCorner > AverageLT ) { MinCorner = AverageLT; }
			if ( MaxCorner < AverageLT ) { MaxCorner = AverageLT; }		
		}
	}
	//Right Top
	if ( true==UseSideTop || true==UseSideRight )
	{
		Rect.right = SpaceW; Rect.left = Rect.right-RoiSizeCx;		
		Rect.top  = 0; Rect.bottom = Rect.top+RoiSizeCy;
		JetAPI::BoundaryRect(ImageRect, Rect);
		for ( i=Rect.top; i<Rect.bottom; i++ )
		{
			idx = i*SpaceStep;
			for ( j=Rect.left; j<Rect.right; j++ )
			{
				if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }			
				if ( NULL!=Mask2DPtr && 0==Mask2DPtr[idx+j] )	{	continue;	}
				CountRT ++;
				SumRT += SpacePtr[idx+j];
			}
		}
		RectRT = Rect;
		if ( 0 != CountRT )
		{	
			AverageRT = SumRT/CountRT;	
			if ( MinCorner > AverageRT ) { MinCorner = AverageRT; }
			if ( MaxCorner < AverageRT ) { MaxCorner = AverageRT; }		
		}
	}
	//Left Bottom
	if ( true==UseSideBottom || true==UseSideLeft )
	{
		Rect.left = 0; Rect.right = Rect.left+RoiSizeCx;
		Rect.bottom = SpaceH; Rect.top = Rect.bottom-RoiSizeCy;
		JetAPI::BoundaryRect(ImageRect, Rect);
		for ( i=Rect.top; i<Rect.bottom; i++ )
		{
			idx = i*SpaceStep;
			for ( j=Rect.left; j<Rect.right; j++ )
			{
				if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }				
				if ( NULL!=Mask2DPtr && 0==Mask2DPtr[idx+j] )	{	continue;	}
				CountLB ++;
				SumLB += SpacePtr[idx+j];
			}
		}
		RectLB = Rect;
		if ( 0 != CountLB )
		{	
			AverageLB = SumLB/CountLB;	
			if ( MinCorner > AverageLB ) { MinCorner = AverageLB; }
			if ( MaxCorner < AverageLB ) { MaxCorner = AverageLB; }		
		}
	}
		
	//Right Bottom
	if ( true==UseSideBottom || true==UseSideRight )
	{
		Rect.right = SpaceW; Rect.left = Rect.right-RoiSizeCx;
		Rect.bottom = SpaceH; Rect.top = Rect.bottom-RoiSizeCy;
		JetAPI::BoundaryRect(ImageRect, Rect);
		for ( i=Rect.top; i<Rect.bottom; i++ )
		{
			idx = i*SpaceStep;
			for ( j=Rect.left; j<Rect.right; j++ )
			{
				if ( (MaskPtr[idx+j]&PHASE_MASK_NOISE) != NULL ) { continue; }
				if ( NULL!=Mask2DPtr && 0==Mask2DPtr[idx+j] )	{	continue;	}
				CountRB ++;
				SumRB += SpacePtr[idx+j];
			}
		}
		RectRB = Rect;
		if ( 0 != CountRB )
		{	
			AverageRB =SumRB/CountRB;	
			if ( MinCorner > AverageRB ) { MinCorner = AverageRB; }
			if ( MaxCorner < AverageRB ) { MaxCorner = AverageRB; }		
		}
	}		
	Count = CountLT+CountRT+CountLB+CountRB;
	if ( 0 == Count ) 
	{	return false; }
				
	//剃除過高的端點
	Sum = SumLT+SumRT+SumLB+SumRB;
	Average = Sum/Count;
	const double SysNoise = CalcParam.SystemNoiseRange;//Kai-20170313-因軟板修正-原來為30->60
	//double TiltMax = SpaceSizeMax/10.0;
	double MaxTileAngle = CalcParam.MaxTiltAngle;//板材傾角, 單位角度
	double TanTile = ::tan(MaxTileAngle*DEG_TO_RAD_DBL);
	double TiltMax = (SpaceSizeMax*ImageResolution)*TanTile;//Kai-20171021-因軟板修正
	double HeightGap1 = TiltMax;
	if ( HeightGap1 < SysNoise ) { HeightGap1 = SysNoise; }
	const double UpperGap = HeightGap1*CalcParam.UpperRatio;
	const double LowerGap = HeightGap1*CalcParam.LowerRatio;
	const double AveUpper = Average+(UpperGap);//(SysNoisy*0.5);
	const double AveLower = Average-(LowerGap);//(SysNoisy*0.5);//Kai-20171003-因過低雜訊修正

	Sum = 0.0;
	Count = 0;
	if ( true==UseSideTop || true==UseSideLeft )
	{
		if ( AverageLT<AveUpper && AverageLT>AveLower )
		{
			Sum   += SumLT;
			Count += CountLT;
			UseLT = true;				
		}			
	}
	if ( true==UseSideTop || true==UseSideRight )
	{
		if ( AverageRT<AveUpper && AverageRT>AveLower )
		{
			Sum   += SumRT;
			Count += CountRT;
			UseRT = true;				
		}
	}
	if ( true==UseSideBottom || true==UseSideLeft )
	{
		if ( AverageLB<AveUpper && AverageLB>AveLower )
		{
			Sum   += SumLB;
			Count += CountLB;
			UseLB = true;				
		}			
	}
	if ( true==UseSideBottom || true==UseSideRight )
	{
		if ( AverageRB<AveUpper && AverageRB>AveLower )
		{
			Sum   += SumRB;
			Count += CountRB;
			UseRB = true;				
		}
	}
	if ( 0 != Count )
	{	Average = Sum/Count;	}

	PlaneH     = (SPACE_DATA)(Average+SysNoise);
	PlaneL     = (SPACE_DATA)(PlaneH-500);
	PlaneL     = (SPACE_DATA)(Average-SysNoise);

	PlaneH     = (SPACE_DATA)(Average+(HeightGap1));//Kai-20171021
	PlaneL     = (SPACE_DATA)(Average-(HeightGap1));

	if ( 0 == Count )
	{
		HeightGap1 = (MaxCorner-MinCorner)*0.3;
		Average = (MaxCorner+MinCorner)*0.4;
		PlaneH     = (SPACE_DATA)(Average);
		PlaneL     = (SPACE_DATA)(MinCorner);
	}	
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcSpaceLevelPlane_IsoData(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr, const MASK_PTR MaskPtr, const TBasePlaneParam &CalcParam, const MASK_PTR Mask2DPtr, float &PlaneL, float &PlaneH)//計算空間切平面-IsoData
{
	if ( CheckGrayImage2(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr) == false )
	{	return false; }

	RECT Roi={0};	
	JetAPI::SizeToRect(SpaceW, SpaceH, Roi);
	if ( CalcSpaceImageIsoDataThreshold(SpaceW, SpaceH, SpaceStep, SpacePtr, MaskPtr, Roi, PlaneH) == false )
	{	return false; }
	PlaneL = PlaneH - 500;
	return true;
}
