bool CImageAPI::GetGuidedImage(const int ImgW, const int ImgH, const int ImgStep, const int BitCount, const IMAGE_PTR ImagePtr, IMAGE_PTR &DstPtr)//GuidedImage is GrayImage
{
	const char fnName[] = "CImageAPI::GetGuidedImage";
	if (24 == BitCount)
	{
		if (CheckColorImage(ImgW, ImgH, ImgStep, ImagePtr) == false) {	return false; }
		IMAGE_SIZE GrayStep = JetAPI::GetBMPImagePixelsPerLine(ImgW, 8, 4);
		if (ColorImageToGrayImage(ImgW, ImgH, ImgStep, ImagePtr, GrayStep, DstPtr) == false){ return false; }
#ifdef _DEBUG
		if (NULL != DstPtr)
		{
			CString str;
			str.Format(_T("%s\\RoiGuidedImagePtr.PNG"), AOIDataCollect.GetAOITempDirectory());
			SavePNGImage(str, ImgW, ImgH, ImgStep / 3, 8, DstPtr, true);
		}
#endif
	}
	else if (8 == BitCount)
	{
		if (CheckGrayImage(ImgW, ImgH, ImgStep, ImagePtr) == false) { return false; }
		JetMemory.free_func(DstPtr);
		const size_t BufferSize = CalcBufferSize(ImgStep, ImgH);
		if (JetMemory.alloc_func(BufferSize, DstPtr, fnName, "DstPtr") == false)
		{
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		::memcpy(DstPtr, ImagePtr, sizeof(IMAGE_DATA)*(BufferSize));
	}
	return true;
}
