bool CImageAPI::PhaseImageToSpaceImageByMapping3(int CvtMode, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const PHASE_PTR PhasePtr, int SX, int SY, const double *HeightFactor0, const double *HeightFactor1, const double *HeightFactor2, MASK_PTR MaskPtr, SPACE_PTR DstPtr)//將相位影像轉成空間相對位置	
{
	if ( PHASE_CONVERT_HEIGHT_SCALE == CvtMode )
	{	return false; }
	if ( this->CheckGrayImage6(ImageW, ImageH, ImageStep, PhasePtr, MaskPtr, HeightFactor0, HeightFactor1, HeightFactor2, DstPtr) == false ) 
	{	return false; }
	
#ifdef CUDA_USE
	//const bool IsCudaDeviceUse = CudaFunc.GetIsCudaDeviceUse();
	//const TSystemParameter &SysParam = AOIDataCollect.GetSystemParameter();
	//if ( SysParam.m_CudaFnEnabled==FN_ENABLE && true==IsCudaDeviceUse )
	//{
	//	if ( CudaFunc.CudaPhaseToSpace(ImageW, ImageH, ImageStep, PhasePtr, KPtr, DstPtr) == false )//for 2560x2560=>30 ms
	//	{
	//		SetErrorString(CudaFunc.GetErrorString());
	//		return false;
	//	}
	//	return true;
	//}
#endif//CUDA_USE	

	size_t i=0;
	int    nX=0, nY=0;
	double X=0, Y=0;
	PHASE_DATA Phase=0;
	SPACE_DATA Space = 0;	
	const double *T0 = HeightFactor0;
	const double *T1 = HeightFactor1;
	const double *T2 = HeightFactor2;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);//for 2560x2560=>25ms
	for ( i=0; i<BufferSize; i++ )
	{		
		nX = i%ImageStep;
		nY = i/ImageStep;
		X = nX+SX;//因為參數是以整個FOV為主
		Y = nY+SY;
		Phase = PhasePtr[i];
		ConvertPhaseToSpaceMapFunc(CvtMode, X, Y, Phase, T0, T1, T2, Space);		
		DstPtr[i] = Space;//KValue*Phase;		
	}	
	return true;
}
