//-------------------------------------------------------------------------------------//
bool CImageAPI::Merge2SpaceImage3(IMAGE_SIZE SpaceW, IMAGE_SIZE SpaceH, IMAGE_SIZE SpaceStep, const SPACE_PTR SpacePtr1, MASK_PTR MaskPtr1, const SPACE_PTR SpacePtr2, MASK_PTR MaskPtr2, bool bOpenMP, SPACE_PTR SpacePtr, MASK_PTR MaskPtr)//將2個空間合併同一個空間 
{
	if ( this->CheckGrayImage6(SpaceW, SpaceH, SpaceStep, SpacePtr1, MaskPtr1, SpacePtr2, MaskPtr2, SpacePtr, MaskPtr) == false ) 
	{	return false; }

	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;
	const TSystemParameter &SystemParam = AOIDataCollect.GetSystemParameter();		
	const int PatchSize=SystemParam.m_SpaceNoiseMultiCastPatchSize;	
	const int PatchSpaceCount=(PatchSize*2+1)*(PatchSize*2+1)*4;
	const int PatchArrayUsedSize=MIN(MaxSpaceCount, PatchSpaceCount);

	int OpenMPCountUsed=1;	
	const bool bCrossMask = glbCrossMask;
	const int  BufferSize = (int)(SpaceStep*SpaceH);
	const int  OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
	if ( true == bOpenMP )
	{	OpenMPCountUsed = MAX(1, OpenMPCount); }
	
#pragma omp parallel for num_threads(OpenMPCountUsed)
	for ( int i=0; i<BufferSize; i++ )
	{	
		MASK_DATA   Mask=0;			
		float       Space=0.0f;
		bool  bUsePatchX=false;
		bool  bUsePatchY=false;
		int ImageX = i%SpaceStep;
		int ImageY = i/SpaceStep;
		if ( ImageY<PatchSize || ImageY>=(SpaceH-PatchSize) )
		{	bUsePatchY = false; }
		else
		{	bUsePatchY = true; }
		if ( ImageX<PatchSize || ImageX>=(SpaceW-PatchSize)  )
		{	bUsePatchX = false; }
		else
		{	bUsePatchX = true; }
		MASK_DATA    Mask1=MaskPtr1[i];
		MASK_DATA    Mask2=MaskPtr2[i];		
		SPACE_DATA   Space1=SpacePtr1[i];
		SPACE_DATA   Space2=SpacePtr2[i];		
		if ( Compare2SpaceHeight(Mask1, Space1, Mask2, Space2, Mask, Space) == true )
		{
			MaskPtr[i] = Mask;
			SpacePtr[i] = (SPACE_DATA)(Space);		
			continue;
		}
		if ( false==bUsePatchX || false==bUsePatchY || 0==PatchSize )
		{			
			Merge2SpaceData(Mask1, Space1, Mask2, Space2, Mask, Space);
			MaskPtr[i] = Mask;
			SpacePtr[i] = (SPACE_DATA)(Space);	
		}
		else
		{	
			int         SpaceCount=0;
			MASK_DATA   MaskList[MaxSpaceCount];
			SPACE_DATA  SpaceList[MaxSpaceCount];
			SPACE_DATA  Space1=0, Space2=0;

			::memset(MaskList, 0x00, sizeof(MASK_DATA)*PatchArrayUsedSize);
			::memset(SpaceList, 0x00, sizeof(SPACE_DATA)*PatchArrayUsedSize);
			for ( int v=-PatchSize; v<=PatchSize; v++ )
			{	
				for ( int u=-PatchSize; u<=PatchSize; u++ )
				{
					if ( true == bCrossMask )//十字遮罩
					{
						if ( u<0 && u<(abs(v)-PatchSize) ) 
						{	continue;	}
						else if ( u>0 && u>(PatchSize-abs(v)) ) 
						{	continue;	}
					}
					int t = v+ImageY;
					int s = u+ImageX;
					int j = (t*SpaceStep)+s;
					MaskList[SpaceCount]=MaskPtr1[j];	SpaceList[SpaceCount]=SpacePtr1[j];	SpaceCount++;
					MaskList[SpaceCount]=MaskPtr2[j];	SpaceList[SpaceCount]=SpacePtr2[j];	SpaceCount++;
					if ( (SpaceCount+2) > MaxSpaceCount )
					{	break; }
				}
				if ( (SpaceCount+2) > MaxSpaceCount )
				{	break; }
			}
			Space = 0;
			MergeNSpaceData(MaskList, SpaceList, SpaceCount, Mask, Space);
			MaskPtr[i] = Mask;
			SpacePtr[i] = (SPACE_DATA)(Space);
		}
	}	
	return true;
}
