bool CImageAPI::ShortGrayImageConvertToSpace(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const short *pImage, SPACE_PTR &SpacePtr, bool Reverse)//Short影像轉成空間資料
{
	const char fnName[] = "CImageAPI::ShortGrayImageConvertToSpace";
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(SpacePtr);
	if ( JetMemory.alloc_func(BufferSize, SpacePtr, fnName, "SpacePtr") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}

	if ( CImageAPI::ShortGrayImageConvertToSpace3(ImageW, ImageH, ImageStep, pImage, SpacePtr, Reverse) == false )
	{
		JetMemory.free_func(SpacePtr);
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ShortGrayImageConvertToSpace3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const short *pImage, SPACE_PTR SpacePtr, bool Reverse)//Short影像轉成空間資料	
{
	if ( CImageAPI::CheckGrayImage2(ImageW, ImageH, ImageStep, SpacePtr, pImage) == false )
	{	return false; }

	size_t i=0, j=0;	
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	if ( true == Reverse )
	{
		size_t srcIdx=0, dstIdx=0;
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = (ImageH-i-1)*ImageStep;
			for ( j=0; j<ImageW; j++ )
			{	SpacePtr[dstIdx++] = pImage[srcIdx++];	}
		}
	}
	else
	{
		for ( i=0; i<BufferSize; i++ )
		{	SpacePtr[i] = pImage[i];	}
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::UShortGrayImageConvertToSpace(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned short *pImage, SPACE_PTR &SpacePtr, bool Reverse)//unsigned Short影像轉成空間資料
{
	const char fnName[] = "CImageAPI::UShortGrayImageConvertToSpace";
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(SpacePtr);
	if ( JetMemory.alloc_func(BufferSize, SpacePtr, fnName, "SpacePtr") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}

	if ( CImageAPI::UShortGrayImageConvertToSpace3(ImageW, ImageH, ImageStep, pImage, SpacePtr, Reverse) == false )
	{
		JetMemory.free_func(SpacePtr);
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::UShortGrayImageConvertToSpace3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned short *pImage, SPACE_PTR SpacePtr, bool Reverse)//unsigned Short影像轉成空間資料
{
	if ( CImageAPI::CheckGrayImage2(ImageW, ImageH, ImageStep, SpacePtr, pImage) == false )
	{	return false; }

	size_t i=0, j=0;
	SPACE_DATA Space = 0;
	const SPACE_DATA Offset = SHRT_MIN;//帶負號
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);

	if ( true == Reverse )
	{
		size_t srcIdx=0, dstIdx=0;
		for ( i=0; i<ImageH; i++ )
		{
			srcIdx = i*ImageStep;
			dstIdx = (ImageH-i-1)*ImageStep;
			for ( j=0; j<ImageW; j++ )
			{
				Space  = pImage[srcIdx++];
				Space += Offset;
				SpacePtr[dstIdx++] = Space;
			}
		}
	}
	else
	{
		for ( i=0; i<BufferSize; i++ )
		{
			Space  = pImage[i];
			Space += Offset;		
			SpacePtr[i] = Space;
		}
	}
	return true;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RGBConvertXYZ(unsigned char R, unsigned char G, unsigned char B, float &X, float &Y, float &Z)//RGB轉成XYZ
{
	X = 0.412453f*R + 0.357580f*G + 0.180423f*B;
	Y = 0.212671f*R + 0.715160f*G + 0.072169f*B;
	Z = 0.019334f*R + 0.119193f*G + 0.950227f*B;
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::XYZConvertRGB(float X, float Y, float Z, unsigned char &R, unsigned char &G, unsigned char &B)//XYZ轉成RGB
{
	float r=0, g=0, b=0;
	r =  3.240479*X - 1.537150*Y - 0.498535*Z;
	g = -0.969256*X + 1.875992*Y + 0.041556*Z;
	b =  0.055648*X - 0.204043*Y + 1.057311*Z;
	r += 0.5f;
	g += 0.5f;
	b += 0.5f;
	if ( r < 0.0f ) { R = 0; }
	else if ( r > 255.0f ) { R = 255; }
	else { R = (unsigned char)(r); }

	if ( g < 0.0f ) { G = 0; }
	else if ( g > 255.0f ) { G = 255; }
	else { G = (unsigned char)(g); }

	if ( b < 0.0f ) { B = 0; }
	else if ( b > 255.0f ) { B = 255; }
	else { B = (unsigned char)(b); }
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::XYZConvertLab(float X, float Y, float Z, float &L, float &a, float &b)
{	
	//L = 116 * f(Y/Yn) - 16
	//a = 500 [f(X/Xn) - f(Y/Yn)]
	//b = 200 [f(Y/Yn) - f(Z/Zn)]
	//f(t) = t^(1/3)                      if t > (6/29)^3
	//f(t) = 1/3 * (29/6)^2 * t + (4/29)  otherwise
	const bool nNormalized=true;
	const float param_13 = 1.0f/3.0f;//0.333333333f
	const float param_16116 = 16.0f/116.0f;//0.1379310f;
	if ( true == nNormalized )//將XYZ拉至0~255
	{
		const float nX=0.412453f + 0.357580f + 0.180423f;
		const float nY=0.212671f + 0.715160f + 0.072169f;
		const float nZ=0.019334f + 0.119193f + 0.950227f;
		X /= (255.0f*nX);
		Y /= (255.0f*nY);
		Z /= (255.0f*nZ);
	}
	
	float fX=0.0f, fY=0.0f, fZ=0.0f;
	if( Y > 0.008856f)//(6/29)^3
	{	fY = pow(Y, param_13);	}
	else
	{	fY = 7.787f * Y + param_16116;	}
	
	if (X > 0.008856f)
	{	fX = pow(X, param_13); }
	else
	{	fX = 7.787f * X + param_16116; }
	
	if (Z > 0.008856)
	{	fZ = pow(Z, param_13); }
	else
	{	fZ = 7.787f * Z + param_16116; }
 
	L = 116.0f * fY -16.0f;
	L = MAX(L, 0.0f);
	a = 500.0f * (fX - fY);
	b = 200.0f * (fY - fZ);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::LabConvertXYZ(float L, float a, float b, float &X, float &Y, float &Z)
{
	//Y = Yn * f^-1((L+16)/116)
	//X = Xn * f^-1((L+16)/116 + a/500 )
	//Z = Zn * f^-1((L+16)/116 - a/500 )
	//f^-1(t) = t*t*t                if t>6/29
	//f^-1(t) = 3*(6/29)^2*(t-4/29)  otherwise
	float fX=0, fY=0, fZ=0;
	const bool nNormalized=true;
	const float param_13 = 1.0f/3.0f;//0.333333333f
	const float param_16116 = 16.0f/116.0f;//0.1379310f;
	
	fY = (L + 16.0f) / 116.0f;
	if (fY > 0.206893f)//6/29
	{	Y = fY * fY * fY; }
	else
	{	Y = (fY-param_16116) / 7.787f; }
	
	fX = fY + a/500.0f;
	if (fX > 0.206893f)//6/29
	{	X = fX * fX * fX; }
	else
	{	X = (fX-param_16116) / 7.787f; }
	
	fZ = fY - b/200.0f;
	if (fZ > 0.206893f)//6/29
	{	Z = fZ * fZ * fZ; }
	else
	{	Z = (fZ -param_16116) / 7.787f; }
 
	if ( true == nNormalized )
	{
		const float nX=0.412453f + 0.357580f + 0.180423f;
		const float nY=0.212671f + 0.715160f + 0.072169f;
		const float nZ=0.019334f + 0.119193f + 0.950227f;
		X *= (255.0f*nX);
		Y *= (255.0f*nY);
		Z *= (255.0f*nZ);
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DebayerGrayImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BAYER_PATTERN_MODE BayerMode, unsigned char *&pDst)//原圖還原成灰階圖
{
	const char fnName[] = "CImageAPI::DebayerGrayImage";
	if ( CImageAPI::CheckBayerPattern(BayerMode) == false )
	{	return false; }
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}
	if ( CImageAPI::DebayerGrayImage3(ImageW, ImageH, ImageStep, pImage, BayerMode, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;	
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DebayerGrayImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BAYER_PATTERN_MODE BayerMode, unsigned char *pDst)//原圖還原成灰階圖
{
	if ( CImageAPI::CheckBayerPattern(BayerMode) == false )
	{	return false; }
	if ( CImageAPI::CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }

#ifndef OPENCV_DISABLE		
	try
	{		
		const int cvBayerMode = GetCVBayerModeGray(BayerMode);
		if ( 0 == cvBayerMode ) { return false; }
		const IMAGE_SIZE SrcBitCnt=8;
		const IMAGE_SIZE DstBitCnt=8;
		cv::Mat MatSrc=CreateMat(ImageW, ImageH, ImageStep, SrcBitCnt, pImage);
		cv::Mat MatDst=CreateMat(ImageW, ImageH, ImageStep, DstBitCnt, pDst);
		if ( CheckMatIsValid(MatSrc)==false || CheckMatIsValid(MatDst)==false )
		{	return false;	}	
		cv::cvtColor(MatSrc, MatDst, cvBayerMode);
		if ( CloneMatData(MatDst, ImageW, ImageH, ImageStep, DstBitCnt, pDst)==false )
		{	return false;	}	
		return true;
	}
	catch ( cv::Exception& e )
	{	
		CatchOpenCVException(e);	
		return false;
	}	
#endif//OPENCV_DISABLE
	return ReturnOpenCVDisableException();
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::DebayerColorImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, BAYER_PATTERN_MODE BayerMode, IMAGE_SIZE &DstStep, unsigned char *&pDst)
{
	const char fnName[] = "CImageAPI::DebayerColorImage";
	if ( CImageAPI::CheckBayerPattern(BayerMode) == false )
	{	return false; }
	if ( CImageAPI::CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	const int nAlign = 4;
	const int nBitCount = 24;
	const IMAGE_SIZE TmpStep = GetImageAlignedWidth(ImageW, nBitCount, nAlign);
	const size_t BufferSize = CalcBufferSize(TmpStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false;	
	}
	DstStep = TmpStep;
	if ( CImageAPI::DebayerColorImage3(ImageW, ImageH, ImageStep, pImage, BayerMode, DstStep, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;	
	}
	return true;
}
