bool CImageAPI::ColorImageColorFilter(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *&MaskPtr, bool FullMask, bool bOpenMP)//彩色影像抽色
{
	const char fnName[] = ("CImageAPI::ColorImageColorFilter");
	if ( CImageAPI::CheckRGBToRedTable() == false ) { return false; }
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	size_t BufferSize = 0;
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;	
	if ( true == FullMask )
	{
		if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
		{	return false; }
		BufferSize = CalcBufferSize(MaskStep, ImageH);
	}
	else
	{
		if ( this->CheckGraySize(RoiW, RoiH, MaskStep) == false )
		{	return false; }
		BufferSize = CalcBufferSize(MaskStep, RoiH);
	}	
	JetMemory.free_func(MaskPtr);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr);		
		return false;
	}		
	::memset(MaskPtr, 0xFF, sizeof(unsigned char)*BufferSize);	
	if ( this->ColorImageColorFilter3(ImageW, ImageH, ImageStep, pImage, ColorGoup, RoiRect, MaskStep, MaskPtr, FullMask, bOpenMP) == false )
	{
		JetMemory.free_func(MaskPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ColorImageColorFilter3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *MaskPtr, bool FullMask, bool bOpenMP)//彩色影像抽色
{
	bool IsOK = true;
	const int nRoiSize = (RoiRect.right-RoiRect.left)*(RoiRect.bottom-RoiRect.top);
	const bool OpenMPUsed = AOIDataCollect.CheckOpenMPUsed_ColorFilter(nRoiSize);
	if ( false == OpenMPUsed )
	{	bOpenMP = false; }
	if ( true == bOpenMP )
	{	IsOK = ColorImageColorFilter3_MP(ImageW, ImageH, ImageStep, pImage, ColorGoup, RoiRect, MaskStep, MaskPtr, FullMask);	}
	else
	{	IsOK = ColorImageColorFilter3_SP(ImageW, ImageH, ImageStep, pImage, ColorGoup, RoiRect, MaskStep, MaskPtr, FullMask);	}
	return IsOK;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ColorImageColorFilter3_SP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *MaskPtr, bool FullMask)//彩色影像抽色
{
	if ( CImageAPI::CheckRGBToRedTable() == false ) { return false; }
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }
	
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;	
	if ( true == FullMask )
	{
		if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
		{	return false; }		
	}
	else
	{
		if ( this->CheckGraySize(RoiW, RoiH, MaskStep) == false )
		{	return false; }		
	}	

	int    IR=0, IG=0, IB=0, IV=0;
	bool   InR=false, InG=false, InB=false, InV=false, Inside=true, InsideClr=true;
	size_t R=0, G=0, B=0;
	size_t RID = 0;
	size_t GID = 0;
	size_t BID = 0;
	size_t i=0, j=0, k=0, srcIdx=0, dstIdx=0;
	COLOR_LOGIC_MODE LogicMode=COLOR_LOGIC_INCLUDE;
	//CColorRGBV  *rgbvPtr=NULL;
	const size_t RoiL = RoiRect.left;
	const size_t RoiT = RoiRect.top;
	const size_t RoiR = RoiRect.right;
	const size_t RoiB = RoiRect.bottom;
	const size_t RGBVCount = ColorGoup.GetColorGroupColorCount();
	for ( i=RoiT; i<RoiB; i++ )
	{
		srcIdx = (i*ImageStep)+(RoiL*3);
		if ( true == FullMask )
		{	dstIdx = (i*MaskStep)+RoiL;	}
		else
		{	dstIdx = (i-RoiT)*MaskStep;	}
		
		for ( j=RoiL; j<RoiR; j++ )
		{
			R = pImage[srcIdx+2];
			G = pImage[srcIdx+1];
			B = pImage[srcIdx];

			RID = (R<<16)+(G<<8)+B;
			GID = (G<<16)+(B<<8)+R;
			BID = (B<<16)+(R<<8)+G;			

			IR = this->m_RGBToRedTable[RID];
			IG = this->m_RGBToRedTable[GID];
			IB = this->m_RGBToRedTable[BID];
			IV = (unsigned char)( (R+G+B)/3 );

			Inside = false;
			for ( k=0; k<RGBVCount; k++ )
			{	
				const CColorRGBV  *rgbvPtr = ColorGoup.GetColorGroupColorPtr(k, false);
				if ( NULL == rgbvPtr ) { continue; }
				if ( rgbvPtr->GetUsed() == false ) { continue; }

				LogicMode = rgbvPtr->GetLogicMode();
				if ( false==Inside || COLOR_LOGIC_EXCLUDE==LogicMode )
				{
					InsideClr = rgbvPtr->CheckColorInside(IR, IG, IB, IV);
					if ( false == InsideClr) 
					{	continue; }

					if ( COLOR_LOGIC_EXCLUDE == LogicMode )
					{	
						Inside = false;
						break;
					}
					Inside = true;				
				}
				else
				{	continue; }				
			}
			if ( true == Inside )
			{	MaskPtr[dstIdx] = 0xFF;	}
			else
			{	MaskPtr[dstIdx] = 0x00;	}
			
			dstIdx ++;
			srcIdx += 3;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ColorImageColorFilter3_MP(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *MaskPtr, bool FullMask)//彩色影像抽色-OpenMP
{
#ifdef OPEN_MP_USE
	if ( CImageAPI::CheckRGBToRedTable() == false ) { return false; }
	if ( this->CheckColorImage2(ImageW, ImageH, ImageStep, pImage, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }
	
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;	
	if ( true == FullMask )
	{
		if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
		{	return false; }		
	}
	else
	{
		if ( this->CheckGraySize(RoiW, RoiH, MaskStep) == false )
		{	return false; }		
	}
	
	const int ImageWH=ImageW*ImageH;
	const int OpenMPCount = AOIDataCollect.GetOpenMPCount_General();
	bool      CpuAffinity[MAX_OPEN_MP_COUNT]={false};
	DWORD_PTR AffinityMask = AOIDataCollect.GetThreadAffinityMask();
#pragma omp parallel for num_threads(OpenMPCount)
	for ( int i=0; i<ImageWH; i++ )
	{	
		int tid = omp_get_thread_num();
		if ( false == CpuAffinity[tid] )
		{
			CpuAffinity[tid] = true;
			SetThreadAffinityMask(GetCurrentThread(), AffinityMask);
		}
		int nX = i%ImageW;
		int nY = i/ImageW;		
		if ( nY<RoiRect.top || nY>=RoiRect.bottom ) { continue; }
		if ( nX<RoiRect.left || nX>=RoiRect.right ) { continue; }		
		ColorImageColorFilter3_MP_Fn(nX, nY, ImageW, ImageH, ImageStep, pImage, ColorGoup, RoiRect, MaskStep, MaskPtr, FullMask);
	}
	return true;
#endif//OPEN_MP_USE	
	return ReturnOpenMPDisableException();
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::ColorImageColorFilter3_MP_Fn(int nX, int nY, IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pImage, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *MaskPtr, bool FullMask)//彩色影像抽色-OpenMP
{
	int    IR=0, IG=0, IB=0, IV=0;
	bool   InR=false, InG=false, InB=false, InV=false, Inside=true, InsideClr=true;
	int R=0, G=0, B=0;
	int RID = 0;
	int GID = 0;
	int BID = 0;
	int i=0, j=0, k=0, srcIdx=0, dstIdx=0;
	COLOR_LOGIC_MODE LogicMode=COLOR_LOGIC_INCLUDE;
	//CColorRGBV  *rgbvPtr=NULL;
	int SrcX = 0;
	int SrcY = 0;
	int DstX = 0;
	int DstY = 0;
	
	SrcX = nX;
	SrcY = nY;
	if ( SrcX<RoiRect.left || SrcX>=RoiRect.right ) { return true; }
	if ( SrcY<RoiRect.top || SrcY>=RoiRect.bottom ) { return true; }

	srcIdx = (SrcY*ImageStep)+(SrcX*3);;
	if ( true == FullMask )
	{	dstIdx = (SrcY*MaskStep)+SrcX;	}
	else
	{	dstIdx = (SrcY-RoiRect.top)*MaskStep+(SrcX-RoiRect.left);	}

	R = pImage[srcIdx+2];
	G = pImage[srcIdx+1];
	B = pImage[srcIdx];

	RID = (R<<16)+(G<<8)+B;
	GID = (G<<16)+(B<<8)+R;
	BID = (B<<16)+(R<<8)+G;			

	IR = this->m_RGBToRedTable[RID];
	IG = this->m_RGBToRedTable[GID];
	IB = this->m_RGBToRedTable[BID];
	IV = (unsigned char)( (R+G+B)/3 );

	Inside = false;
	const int RGBVCount = (int)(ColorGoup.GetColorGroupColorCount());	
	for ( k=0; k<RGBVCount; k++ )
	{	
		const CColorRGBV  *rgbvPtr = ColorGoup.GetColorGroupColorPtr(k, false);
		if ( NULL == rgbvPtr ) { continue; }
		if ( rgbvPtr->GetUsed() == false ) { continue; }

		LogicMode = rgbvPtr->GetLogicMode();
		if ( false==Inside || COLOR_LOGIC_EXCLUDE==LogicMode )
		{
			InsideClr = rgbvPtr->CheckColorInside(IR, IG, IB, IV);
			if ( false == InsideClr) 
			{	continue; }

			if ( COLOR_LOGIC_EXCLUDE == LogicMode )
			{	
				Inside = false;
				break;
			}
			Inside = true;				
		}
		else
		{	continue; }				
	}
	if ( true == Inside )
	{	MaskPtr[dstIdx] = 0xFF;	}
	else
	{	MaskPtr[dstIdx] = 0x00;	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RGBImageColorFilter(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *&MaskPtr, bool FullMask)//彩色影像抽色
{
	const char fnName[] = ("CImageAPI::RGBImageColorFilter");
	if ( CImageAPI::CheckRGBToRedTable() == false ) { return false; }
	if ( this->CheckGrayImage3(ImageW, ImageH, ImageStep, pR, pG, pB) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	size_t BufferSize = 0;
	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;	
	if ( true == FullMask )
	{
		if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
		{	return false; }
		BufferSize = CalcBufferSize(MaskStep, ImageH);
	}
	else
	{
		if ( this->CheckGraySize(RoiW, RoiH, MaskStep) == false )
		{	return false; }
		BufferSize = CalcBufferSize(MaskStep, RoiH);
	}	
	JetMemory.free_func(MaskPtr);
	if ( JetMemory.alloc_func(BufferSize, MaskPtr, fnName, "MaskPtr") == false )
	{
		SetErrorString(JetMemory.GetErrorString());
		JetMemory.free_func(MaskPtr);		
		return false;
	}		
	::memset(MaskPtr, 0xFF, sizeof(unsigned char)*BufferSize);	
	if ( this->RGBImageColorFilter3(ImageW, ImageH, ImageStep, pR, pG, pB, ColorGoup, RoiRect, MaskStep, MaskPtr, FullMask) == false )
	{
		JetMemory.free_func(MaskPtr);
		return false;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::RGBImageColorFilter3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, const unsigned char *pR, const unsigned char *pG, const unsigned char *pB, const CColorGroup &ColorGoup, const RECT &RoiRect, IMAGE_SIZE MaskStep, unsigned char *MaskPtr, bool FullMask)//彩色影像抽色
{
	if ( CImageAPI::CheckRGBToRedTable() == false ) { return false; }
	if ( this->CheckGrayImage4(ImageW, ImageH, ImageStep, pR, pG, pB, MaskPtr) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	const int RoiW = RoiRect.right-RoiRect.left;
	const int RoiH = RoiRect.bottom-RoiRect.top;	
	if ( true == FullMask )
	{
		if ( this->CheckGraySize(ImageW, ImageH, MaskStep) == false )
		{	return false; }		
	}
	else
	{
		if ( this->CheckGraySize(RoiW, RoiH, MaskStep) == false )
		{	return false; }		
	}	

	COLOR_LOGIC_MODE LogicMode=COLOR_LOGIC_INCLUDE;
	int    IR=0, IG=0, IB=0, IV=0;
	bool   InR=false, InG=false, InB=false, InV=false, Inside=true, InsideClr=true;
	size_t R=0, G=0, B=0;
	size_t RID = 0;
	size_t GID = 0;
	size_t BID = 0;
	size_t i=0, j=0, k=0, srcIdx=0, dstIdx=0;
	//CColorRGBV  *rgbvPtr=NULL;
	const size_t RoiL = RoiRect.left;
	const size_t RoiT = RoiRect.top;
	const size_t RoiR = RoiRect.right;
	const size_t RoiB = RoiRect.bottom;
	const size_t RGBVCount = ColorGoup.GetColorGroupColorCount();
	for ( i=RoiT; i<RoiB; i++ )
	{
		srcIdx = i*ImageStep+RoiL;
		if ( true == FullMask )
		{	dstIdx = (i*MaskStep)+RoiL;	}
		else
		{	dstIdx = (i-RoiT)*MaskStep;	}
		
		for ( j=RoiL; j<RoiR; j++ )
		{
			R = pR[srcIdx];
			G = pG[srcIdx];
			B = pB[srcIdx];

			RID = (R<<16)+(G<<8)+B;
			GID = (G<<16)+(B<<8)+R;
			BID = (B<<16)+(R<<8)+G;			

			IR = this->m_RGBToRedTable[RID];
			IG = this->m_RGBToRedTable[GID];
			IB = this->m_RGBToRedTable[BID];
			IV = (unsigned char)( (R+G+B)/3 );

			Inside = false;
			for ( k=0; k<RGBVCount; k++ )
			{	
				const CColorRGBV  *rgbvPtr = ColorGoup.GetColorGroupColorPtr(k, false);
				if ( NULL == rgbvPtr ) { continue; }
				if ( rgbvPtr->GetUsed() == false ) { continue; }

				LogicMode = rgbvPtr->GetLogicMode();
				if ( false==Inside || COLOR_LOGIC_EXCLUDE==LogicMode )
				{
					InsideClr = rgbvPtr->CheckColorInside(IR, IG, IB, IV);
					if ( false == InsideClr) 
					{	continue; }

					if ( COLOR_LOGIC_EXCLUDE == LogicMode )
					{	
						Inside = false;
						break;
					}
					Inside = true;				
				}
				else
				{	continue; }
			}

			if ( true == Inside )
			{	MaskPtr[dstIdx] = 0xFF;	}
			else
			{	MaskPtr[dstIdx] = 0x00;	}

			srcIdx ++;
			dstIdx ++;
		}
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillBarcodeImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *&pDst)//填滿條碼影像	
{
	const char fnName[] = "CImageAPI::FillBarcodeImage";
	if ( CImageAPI::CheckGrayBitCount(BitCount) == false ) { return false; }
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FillBarcodeImage3(ImageW, ImageH, ImageStep, BitCount, pImage, KerSize, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillBarcodeImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *pDst)//填滿條碼影像	
{
	const char fnName[] = "CImageAPI::FillBarcodeImage3";
	if ( CImageAPI::CheckGrayBitCount(BitCount) == false ) { return false; }
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }	

	int      ThL=0;
	int      ThH=255;	
	bool     bSecondBlob=false;
	RECT     RoiRect={0, 0, 0, 0};	
	unsigned char *BufferPtr = NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);
	RoiRect.right = (int)(ImageW);
	RoiRect.bottom = (int)(ImageH);
	if ( KerSize > 1 )
	{
		const int IterCount = 1;
		if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
		{	
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		if ( ErodeImage3(ImageW, ImageH, ImageStep, BitCount, pImage, KerSize, IterCount, BufferPtr) == false )
		{
			JetMemory.free_func(BufferPtr);
			return false; 
		}
		bSecondBlob=true;
	}
	else
	{	BufferPtr = pImage;	}
	if ( CalcGrayImageOTSUThreshold(ImageW, ImageH, ImageStep, BufferPtr, RoiRect, ThL) == false )
	{
		if ( BufferPtr != pImage )
		{	JetMemory.free_func(BufferPtr); }
		return false; 
	}

	CJetBlob BlobDetector;	
	BlobDetector.InitialBlob();
	BlobDetector.SetBlobSortMode(BLOB_SORT_PIXELS);
	BlobDetector.SetBlobConnectivity(BLOB_CONNECTIVITY_4);
	if ( BlobDetector.GrayImageBlobDetect(ImageW, ImageH, ImageStep, BufferPtr, ThL, ThH) == false )
	{
		if ( BufferPtr != pImage )
		{	JetMemory.free_func(BufferPtr); }
		return false;	
	}
	if ( BufferPtr != pImage )
	{	JetMemory.free_func(BufferPtr); }

	int          i=0, j=0;
	RECT         BlobRect={0,0,0,0};	
	int          BlobFillRatioRes=0;
	int          BlobW=0, BlobH=0, BlobArea=0, BlobFillRatio=0;		
	TBlobResult *BlobPtr=NULL;	
	TBlobResult *BlobPtrRes=NULL;	
	const int    BlobMinW=ImageW/4;
	const int    BlobMinH=ImageH/4;
	const size_t BlobCount = BlobDetector.GetBlobCount();
	std::vector<TBlobResult> BlobList(BlobCount);	
	
	for ( i=0; i<BlobCount; i++ )
	{
		BlobPtr = BlobDetector.GetBlobPtr(i, false);
		if ( NULL == BlobPtr ) { continue; }		
		BlobW = BlobPtr->GetBlobRectW();
		BlobH = BlobPtr->GetBlobRectH();		
		if ( BlobW < BlobMinW ) { continue; }
		if ( BlobH < BlobMinH ) { continue; }

		BlobArea = BlobPtr->m_BlobPixels;				
		BlobFillRatio = BlobArea*100.0/(BlobW*BlobH);
		if ( NULL==BlobPtrRes || BlobFillRatioRes<BlobFillRatio )
		{
			BlobPtrRes = BlobPtr;
			BlobFillRatioRes = BlobFillRatio;
		}
	}
	if ( NULL == BlobPtrRes ) 
	{	return false; }
	
	BlobPtr = BlobPtrRes;
	unsigned char FillGray=255;	
	const size_t ImageSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pImage, sizeof(unsigned char)*ImageSize);	

	if ( BlobDetector.GetBlobAveGray(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray) == false )
	{	return false; }
	
	int Gap=5;
	int FillGray2 = FillGray;
	FillGray2 += Gap;
	if ( FillGray2 > 255 ) { FillGray = 255; }
	else if ( FillGray2 < 0 ) { FillGray = 0; }
	else { FillGray = (unsigned char)(FillGray); }	

	//FillGray
	int FillGray3 = FillGray;
	if ( true == bSecondBlob )//如果有開過濾器, 就先將周圍填黑, 準備第2次運作
	{	FillGray3 = 0x00; }
	if ( BlobDetector.FillBlobOutside(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray3) == false )
	{	return false; }

	//Fill Original Image 
	if ( true == bSecondBlob )
	{		
		RECT FillRect={0,0,0,0};
		RECT BolbRect=BlobPtr->m_BlobRect;
		const int BlobRectW=(BolbRect.right-BolbRect.left);
		const int BlobRectH=(BolbRect.bottom-BolbRect.top);
		const int BlobRectCpX=(BolbRect.left+BolbRect.right)/2;
		const int BlobRectCpY=(BolbRect.top+BolbRect.bottom)/2;		

		int FillRectW=(int)(BlobRectW);
		int FillRectH=(int)(BlobRectH);
		if ( BlobRectW < BlobRectH )
		{	FillRectH=(int)(BlobRectH);	}
		else
		{	FillRectW=(int)(BlobRectW);	}
		const int FillRectW2=FillRectW/2;
		const int FillRectH2=FillRectH/2;
		FillRect.left = BlobRectCpX-(FillRectW/2);
		FillRect.top  = BlobRectCpY-(FillRectH/2);
		FillRect.right= FillRect.left+FillRectW;
		FillRect.bottom= FillRect.top+FillRectH;
		
		RECT SubRect1=BolbRect;
		RECT SubRect2=BolbRect;
		RECT CalcRect1=BolbRect;
		RECT CalcRect2=BolbRect;
		
		if ( BlobRectW < BlobRectH )//條碼垂直貼, 回填左右側
		{
			int CopyLen=0;
			int nX=0, nY=0, nLeft=0, nRight=0;
			const int CalcRange=BlobRectH*0.1;
			if ( CalcRange > 0 )
			{
				CalcRect1.bottom = CalcRect1.top+(CalcRange);//上端
				CalcRect2.top = CalcRect2.bottom-(CalcRange);//下端
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect1, SubRect1);
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect2, SubRect2);
				const int    SubW1=SubRect1.right-SubRect1.left;
				const int    SubW2=SubRect2.right-SubRect2.left;
				const int    SubWUsd=(SubW1+SubW2)/2-4;
				const int    SubWUsd2=SubWUsd/2;
				const double SubCpX1=(SubRect1.left+SubRect1.right)/2.0;
				const double SubCpY1=(SubRect1.top+SubRect1.bottom)/2.0;
				const double SubCpX2=(SubRect2.left+SubRect2.right)/2.0;
				const double SubCpY2=(SubRect2.top+SubRect2.bottom)/2.0;
				if ( SubCpY2 != SubCpY1 )
				{
					const double mXY=(SubCpX2-SubCpX1)/(SubCpY2-SubCpY1);
					for ( i=FillRect.top; i<FillRect.bottom; i++ )
					{
						nY = i;
						nX = (int)(((nY-SubCpY1)*mXY)+SubCpX1);
						nLeft = nX-SubWUsd2;
						nRight= nLeft+SubWUsd;
						if ( nLeft < 0 ) { nLeft = 0; }
						if ( nRight > ImageW ) { nRight = ImageW; }
						CopyLen = nRight-nLeft;
						j = (nY*ImageStep)+(nLeft);							
						::memcpy(&(pDst[j]), &(pImage[j]), sizeof(IMAGE_DATA)*CopyLen);			
					}
				}
			}
		}
		else //條碼水平貼, 回填上下側
		{			
			int k=0;
			int nX=0, nY=0, nTop=0, nBot=0;
			const int CalcRange=BlobRectW*0.1;
			if ( CalcRange > 0 )
			{
				CalcRect1.right = CalcRect1.left+(CalcRange);//上端
				CalcRect2.left = CalcRect2.right-(CalcRange);//下端
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect1, SubRect1);
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect2, SubRect2);
				const int    SubH1=SubRect1.bottom-SubRect1.top;
				const int    SubH2=SubRect2.bottom-SubRect2.top;
				const int    SubHUsd=(SubH1+SubH2)/2-4;
				const int    SubHUsd2=SubHUsd/2;
				const double SubCpX1=(SubRect1.left+SubRect1.right)/2.0;
				const double SubCpY1=(SubRect1.top+SubRect1.bottom)/2.0;
				const double SubCpX2=(SubRect2.left+SubRect2.right)/2.0;
				const double SubCpY2=(SubRect2.top+SubRect2.bottom)/2.0;
				if ( SubCpX2 != SubCpX1 )
				{
					const double mYX=(SubCpY2-SubCpY1)/(SubCpX2-SubCpX1);
					for ( i=FillRect.left; i<FillRect.right; i++ )
					{
						nX = i;
						nY = (int)(((nX-SubCpX1)*mYX)+SubCpY1);
						nTop = nY-SubHUsd2;
						nBot= nTop+SubHUsd;
						if ( nTop < 0 ) { nTop = 0; }
						if ( nBot > ImageH ) { nBot = ImageH; }
						for ( j=nTop; j<nBot; j++ )
						{
							k = (j*ImageStep)+i;
							pDst[k] = pImage[k];
						}
					}
				}
			}
		}

		//Blob again
		if ( BlobDetector.GrayImageBlobDetect(ImageW, ImageH, ImageStep, pDst, ThL, ThH) == false )
		{	return false; }

		const size_t BlobCount2 = BlobDetector.GetBlobCount();
		std::vector<TBlobResult> BlobList2(BlobCount2);		
		for ( i=0; i<BlobCount2; i++ )
		{
			BlobPtr = BlobDetector.GetBlobPtr(i, false);
			if ( NULL == BlobPtr ) { continue; }		
			BlobW = BlobPtr->GetBlobRectW();
			BlobH = BlobPtr->GetBlobRectH();		
			if ( BlobW < BlobMinW ) { continue; }
			if ( BlobH < BlobMinH ) { continue; }

			BlobArea = BlobPtr->m_BlobPixels;				
			BlobFillRatio = BlobArea*100.0/(BlobW*BlobH);
			if ( NULL==BlobPtrRes || BlobFillRatioRes<BlobFillRatio )
			{
				BlobPtrRes = BlobPtr;
				BlobFillRatioRes = BlobFillRatio;
			}
		}
		if ( NULL == BlobPtrRes ) 
		{	return false;	}		
		BlobPtr = BlobPtrRes;

		//FillGray
		if ( BlobDetector.FillBlobOutside(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray) == false )
		{	return false; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillBarcode2DImage(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *&pDst)//填滿條碼2D影像	
{
	const char fnName[] = "CImageAPI::FillBarcode2DImage";
	if ( CImageAPI::CheckGrayBitCount(BitCount) == false ) { return false; }
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }

	const size_t BufferSize = CalcBufferSize(ImageStep, ImageH);
	JetMemory.free_func(pDst);
	if ( JetMemory.alloc_func(BufferSize, pDst, fnName, "pDst") == false )
	{	
		SetErrorString(JetMemory.GetErrorString());
		return false; 
	}
	if ( this->FillBarcode2DImage3(ImageW, ImageH, ImageStep, BitCount, pImage, KerSize, pDst) == false )
	{
		JetMemory.free_func(pDst);
		return false;
	}		
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillBarcode2DImage3(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, IMAGE_SIZE KerSize, unsigned char *pDst)//填滿條碼2D影像	
{
	const char fnName[] = "CImageAPI::FillBarcode2DImage3";
	if ( CImageAPI::CheckGrayBitCount(BitCount) == false ) { return false; }
	if ( this->CheckGrayImage2(ImageW, ImageH, ImageStep, pImage, pDst) == false )
	{	return false; }	

#ifdef _DEBUG
	CString  str;
	const bool bSaveImage=false;
	CString  strFolder=_T("R:\\Barcode");	
#endif//_DEBUG

	int      ThL=0;
	int      ThH=255;	
	bool     bSecondBlob=false;
	RECT     RoiRect={0, 0, 0, 0};	
	unsigned char *BufferPtr = NULL;
	const size_t BufferSize=CalcBufferSize(ImageStep, ImageH);	
	RoiRect.right = (int)(ImageW);
	RoiRect.bottom = (int)(ImageH);
#ifdef _DEBUG
	if ( true == bSaveImage )
	{	::CreateDirectory(strFolder, NULL);	}

	if ( true == bSaveImage )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("SrcImage.PNG"));
		SaveImage(str, ImageW, ImageH, ImageStep, BitCount, pImage, true);
	}
#endif//_DEBUG
	if ( KerSize > 1 )
	{
		const int IterCount = 1;
		const int MorphMode = MORPH_OPEN;
		const int ShapeMode = MORPH_SHAPE_ELLIPSE;
		if ( JetMemory.alloc_func(BufferSize, BufferPtr, fnName, "BufferPtr") == false )
		{	
			SetErrorString(JetMemory.GetErrorString());
			return false;
		}
		//if ( ErodeImage3(ImageW, ImageH, ImageStep, BitCount, pImage, KerSize, IterCount, BufferPtr) == false )
		if ( MorphImage3(ImageW, ImageH, ImageStep, BitCount, pImage, MorphMode, ShapeMode, KerSize, IterCount, BufferPtr) == false )
		{	
			JetMemory.free_func(BufferPtr);
			return false; 
		}
		bSecondBlob = true;
	}
	else
	{	BufferPtr = pImage;	}
#ifdef _DEBUG
	if ( true == bSaveImage )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("ErodeImage.PNG"));
		SaveImage(str, ImageW, ImageH, ImageStep, BitCount, BufferPtr, true);
	}
#endif//_DEBUG
	if ( CalcGrayImageOTSUThreshold(ImageW, ImageH, ImageStep, BufferPtr, RoiRect, ThL) == false )
	{
		if ( BufferPtr != pImage )
		{	JetMemory.free_func(BufferPtr); }
		return false; 
	}

	CJetBlob BlobDetector;	
	BlobDetector.InitialBlob();
	BlobDetector.SetBlobSortMode(BLOB_SORT_PIXELS);
	BlobDetector.SetBlobConnectivity(BLOB_CONNECTIVITY_4);
	if ( BlobDetector.GrayImageBlobDetect(ImageW, ImageH, ImageStep, BufferPtr, ThL, ThH) == false )
	{
		if ( BufferPtr != pImage )
		{	JetMemory.free_func(BufferPtr); }
		return false;	
	}
	if ( BufferPtr != pImage )
	{	JetMemory.free_func(BufferPtr); }

	int          i=0, j=0;
	RECT         BlobRect={0,0,0,0};	
	int          BlobFillRatioRes=0;
	int          BlobW=0, BlobH=0, BlobArea=0, BlobFillRatio=0;		
	TBlobResult *BlobPtr=NULL;	
	TBlobResult *BlobPtrRes=NULL;	
	const int    BlobMinW=ImageW/4;
	const int    BlobMinH=ImageH/4;
	const size_t BlobCount = BlobDetector.GetBlobCount();
	std::vector<TBlobResult> BlobList(BlobCount);	
	
	for ( i=0; i<BlobCount; i++ )
	{
		BlobPtr = BlobDetector.GetBlobPtr(i, false);
		if ( NULL == BlobPtr ) { continue; }		
		BlobW = BlobPtr->GetBlobRectW();
		BlobH = BlobPtr->GetBlobRectH();		
		if ( BlobW < BlobMinW ) { continue; }
		if ( BlobH < BlobMinH ) { continue; }

		BlobArea = BlobPtr->m_BlobPixels;				
		BlobFillRatio = BlobArea*100.0/(BlobW*BlobH);
		if ( NULL==BlobPtrRes || BlobFillRatioRes<BlobFillRatio )
		{
			BlobPtrRes = BlobPtr;
			BlobFillRatioRes = BlobFillRatio;
		}
	}
	if ( NULL == BlobPtrRes ) 
	{	return false; }
	
	BlobPtr = BlobPtrRes;
	unsigned char FillGray=255;	
	const size_t ImageSize = CalcBufferSize(ImageStep, ImageH);
	::memcpy(pDst, pImage, sizeof(unsigned char)*ImageSize);	

	if ( BlobDetector.GetBlobAveGray(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray) == false )
	{	return false; }
	
	int Gap=5;
	int FillGray2 = FillGray;
	FillGray2 += Gap;
	if ( FillGray2 > 255 ) { FillGray = 255; }
	else if ( FillGray2 < 0 ) { FillGray = 0; }
	else { FillGray = (unsigned char)(FillGray); }	

	bSecondBlob = false;//細節先不回填, 會有問題

	//FillGray
	int FillGray3 = FillGray;
	if ( true == bSecondBlob )//如果有開過濾器, 就先將周圍填黑, 準備第2次運作
	{	FillGray3 = 0x00; }
	if ( BlobDetector.FillBlobRectOutside(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray3) == false )
	{	return false; }

	double BlobAngle=0.0;
	double aCpx=0, aCpy=0, aSizeX=0, aSizeY=0;
#ifndef OPENCV_DISABLE	
	//以下概算角度, 回填細節
	cv::RotatedRect RotRect;
	std::vector<cv::Point> PtList;
	if ( BlobDetector.GetBlobPixelList(BlobPtr, PtList) == true )
	{	
		RotRect=cv::minAreaRect(PtList);
		BlobAngle=RotRect.angle;
		BlobAngle = -1*BlobAngle;
		aCpx=RotRect.center.x;
		aCpy=RotRect.center.y;
		aSizeX=RotRect.size.width;
		aSizeY=RotRect.size.height;
	}	
#endif//OPENCV_DISABLE
	if ( fabs(BlobAngle) > 0.1 )
	{		
		RECT Rect=BlobPtr->m_BlobRect;
		const double RevAngle=BlobAngle*DEG_TO_RAD_DBL;//應該是反向?
		const double COS=::cos(RevAngle);
		const double SIN=::sin(RevAngle);
		const double Left=aCpx-(aSizeX/2);
		const double Top =aCpy-(aSizeY/2);
		const double Right=aCpx+(aSizeX/2);
		const double Bot =aCpy+(aSizeY/2);
		//::memset(pDst, 0x00, sizeof(unsigned char)*BufferSize);
		for ( int i=Rect.top; i<Rect.bottom; i++ )
		{
			for ( int j=Rect.left; j<Rect.right; j++ )
			{				
				double x=j-aCpx;
				double y=i-aCpy;
				double x2=(x*COS)-(y*SIN)+aCpx;
				double y2=(x*SIN)+(y*COS)+aCpy;
				if ( x2<Left || x2>Right || y2<Top || y2>Bot )
				{
					int k=0;
					if ( 24 == BitCount )
					{
						k=(i*ImageStep)+(j*3);
						pDst[k] = pDst[k+1] = pDst[k+2] = FillGray3;	
					}
					else
					{
						k=(i*ImageStep)+j;
						pDst[k] = FillGray3;	
					}
					
				}
			}
		}
	}	

#ifdef _DEBUG
	if ( true == bSaveImage )
	{
		str.Format(_T("%s\\%s"), strFolder, _T("FillBlobOutside.PNG"));
		SaveImage(str, ImageW, ImageH, ImageStep, BitCount, pDst, true);
	}
#endif//_DEBUG

	//Fill Original Image 
	if ( true == bSecondBlob )
	{		
		RECT FillRect={0,0,0,0};
		RECT BolbRect=BlobPtr->m_BlobRect;
		const int BlobRectW=(BolbRect.right-BolbRect.left);
		const int BlobRectH=(BolbRect.bottom-BolbRect.top);
		const int BlobRectCpX=(BolbRect.left+BolbRect.right)/2;
		const int BlobRectCpY=(BolbRect.top+BolbRect.bottom)/2;		

		int FillRectW=(int)(BlobRectW);
		int FillRectH=(int)(BlobRectH);
		if ( BlobRectW < BlobRectH )
		{	FillRectH=(int)(BlobRectH);	}
		else
		{	FillRectW=(int)(BlobRectW);	}
		const int FillRectW2=FillRectW/2;
		const int FillRectH2=FillRectH/2;
		FillRect.left = BlobRectCpX-(FillRectW/2);
		FillRect.top  = BlobRectCpY-(FillRectH/2);
		FillRect.right= FillRect.left+FillRectW;
		FillRect.bottom= FillRect.top+FillRectH;
		
		RECT SubRect1=BolbRect;
		RECT SubRect2=BolbRect;
		RECT CalcRect1=BolbRect;
		RECT CalcRect2=BolbRect;
		
		if ( BlobRectW < BlobRectH )//條碼垂直貼, 回填左右側
		{
			int CopyLen=0;
			int nX=0, nY=0, nLeft=0, nRight=0;
			const int CalcRange=BlobRectH*0.1;
			if ( CalcRange > 0 )
			{
				CalcRect1.bottom = CalcRect1.top+(CalcRange);//上端
				CalcRect2.top = CalcRect2.bottom-(CalcRange);//下端
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect1, SubRect1);
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect2, SubRect2);
				const int    SubW1=SubRect1.right-SubRect1.left;
				const int    SubW2=SubRect2.right-SubRect2.left;
				const int    SubWUsd=(SubW1+SubW2)/2-4;
				const int    SubWUsd2=SubWUsd/2;
				const double SubCpX1=(SubRect1.left+SubRect1.right)/2.0;
				const double SubCpY1=(SubRect1.top+SubRect1.bottom)/2.0;
				const double SubCpX2=(SubRect2.left+SubRect2.right)/2.0;
				const double SubCpY2=(SubRect2.top+SubRect2.bottom)/2.0;
				if ( SubCpY2 != SubCpY1 )
				{
					const double mXY=(SubCpX2-SubCpX1)/(SubCpY2-SubCpY1);
					for ( i=FillRect.top; i<FillRect.bottom; i++ )
					{
						nY = i;
						nX = (int)(((nY-SubCpY1)*mXY)+SubCpX1);
						nLeft = nX-SubWUsd2;
						nRight= nLeft+SubWUsd;
						if ( nLeft < 0 ) { nLeft = 0; }
						if ( nRight > ImageW ) { nRight = ImageW; }
						CopyLen = nRight-nLeft;
						j = (nY*ImageStep)+(nLeft);							
						::memcpy(&(pDst[j]), &(pImage[j]), sizeof(IMAGE_DATA)*CopyLen);			
					}
				}
			}
		}
		else //條碼水平貼, 回填上下側
		{			
			int k=0;
			int nX=0, nY=0, nTop=0, nBot=0;
			const int CalcRange=BlobRectW*0.1;
			if ( CalcRange > 0 )
			{
				CalcRect1.right = CalcRect1.left+(CalcRange);//上端
				CalcRect2.left = CalcRect2.right-(CalcRange);//下端
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect1, SubRect1);
				BlobDetector.CalcBlobSubRect(BlobPtr, CalcRect2, SubRect2);
				const int    SubH1=SubRect1.bottom-SubRect1.top;
				const int    SubH2=SubRect2.bottom-SubRect2.top;
				const int    SubHUsd=(SubH1+SubH2)/2-4;
				const int    SubHUsd2=SubHUsd/2;
				const double SubCpX1=(SubRect1.left+SubRect1.right)/2.0;
				const double SubCpY1=(SubRect1.top+SubRect1.bottom)/2.0;
				const double SubCpX2=(SubRect2.left+SubRect2.right)/2.0;
				const double SubCpY2=(SubRect2.top+SubRect2.bottom)/2.0;
				if ( SubCpX2 != SubCpX1 )
				{
					const double mYX=(SubCpY2-SubCpY1)/(SubCpX2-SubCpX1);
					for ( i=FillRect.left; i<FillRect.right; i++ )
					{
						nX = i;
						nY = (int)(((nX-SubCpX1)*mYX)+SubCpY1);
						nTop = nY-SubHUsd2;
						nBot= nTop+SubHUsd;
						if ( nTop < 0 ) { nTop = 0; }
						if ( nBot > ImageH ) { nBot = ImageH; }
						for ( j=nTop; j<nBot; j++ )
						{
							k = (j*ImageStep)+i;
							pDst[k] = pImage[k];
						}
					}
				}
			}
		}

		//Blob again
		if ( BlobDetector.GrayImageBlobDetect(ImageW, ImageH, ImageStep, pDst, ThL, ThH) == false )
		{	return false; }

		const size_t BlobCount2 = BlobDetector.GetBlobCount();
		std::vector<TBlobResult> BlobList2(BlobCount2);		
		for ( i=0; i<BlobCount2; i++ )
		{
			BlobPtr = BlobDetector.GetBlobPtr(i, false);
			if ( NULL == BlobPtr ) { continue; }		
			BlobW = BlobPtr->GetBlobRectW();
			BlobH = BlobPtr->GetBlobRectH();		
			if ( BlobW < BlobMinW ) { continue; }
			if ( BlobH < BlobMinH ) { continue; }

			BlobArea = BlobPtr->m_BlobPixels;				
			BlobFillRatio = BlobArea*100.0/(BlobW*BlobH);
			if ( NULL==BlobPtrRes || BlobFillRatioRes<BlobFillRatio )
			{
				BlobPtrRes = BlobPtr;
				BlobFillRatioRes = BlobFillRatio;
			}
		}
		if ( NULL == BlobPtrRes ) 
		{	return false;	}		
		BlobPtr = BlobPtrRes;

		//FillGray
		if ( BlobDetector.FillBlobOutside(BlobPtr, ImageW, ImageH, ImageStep, BitCount, pDst, FillGray) == false )
		{	return false; }
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, IMAGE_SIZE BitCount, unsigned char *pImage, const RECT &RoiRect, unsigned char Red, unsigned char Grn, unsigned char Blu)//填滿區域影像
{
	if ( CImageAPI::CheckBitCount(BitCount) == false ) { return false; }	
	if ( 8 == BitCount ) 
	{	return CImageAPI::FillGrayImageRoi(ImageW, ImageH, ImageStep, pImage, RoiRect, Red); }
	if ( 24 == BitCount ) 
	{	return CImageAPI::FillColorImageRoi(ImageW, ImageH, ImageStep, pImage, RoiRect, Red, Grn, Blu); }
	return false;	
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillGrayImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, unsigned char Gray)//填滿區域影像
{
	if ( this->CheckGrayImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int   i=0;
	int   j=0;
	int   nIndex=0;
	unsigned char *pSrc=NULL;
	const int nStep = (int)(ImageStep);

	nIndex = (RoiRect.top*nStep)+RoiRect.left;
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		pSrc = &(pImage[nIndex]);
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			(*pSrc++) = Gray;			
		}
		nIndex += nStep;
	}
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::FillColorImageRoi(IMAGE_SIZE ImageW, IMAGE_SIZE ImageH, IMAGE_SIZE ImageStep, unsigned char *pImage, const RECT &RoiRect, unsigned char Red, unsigned char Grn, unsigned char Blu)//填滿區域影像
{
	if ( this->CheckColorImage(ImageW, ImageH, ImageStep, pImage) == false )
	{	return false; }
	if ( this->CheckRoiRect(ImageW, ImageH, RoiRect) == false )
	{	return false; }

	int   i=0;
	int   j=0;
	int   nIndex=0;
	unsigned char *pSrc=NULL;
	const int nStep = (int)(ImageStep);

	nIndex = (RoiRect.top*nStep)+(RoiRect.left*3);
	for ( i=RoiRect.top; i<RoiRect.bottom; i++ )
	{
		pSrc = &(pImage[nIndex]);
		for ( j=RoiRect.left; j<RoiRect.right; j++ )
		{
			(*pSrc++) = Red;
			(*pSrc++) = Grn;
			(*pSrc++) = Blu;
		}
		nIndex += nStep;
	}
	return true;
}
