bool CImageAPI::DeductBasePhase_Public(PHASE_DATA BasePhase, int &Phase)//扣除相平面
{
	return DeductBasePhase(BasePhase, Phase);
	return true;
}
//-------------------------------------------------------------------------------------//
bool CImageAPI::CalcCombinePhasePeriodRatio_Public(int Mode, double P1, double P2, double &Ratio)//計算合併比例
{
	return CalcCombinePhasePeriodRatio(Mode, P1, P2, Ratio);
	return true;
}
